insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/wp-content/uploads/2026/04/RFE-20.4.2026-deifinitif-et-validei.pdf' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2026/04/RFE-20.4.2026-deifinitif-et-validei.pdf' and s.acronym in ('SFAR', 'GIHP')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2026/04/RFE-20.4.2026-deifinitif-et-validei.pdf' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'anticoagulants',
  card_json = $mgjson${"badge":"GRADE","title":"Anticoagulants & procédure invasive","short":"Gestion péri-procédurale des anticoagulants pour une procédure invasive programmée.","society":"SFAR / GIHP — RFE 2026","version":"20 avril 2026","validated":"CA SFAR le 18/03/2026","methodology":"GRADE","pages":19,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"anticoagulants","sections":[{"title":"Principes généraux & délais d'arrêt","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Principe general (R1 — GRADE 1+, accord fort) :</b> la gestion péri-procédurale des anticoagulants se decide en croisant 3 elements : le <b>risque hémorragique de la procédure</b>, le <b>risque thromboembolique du patient</b>, et les <b>conséquences d'un report</b> de la procédure si les deux risques sont élevés.","style":"body"}},{"t":"section","text":"Légende des grades (méthodologie GRADE)","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"p","html":"Recommandé (forte)","style":"badge_head"},{"t":"chip","label":"1-"},{"t":"p","html":"Non recommandé (forte)","style":"badge_head"},{"t":"chip","label":"2+"},{"t":"p","html":"Proposé (optionnel)","style":"badge_head"},{"t":"chip","label":"2-"},{"t":"p","html":"Proposé de ne pas faire","style":"badge_head"},{"t":"chip","label":"AE"},{"t":"p","html":"Avis d'experts","style":"badge_head"}]]},{"t":"section","text":"Définitions — Risque hémorragique de la procédure","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"<b>Risque faible</b>","style":"cell_b"},{"t":"p","html":"Saignements peu fréquents, de faible intensité ou aisément contrôlés. Réalisable sous anticoagulant curatif.","style":"cell"}],[{"t":"p","html":"<b>Risque élevé</b>","style":"cell_b"},{"t":"p","html":"Nécessite l'arrêt de l'anticoagulant : le saignement est majoré chez le patient anticoagulé.","style":"cell"}],[{"t":"p","html":"<b>Procédures neuraxiales</b>","style":"cell_b"},{"t":"p","html":"Ponction lombaire, rachianesthésie, péridurale, péri-rachianesthésie combinée (hors chirurgie rachidienne) — considérées à risque hémorragique très élevé.","style":"cell"}]]},{"t":"section","text":"Procédure à risque hémorragique FAIBLE — pas d'arrêt","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"2.1","style":"cell_b"},{"t":"p","html":"AVK : poursuivre le traitement ; contrôler l'INR dans la semaine précédant la procédure (absence de surdosage).","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"2.2","style":"cell_b"},{"t":"p","html":"AOD (apixaban, dabigatran, édoxaban, rivaroxaban) : sauter la prise de la veille au soir ET celle du matin de la procédure (quel que soit le schéma), reprise aux doses habituelles ≥ 6h après le geste.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}]]},{"t":"section","text":"Procédure à risque hémorragique ÉLEVÉ — délais d'arrêt pré-procédural","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Anticoagulant","style":"head_w"},{"t":"p","html":"Dernière prise / injection avant la procédure (J0)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"AVK — Warfarine (Coumadine®)","style":"cell"},{"t":"p","html":"J-6, puis contrôle INR la veille (objectif ≤ 1,5 ; ≤ 1,2 si neurochirurgie/neuraxial)","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"AVK — Fluindione (Préviscan®)","style":"cell"},{"t":"p","html":"J-5, puis contrôle INR la veille","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"AVK — Acénocoumarol (Sintrom®)","style":"cell"},{"t":"p","html":"J-4, puis contrôle INR la veille","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"AOD anti-Xa (apixaban, édoxaban, rivaroxaban)","style":"cell"},{"t":"p","html":"J-3 si fonction rénale normale ; J-5 si risque hémorragique très élevé (neurochirurgie intracrânienne, neuraxial)","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Dabigatran","style":"cell"},{"t":"p","html":"J-3 (fonction rénale normale) ; adapter si IRC (cf. tableau rénal)","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"HBPM dose curative","style":"cell"},{"t":"p","html":"24h avant la procédure","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"HNF sous-cutanée dose curative","style":"cell"},{"t":"p","html":"24h avant la procédure","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"HNF IVSE dose curative","style":"cell"},{"t":"p","html":"6h avant la procédure","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Fondaparinux dose curative","style":"cell"},{"t":"p","html":"J-4","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"* Si INR > seuil de sécurité la veille : vitamine K 2 à 5 mg PO (voie orale préférée à l'IV : risque anaphylactique décrit par voie IV), contrôle INR le lendemain.","style":"note"},{"t":"p","html":"* Reprise post-procédurale (risque hémorragique élevé) : AVK dans les 24 premières heures, posologie habituelle, sans dose de charge (R4.1, GRADE 2+, Fort — upgradé à 1+ pour la FA spécifiquement, cf. p.2). AOD idéalement entre 48h et 72h, sans relais héparinique (R4.5/R5.6/R7.10, GRADE 2+, Fort). Si reprise impossible : héparine dose curative 48-72h après (R4.2/R4.6, GRADE 2+, Fort). Thromboprophylaxie veineuse post-procédurale recommandée dans l'attente (R4.7, GRADE 1+, Fort).","style":"note"}]},{"title":"Synthèse par indication — Fibrillation atriale & valve mécanique","items":[{"t":"section","text":"Fibrillation atriale (FA) — patient sous AOD","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"5.1","style":"cell_b"},{"t":"p","html":"ATCD d'AVC ischémique : différer la procédure au-delà du 3ème mois post-AVC si possible (sauf urgence vitale/fonctionnelle).","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"3.3/5.5","style":"cell_b"},{"t":"p","html":"Risque hémorragique élevé : arrêt AOD, dernière prise à J-3 (DFG normal), sans relais héparinique.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"5.6","style":"cell_b"},{"t":"p","html":"Reprise du traitement curatif par l'AOD habituel, idéalement entre 48h et 72h, sans relais héparinique.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"4.7","style":"cell_b"},{"t":"p","html":"Thromboprophylaxie veineuse post-procédurale dans l'attente de la reprise curative.","style":"cell"},{"t":"chip","label":"1+"},{"t":"p","html":"Fort","style":"cell_c"}]]},{"t":"section","text":"Fibrillation atriale (FA) — patient sous AVK","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"3.1/3.2","style":"cell_b"},{"t":"p","html":"Arrêt AVK avant procédure à risque élevé (délais p.1) + contrôle INR veille ; vitamine K si besoin.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"5.2","style":"cell_b"},{"t":"p","html":"Sans ATCD d'AVC/AIT/embolie systémique : PAS de relais héparinique pré-procédural.","style":"cell"},{"t":"chip","label":"1-"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"5.3","style":"cell_b"},{"t":"p","html":"Avec ATCD d'AVC/AIT/embolie systémique : relais pré-procédural par HBPM dose curative (1ère inj. soir J-3, dernière au plus tard matin J-1), sans contrôle anti-Xa systématique.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"4.1","style":"cell_b"},{"t":"p","html":"Reprise des AVK dans les 24 premières heures post-procédure, posologie habituelle, sans dose de charge, sans relais héparinique.","style":"cell"},{"t":"chip","label":"1+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"4.2","style":"cell_b"},{"t":"p","html":"Si reprise AVK impossible <24h : héparine dose curative (HBPM préférée), idéalement 48-72h post-procédure.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}]]},{"t":"section","text":"Valve cardiaque mécanique (AVK)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"6.1","style":"cell_b"},{"t":"p","html":"Relais pré-procédural systématique par HBPM dose curative 2x/j (1ère inj. soir J-3, dernière matin J-1), sans contrôle anti-Xa.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"6.2","style":"cell_b"},{"t":"p","html":"Programmer la procédure le matin pour ne pas prolonger l'arrêt des anticoagulants.","style":"cell"},{"t":"chip","label":"AE"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"6.3","style":"cell_b"},{"t":"p","html":"Valve aortique à double ailettes, rythme sinusal, sans ATCD thrombotique : pas de relais héparinique post-procédural si AVK repris <24h.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"6.4","style":"cell_b"},{"t":"p","html":"Autres cas : relais héparinique post-procédural (HBPM 2x/j), débuté idéalement 48-72h après, arrêté au 1er INR ≥ 2.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}]]}]},{"title":"Synthèse par indication — Maladie thromboembolique veineuse","items":[{"t":"section","text":"Maladie thromboembolique veineuse (MTEV) — stratification du risque","color":"navy"},{"t":"panel","tone":"default","content":{"t":"table","rows":[[{"t":"p","html":"<b>Très élevé</b>","style":"cell_b"},{"t":"p","html":"EP ou TVP proximale < 1 mois","style":"cell"}],[{"t":"p","html":"<b>Élevé</b>","style":"cell_b"},{"t":"p","html":"EP ou TVP proximale de 1 à 3 mois","style":"cell"}],[{"t":"p","html":"<b>À évaluer</b>","style":"cell_b"},{"t":"p","html":"SAPL, HTP-TEC, thrombophilie majeure, TIH en cours, récidive sous traitement → <b>discussion multidisciplinaire</b>","style":"cell"}],[{"t":"p","html":"<b>Modéré</b>","style":"cell_b"},{"t":"p","html":"Autres cas","style":"cell"}]]}},{"t":"p","html":"Différer la procédure au-delà du 1er mois (idéalement > 3 mois) après EP/TVP proximale si possible (R7.2, GRADE 2+, Fort).","style":"note"},{"t":"section","text":"MTEV — patient sous AOD","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"3.3","style":"cell_b"},{"t":"p","html":"Risque hémorragique élevé, cas non complexe : arrêt AOD, dernière prise à J-3 (DFG normal), sans relais.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"7.8","style":"cell_b"},{"t":"p","html":"EP/TVP proximale < 1 mois : stratégie personnalisée multidisciplinaire.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"7.9","style":"cell_b"},{"t":"p","html":"Autres cas de MTEV : interrompre l'AOD sans relais héparinique pré-procédural.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"7.10","style":"cell_b"},{"t":"p","html":"Reprise du traitement curatif par l'AOD habituel, idéalement 48-72h après, sans relais héparinique.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"4.6","style":"cell_b"},{"t":"p","html":"Si le traitement curatif ne peut pas être repris par l'AOD habituel, initier une anticoagulation par héparines à dose curative (HBPM de préférence), idéalement 48-72h après la procédure.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}]]},{"t":"section","text":"MTEV — patient sous AVK","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"7.4","style":"cell_b"},{"t":"p","html":"EP/TVP proximale < 3 mois : relais pré-procédural par HBPM dose curative (1ère inj. soir J-3, dernière au plus tard matin J-1).","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"7.5","style":"cell_b"},{"t":"p","html":"Risque de récidive modéré : PAS de relais héparinique pré-procédural.","style":"cell"},{"t":"chip","label":"2-"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"7.6","style":"cell_b"},{"t":"p","html":"EP/TVP < 3 mois ou déficit connu en prot. C/S : relais post-procédural par héparine dose curative, débuté 48-72h après, arrêté au 1er INR ≥ 2.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"7.7","style":"cell_b"},{"t":"p","html":"Autres cas : pas de relais post-procédural si AVK repris < 24h.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}]]},{"t":"section","text":"MTEV — filtre cave & thromboprophylaxie mécanique","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"7.11","style":"cell_b"},{"t":"p","html":"EP/TVP proximale < 1 mois + procédure à risque hémorragique élevé : discuter un filtre cave optionnel pré-procédural.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"7.12","style":"cell_b"},{"t":"p","html":"Retrait du filtre programmé dès reprise de l'anticoagulation curative (idéalement < 3 mois).","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"7.13","style":"cell_b"},{"t":"p","html":"TVP distale symptomatique : différer la procédure au-delà du 1er mois suivant la thrombose si cela ne génère pas de risque vital/fonctionnel majeur.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"7.14","style":"cell_b"},{"t":"p","html":"Risque hémorragique ET thromboembolique élevés : compression pneumatique intermittente per- et post-procédurale, en association à la prophylaxie pharmacologique.","style":"cell"},{"t":"chip","label":"2+"},{"t":"p","html":"Fort","style":"cell_c"}],[{"t":"p","html":"7.15","style":"cell_b"},{"t":"p","html":"Contentions élastiques graduées : NON recommandées quel que soit le risque thromboembolique.","style":"cell"},{"t":"chip","label":"1-"},{"t":"p","html":"Fort","style":"cell_c"}]]}]},{"title":"Adaptation à l'insuffisance rénale","items":[{"t":"section","text":"Insuffisance rénale chronique (IRC) — stades (CKD-EPI)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Stade","style":"head_w"},{"t":"p","html":"DFGe (mL/min/1,73m²)","style":"head_w_c"}],[{"t":"p","html":"IRC modérée (3)","style":"cell"},{"t":"p","html":"30 – 49","style":"cell_c"}],[{"t":"p","html":"IRC sévère (4)","style":"cell"},{"t":"p","html":"15 – 29","style":"cell_c"}],[{"t":"p","html":"IRC terminale (5 / 5D)","style":"cell"},{"t":"p","html":"< 15","style":"cell_c"}]]},{"t":"p","html":"AVK et HNF : maniement inchangé quel que soit le stade d'IRC (élimination non rénale). AOD et HBPM : cf. tableaux ci-dessous.","style":"note"},{"t":"section","text":"Délai d'arrêt pré-procédural des AOD selon le DFGe (FA)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Molécule","style":"head_w"},{"t":"p","html":"DFGe","style":"head_w_c"},{"t":"p","html":"Risque faible","style":"head_w_c"},{"t":"p","html":"Risque élevé","style":"head_w_c"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","ht