where d.source_url = 'https://sfar.org/ventilation-non-invasive%E2%80%A8au-cours-de-linsuffisance-respiratoire-aigue-nouveau-ne-exclu/' and s.acronym in ('SFAR', 'SPLF', 'SRLF')
