update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/actualisation-de-recommandations-intubation-difficile-et-extubation-en-anesthesie-chez-ladulte/' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'intubation_difficile_adulte',
  card_json = $mgjson${"badge":"GRADE","title":"Intubation difficile & extubation (adulte)","short":"Actualisation de la Conférence d'Experts Intubation difficile 2006 : vidéolaryngoscopes en intubation prévue et non prévue, techniques d'oxygénation, anesthésie et curarisation, stratégie de gestion des voies aériennes en cas d'intubation difficile non prévue, extubation à risque (facteurs de risque, leadership et décision).","society":"SFAR — RFE 2017","version":"2017","validated":"Texte validé par le CA SFAR le 29/06/2017","methodology":"GRADE","pages":11,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"intubation_difficile_adulte","sections":[{"title":"Introduction, méthodologie & les 6 questions","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> actualisation de la Conférence d'Experts « Intubation difficile » de 2006 — prévention de la désaturation, place des vidéolaryngoscopes, anesthésie et curarisation en situation difficile, critères d'extubation à risque, et synthèse sous forme d'algorithmes. Comité de 13 experts, méthode GRADE®, format PICO, 6 questions.<br/><br/><b>Résultats (résumé officiel) :</b> 13 recommandations formalisées ; 5 de niveau de preuve élevé (Grade 1), 8 de niveau de preuve faible (Grade 2). Accord fort obtenu pour <b>99 %</b> des recommandations — une seule (R2.3) n'a recueilli qu'un accord faible, reproduit fidèlement ci-dessous plutôt que reformulé en « accord fort ».","style":"body"}},{"t":"section","text":"Légende des grades (méthodologie GRADE)","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"p","html":"Il faut faire","style":"badge_head"},{"t":"chip","label":"1-"},{"t":"p","html":"Il ne faut pas faire","style":"badge_head"},{"t":"chip","label":"2+"},{"t":"p","html":"Il faut probablement","style":"badge_head"},{"t":"chip","label":"2-"},{"t":"p","html":"Il ne faut probablement pas","style":"badge_head"}]]},{"t":"section","text":"Les 6 questions traitées par la RFE","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"#","style":"head_w"},{"t":"p","html":"Question","style":"head_w"}],[{"t":"p","html":"1","style":"cell"},{"t":"p","html":"Techniques de préoxygénation et d'oxygénation apnéique pour éviter la désaturation lors des manœuvres d'intubation","style":"cell"}],[{"t":"p","html":"2","style":"cell"},{"t":"p","html":"Vidéolaryngoscopes vs laryngoscopie standard pour faciliter l'exposition trachéale (intubation difficile prévue, hors fibroscopie)","style":"cell"}],[{"t":"p","html":"3","style":"cell"},{"t":"p","html":"AIVOC/AINOC vs sédation par bolus pour le contrôle des voies aériennes en respiration spontanée","style":"cell"}],[{"t":"p","html":"4","style":"cell"},{"t":"p","html":"Anesthésie et curarisation chez un patient avec critères d'intubation difficile et ventilation au masque potentiellement difficile","style":"cell"}],[{"t":"p","html":"5","style":"cell"},{"t":"p","html":"Critères permettant d'anticiper les difficultés d'extubation trachéale postopératoire","style":"cell"}],[{"t":"p","html":"6","style":"cell"},{"t":"p","html":"Arbres décisionnels et algorithmes pour optimiser la prise en charge d'une difficulté prévue ou non","style":"cell"}]]}]},{"title":"Q1 — Préoxygénation & oxygénation apnéique","items":[{"t":"section","text":"Question 1 — Préoxygénation et oxygénation apnéique","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.1","style":"cell_b"},{"t":"p","html":"Il faut prévenir systématiquement la désaturation artérielle en oxygène lors des manœuvres d'intubation trachéale ou d'insertion de dispositif supraglottique en raison des conséquences en termes de morbidité et de mortalité lors de sa survenue.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R1.2","style":"cell_b"},{"t":"p","html":"Afin de prévenir une désaturation artérielle lors des manœuvres d'intubation trachéale ou d'insertion de dispositif supraglottique, il faut réaliser systématiquement une procédure de préoxygénation (3 min / 8 inspirations profondes), y compris dans le cadre de l'urgence.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R1.3","style":"cell_b"},{"t":"p","html":"Dans certains cas, il faut probablement utiliser des techniques d'oxygénation apnéique avec des techniques spécifiques pour prévenir une désaturation artérielle en oxygène.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"NAP4 (Royaume-Uni) : l'intubation difficile ou l'échec d'intubation représentait 39 % des incidents liés au contrôle des voies aériennes. Sans préoxygénation, désaturation &lt; 90 % chez 30-60 % des patients ASA I. Délai de désaturation : 1-2 min en air ambiant, prolongé à 6-8 min après préoxygénation en O2 pur. FeO2 &gt; 90 % = préoxygénation efficace. Position proclive (20-30°) : bénéfice démontré chez l'obèse (délai de désaturation +30 %, jusqu'à 3,5 min vs 2,5 min en décubitus dorsal) et en population générale ; bénéfice non démontré chez la femme enceinte malgré l'augmentation de CRF. Oxygénation apnéique (canule nasale 5 L/min ou oxygène nasal à haut débit) : particulièrement utile chez l'obèse (doublement du délai de désaturation) et en cas d'intubation difficile prévue ou en technique de sauvetage.","style":"note"}]},{"title":"Q2 (1/2) — Vidéolaryngoscopes : intubation prévue","items":[{"t":"section","text":"Question 2 (1/2) — Vidéolaryngoscopes : intubation difficile prévue","color":"navy"},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Prérequis</b> — un vidéolaryngoscope ne doit pas être utilisé si : ouverture de bouche &lt; 2,5 cm • rachis cervical fixé en flexion • tumeur des voies aérodigestives supérieures avec stridor. Vérifier la possibilité d'introduction avant d'endormir le patient. Dans le cas d'une induction en séquence rapide pour estomac plein, les données de la littérature ne permettent pas de formuler de recommandation concernant l'utilisation des vidéolaryngoscopes. Une désaturation &lt; 95 % impose l'arrêt des manœuvres d'intubation au profit de l'oxygénation — le vidéolaryngoscope ne peut pas se substituer à un dispositif supraglottique en cas de risque avéré d'hypoxémie.","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R2.1","style":"cell_b"},{"t":"p","html":"Dans le cadre d'une chirurgie programmée, il faut utiliser en première intention les vidéolaryngoscopes chez les patients avec une ventilation au masque possible et au moins deux critères d'intubation difficile.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"Chez les patients avec ≥ 2 facteurs prédictifs (dont Mallampati III/IV), les vidéolaryngoscopes améliorent la vision glottique et le taux de succès à la première tentative vs lame de Macintosh. En cas de rachis cervical pathologique, une méta-analyse montre un taux de succès plus élevé, une meilleure vision et moins de complications avec un Airtraq® qu'avec une lame Macintosh classique. Chez l'obèse (IMC &gt; 30 kg/m²) : meilleure visualisation, meilleur taux de succès, moins de désaturation &lt; 92 %.","style":"note"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Pas de recommandation</b> — La durée nécessaire pour une intubation trachéale avec un vidéolaryngoscope peut être plus courte, identique ou plus longue qu'avec une lame de Macintosh (paramètre dépendant du dispositif, de l'opérateur et du terrain) : les vidéolaryngoscopes ne peuvent pas être proposés systématiquement en première intention chez les patients à risque de régurgitation et d'inhalation (estomac plein) — la manœuvre de Sellick pourrait altérer la vision glottique sous vidéolaryngoscope.","style":"body_sm"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Prérequis</b> — chez le patient avec une intubation difficile <b>non prévue</b>, une à deux laryngoscopies par un praticien expert sont effectuées en première intention, en utilisant tous les moyens d'optimisation possibles (repositionnement de la tête du patient, long mandrin béquillé type Eschmann, appui laryngé externe BURP) pour visualiser la glotte et parvenir à intuber la trachée. Le mandrin béquillé fait partie de la première étape de la stratégie d'optimisation de la gestion des voies aériennes en cas d'intubation difficile non prévue.","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R2.2","style":"cell_b"},{"t":"p","html":"Si une intubation difficile n'est pas prévue, il faut probablement utiliser les vidéolaryngoscopes en seconde intention chez les patients avec un stade de Cormack et Lehane III ou plus, si la ventilation au masque est possible.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"Réduit l'incidence des scores Cormack-Lehane III/IV observés initialement en laryngoscopie directe. Étude rétrospective multicentrique (7 centres, 2004-2013, 1427 échecs de laryngoscopie directe) : la vidéolaryngoscopie est la méthode de secours la plus utilisée en première intention, avec le taux de succès le plus élevé parmi les dispositifs de secours.","style":"note"}]},{"title":"Q2 (2/2) — Vidéolaryngoscopes en ventilation spontanée","items":[{"t":"section","text":"Question 2 (2/2) — Vidéolaryngoscopes en ventilation spontanée","color":"navy"},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Prérequis</b> — en cas d'intubation impossible, la fibroscopie reste la méthode de référence (indication privilégiée : tumeurs de la base de langue). En cas de stridor associé à une détresse respiratoire, une trachéotomie première doit être envisagée en première intention. En cas d'échec de fibroscopie, les vidéolaryngoscopes ont probablement une place chez les patients avec une ouverture de bouche suffisante (&gt; 2,5 cm), seuls ou en association. Quelle que soit la technique choisie en cas d'intubation et ventilation au masque difficiles, le patient sédaté doit garder une respiration spontanée efficace.","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R2.3","style":"cell_b"},{"t":"p","html":"Il faut probablement utiliser les vidéolaryngoscopes en technique alternative à l'utilisation du fibroscope chez les patients en ventilation spontanée, avec des critères d'intubation prévue difficile ou impossible et de ventilation au masque difficile.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Seule recommandation de cette RFE à ne pas avoir recueilli d'« Accord FORT »</b> — son grade est explicitement qualifié d'« Accord faible » dans le texte source, reproduit tel quel (les 12 autres recommandations ont toutes recueilli un Accord FORT).","style":"body_sm"}},{"t":"p","html":"Peu d'études disponibles. Intubation orale ou nasale sous vidéolaryngoscopie en ventilation spontanée réalisable par des opérateurs entraînés, avec une technique de sédation (anesthésie topique + AIVOC rémifentanil) comparable à celle de la fibro-intubation — technique alternative acceptable pour des ouvertures buccales ≥ 2,5 cm, hors pathologie tumorale, chez des opérateurs expérimentés.","style":"note"}]},{"title":"Q3-Q4 — Anesthésie & curarisation","items":[{"t":"section","text":"Questions 3-4 — Anesthésie et curarisation","color":"navy"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Pas de recommandation</b> — Faut-il utiliser l'AIVOC/AINOC plutôt que la sédation par bolus pour le contrôle des voies aériennes en cas de difficulté suspectée ou avérée chez un patient en respiration spontanée ? La CE/ID de 2006 précisait déjà que l'utilisation du propofol ou du rémifentanil en AIVOC s'accompagne d'un risque faible de désaturation, améliore les conditions d'intubation pour l'opérateur et le confort du patient — le rémifentanil permet une meilleure coopération. Les données récentes de la littérature ne permettent pas de formuler une nouvelle proposition au-delà de ce constat déjà établi.","style":"body_sm"}},{"t":"p","html":"Il est indispensable de s'assurer de la disponibilité des techniques d'oxygénation avant d'envisager une anesthésie générale.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R4.1","style":"cell_b"},{"t":"p","html":"Il faut maintenir un niveau d'anesthésie profond afin d'optimiser les conditions de ventilation au masque et d'intubation en utilisant des agents rapidement réversibles.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R4.2","style":"cell_b"},{"t":"p","html":"En cas d'intubation difficile prévue, il faut probablement utiliser un curare afin d'améliorer les conditions de ventilation au masque et d'intubation, en utilisant un curare d'action courte ou rapidement inactivée sous couvert du monitorage systématique de la curarisation.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"Propofol et sévoflurane = hypnotiques de choix (action rapidement réversible). L'administration d'un curare en cas d'obstruction des voies aériennes supérieures est un standard chez l'adulte, y compris quand une trachéotomie de sauvetage est décidée — tester la ventilation au masque avant l'injection de curare ne repose sur aucune donnée publiée. Deux curares d'action courte ou rapidement inactivée : succinylcholine 1 mg/kg (poids réel), ou rocuronium 0,6 mg/kg (1,0 mg/kg en ISR), inactivable même en cas de bloc profond par sugammadex 8-16 mg/kg selon la dose de rocuronium et le délai — la dose nécessaire de sugammadex doit être immédiatement disponible en cas d'usage du rocuronium pour une intubation difficile prévue.","style":"note"}]},{"title":"Q5 (1/2) — Critères et stratégie d'extubation","items":[{"t":"section","text":"Question 5 (1/2) — Critères et stratégie d'extubation","color":"navy"},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Prérequis — conditions de sécurité pour extuber</b> : TOF quantitatif &gt; 90 % (l'absence de signal fiable doit faire poser la question de l'antagonisation systématique) • respiration spontanée régulière avec échanges gazeux satisfaisants • conditions hémodynamiques satisfaisantes • patient éveillé (ouverture des yeux/réponse aux ordres/sans agitation), sauf décision d'extuber sous anesthésie • absence de risque immédiat de complication chirurgicale.","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R5.1","style":"cell_b"},{"t":"p","html":"Il faut probablement adapter la prise en charge aux facteurs de risque d'échec d'extubation car la réintubation est source d'une surmorbidité et de surmortalité.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R5.2","style":"cell_b"},{"t":"p","html":"Il faut probablement rechercher des facteurs de risque d'échec avant extubation.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"Facteurs de risque de réintubation postopératoire : curarisation résiduelle, facteurs humains évitables (inexpérience, absence de procédures), facteurs médicaux (réserves cardiaque/respiratoire limitées — BPCO et insuffisance cardiaque dominent), obstruction des voies aériennes, dénutrition. Chirurgies à risque : chirurgie lourde (vasculaire, transplantation, neurochirurgie, thoracique, cardiaque), chirurgie tête et cou, chirurgie longue (&gt; 4h) en position déclive avec remplissage sans monitorage et sonde &gt; 7,5 mm. Enquête prospective : 38 incidents post-extubation (20 en SOP, 2 pendant le transport, 16 en SSPI) — 4 causes principales : laryngospasme, morsure du tube (anoxie/œdème à pression négative), caillot obstructif, œdème cervical après position de Trendelenburg prolongée ; 16/38 en chirurgie ORL. Test de fuite non reconnu fiable en anesthésie (contrairement à la réanimation).","style":"note"}]},{"title":"Q5 (2/2) — Mesures préventives d'extubation","items":[{"t":"section","text":"Question 5 (2/2) — Mesures préventives et prise en charge","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R5.3","style":"cell_b"},{"t":"p","html":"Il faut probablement extuber un patient en suivant une stratégie rigoureuse.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R5.4","style":"cell_b"},{"t":"p","html":"Il faut probablement prendre des mesures préventives en présence de facteurs de risque de difficultés d'extubation.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"<b>Stratégie rigoureuse d'extubation :</b> utiliser un algorithme dédié • extuber en position demi-assise (obèse/SAOS) ou décubitus latéral si doute sur la vacuité gastrique • dégonfler le ballonnet à la seringue • aspirer la bouche en évitant les aspirations endotrachéales • prévenir les morsures de sonde avant l'extubation, y compris pendant le transport • FiO2 = 1 et retrait en pression positive, en fin d'inspiration • oxygéner et contrôler immédiatement la reprise d'une ventilation spontanée de qualité (capnographe) • présence de 2 professionnels de santé, dont un médecin anesthésiste-réanimateur disponible sans délai.<br/><br/><b>Mesures préventives si facteurs de risque :</b> leadership pour dérouler l'algorithme de façon coordonnée • extubation seulement si matériel d'oxygénation/réintubation disponible et 2 personnes présentes • attitude consensuelle avec les opérateurs (item n°9 de la check-list HAS). En cas de risque, options : extubation différée, trachéotomie, ou extubation sur guide échangeur creux (efficace pour les réintubations dans les 10h postopératoires ; échecs 7-14 %, surtout avec les petits diamètres ; ne pas laisser en place &gt; 24h ; oxygénation par jet-ventilation manuelle réservée à l'extrême urgence, risque de barotraumatisme). Information écrite du patient sur les circonstances de la difficulté rencontrée.","style":"note"}]},{"title":"Q6 — Algorithmes : principes & intubation prévue","items":[{"t":"section","text":"Question 6 — Arbres décisionnels et algorithmes","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R6.1","style":"cell_b"},{"t":"p","html":"Il faut s'appuyer sur des arbres décisionnels ou algorithmes pour optimiser la gestion d'un contrôle difficile des voies aériennes.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"Priorité absolue : le maintien de l'oxygénation du patient en toutes circonstances — dénominateur commun et intemporel de tous les algorithmes. Accepter à temps l'échec d'une intubation trachéale (2 tentatives maximum) et l'appel à l'aide (renfort technique et/ou anesthésiste senior) doivent être la règle devant toute situation imprévue d'oxygénation et/ou d'intubation difficiles. Il n'est pas souhaitable de pratiquer une laryngoscopie pour évaluer la difficulté quand celle-ci est prévue/prévisible (profondeur d'anesthésie insuffisante, risque de situation critique).","style":"note"},{"t":"section","text":"Algorithme 1 — Intubation difficile prévue","color":"grey"},{"t":"p","html":"Transcrit intégralement depuis le rendu visuel de la source (pages 565-566, pures images).","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Étape","style":"head_w"},{"t":"p","html":"Décision / actions","style":"head_w"},{"t":"p","html":"Résultat / suite","style":"head_w"}],[{"t":"p","html":"Orientation stratégique","style":"cell"},{"t":"p","html":"Évaluer la difficulté prévisible de la ventilation au masque facial → prévoir le maintien de l'oxygénation (masque laryngé ou masque laryngé pour l'intubation utilisables ? abord trachéal possible ? repérage échographique préalable ?) → choix des techniques d'anesthésie (apnée ou ventilation spontanée ?).","style":"cell"},{"t":"p","html":"—","style":"cell"}],[{"t":"p","html":"Si apnée possible","style":"cell"},{"t":"p","html":"1 critère ID : laryngoscope. ≥ 2 critères ID : vidéolaryngoscope. Dans tous les cas : 2 essais maximum, exposition glottique optimisée, possibilité de long mandrin béquillé.","style":"cell"},{"t":"p","html":"Succès → intubation. Échec → masque laryngé pour l'intubation (± fibroscope) → succès : intubation ± fibroscope / échec : réveil.","style":"cell"}],[{"t":"p","html":"Si ventilation spontanée","style":"cell"},{"t":"p","html":"Aide prévue systématique. Masque laryngé pour l'intubation.","style":"cell"},{"t":"p","html":"Succès → intubation. Échec → fibroscope → succès : intubation / échec : réveil, abord trachéal si réveil impossible.","style":"cell"}]]}]},{"title":"Algorithmes 2-3 — Intubation non prévue & oxygénation","items":[{"t":"section","text":"Algorithme 2 — Intubation difficile non prévue","color":"grey"},{"t":"p","html":"Transcrit depuis le rendu visuel de la source (page 568). Appel à l'aide dans tous les cas + chariot d'intubation difficile + maintien de l'anesthésie + leadership.","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Étape","style":"head_w"},{"t":"p","html":"Décision / actions","style":"head_w"},{"t":"p","html":"Résultat / suite","style":"head_w"}],[{"t":"p","html":"Ventilation au masque facial","style":"cell"},{"t":"p","html":"Évaluer immédiatement l'efficacité de la ventilation.","style":"cell"},{"t":"p","html":"Efficace → 1 critère ID : laryngoscope ; ≥ 2 critères ID : vidéolaryngoscope (2 essais max) → échec → masque laryngé pour l'intubation. Inefficace → masque laryngé pour l'intubation directement.","style":"cell"}],[{"t":"p","html":"Masque laryngé pour l'intubation","style":"cell"},{"t":"p","html":"Évaluer l'efficacité de la ventilation à travers le dispositif.","style":"cell"},{"t":"p","html":"Efficace → Algorithme de l'intubation (Algorithme 1, arbre détaillé page précédente). Inefficace → Algorithme de l'oxygénation (Algorithme 3, ci-dessous).","style":"cell"}]]},{"t":"section","text":"Algorithme 3 — Oxygénation : ventilation au masque inefficace et échec d'intubation","color":"red"},{"t":"p","html":"Transcrit depuis le rendu visuel de la source (page 567). Appel à l'aide dans tous les cas + leadership.","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Étape","style":"head_w"},{"t":"p","html":"Décision / actions","style":"head_w"},{"t":"p","html":"Résultat / suite","style":"head_w"}],[{"t":"p","html":"1re étape","style":"cell"},{"t":"p","html":"Masque laryngé pour l'intubation (DSG).","style":"cell"},{"t":"p","html":"Succès → intubation ou réveil. Échec/contre-indication → O2 transtrachéal.","style":"cell"}],[{"t":"p","html":"2e étape","style":"cell"},{"t":"p","html":"O2 transtrachéal.","style":"cell"},{"t":"p","html":"Succès → réveil ou poursuite (autres techniques d'intubation / cricothyroïdotomie-trachéotomie). Échec → cricothyroïdotomie/trachéotomie directement.","style":"cell"}],[{"t":"p","html":"3e étape (si autres techniques d'intubation tentées)","style":"cell"},{"t":"p","html":"Autres techniques d'intubation.","style":"cell"},{"t":"p","html":"Succès → intubation. Échec → réveil ou cricothyroïdotomie/trachéotomie.","style":"cell"}]]}]},{"title":"Algorithmes 4-5 — Extubation","items":[{"t":"section","text":"Algorithme 4 — Extubation : facteurs de risque","color":"grey"},{"t":"p","html":"Transcrit depuis le rendu visuel de la source (page 562). Point d'entrée : critères d'extubation présents et minimisation du risque d'inhalation (patient éveillé en position assise, décurarisation complète, vidange de l'estomac, stabilité hémodynamique).","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Branche","style":"head_w"},{"t":"p","html":"Facteurs / actions","style":"head_w"},{"t":"p","html":"Suite","style":"head_w"}],[{"t":"p","html":"Chirurgie à risque — facteurs locaux","style":"cell"},{"t":"p","html":"Chirurgie cervico-faciale, œdème cervical, modifications anatomiques des VAS, risque de reprise chirurgicale, position proclive prolongée, intubation traumatique, SAOS.","style":"cell"},{"t":"p","html":"→ Guide échangeur, trachéotomie ou masque laryngé, report de l'extubation, VNI si SAOS.","style":"cell"}],[{"t":"p","html":"Chirurgie à risque — facteurs généraux","style":"cell"},{"t":"p","html":"BPCO, insuffisance cardiaque.","style":"cell"},{"t":"p","html":"→ Oxygénothérapie, oxygène nasal à haut débit, CPAP/VNI, optimisation médicale.","style":"cell"}],[{"t":"p","html":"Les deux branches convergent vers","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Réanimation / soins continus / hospitalisation conventionnelle, avec une durée de surveillance fixée (risque de dégradation retardée).","style":"cell"}],[{"t":"p","html":"Actions parallèles","style":"cell"},{"t":"p","html":"Évaluer les facteurs de risque d'échec locaux et/ou généraux d'extubation.","style":"cell"},{"t":"p","html":"→ Décision d'extuber (leadership +++, prudence si association de facteurs locaux et généraux) → gestion du transport et surveillance adaptée.","style":"cell"}]]},{"t":"section","text":"Algorithme 5 — Extubation : leadership et décision","color":"grey"},{"t":"p","html":"Transcrit depuis le rendu visuel de la source (page 563). Point d'entrée : leadership de la procédure (considérer le risque d'inhalation post-extubation, l'hyper-réactivité bronchique des VAS) → deux professionnels de santé dont un médecin anesthésiste-réanimateur disponible sans délai, matériel d'oxygénation prêt à l'usage → consensus dans l'équipe d'anesthésie, concertation avec l'opérateur.","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Choix","style":"head_w"},{"t":"p","html":"Actions","style":"head_w"},{"t":"p","html":"Suite","style":"head_w"}],[{"t":"p","html":"Choix d'extuber","style":"cell"},{"t":"p","html":"Extubation simple ou sur guide creux ; extubation différée sans sédation en SSPI ou réanimation.","style":"cell"},{"t":"p","html":"→ Maintien de l'oxygénation en position assise, sous oxygène voire sous VNI → fixer un lieu de surveillance adapté au risque.","style":"cell"}],[{"t":"p","html":"Choix de ne pas extuber","style":"cell"},{"t":"p","html":"Maintien de l'anesthésie ; trachéotomie.","style":"cell"},{"t":"p","html":"→ Transmettre par écrit le risque et la conduite à tenir.","style":"cell"}]]}]},{"title":"Synthèse, sources & traçabilité","items":[{"t":"section","text":"Synthèse et messages clés","color":"navy"},{"t":"p","html":"• Préoxygénation systématique (3 min / 8 inspirations profondes), y compris en urgence ; position proclive chez l'obèse ; oxygénation apnéique en complément dans les situations à risque.<br/>• Vidéolaryngoscope en 1re intention si ≥ 2 critères d'intubation difficile et ventilation au masque possible ; en 2e intention (Cormack-Lehane III+) si intubation difficile non prévue ; pas de recommandation systématique en cas de risque de régurgitation.<br/>• Anesthésie profonde avec agents rapidement réversibles ; curare d'action courte (succinylcholine 1 mg/kg, ou rocuronium 0,6-1,0 mg/kg + sugammadex disponible) si intubation difficile prévue, sous monitorage systématique.<br/>• TOF &gt; 90 % avant toute extubation ; rechercher activement les facteurs de risque locaux (chirurgie cervico-faciale, œdème, SAOS) et généraux (BPCO, insuffisance cardiaque) ; leadership et présence de 2 professionnels dont un anesthésiste-réanimateur disponible sans délai.<br/>• S'appuyer systématiquement sur les algorithmes — 2 tentatives maximum avant d'accepter l'échec et d'appeler à l'aide ; priorité absolue : maintenir l'oxygénation en toutes circonstances.<br/>• Connaître la filière de secours en cas d'échec combiné ventilation/intubation : masque laryngé pour l'intubation → O2 transtrachéal → cricothyroïdotomie/trachéotomie.","style":"body"},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Intubation difficile et extubation en anesthésie chez l'adulte » (actualisation de la Conférence d'Experts Intubation difficile 2006) — Recommandations Formalisées d'Experts SFAR, Anesth Reanim. 2017;3:552-571. Comité de 13 experts, coordination O. Langeron, K. Nouette-Gaulain. Texte validé par le CA SFAR le 29/06/2017.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> GRADE®, tags « (Grade X+/-) Accord FORT » (ou « Accord faible » pour R2.3) imprimés littéralement après chaque recommandation — cités ici tels quels.","style":"source"},{"t":"p","html":"<b>Couverture :</b> 13 recommandations (R1.1-R1.3, R2.1-R2.3, R4.1-R4.2, R5.1-R5.4, R6.1 — pas de R3, la question 3 a abouti à « pas de recommandation ») et 2 questions « pas de recommandation » reproduites intégralement, ainsi que les 6 algorithmes-diagrammes (pages 562-563 et 565-568 de la source, pures images sans texte extractible, vérifiés visuellement et retranscrits intégralement sous forme de tableaux structurés).","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Il reprend l'intégralité des recommandations de la RFE mais ne remplace pas le texte intégral et n'est ni édité ni validé par la SFAR. En cas de doute, se référer au texte intégral, aux recommandations ultérieures et/ou à un avis spécialisé.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/actualisation-de-recommandations-intubation-difficile-et-extubation-en-anesthesie-chez-ladulte/';

