update public.documents set
  fiche_key = 'nvpo',
  card_json = $mgjson${"badge":"GRADE","title":"NVPO — Nausées et vomissements postopératoires","short":"Facteurs de risque et scores prédictifs (Apfel, Koivuranta), sétrons, dexaméthasone, dropéridol, antagonistes NK1 (aprépitant), traitements alternatifs, stratégies de prévention multimodale et algorithme décisionnel par niveau de risque, particularités pédiatriques et en chirurgie ambulatoire — conférence d'experts, ~60 recommandations.","society":"SFAR — Conférence d'experts 2007/2008","version":"2008","validated":"Publié Ann Fr Anesth Réanim 2008;27:866-878","methodology":"GRADE","pages":7,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"nvpo","sections":[{"title":"Q1-4 — Introduction, facteurs de risque, sétrons, stéroïdes","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> prise en charge des nausées et vomissements postopératoires (NVPO) chez l'adulte et l'enfant — prévention (identification du risque, prophylaxie pharmacologique et non pharmacologique) et traitement curatif. Conférence d'experts SFAR (texte court), 10 « Questions » (chapitres), publiée 2008. <b>Convention de cotation propre à ce document</b> : G1+ = il faut faire ; G2+ = il faut probablement faire ; G1- = il ne faut pas faire ; G2- = il ne faut probablement pas faire — <b>pas de catégorie « avis d'experts »</b> : lorsque les données sont insuffisantes, le panel déclare explicitement ne pas être en mesure de formuler de recommandation (4 occurrences, signalées explicitement dans cette fiche).<br/><br/><b>Q1 — Les NVPO, un problème important ?</b> Environ 30 % des patients opérés sont sujets à des NVPO, jusqu'à 80 % dans certains groupes à risque. Facteurs associés : sexe féminin, enfants/adolescents, antécédents de NVPO/mal des transports (incidence augmentée) ; tabagisme, alcoolisme (incidence réduite) ; anesthésie générale par inhalation halogénée (vs AIVOC propofol) ; opiacés périopératoires ; néostigmine &gt; 2,5 mg ; durée d'anesthésie/chirurgie prolongée. Conséquences : inconfort, douleur postopératoire majorée, pneumopathie d'inhalation, troubles hydroélectrolytiques, désunion de sutures, retard de mobilisation, surcoûts (SSPI, réadmissions).","style":"body"}},{"t":"section","text":"Légende des grades (convention propre à ce document)","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"p","html":"Il faut faire","style":"badge_head"},{"t":"chip","label":"2+"},{"t":"p","html":"Il faut probablement faire","style":"badge_head"},{"t":"chip","label":"1-"},{"t":"p","html":"Il ne faut pas faire","style":"badge_head"},{"t":"chip","label":"2-"},{"t":"p","html":"Il ne faut probablement pas faire","style":"badge_head"}]]},{"t":"section","text":"Q2 — Facteurs de risque des NVPO chez l'adulte","color":"navy"},{"t":"p","html":"Facteurs bien établis : sexe féminin (OR≈3, facteur indépendant le plus important) ; non-fumeur (OR≈2) ; antécédents de NVPO/mal des transports ; anesthésie par inhalation halogénée (double le risque vs AIVOC) ; protoxyde d'azote (facteur indépendant, influence moindre que les halogénés) ; morphiniques postopératoires (double le risque). Facteurs possibles : ASA I-II, migraine, anesthésie locorégionale (risque moindre), hydratation pré/peropératoire optimale (pourrait réduire le risque), sonde nasogastrique (aggravant), néostigmine aux doses habituelles (≤2,5 mg, sans sur-risque probable) ; type de chirurgie non clairement démontré comme facteur (données plus controversées pour la chirurgie gynécologique/laparoscopique). Facteurs réfutés : obésité, cycle menstruel, rémifentanil, FiO2 élevée (80 %).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Scores de\nprédiction","style":"cell_b"},{"t":"p","html":"Utiliser des scores de prédiction simplifiés pour estimer le risque de NVPO d'un patient donné.","style":"cell"},{"t":"chip","label":"1+"}]]},[{"t":"p","html":"<b>TABLEAU 1</b> — Scores simplifiés de prédiction des NVPO","style":"h2"},null,{"t":"table","rows":[[{"t":"p","html":"Facteur de risque","style":"head_w"},{"t":"p","html":"Apfel et al.","style":"head_w"},{"t":"p","html":"Koivuranta et al.","style":"head_w"}],[{"t":"p","html":"Sexe féminin","style":"cell"},{"t":"p","html":"+","style":"cell"},{"t":"p","html":"+","style":"cell"}],[{"t":"p","html":"Antécédent de NVPO","style":"cell"},{"t":"p","html":"+","style":"cell"},{"t":"p","html":"+","style":"cell"}],[{"t":"p","html":"Mal des transports","style":"cell"},{"t":"p","html":"","style":"cell"},{"t":"p","html":"+","style":"cell"}],[{"t":"p","html":"Non-fumeur","style":"cell"},{"t":"p","html":"+","style":"cell"},{"t":"p","html":"+","style":"cell"}],[{"t":"p","html":"Morphiniques postopératoires","style":"cell"},{"t":"p","html":"+","style":"cell"},{"t":"p","html":"","style":"cell"}],[{"t":"p","html":"Durée d'anesthésie > 60 min","style":"cell"},{"t":"p","html":"","style":"cell"},{"t":"p","html":"+","style":"cell"}],[{"t":"p","html":"Pouvoir discriminant (AUC ROC)","style":"cell"},{"t":"p","html":"0,68-0,71","style":"cell"},{"t":"p","html":"0,70-0,71","style":"cell"}]]},null,{"t":"p","html":"<i>Risque de NVPO (%) selon le nombre de facteurs présents — Apfel : 0→&lt;10 %, 1→21 %, 2→39 %, 3→61 %, 4→79 % ; Koivuranta : 0→17 %, 1→18 %, 2→42 %, 3→54 %, 4→74 %, 5→87 %. Score Apfel = 4 critères ; score Koivuranta = 5 critères.</i>","style":"note"}],{"t":"section","text":"Q3 — Les antagonistes du récepteur 5HT3 (AR-5HT3, « sétrons »)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Prophylaxie\nsystématique","style":"cell_b"},{"t":"p","html":"L'administration prophylactique systématique d'AR-5HT3 n'est pas recommandée.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Prophylaxie\nciblée","style":"cell_b"},{"t":"p","html":"L'administration prophylactique d'un AR-5HT3 est recommandée en fin d'intervention chez les patients à risque.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Approche\nmultimodale","style":"cell_b"},{"t":"p","html":"L'usage d'AR-5HT3 est recommandé dans le cadre de l'approche multimodale des NVPO.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Traitement\ncuratif","style":"cell_b"},{"t":"p","html":"L'usage d'AR-5HT3 est recommandé dans le traitement curatif de première intention des NVPO.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"Efficaces quels que soient type d'intervention/anesthésie/patient ; pas de supériorité démontrée sur la dexaméthasone ou le dropéridol. Doses prophylaxie : ondansétron 4 mg, granisétron 0,3 mg, dolasétron 12,5 mg, tropisétron 2 mg. Doses traitement : ondansétron 4 mg (efficace dès 1 mg), dolasétron 12,5 mg, granisétron 0,1 mg, tropisétron 0,5 mg. Ne pas répéter le même antiémétique avant 6h ; changer de classe en cas d'échec. Effets secondaires modérés (céphalées 10-20 %, constipation 5-10 %) ; allongement du QT (effet de classe, sans conséquence clinique démontrée chez l'adulte).","style":"note"},[{"t":"p","html":"<b>TABLEAU 2</b> — Pharmacocinétique et posologies des principaux AR-5HT3 (adulte)","style":"h2"},null,{"t":"table","rows":[[{"t":"p","html":"AR-5HT3","style":"head_w"},{"t":"p","html":"Demi-vie (h)","style":"head_w"},{"t":"p","html":"Métabolisme CYP450","style":"head_w"},{"t":"p","html":"Posologie NVPO (mg)","style":"head_w"}],[{"t":"p","html":"Ondansétron","style":"cell"},{"t":"p","html":"3","style":"cell"},{"t":"p","html":"2D6 + autres","style":"cell"},{"t":"p","html":"4,0","style":"cell"}],[{"t":"p","html":"Granisétron","style":"cell"},{"t":"p","html":"9-11","style":"cell"},{"t":"p","html":"3A","style":"cell"},{"t":"p","html":"0,3-1,0","style":"cell"}],[{"t":"p","html":"Tropisétron","style":"cell"},{"t":"p","html":"7,3","style":"cell"},{"t":"p","html":"2D6","style":"cell"},{"t":"p","html":"5,0","style":"cell"}],[{"t":"p","html":"Dolasétron","style":"cell"},{"t":"p","html":"7-9","style":"cell"},{"t":"p","html":"2D6","style":"cell"},{"t":"p","html":"12,5","style":"cell"}]]}],{"t":"section","text":"Q4 — Corticostéroïdes (dexaméthasone) et dropéridol","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Dexa —\nprophylaxie","style":"cell_b"},{"t":"p","html":"La dexaméthasone est recommandée dans la prévention des NVPO des patients à risque ; chez les patients à risque élevé, l'association à un AR-5HT3 et/ou au dropéridol est recommandée.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Dexa — ACP","style":"cell_b"},{"t":"p","html":"Dans l'état actuel des connaissances, la dexaméthasone administrée en peropératoire n'est pas suffisante pour se substituer à l'ajout de dropéridol dans la prévention des NV induits par la morphine en ACP.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Dexa —\ntraitement","style":"cell_b"},{"t":"p","html":"La dexaméthasone ne doit pas être utilisée seule dans le traitement curatif de NVPO.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Dexa — dose","style":"cell_b"},{"t":"p","html":"La dose intraveineuse recommandée de dexaméthasone est comprise entre 4 et 8 mg, administrée à l'induction de l'anesthésie.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Dexa —\nitération","style":"cell_b"},{"t":"p","html":"L'administration répétée de dexaméthasone n'a pas été évaluée dans cette indication et ne peut de ce fait pas être recommandée.","style":"cell"},{"t":"chip","label":"2-"}]]},{"t":"p","html":"Dexaméthasone : efficacité similaire aux AR-5HT3 et au dropéridol, supérieure au métoclopramide ; simple, bien tolérée, peu coûteuse en dose unique. Hyperglycémie possible (diabétiques et non diabétiques) ; données rassurantes sur le risque infectieux.","style":"note"}]},{"title":"Q4-6 — Dropéridol, NK1, autres traitements","items":[{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Dropéridol —\nprophylaxie","style":"cell_b"},{"t":"p","html":"Le dropéridol est recommandé dans la prophylaxie des NVPO chez les patients à risque.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Dropéridol —\ntraitement","style":"cell_b"},{"t":"p","html":"Le dropéridol est recommandé pour le traitement des NVPO.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Dropéridol —\nhaut risque","style":"cell_b"},{"t":"p","html":"Chez les patients à haut risque, l'association du dropéridol à un AR-5HT3 et/ou à la dexaméthasone peut être recommandée ; le dropéridol est recommandé dans la prévention des NV induits par la morphine en ACP.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Dropéridol —\nQT long","style":"cell_b"},{"t":"p","html":"Le dropéridol devrait être évité dans les syndromes du QT long congénitaux ou acquis.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Dropéridol —\ndose/itération","style":"cell_b"},{"t":"p","html":"Il est recommandé d'utiliser la dose minimale efficace de dropéridol (0,625 à 1,25 mg IV) ; en cas de nécessité, il pourrait être réadministré au bout de 6 heures.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"Posologie en ACP : dropéridol 0,015 à 0,050 mg par mg de morphine. Le moment optimal d'administration du dropéridol n'a pas pu être déterminé par le panel d'experts (pas de recommandation sur ce point précis). Bien toléré globalement ; peut majorer la sédation et les symptômes extrapyramidaux (surtout en ACP) ; allonge le QT à faible dose (données épidémiologiques rassurantes sur le risque rythmique).","style":"note"},{"t":"section","text":"Q5 — Antagonistes du récepteur NK1 (AR-NK1)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Aprépitant","style":"cell_b"},{"t":"p","html":"L'aprépitant (40 mg per os, 1 à 3 heures avant l'intervention) peut être utilisé pour la prévention des NVPO.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Enfant/\nadolescent","style":"cell_b"},{"t":"p","html":"La tolérance et l'efficacité n'ayant pas été établies chez l'enfant et l'adolescent, l'utilisation chez les patients de moins de 18 ans n'est pas recommandée.","style":"cell"},{"t":"chip","label":"1-"}]]},{"t":"p","html":"Seul AR-NK1 approuvé en France en 2008 pour la prévention des NVPO. Supérieur à l'ondansétron 4 mg IV sur les vomissements et les nausées postopératoires. Forme injectable non disponible en France à la date de publication.","style":"note"},{"t":"section","text":"Q6 — Autres traitements (hors sétrons, dropéridol, stéroïdes, AR-NK1)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Acupuncture","style":"cell_b"},{"t":"p","html":"Chez les patients à risque opposés à une prophylaxie pharmacologique recherchant des alternatives, une technique par stimulation de points d'acupuncture (point P6) peut être considérée.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Relaxation/\nhypnose","style":"cell_b"},{"t":"p","html":"Ni la relaxation, ni l'hypnose ne peuvent être recommandées pour la prise en charge des NVPO.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Cannabinoïdes","style":"cell_b"},{"t":"p","html":"Les cannabinoïdes ne doivent pas être utilisés pour le contrôle des NVPO.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Aromathérapie","style":"cell_b"},{"t":"p","html":"L'aromathérapie ne peut être recommandée pour le contrôle des NVPO.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Oxygène —\npéropératoire","style":"cell_b"},{"t":"p","html":"La supplémentation en oxygène ne peut être recommandée en tant que mesure de contrôle des NVPO réalisée en peropératoire.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Oxygène —\npostopératoire","style":"cell_b"},{"t":"p","html":"La supplémentation en oxygène ne peut être recommandée en tant que mesure de contrôle des NVPO réalisée en postopératoire.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Soluté de\nremplissage","style":"cell_b"},{"t":"p","html":"La période de jeûne doit être compensée par l'administration d'une quantité adéquate de fluide.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Métoclo-\npramide","style":"cell_b"},{"t":"p","html":"En raison d'une activité antiémétique modeste aux doses faibles et du risque accru d'effets indésirables aux doses élevées, le métoclopramide ne peut être recommandé en antiémétique de première ligne.","style":"cell"},{"t":"chip","label":"1-"}]]},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Halopéridol —\nutilisation","style":"cell_b"},{"t":"p","html":"L'halopéridol à petites doses peut être utilisé comme antiémétique pour le contrôle des NVPO.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Halopéridol —\n1ère ligne","style":"cell_b"},{"t":"p","html":"L'halopéridol ne peut pas être considéré comme un médicament de première ligne dans cette indication.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Scopolamine\ntransdermique","style":"cell_b"},{"t":"p","html":"En l'absence de contre-indication, la scopolamine transdermique peut être considérée en tant qu'antiémétique pour la prévention des NVPO.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"AR-H1\n(prométhazine…)","style":"cell_b"},{"t":"p","html":"Les anesthésistes peuvent envisager le recours à la prométhazine ou au dimenhydrinate lorsque les autres antiémétiques dont l'effet est mieux établi ne sont pas disponibles.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"AR-H2","style":"cell_b"},{"t":"p","html":"Pour la prévention ou le traitement des NVPO, les AR-H2 ne peuvent être recommandés.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Gingembre","style":"cell_b"},{"t":"p","html":"Du fait de l'absence de données validées suffisantes, le groupe ne peut recommander le gingembre pour le contrôle des NVPO.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Midazolam","style":"cell_b"},{"t":"p","html":"Les anesthésistes peuvent considérer le midazolam en tant qu'alternative lorsque d'autres antiémétiques dont l'effet est mieux établi ne sont pas disponibles.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Propofol à\npetites doses","style":"cell_b"},{"t":"p","html":"Pour le contrôle des NVPO établis résistant à d'autres traitements, on peut envisager la perfusion de propofol à petites doses subanesthésiques, sous surveillance par du personnel médical qualifié dans une structure adaptée.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Pas de recommandation possible (données insuffisantes)</b> — le panel déclare explicitement, dans les mêmes termes pour chacune des 4 substances suivantes, « ne pas être en mesure de proposer de recommandation » : <b>dixyrazine</b> (relation dose-effet inconnue, effets secondaires mal compris) ; <b>éphédrine</b> (peu d'essais, relation dose-effet non établie) ; <b>clonidine</b> (très peu d'essais randomisés) ; <b>gabapentine</b> (effet antiémétique propre non distingué d'un effet d'épargne opioïde).","style":"body_sm"}}]},{"title":"Q7-9 — Stratégies, algorithme, situations locales, pédiatrie","items":[{"t":"section","text":"Q7 — Stratégies de prise en charge des NVPO","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Monothérapie","style":"cell_b"},{"t":"p","html":"La prévention antiémétique par un seul agent n'est recommandée que chez des patients à faible risque de NVPO, et seulement si un traitement de secours rapidement efficace peut être assuré sans délai.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Combinaison","style":"cell_b"},{"t":"p","html":"Une combinaison de deux agents antiémétiques au moins doit être utilisée pour la prévention des NVPO chez les patients présentant des risques modérés ou élevés.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Multimodal\nhaut risque","style":"cell_b"},{"t":"p","html":"Les patients à haut risque doivent bénéficier d'une approche multimodale de prévention des NVPO.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Secours —\n1ère intention","style":"cell_b"},{"t":"p","html":"En l'absence de prophylaxie, les AR-5HT3 sont recommandés pour le traitement de première intention des NVPO.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Secours —\néchec prophylaxie","style":"cell_b"},{"t":"p","html":"Si une prophylaxie a échoué dans les six heures suivant son administration, il est recommandé d'utiliser pour le traitement de secours un antiémétique d'une autre classe que celle qui a été choisie pour la prophylaxie ; une association d'antiémétiques est raisonnable pour assurer un traitement curatif et une prophylaxie secondaire efficaces.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"<b>Conclusion (non graduée) :</b> les algorithmes améliorent la prise en charge antiémétique. Il n'existe cependant pas de preuve de la supériorité d'un algorithme par rapport aux autres — le facteur le plus important est le nombre d'antiémétiques administrés, pas l'algorithme précis suivi.","style":"note"},[{"t":"p","html":"<b>FIGURE 1</b> — Exemple d'algorithme de prise en charge des NVPO","style":"h2"},null,{"t":"p","html":"<i>Redessin en tableau de l'algorithme de la page 876 du document source (vérifié visuellement à 200dpi) — combine le score de risque simplifié (Tableau 1, 0 à 4 facteurs), les circonstances/souhaits du patient, et 3 filières prophylaxie/secours par niveau de risque.</i>","style":"note"},null,{"t":"table","rows":[[{"t":"p","html":"Niveau de risque","style":"head_w"},{"t":"p","html":"Prophylaxie","style":"head_w"},{"t":"p","html":"Traitement de secours","style":"head_w"}],[{"t":"p","html":"Faible\n(0-1 facteur)","style":"cell"},{"t":"p","html":"Expectative armée (pas de prophylaxie systématique, traitement de secours prêt) — la monothérapie prophylactique reste une option à ce niveau de risque si un traitement de secours rapide est assuré (cf. Q7)","style":"cell"},{"t":"p","html":"1) AR-5HT3 ; 2) autre antiémétique validé ; 3) envisager la combinaison d'interventions","style":"cell"}],[{"t":"p","html":"Moyen\n(≈2 facteurs)","style":"cell"},{"t":"p","html":"Dexaméthasone 4 mg + un autre antiémétique","style":"cell"},{"t":"p","html":"1) antiémétique(s) de classe(s) différente(s) ; 2) combinaison d'interventions","style":"cell"}],[{"t":"p","html":"Élevé\n(3-4 facteurs)","style":"cell"},{"t":"p","html":"AG intraveineuse + dexaméthasone 4 mg + un autre antiémétique (si possible, réduire le risque de base : ALR, éviter halogénés peropératoires et morphiniques postopératoires)","style":"cell"},{"t":"p","html":"1) antiémétique(s) de classe(s) différente(s) ; 2) combinaison d'interventions","style":"cell"}]]}],{"t":"section","text":"Q8 — Intégration des situations locales ou particulières","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Algorithme","style":"cell_b"},{"t":"p","html":"Il est recommandé d'utiliser un algorithme pour la prise en charge des NVPO, et d'adapter cette prise en charge aux situations locales ou particulières.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Programme\nqualité","style":"cell_b"},{"t":"p","html":"Cette démarche peut s'inscrire dans le cadre général d'un programme qualité institutionnel.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Facteurs\nsuppl.","style":"cell_b"},{"t":"p","html":"Au-delà des facteurs de risque reconnus, il est recommandé de prendre en compte les situations où les vomissements entraînent un risque particulier pour le patient, de considérer les contraintes locales périopératoires, et de tenir compte des désirs exprimés par le patient.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"section","text":"Q9 — Particularités en chirurgie pédiatrique","color":"navy"},{"t":"p","html":"Incidence des VPO ≈ 30 % tous âges/chirurgies confondus, jusqu'à 80 % pour strabisme, amygdalectomie, hernie inguinale, neurochirurgie. Facteur âge : faible avant 3 ans, augmente ensuite ; sexe : jeunes filles plus affectées après la puberté ; antécédent personnel/familial de VPO/NVPO/mal des transports.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Dépistage","style":"cell_b"},{"t":"p","html":"L'identification des facteurs de risque est souhaitable pour établir une stratégie de prise en charge préventive des VPO de l'enfant.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Faible risque","style":"cell_b"},{"t":"p","html":"Chez les enfants à faible risque, l'administration prophylactique d'antiémétique n'est pas indiquée.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Risque de base","style":"cell_b"},{"t":"p","html":"Il est recommandé de réduire autant que possible le risque de base, en proposant une technique anesthésique la moins émétisante possible.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Risque modéré/\nélevé","style":"cell_b"},{"t":"p","html":"Il est recommandé d'utiliser une stratégie préventive privilégiant les associations d'antiémétiques, supérieures aux monothérapies, en tenant compte de l'efficacité, des effets secondaires et du coût.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"1ère intention","style":"cell_b"},{"t":"p","html":"L'association thérapeutique préconisée en première intention combine un AR-5HT3 à la dexaméthasone.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Traitement\nétabli","style":"cell_b"},{"t":"p","html":"Le traitement des NVPO établis ou de leur récidive est extrapolé de celui de l'adulte.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Échec\nprophylaxie","style":"cell_b"},{"t":"p","html":"En cas d'échec d'une prophylaxie, il est recommandé d'utiliser une autre classe antiémétique que celle déjà mise en œuvre.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Réadmin.\nantiémétique","style":"cell_b"},{"t":"p","html":"Il est éventuellement possible de réadministrer le même antiémétique après une durée de six heures.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Réadmin.\ndexaméthasone","style":"cell_b"},{"t":"p","html":"Il est recommandé de ne pas réadministrer la dexaméthasone.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Dropéridol —\nusage restreint","style":"cell_b"},{"t":"p","html":"Il est recommandé de n'utiliser le dropéridol qu'en cas d'échec des autres classes et seulement si le patient est hospitalisé.","style":"cell"},{"t":"chip","label":"2+"}]]}]},{"title":"Q9-10 — Pédiatrie (suite), ambulatoire, traçabilité","items":[[{"t":"p","html":"<b>TABLEAU 3</b> — Facteurs de risque de NVPO chez l'enfant","style":"h2"},null,{"t":"table","rows":[[{"t":"p","html":"Facteur de risque","style":"head_w"}],[{"t":"p","html":"Âge supérieur à 3-4 ans","style":"cell"}],[{"t":"p","html":"Antécédent de NVPO/mal des transports, personnel ou familial","style":"cell"}],[{"t":"p","html":"Durée de chirurgie supérieure à 30-45 min","style":"cell"}],[{"t":"p","html":"Chirurgie du strabisme","style":"cell"}]]}],[{"t":"p","html":"<b>TABLEAU 4</b> — Antiémétiques en pédiatrie : posologies en monothérapie","style":"h2"},null,{"t":"table","rows":[[{"t":"p","html":"Antiémétique","style":"head_w"},{"t":"p","html":"Posologie (IV, mg/kg)","style":"head_w"},{"t":"p","html":"Dose maximale (mg)","style":"head_w"}],[{"t":"p","html":"Dropéridol","style":"cell"},{"t":"p","html":"50 à 75 µg/kg","style":"cell"},{"t":"p","html":"1,25","style":"cell"}],[{"t":"p","html":"Dexaméthasone","style":"cell"},{"t":"p","html":"150 µg/kg","style":"cell"},{"t":"p","html":"5,00","style":"cell"}],[{"t":"p","html":"Ondansétron","style":"cell"},{"t":"p","html":"50 à 100 µg/kg","style":"cell"},{"t":"p","html":"4,00","style":"cell"}],[{"t":"p","html":"Dolasétron","style":"cell"},{"t":"p","html":"350 µg/kg","style":"cell"},{"t":"p","html":"12,50","style":"cell"}]]},null,{"t":"p","html":"<i>D'après Gan TJ, et al. Anesth Analg 2003;97:62-71. Unité de posologie confirmée µg/kg par vérification visuelle de la page source (l'extraction automatique du texte supprime le glyphe µ — bug d'extraction déjà rencontré ailleurs dans ce corpus).</i>","style":"note"}],{"t":"section","text":"Q10 — Particularités en chirurgie ambulatoire","color":"navy"},{"t":"p","html":"Les NVPO prolongent le séjour, retardent le retour à domicile, augmentent le risque d'admission imprévue et diminuent la satisfaction du patient. Aucune stratégie spécifique à la chirurgie ambulatoire ne réduit la survenue des NVPO au-delà de la réduction du risque de base (analgésie multimodale, hydratation IV, anesthésie locorégionale).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Haut risque\nambulatoire","style":"cell_b"},{"t":"p","html":"Il est recommandé d'adopter une stratégie antiémétique prophylactique multimodale chez les patients ambulatoires identifiés à haut risque de NVPO.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Après la\nsortie","style":"cell_b"},{"t":"p","html":"Le traitement des NVPO survenant après la sortie repose sur la prescription d'antiémétiques validés en prophylaxie, en changeant de classe et sous une forme galénique adaptée.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Prise en charge des nausées et vomissements postopératoires » — Conférence d'experts, texte court, SFAR. Coordonnateur : P. Diemunsch (Strasbourg). 10 chapitres rédigés par un panel international d'auteurs (France, Belgique, Suisse, Allemagne, Finlande, États-Unis).","style":"source"},{"t":"p","html":"<b>Publication :</b> Ann Fr Anesth Réanim 2008;27:866-878, disponible en ligne le 25/10/2008. DOI 10.1016/j.annfar.2008.09.004.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> système GRADE, convention de cotation propre au document (G1+/G2+/G1-/G2-, pondérée par la balance bénéfices/risques ; pas de catégorie « avis d'experts » — items sans recommandation possible déclarés explicitement comme tels).","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/prise-en-charge-des-nausees-et-vomissements-postoperatoires/","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Il reprend l'intégralité des recommandations graduées, des 4 items « pas de recommandation » et des 4 tableaux + 1 figure de la conférence d'experts, mais ne remplace pas le texte intégral et n'est ni édité ni validé par la SFAR. En cas de doute, se référer au texte intégral et/ou à un avis spécialisé.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/prise-en-charge-des-nausees-et-vomissements-postoperatoires/';

insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/wp-content/uploads/2018/03/2_Gestion-des-agents-antiplaquettaires-pour-une-procedure-invasive-programmee.pdf' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade', 'medecine_intensive_reanimation')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2018/03/2_Gestion-des-agents-antiplaquettaires-pour-une-procedure-invasive-programmee.pdf' and s.acronym in ('GIHP', 'GFHT', 'SFAR')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2018/03/2_Gestion-des-agents-antiplaquettaires-pour-une-procedure-invasive-programmee.pdf' and d.society_id is null and s.acronym = 'GIHP';
update public.documents set
  fiche_key = 'aap_programmee',
  card_json = $mgjson${"badge":"PROPOSITIONS","title":"Agents antiplaquettaires — procédure invasive programmée","short":"Classification du risque hémorragique de la procédure (faible/intermédiaire/élevé) et du risque thrombotique du patient, délais d'arrêt par molécule (J-3 aspirine, J-5 clopidogrel/ticagrélor, J-7 prasugrel), gestion selon l'indication, bithérapie et stent coronaire, anesthésie locorégionale rachidienne et blocs périphériques, chirurgie de pontage aortocoronaire — complète la fiche dédiée à la procédure non programmée/l'hémorragie.","society":"GIHP & GFHT, en collaboration avec la SFAR — Propositions 2018","version":"2018","validated":"Publié Anesth Reanim 2018 (ANREA-314), doi 10.1016/j.anrea.2018.01.002","methodology":"Propositions (vote GIHP/GFHT, n=37 — non GRADE)","pages":7,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"aap_programmee","sections":[{"title":"Introduction, méthodologie & légende","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> gestion péri-procédurale d'un traitement antiplaquettaire (AAP) oral au long cours — aspirine, clopidogrel, prasugrel, ticagrélor — chez un patient devant bénéficier d'une <b>procédure invasive programmée</b> (élective). Complète la fiche déjà construite dans ce site pour la procédure invasive <b>non programmée / l'hémorragie</b> (document distinct, même groupe de travail).<br/><br/><b>Méthodologie — distincte de GRADE :</b> ce document ne comporte pas de niveaux GRADE 1+/1-/2+/2-. Les propositions ont été rédigées par cinq groupes de travail du Groupe d'intérêt en hémostase périopératoire (GIHP) et du Groupe français d'études sur l'hémostase et la thrombose (GFHT), en collaboration avec la SFAR, puis soumises à un vote (n = 37) : une proposition est retenue si au moins 50 % des votants expriment leur accord (et moins de 20 % une opinion contraire) ; l'accord est qualifié de <b>« fort »</b> si le seuil atteint 70 %. En l'absence d'accord, les propositions étaient reformulées puis resoumises au vote.","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Divergence source-interne (disclosure) :</b> le Résumé de la source affirme : « Ces propositions ont été discutées et validées par vote ; <i>toutes sauf une</i> ont fait l'objet d'un accord fort. » Une vérification directe, proposition par proposition, de l'intégralité du corps du texte (y compris les propositions associées à la Figure 1 et au Tableau I, vérifiées visuellement sur le rendu de page) montre que <b>toutes les propositions retrouvées portent explicitement le tag « (accord fort) »</b>, sans qu'aucune ne porte un tag différent ou plus faible nulle part dans le document. L'exception annoncée par le résumé n'est donc <b>pas identifiable</b> dans le corps du texte source — elle n'est pas devinée ici ; les deux constats (l'affirmation du résumé et l'absence de toute proposition tagée autrement que « accord fort » dans le corps du texte) sont disclosés tels quels, sans résolution silencieuse.","style":"body_sm"}},{"t":"section","text":"Légende (convention de ce document)","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"Fort"},{"t":"p","html":"Proposition retenue par vote du groupe de travail GIHP/GFHT (n = 37) avec « accord fort » (≥ 70 % des voix). Seul tag de force imprimé par la source à côté de chaque proposition individuelle du corps du texte (voir encadré ci-dessous).","style":"badge_head"}]]}]},{"title":"Classification du risque hémorragique de la procédure","items":[[{"t":"section","text":"Classification du risque hémorragique de la procédure","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"Principe","style":"cell_b"},{"t":"p","html":"Il est proposé de diviser le risque hémorragique associé à la procédure invasive en risque élevé, intermédiaire et faible.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Risque élevé","style":"cell_b"},{"t":"p","html":"Les procédures à risque hémorragique élevé sont définies comme non réalisables sous AAP, même sous aspirine en monothérapie. Ce sont celles pour lesquelles le risque hémorragique sous aspirine est soit inconnu mais considéré comme potentiellement préoccupant, soit inacceptable ou jugé comme tel (risque létal ou fonctionnel). Elles sont peu fréquentes et incluent, par exemple, certains actes d'urologie lorsque des techniques alternatives ne peuvent pas être utilisées, de nombreux actes de neurochirurgie intracrânienne, les chirurgies avec des délabrements importants ou de grandes dissections, certains actes de chirurgie hépatique ou thoracique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Risque intermédiaire","style":"cell_b"},{"t":"p","html":"Les procédures à risque hémorragique intermédiaire sont définies comme réalisables sous aspirine seule. Il s'agit de la majorité des procédures invasives.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Risque faible","style":"cell_b"},{"t":"p","html":"Les procédures à faible risque hémorragique sont définies comme réalisables sous bithérapie antiplaquettaire. Elles incluent, par exemple, la chirurgie de la cataracte, certains actes de chirurgie buccodentaire, certains actes d'urologie telle l'uréthrocystoscopie, certains actes de chirurgie vasculaire, certaines bronchoscopies, certains actes d'endoscopie digestive, incluant par exemple, toutes les endoscopies diagnostiques avec ou sans biopsies, les cholangio-pancréatographies rétrogrades endoscopiques sans sphinctérotomie, les polypectomies coliques &lt; 1 cm. Toutefois, l'expérience de ces procédures avec le ticagrélor ou le prasugrel est limitée. De plus, l'administration associée d'autres médicaments interférant avec l'hémostase, ou l'existence d'une comorbidité augmentant le risque hémorragique, peuvent conduire à choisir l'interruption de l'anti-P2Y12.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Absence de consensus","style":"cell_b"},{"t":"p","html":"Lorsqu'il n'existe pas de consensus ou de référentiel pour classer un acte invasif dans une de ces catégories, il est proposé qu'une équipe référente (opérateur, anesthésiste, cardiologue, pneumologue, médecin vasculaire, hémostasien…) dans l'établissement de santé définisse une attitude de prise en charge, au cas par cas, ou pour un profil de patient ou de geste. Ces décisions sont notifiées dans le dossier du patient ou dans les procédures de l'établissement.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Endoscopies digestives","style":"cell_b"},{"t":"p","html":"Concernant les endoscopies digestives, il est proposé que des stratégies de gestion des AAP soient définies dans chaque centre en fonction du profil des patients pris en charge et donc du geste invasif pouvant être potentiellement réalisé pendant l'endoscopie. Ainsi, si la probabilité d'un geste nécessitant une interruption des AAP pour un profil de patient déterminé est jugée élevée, c'est cette stratégie qui est adoptée (ex. : sphinctérotomie, gastrostomie…). En revanche, si la probabilité est faible, c'est la poursuite des AAP qui est privilégiée (ex. : maladies inflammatoires chroniques de l'intestin, dyspepsie…). Quand la probabilité et la nature des lésions à réséquer n'est pas connue a priori, chaque centre détermine son attitude (ex. : recherche de polypes).","style":"cell"},{"t":"chip","label":"Fort"}]]}]]},{"title":"Figure 1 — synthèse des propositions & Tableau I","items":[{"t":"section","text":"Figure 1 — Synthèse des propositions","color":"navy"},{"t":"p","html":"<i>Tableau-matrice reproduisant intégralement la Figure 1 du document source (risque hémorragique de la procédure en colonnes, risque thrombotique du patient en lignes).</i>","style":"note"},{"t":"table","rows":[[{"t":"p","html":"","style":"mx_head"},{"t":"p","html":"Risque hémorragique de la procédure (à évaluer avec le chirurgien ou le responsable de la procédure)","style":"mx_super"},"",""],[{"t":"p","html":"Risque thrombotique du patient","style":"mx_head"},{"t":"p","html":"Faible","style":"mx_head"},{"t":"p","html":"Intermédiaire","style":"mx_head"},{"t":"p","html":"Élevé","style":"mx_head"}],[{"t":"p","html":"Aspirine en prévention primaire","style":"mx_b"},{"t":"p","html":"Arrêt ou poursuite","style":"mx"},{"t":"p","html":"Arrêt","style":"mx"},{"t":"p","html":"Arrêt","style":"mx"}],[{"t":"p","html":"AAP en prévention secondaire (prévention cardiovasculaire, artériopathie des membres inférieurs, antécédent d'accident vasculaire cérébral ischémique)","style":"mx_group"},"","",""],[{"t":"p","html":"Aspirine en monothérapie","style":"mx_b"},{"t":"p","html":"Poursuite","style":"mx"},{"t":"p","html":"Poursuite","style":"mx"},{"t":"p","html":"Arrêt","style":"mx"}],[{"t":"p","html":"Clopidogrel en monothérapie","style":"mx_b"},{"t":"p","html":"Poursuite","style":"mx"},{"t":"p","html":"Arrêt et relais par aspirine","style":"mx"},{"t":"p","html":"Arrêt","style":"mx"}],[{"t":"p","html":"Bithérapie antiplaquettaire pour stent coronaire (différer la procédure à la fin de la bithérapie antiplaquettaire en l'absence de risque vital ou fonctionnel)","style":"mx_group"},"","",""],[{"t":"p","html":"Stent &lt; 1 mois / stent &lt; 6 mois à haut risque thrombotique* / IDM &lt; 6 mois","style":"mx_b"},{"t":"p","html":"Différer la procédure. Si impossible : poursuivre les 2 AAP","style":"mx"},{"t":"p","html":"Différer la procédure. Si impossible : poursuivre l'aspirine, interrompre l'anti-P2Y12","style":"mx"},{"t":"p","html":"Différer la procédure. Si impossible : interrompre les 2 AAP**","style":"mx"}],[{"t":"p","html":"Aucun des 3 critères ci-dessus","style":"mx_b"},{"t":"p","html":"Poursuivre les 2 AAP","style":"mx"},{"t":"p","html":"Poursuivre l'aspirine, interrompre l'anti-P2Y12","style":"mx"},{"t":"p","html":"Interrompre les 2 AAP","style":"mx"}]]},{"t":"p","html":"<b>Risque hémorragique de la procédure</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Faible","style":"head_w"},{"t":"p","html":"Intermédiaire","style":"head_w"},{"t":"p","html":"Élevé","style":"head_w"}],[{"t":"p","html":"Réalisable sous bithérapie antiplaquettaire (ex : cataracte)","style":"cell"},{"t":"p","html":"Réalisable sous aspirine seule (ex : PTH)","style":"cell"},{"t":"p","html":"Non réalisable sous AAP (ex : ampullectomie endoscopique)","style":"cell"}]]},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Délai d'arrêt des AAP — dernière prise à :</b> J-3 pour l'aspirine ; J-5 pour le clopidogrel et le ticagrélor ; J-7 pour le prasugrel (ajouter 2 jours à chaque durée si neurochirurgie intracrânienne). En post-opératoire, reprendre les 2 AAP au plus vite, en fonction du risque hémorragique.","style":"body_sm"}},[{"t":"p","html":"<b>TABLEAU I</b> — Caractéristiques d'un stent à haut risque thrombotique*","style":"h2"},null,{"t":"table","rows":[[{"t":"p","html":"Caractéristique","style":"head_w"}],[{"t":"p","html":"Antécédent de thrombose de stent sous bithérapie antiplaquettaire","style":"cell"}],[{"t":"p","html":"Maladie coronaire diffuse en particulier chez le diabétique","style":"cell"}],[{"t":"p","html":"Insuffisance rénale chronique (i.e. ClCr &lt; 60 mL/min)","style":"cell"}],[{"t":"p","html":"Traitement d'une occlusion coronaire chronique","style":"cell"}],[{"t":"p","html":"Stenting de la dernière artère coronaire perméable","style":"cell"}],[{"t":"p","html":"Au moins trois stents implantés","style":"cell"}],[{"t":"p","html":"Au moins trois lésions traitées","style":"cell"}],[{"t":"p","html":"Bifurcation avec deux stents implantés","style":"cell"}],[{"t":"p","html":"Longueur totale de stent &gt; 60 mm","style":"cell"}]]},null,{"t":"p","html":"<i>* Renvoi de la Figure 1 et du Tableau I. ** Si stent &lt; 1 mois, discuter un relais par AAP injectable.</i>","style":"note"}]]},{"title":"Durées d'interruption, relais & gestion selon l'indication","items":[[{"t":"section","text":"Durées d'interruption des AAP et relais","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"Durées d'interruption","style":"cell_b"},{"t":"p","html":"Si l'interruption des AAP avant une procédure invasive est indiquée, il est proposé de les interrompre de la façon suivante : dernière prise d'aspirine à J-3 (J0 correspond au jour de la procédure) ; dernière prise de clopidogrel et de ticagrélor à J-5 ; dernière prise de prasugrel à J-7.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Relais","style":"cell_b"},{"t":"p","html":"Il est recommandé de n'utiliser ni les héparines (HNF ou HBPM) ni les AINS en relais des AAP.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Aspirine — posologie","style":"cell_b"},{"t":"p","html":"Chez les patients traités au long cours par aspirine à des posologies allant jusqu'à 300 mg/j, il est proposé de ne pas réduire la posologie en vue de la chirurgie.","style":"cell"},{"t":"chip","label":"Fort"}]]}],{"t":"p","html":"<b>Note (neurochirurgie intracrânienne) :</b> pour la neurochirurgie intracrânienne, il est proposé que la dernière prise soit à J-5 pour l'aspirine, J-7 pour le clopidogrel et le ticagrélor, J-9 pour le prasugrel (accord fort).","style":"note"},{"t":"p","html":"<b>Note (ticagrélor, pontage semi-urgent) :</b> des données récentes suggèrent que la chirurgie semi-urgente de pontage aortocoronaire puisse être réalisée après une interruption plus courte du ticagrélor, de trois à cinq jours, sans surrisque hémorragique pour la majorité des patients. Cependant, dans cette situation, les patients n'ayant pas une correction de l'inhibition plaquettaire induite par le ticagrélor sont exposés à un risque accru d'hémorragie.","style":"note"},[{"t":"section","text":"Gestion des AAP en fonction de leur indication","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"Prévention primaire — non-initiation","style":"cell_b"},{"t":"p","html":"Il est proposé de ne pas initier un traitement par aspirine en préopératoire d'une chirurgie non cardiaque (à l'exception de l'endartériectomie carotidienne) dans le but de réduire les évènements cardiovasculaires périopératoires.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Prévention primaire — arrêt","style":"cell_b"},{"t":"p","html":"Il est proposé d'arrêter l'aspirine en préopératoire lorsqu'elle est prescrite en prévention primaire.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Prévention secondaire — poursuite","style":"cell_b"},{"t":"p","html":"Il est proposé de ne pas arrêter l'aspirine en préopératoire lorsqu'elle est prescrite en prévention cardiovasculaire secondaire (post-accident vasculaire cérébral ischémique, coronaropathie, artériopathie des membres inférieurs), à l'exception des procédures à risque hémorragique élevé.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Anti-P2Y12 monothérapie — relais aspirine","style":"cell_b"},{"t":"p","html":"Il est proposé que chez les patients traités par un anti-P2Y12 en monothérapie et programmés pour une chirurgie à risque intermédiaire, l'AAP soit remplacé par de l'aspirine, à la dose journalière 75 à 100 mg. Ce changement pourrait avoir lieu plus de sept jours avant la chirurgie, afin de permettre une correction complète de l'inhibition plaquettaire induite par l'anti-P2Y12.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Reprise postopératoire","style":"cell_b"},{"t":"p","html":"Il est proposé que la reprise de l'AAP soit aussi précoce que possible, en fonction du risque de saignement postopératoire, chez les patients ayant une indication à un traitement par AAP en monothérapie au long cours.","style":"cell"},{"t":"chip","label":"Fort"}]]}]]},{"title":"Bithérapie antiplaquettaire — stent coronaire","items":[[{"t":"section","text":"Bithérapie antiplaquettaire chez le patient porteur de stent coronaire","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"Décision multidisciplinaire","style":"cell_b"},{"t":"p","html":"Il est proposé que la gestion préopératoire des AAP et leur reprise postopératoire soit discutée avec le cardiologue du patient ou un cardiologue référent et tracée dans le dossier lorsqu'il s'agit d'une procédure à risque hémorragique intermédiaire ou élevé.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Report de la chirurgie","style":"cell_b"},{"t":"p","html":"Il est proposé de reporter toute chirurgie non cardiaque à la fin de la durée recommandée de la bithérapie antiplaquettaire quand cela ne génère pas de risque vital ou fonctionnel majeur pour le patient.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Si report impossible","style":"cell_b"},{"t":"p","html":"Si ce report n'est pas possible, il est proposé de repousser toute chirurgie non cardiaque au-delà du 1er mois qui suit la pose de stent, quel que soit le type de stent, quelle que soit l'indication (IDM ou coronaropathie stable). Si le geste ne peut être différé au-delà du 1er mois, il est proposé de réaliser cette chirurgie en poursuivant l'aspirine et dans un centre ayant un plateau de cardiologie interventionnelle actif 24 heures sur 24.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Haut risque thrombotique / IDM","style":"cell_b"},{"t":"p","html":"Chez les patients sous bithérapie antiplaquettaire dans les suites d'un IDM ou en cas de pose de stent associé à des caractéristiques à haut risque thrombotique, il est proposé de reporter toute chirurgie non cardiaque au-delà du 6e mois qui suit la pose de stent.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Aspirine — poursuite","style":"cell_b"},{"t":"p","html":"Il est recommandé de poursuivre l'aspirine en préopératoire. Si elle a été interrompue, il est recommandé de la reprendre aussi précocement que possible après la procédure invasive, au mieux le jour même, en fonction du risque de saignement postopératoire.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Relais parentéral (cas exceptionnels)","style":"cell_b"},{"t":"p","html":"Si les deux AAP doivent être interrompus dans le 1er mois suivant la pose de stent, un relais par des AAP parentéraux réversibles comme le tirofiban ou le cangrélor peut être discuté au cas par cas, avec une approche multidisciplinaire (utilisation hors AMM). Dans ces situations exceptionnelles, associées à un haut risque hémorragique et thrombotique, le relais doit être réalisé en soins intensifs et la chirurgie doit être réalisée dans un centre ayant un service de cardiologie interventionnelle actif 24 heures sur 24.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Reprise des anti-P2Y12","style":"cell_b"},{"t":"p","html":"Si les anti-P2Y12 ont été interrompus avant la chirurgie, ils doivent être repris précocement, au mieux dans les 24 à 72 heures après la chirurgie, compte tenu de l'augmentation du risque thrombotique. La reprise se fait avec le même anti-P2Y12 qu'en préopératoire.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"AINS","style":"cell_b"},{"t":"p","html":"Il est proposé de ne pas administrer d'AINS en périopératoire chez les patients traités par bithérapie antiplaquettaire.","style":"cell"},{"t":"chip","label":"Fort"}]]}],{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Absence de proposition</b> — concernant le recours, ou non, à une dose de charge lors de la reprise des anti-P2Y12 après leur interruption préopératoire, aucune proposition ne peut être faite.","style":"body_sm"}},{"t":"p","html":"<b>Note (AINS) :</b> l'utilisation périopératoire des coxibs reste possible.","style":"note"}]},{"title":"Anesthésie locorégionale (rachidienne & blocs périphériques)","items":[[{"t":"section","text":"Anesthésie locorégionale rachidienne (ALR-R)","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"Aspirine","style":"cell_b"},{"t":"p","html":"L'aspirine ne contre-indique pas une ALR rachidienne si le rapport bénéfice-risque est favorable, en vérifiant l'absence d'anomalie associée de l'hémostase, incluant un traitement anticoagulant. Il est proposé de préférer si possible la rachianesthésie en ponction unique à la péridurale.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Anti-P2Y12","style":"cell_b"},{"t":"p","html":"L'ALR rachidienne est contre-indiquée en cas de traitement par anti-P2Y12 (clopidogrel, prasugrel, ticagrélor), sauf si ces AAP ont été interrompus respectivement 5, 7 et 5 jours avant le geste.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Cathéter péridural","style":"cell_b"},{"t":"p","html":"La mise en place d'un cathéter péridural expose à une gestion complexe des AAP. Le retrait du cathéter suit les mêmes règles que la pose. Le recours au cathéter péridural ne doit pas compromettre la reprise postopératoire des AAP, et en particulier des anti-P2Y12.","style":"cell"},{"t":"chip","label":"Fort"}]]}],{"t":"section","text":"Blocs nerveux périphériques","color":"navy"},{"t":"p","html":"<b>Blocs à faible risque hémorragique</b> (saignement facilement contrôlable, zone compressible) : blocs superficiels — bloc fémoral, bloc axillaire, bloc sciatique au creux poplité, etc.<br/><b>Blocs à haut risque hémorragique</b> (saignement non compressible ou aux conséquences potentiellement graves) : blocs profonds — bloc infraclaviculaire, bloc sciatique para-sacré, bloc du plexus lombaire postérieur, etc. ; contre-indiqués sous anti-P2Y12.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"Faible risque","style":"cell_b"},{"t":"p","html":"Il est proposé que les blocs nerveux périphériques à faible risque hémorragique puissent être réalisés sous AAP, en mono- ou en bithérapie, si le rapport bénéfice/risque est favorable.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Haut risque","style":"cell_b"},{"t":"p","html":"Il est proposé que les blocs nerveux périphériques à haut risque hémorragique puissent être réalisés sous aspirine en monothérapie si le rapport bénéfice/risque est favorable. Ces blocs sont contre-indiqués sous anti-P2Y12 (clopidogrel, prasugrel, ticagrélor), sauf si ces AAP ont été interrompus respectivement 5, 7 et 5 jours avant le geste.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Échoguidage","style":"cell_b"},{"t":"p","html":"Il est proposé que ces blocs (superficiels ou profonds) soient réalisés par échoguidage et par un opérateur expérimenté.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Cathéter périnerveux","style":"cell_b"},{"t":"p","html":"La mise en place d'un cathéter périnerveux ne doit pas compromettre la reprise postopératoire des AAP, et en particulier des anti-P2Y12. Son retrait suit les mêmes règles que la pose.","style":"cell"},{"t":"chip","label":"Fort"}]]}]},{"title":"Chirurgie de pontage aortocoronaire & traçabilité","items":[[{"t":"section","text":"Chirurgie cardiaque de pontage aortocoronaire (PAC)","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"Décision multidisciplinaire","style":"cell_b"},{"t":"p","html":"Il est proposé que la stratégie de gestion des AAP en vue de pontage aortocoronaire (PAC) soit décidée de façon multidisciplinaire en fonction du risque hémorragique et du risque thrombotique de chaque patient.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Aspirine","style":"cell_b"},{"t":"p","html":"Il est proposé de poursuivre l'aspirine pour la chirurgie de PAC.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Anti-P2Y12 — durées","style":"cell_b"},{"t":"p","html":"Pour les patients traités par bithérapie antiplaquettaire, il est proposé de réaliser les procédures de PAC après interruption des anti-P2Y12, avec dernière prise de clopidogrel et de ticagrélor à J-5 et une dernière prise de prasugrel à J-7.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Ticagrélor — données récentes","style":"cell_b"},{"t":"p","html":"Des données récentes suggèrent que la chirurgie semi-urgente puisse être réalisée après une interruption plus courte du ticagrélor, de 3 à 5 jours, sans surrisque hémorragique pour la majorité des patients. Cependant, dans cette situation, les patients n'ayant pas une correction de l'inhibition plaquettaire induite par le ticagrélor sont exposés à un risque d'hémorragie.","style":"cell"},{"t":"chip","label":"Fort"}]]}],{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Gestion des agents antiplaquettaires pour une procédure invasive programmée » — Propositions du Groupe d'intérêt en hémostase périopératoire (GIHP) et du Groupe français d'études sur l'hémostase et la thrombose (GFHT), en collaboration avec la Société française d'anesthésie-réanimation (SFAR). Anne Godier, Pierre Fontana, Serge Motte, Annick Steib, Fanny Bonhomme, Sylvie Schlumberger, Thomas Lecompte, Nadia Rosencher, Sophie Susen, André Vincentelli, Yves Gruel, Pierre Albaladejo, Jean-Philippe Collet, et le French Working Group on perioperative hemostasis (GIHP). Anesth Reanim 2018 (ANREA-314).","style":"source"},{"t":"p","html":"<b>Publication :</b> doi 10.1016/j.anrea.2018.01.002.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> pas de système GRADE — propositions rédigées par cinq groupes de travail GIHP/GFHT puis validées par vote (n = 37) ; seuil de 50 % pour retenir une proposition, seuil de 70 % pour un « accord fort » (voir légende page 1 et disclosure sur la divergence source-interne concernant l'unique exception annoncée par le résumé mais non identifiable dans le corps du texte).","style":"source"},{"t":"p","html":"<b>Couverture :</b> cette fiche reprend l'intégralité des propositions du corps du texte (classification du risque hémorragique de la procédure, durées d'interruption et relais, gestion selon l'indication, bithérapie pour stent coronaire, anesthésie locorégionale rachidienne et blocs périphériques, chirurgie de pontage aortocoronaire), ainsi que la Figure 1 (synthèse des propositions) et le Tableau I (caractéristiques d'un stent à haut risque thrombotique), reproduits intégralement en tableaux structurés.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Il reprend l'intégralité des propositions, de la Figure 1 et du Tableau I du document source, mais ne remplace pas le texte intégral (argumentaire complet, références bibliographiques) et n'est ni édité ni validé par le GIHP, le GFHT ou la SFAR. En cas de doute, se référer au texte intégral et/ou à un avis spécialisé. Document de 2018 : vérifier l'existence d'une actualisation plus récente en cas de doute.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2018/03/2_Gestion-des-agents-antiplaquettaires-pour-une-procedure-invasive-programmee.pdf';

insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/prevention-de-la-maladie-thromboembolique-veineuse-peri-operatoire/' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/prevention-de-la-maladie-thromboembolique-veineuse-peri-operatoire/' and s.acronym in ('GIHP', 'SFAR', 'SFTH', 'SFMV')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/prevention-de-la-maladie-thromboembolique-veineuse-peri-operatoire/' and d.society_id is null and s.acronym = 'GIHP';
update public.documents set
  fiche_key = 'mtev_perioperatoire',
  card_json = $mgjson${"badge":"GRADE","title":"Prévention de la MTEV péri-opératoire","short":"Actualisation 2024 des recommandations SFAR 2011 : implémentation de protocoles, facteurs de risque liés au patient, thromboprophylaxie pharmacologique par type de chirurgie (orthopédie/traumatologie, abdominopelvienne, carcinologique, vasculaire), délai d'introduction et anesthésie locorégionale, compression pneumatique intermittente, filtre cave, insuffisance rénale, obésité, pédiatrie, réanimation, acide tranexamique, monitorage biologique, TVP distale — 77 recommandations et schéma de synthèse.","society":"GIHP, en collaboration avec la SFAR, la SFTH et la SFMV — RFE 2024","version":"16.5.2024","validated":"Validation SFAR 30/04/2024, SFTH 23/02/2024, SFMV janvier 2024","methodology":"GRADE","pages":14,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"mtev_perioperatoire","sections":[{"title":"Introduction, méthodologie & légende","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> prévention de la maladie thromboembolique veineuse (MTEV) péri-opératoire chez l'adulte (toutes chirurgies) et chez l'enfant, actualisant les recommandations SFAR de 2011. RFE du Groupe d'intérêt en Hémostase Péri-opératoire (GIHP), en collaboration avec la SFAR, la Société Française de Thrombose et d'Hémostase (SFTH) et la Société Française de Médecine Vasculaire (SFMV) ; endossée par la Société Française de Chirurgie Digestive (SFCD), la Société Française de Pharmacologie et de Thérapeutique (SFPT) et le réseau INNOVTE. <b>Les patients ayant une pathologie hémorragique constitutionnelle ne sont pas concernés par ces recommandations.</b><br/><br/><b>Méthodologie GRADE, format PICO :</b> un niveau de preuve global fort permet une recommandation <b>forte</b> (« il est recommandé de » — GRADE 1+/1-) ; un niveau modéré ou faible aboutit à une recommandation <b>optionnelle</b> (« il est proposé de » — GRADE 2+/2-) ; en l'absence de littérature suffisante, un <b>avis d'experts</b> (AE) est formulé. Chaque recommandation est ensuite validée par un vote (n = 37 participants) : accord <b>fort</b> si ≥ 70 % d'accord et &lt; 20 % d'opposition ; à défaut, reformulation et nouveau vote.","style":"body"}},{"t":"panel","tone":"good","content":{"t":"p","html":"<b>Particularité de ce document (vérifiée par recherche exhaustive sur l'extraction texte complète) :</b> à la différence d'autres RFE de ce corpus, <b>100 % des 77 recommandations graduées retrouvées portent la mention d'accord « Fort »</b> — aucune occurrence d'« Accord Faible » n'apparaît nulle part dans les 79 pages sources. Cette fiche n'affiche donc pas de colonne « Accord » séparée (elle serait constante et non informative) : seule la colonne <b>Grade</b> (GRADE 1+/1-/2+/2-/AE) figure dans les tableaux ci-après.","style":"body_sm"}},{"t":"section","text":"Légende des grades (méthodologie GRADE)","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"p","html":"Recommandé (forte)","style":"badge_head"},{"t":"chip","label":"1-"},{"t":"p","html":"Non recommandé (forte)","style":"badge_head"},{"t":"chip","label":"2+"},{"t":"p","html":"Proposé (optionnel)","style":"badge_head"},{"t":"chip","label":"2-"},{"t":"p","html":"Proposé de ne pas faire","style":"badge_head"},{"t":"chip","label":"AE"},{"t":"p","html":"Avis d'experts","style":"badge_head"}]]},{"t":"section","text":"Couverture de cette fiche","color":"grey"},{"t":"p","html":"Cette fiche reprend l'intégralité des <b>77 recommandations individuelles graduées</b> des 14 questions PICO du document (comportant au total 21 sous-thèmes cliniques, ex. 5 sous-chirurgies orthopédiques distinctes), ainsi que les 3 figures (PTH/PTG p.16 ; TVP distale post-opératoire p.74 ; schéma de synthèse p.79 — images pures, redessinées ici en tableaux/panneaux structurés fidèles au contenu et aux grades imprimés) et les tableaux chiffrés (fonction rénale p.52 ; délais avant geste neuraxial p.41 ; méta-analyses de la section réanimation p.63-64). L'argumentaire complet (littérature discutée, figures de recherche) et les ~400 références bibliographiques ne sont <b>pas</b> repris : se référer au texte intégral. Une brève note d'évidence (1-2 phrases) accompagne chaque table de recommandations lorsqu'utile.","style":"body_sm"}]},{"title":"Impact des protocoles & facteurs de risque liés au patient","items":[[{"t":"section","text":"Q1 — Impact de l'implémentation de protocoles de thromboprophylaxie","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Protocoles locaux","style":"cell_b"},{"t":"p","html":"Il est recommandé d'implémenter localement des protocoles de thromboprophylaxie veineuse pour réduire le risque de complications péri-opératoires. Ces protocoles incluent la déambulation précoce et la thromboprophylaxie pharmacologique et mécanique, dont l'indication, les modalités et la durée dépendent du risque thromboembolique veineux de la chirurgie et du patient, du risque hémorragique et du parcours de soin.","style":"cell"},{"t":"chip","label":"1+"}]]}],[{"t":"section","text":"Q2 — Facteurs de risque thromboembolique veineux liés au patient","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Chirurgie faible risque + FdR patient","style":"cell_b"},{"t":"p","html":"Après une chirurgie à faible risque thromboembolique veineux, si le patient présente un facteur de risque majeur ou plusieurs facteurs de risque mineurs, il est proposé de prescrire une thromboprophylaxie par anticoagulant pendant une durée minimale de 7 jours.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Thrombophilie majeure sans AC","style":"cell_b"},{"t":"p","html":"En cas de thrombophilie majeure sans traitement anticoagulant au long cours, il est suggéré de se rapprocher d'un centre spécialisé afin de documenter la thrombophilie et d'évaluer le risque thromboembolique veineux.","style":"cell"},{"t":"chip","label":"AE"}]]}],{"t":"panel","tone":"default","content":[{"t":"p","html":"<b>Facteurs de risque majeurs</b> (# — seuils de continuum, cf argumentaire) : antécédent(s) personnel(s) d'ETEV • thrombophilie majeure connue (syndrome des anticorps antiphospholipides, déficit AT/PC/PS, polymorphismes homozygotes ou hétérozygoties composites Leiden/facteur II) • cancer actif (traitement &lt;6 mois) • obésité de classe III ou plus (IMC ≥ 40 kg/m²).","style":"body_sm"},null,{"t":"p","html":"<b>Facteurs de risque modérés ou mineurs :</b> âge ≥ 75 ans • insuffisance cardiaque ou respiratoire, BPCO • insuffisance rénale sévère (DFG &lt; 30 mL/min/1,73 m²) • maladie inflammatoire chronique (PR, MICI, lupus) • traitement hormonal œstrogénique • grossesse en cours ou post-partum • obésité de classe I-II (IMC 30-40) • alitement prolongé récent • déficit neurologique &lt;1 mois (AVC, lésion médullaire) • immobilisation orthopédique ou alitement post-opératoire.","style":"body_sm"}]},{"t":"p","html":"<i>Thrombophilie majeure + anticoagulation au long cours :</i> thromboprophylaxie post-opératoire tant que le traitement antérieur n'est pas repris. <i>Thrombophilie mineure :</i> pas de thromboprophylaxie systématique. <i>Pas de thrombophilie connue :</i> pas d'indication à un bilan de thrombophilie pour stratifier le risque post-opératoire (sauf antécédent familial documenté). Durée minimale d'une semaine proposée pour couvrir la période la plus à risque (délai médian de survenue d'un ETEV post-opératoire : 8 jours [IQR 5-13] en chirurgie ambulatoire).","style":"note"}]},{"title":"Orthopédie — PTH/PTG & Figure 1","items":[[{"t":"section","text":"Orthopédie — Prothèse totale de hanche (PTH) ou de genou (PTG), hors fracture","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Indication","style":"cell_b"},{"t":"p","html":"Il est recommandé de prescrire une thromboprophylaxie pharmacologique après PTH ou PTG.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Durée","style":"cell_b"},{"t":"p","html":"Il est recommandé que la durée de thromboprophylaxie pharmacologique soit de 35 jours après PTH et 14 jours après PTG.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Modalités","style":"cell_b"},{"t":"p","html":"Il est recommandé de prescrire soit un anticoagulant (AOD, HBPM ou fondaparinux) pendant toute la durée, soit une thromboprophylaxie séquentielle (5 jours d'anticoagulant puis aspirine 75-100 mg/j pendant 30 jours après PTH ou 9 jours après PTG) si le patient est pris en charge dans un parcours de RAAC réussi et sans facteur de risque thromboembolique veineux majeur** ni plusieurs facteurs mineurs.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"** Facteurs de risque majeurs : antécédents personnels d'ETEV, thrombophilie majeure connue, cancer actif, obésité morbide (IMC ≥ 40 kg/m²) — cf Q2.","style":"note"}],{"t":"p","html":"<i>Posologies :</i> apixaban 2,5 mg x2/j (débuté à H12-H24) ; rivaroxaban 10 mg x1/j (H6-H8) ; dabigatran 220 mg x1/j (150 mg si &gt;75 ans, ClCr 30-50, ou interaction vérapamil/amiodarone/quinidine) ; fondaparinux 2,5 mg x1/j SC (≥ H8) ; HBPM ≥ 4000 UI anti-Xa. Parcours optimisé (RAAC/ambulatoire) = chirurgie &lt;120 min ET marche avec déroulé du pas &lt;24h ET hospitalisation &lt;5 jours.","style":"note"},{"t":"section","text":"Figure 1 (p.16) — Thromboprophylaxie après PTH ou PTG","color":"teal-dark"},{"t":"p","html":"<i>Redessin structuré du diagramme source (image pure) — mêmes issues cliniques et grades imprimés sur le schéma original, sous forme de tableau.</i>","style":"note"},{"t":"table","rows":[[{"t":"p","html":"PTH ou PTG — parcours de RAAC/ambulatoire prévu ET réussi (chirurgie <120 min, marche <24h, hospitalisation <5j) ET absence de FdR thromboembolique majeur ou de plusieurs FdR mineurs","style":"flow_lbl"}]]},{"t":"table","rows":[[{"t":"p","html":"-> Thromboprophylaxie SÉQUENTIELLE : anticoagulant 5 jours puis aspirine 75-100 mg/j pendant 30 jours (PTH) ou 9 jours (PTG).","style":"body_sm"},{"t":"chip","label":"1+"}]]},{"t":"table","rows":[[{"t":"p","html":"Sinon (RAAC non prévu, conditions RAAC finalement non respectées, ou FdR thromboembolique veineux du patient présent)","style":"flow_lbl"}]]},{"t":"table","rows":[[{"t":"p","html":"-> Thromboprophylaxie par ANTICOAGULANT SEUL pendant toute la durée : HBPM, apixaban, dabigatran ou rivaroxaban, ou fondaparinux, débuté entre H12 et H24 post-opératoires (entre H6 et H12 si risque thromboembolique veineux élevé lié au patient — cf Q7 pour le détail des délais). Durée : 35 j (PTH) / 14 j (PTG).","style":"body_sm"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"Si très haut risque thromboembolique veineux, associer une compression pneumatique intermittente (CPI) — cf Q8.","style":"body_sm"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"Dans tous les cas : déambulation précoce et hydratation optimale.","style":"body_sm"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"Dans tous les cas : pas de contention élastique graduée.","style":"body_sm"},{"t":"chip","label":"1-"}]]},{"t":"p","html":"<i>Liste complète des facteurs de risque thromboembolique veineux du patient : cf Q2, page précédente.</i>","style":"note"}]},{"title":"Orthopédie/traumatologie — fractures & gestes non majeurs","items":[[{"t":"section","text":"Fracture de l'extrémité supérieure du fémur (ESF)","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Anticoagulant","style":"cell_b"},{"t":"p","html":"Une thromboprophylaxie par anticoagulant (HBPM ou fondaparinux) est recommandée pendant 4 semaines après la chirurgie.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Chirurgie retardée","style":"cell_b"},{"t":"p","html":"Si la chirurgie est retardée, il est proposé de débuter la thromboprophylaxie en pré-opératoire, en préférant une HBPM et en respectant un délai de 12h entre la dernière injection d'HBPM et la chirurgie.","style":"cell"},{"t":"chip","label":"2+"}]]}],{"t":"p","html":"<i>Fondaparinux 2,5 mg x1/j SC (poids &gt;50 kg, DFG &gt;50) débuté ≥ H8. Aspirine non recommandée dans cette indication à haut risque thrombotique (non comparée aux HBPM).</i>","style":"note"},[{"t":"section","text":"Fracture diaphyse fémorale, plateau tibial, rotule, tibia, cheville, tendon d'Achille","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Anticoagulant","style":"cell_b"},{"t":"p","html":"Une thromboprophylaxie par anticoagulant (AOD anti-Xa ou HBPM) est recommandée après chirurgie pour ces fractures/ruptures.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Choix","style":"cell_b"},{"t":"p","html":"Il est proposé de préférer un AOD anti-Xa à une HBPM (essai PRONOMOS : rivaroxaban plus efficace que l'enoxaparine sans excès hémorragique).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Chirurgie différée","style":"cell_b"},{"t":"p","html":"Si l'intervention est prévue plus de 12h après l'hospitalisation, une thromboprophylaxie pré-opératoire par HBPM est proposée (délai 12h avant la chirurgie).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Durée","style":"cell_b"},{"t":"p","html":"Il est proposé de poursuivre jusqu'à l'appui plantaire avec déroulé du pied, durée minimale 7 jours.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Aspirine","style":"cell_b"},{"t":"p","html":"Il n'est pas recommandé de prescrire de l'aspirine pour la thromboprophylaxie veineuse.","style":"cell"},{"t":"chip","label":"1-"}]]}],[{"t":"section","text":"Ligamentoplastie du genou, arthroscopie simple, méniscectomie, chir. avant-pied, ablation de matériel","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Pas de systématique","style":"cell_b"},{"t":"p","html":"Il est proposé de ne pas prescrire de thromboprophylaxie pharmacologique systématique après ces gestes.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Si FdR patient","style":"cell_b"},{"t":"p","html":"Si le patient présente un facteur de risque thromboembolique veineux majeur ou plusieurs facteurs mineurs, une thromboprophylaxie par anticoagulant (AOD anti-Xa ou HBPM) est proposée.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Durée si prescrite","style":"cell_b"},{"t":"p","html":"Si une thromboprophylaxie pharmacologique est prescrite, une durée de 7 jours minimum est suggérée.","style":"cell"},{"t":"chip","label":"AE"}]]}]]},{"title":"Chirurgie abdomino-pelvienne, carcinologique & vasculaire","items":[[{"t":"section","text":"Chirurgie abdomino-pelvienne (carcinologique ou non)","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Risque élevé — HBPM","style":"cell_b"},{"t":"p","html":"Après chirurgie abdomino-pelvienne à risque élevé (carcinologique ou non), il est recommandé de prescrire une thromboprophylaxie par HBPM pour une durée de 4 semaines, y compris en cas de chirurgie mini-invasive ou de parcours de RAAC.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Risque élevé — fondaparinux","style":"cell_b"},{"t":"p","html":"Il est proposé que le fondaparinux puisse être utilisé en alternative aux HBPM.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Risque élevé — AOD en relais","style":"cell_b"},{"t":"p","html":"Il est proposé que les AOD anti-Xa puissent être utilisés en relais des HBPM après reprise du transit.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Risque intermédiaire","style":"cell_b"},{"t":"p","html":"Il est proposé de prescrire une thromboprophylaxie par HBPM pour une durée minimale de 7 jours.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Risque faible","style":"cell_b"},{"t":"p","html":"Il est proposé de ne pas prescrire de thromboprophylaxie pharmacologique systématique. Elle est proposée si le patient présente un facteur de risque majeur, plusieurs facteurs mineurs, une chirurgie prolongée ou une complication post-opératoire.","style":"cell"},{"t":"chip","label":"2-"}]]}],{"t":"p","html":"<i>Chirurgie à risque élevé (durée &gt;2h, résection étendue, maladie carcinologique/inflammatoire) : ex. hépatectomie majeure, colectomie, gastrectomie, prostatectomie, cystectomie, néphrectomie, hystérectomie par voie haute, chirurgie du cancer de l'utérus/ovaire. Risque intermédiaire : ex. sigmoïdectomie à distance d'une poussée, néphrectomie pour don vivant. Risque faible : ex. cholécystectomie programmée, RTUP, conisation, hystéroscopie.</i>","style":"note"},[{"t":"section","text":"Chirurgie carcinologique (hors abdomino-pelvienne : sein, ORL, poumon…)","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Risque élevé","style":"cell_b"},{"t":"p","html":"Après chirurgie carcinologique à risque thromboembolique élevé, il est recommandé de prescrire une thromboprophylaxie par HBPM pour une durée minimale de 7 jours.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Délai","style":"cell_b"},{"t":"p","html":"Il est proposé de commencer la thromboprophylaxie pharmacologique en post-opératoire.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"CPI","style":"cell_b"},{"t":"p","html":"Il est proposé d'utiliser la CPI en per- et post-opératoire en cas de très haut risque thromboembolique veineux# ou de contre-indication à la thromboprophylaxie pharmacologique.","style":"cell"},{"t":"chip","label":"2+"}]]}],{"t":"p","html":"<i># Combinaison d'un FdR majeur lié au patient et d'un risque chirurgical élevé. Sein : risque bas (&lt;0,5%), pas de prophylaxie systématique sauf mastectomie avec reconstruction, chimiothérapie péri-opératoire ou tamoxifène. ORL : majorité ambulatoire sans prophylaxie, prophylaxie si chirurgie majeure avec lambeau. Poumon : incidence élevée (2-5% à 1 mois) malgré prophylaxie, durée optimale non établie (certaines recommandations suggèrent jusqu'à 1 mois par analogie).</i>","style":"note"},[{"t":"section","text":"Chirurgie vasculaire","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Carotidienne","style":"cell_b"},{"t":"p","html":"Après chirurgie carotidienne, il est proposé de ne pas prescrire de thromboprophylaxie veineuse systématique.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Aortique / revasc. MI ouverte","style":"cell_b"},{"t":"p","html":"Après chirurgie aortique abdominale (ouverte ou endoprothèse) ou revascularisation artérielle des membres inférieurs par voie ouverte, il est proposé de prescrire une thromboprophylaxie jusqu'à reprise de la marche.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Endovasculaire MI","style":"cell_b"},{"t":"p","html":"Après procédure endovasculaire artérielle (angioplastie et/ou endoprothèse) des membres inférieurs, il est proposé de ne pas prescrire de thromboprophylaxie systématique.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Revasc. MI + rivaroxaban","style":"cell_b"},{"t":"p","html":"Chez un patient éligible au rivaroxaban 2,5 mg x2/j + aspirine 100 mg/j (prévention cardiovasculaire), il est proposé de différer l'introduction du rivaroxaban à la fin de la thromboprophylaxie veineuse par HBPM lorsque celle-ci est indiquée.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"CPI contre-indiquée","style":"cell_b"},{"t":"p","html":"Il est proposé de ne pas utiliser de CPI en péri-opératoire de chirurgie de revascularisation artérielle des membres inférieurs (risque d'altération de la perfusion artérielle).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Varices — chirurgie ouverte","style":"cell_b"},{"t":"p","html":"Après chirurgie ouverte de varices (stripping), il est proposé de réaliser une thromboprophylaxie de courte durée (≤ 7 jours).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Varices — endoveineux thermique","style":"cell_b"},{"t":"p","html":"Après procédure thermique endovasculaire des varices, il est proposé de ne pas prescrire de thromboprophylaxie sauf en cas de facteurs de risque liés au patient.","style":"cell"},{"t":"chip","label":"2-"}]]}],{"t":"p","html":"<i>Rivaroxaban 2,5 mg x2/j + aspirine : AMM post-opératoire de chirurgie vasculaire artérielle des MI (essai VOYAGER PAD) en prévention des évènements cardiaques et vasculaires majeurs, initié dans les 10 jours post-opératoires ; si HBPM veineuse prescrite, décaler le rivaroxaban à l'arrêt de l'HBPM (J5-J10).</i>","style":"note"}]},{"title":"Délai d'introduction & anesthésie locorégionale","items":[[{"t":"section","text":"Délai d'introduction de la thromboprophylaxie pharmacologique","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Post-opératoire","style":"cell_b"},{"t":"p","html":"En chirurgie programmée, lorsqu'une thromboprophylaxie pharmacologique est indiquée, il est proposé d'en administrer la première dose en post-opératoire pour réduire le risque hémorragique.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"H12-H24","style":"cell_b"},{"t":"p","html":"Il est proposé de débuter la thromboprophylaxie entre la 12e et la 24e heure post-opératoire (le lendemain matin pour la chirurgie programmée).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"H6-H12 si FdR élevé","style":"cell_b"},{"t":"p","html":"En cas de risque thromboembolique veineux élevé lié au patient# les experts proposent de débuter entre la 6e et la 12e heure post-opératoire, en commençant par une HBPM quel que soit l'anticoagulant du lendemain.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Chirurgie urgente différée","style":"cell_b"},{"t":"p","html":"En cas de chirurgie urgente différée de plus de 12h, il est proposé de débuter la thromboprophylaxie en pré-opératoire par une HBPM, en respectant un délai de 12h avant la chirurgie.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Délais avant ALR","style":"cell_b"},{"t":"p","html":"Il est recommandé de respecter les délais minimaux de sécurité entre la thromboprophylaxie pharmacologique et la réalisation de procédures d'ALR neuraxiale.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"# lié au patient : antécédent personnel d'ETEV, thrombophilie majeure connue, cancer actif, IMC ≥ 40 kg/m², ou association de plusieurs facteurs de risque (cf Q2).","style":"note"}],{"t":"p","html":"<b>Délais entre thromboprophylaxie pharmacologique et geste neuraxial</b> (rachianesthésie, péridurale, péri-rachi combinée, y compris retrait de cathéter)","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Anticoagulant (dose préventive)","style":"head_w"},{"t":"p","html":"Demi-vie","style":"head_w"},{"t":"p","html":"Délai minimum avant le geste neuraxial","style":"head_w"}],[{"t":"p","html":"HBPM","style":"cell"},{"t":"p","html":"5-7h","style":"cell"},{"t":"p","html":"12h (si DFG &gt; 30 mL/min/1,73 m²)","style":"cell"}],[{"t":"p","html":"HNF SC","style":"cell"},{"t":"p","html":"2h","style":"cell"},{"t":"p","html":"4h","style":"cell"}],[{"t":"p","html":"Apixaban","style":"cell"},{"t":"p","html":"12h*","style":"cell"},{"t":"p","html":"36h","style":"cell"}],[{"t":"p","html":"Rivaroxaban","style":"cell"},{"t":"p","html":"5-9h (11-13h chez le sujet âgé)*","style":"cell"},{"t":"p","html":"24h (si DFG &gt; 30 mL/min/1,73 m²)","style":"cell"}],[{"t":"p","html":"Dabigatran","style":"cell"},{"t":"p","html":"11-15h si DFG &gt; 50*","style":"cell"},{"t":"p","html":"24-36h (si DFG &gt; 50 mL/min/1,73 m²)","style":"cell"}],[{"t":"p","html":"Fondaparinux","style":"cell"},{"t":"p","html":"17h (21h chez le sujet âgé)*","style":"cell"},{"t":"p","html":"36h (si DFG &gt; 50 mL/min/1,73 m²)","style":"cell"}]]},{"t":"p","html":"<i>* Données du RCP. Discuter d'allonger les délais ou de réaliser un dosage en cas d'insuffisance rénale (DFG &lt;50), petit poids, ou sujet âgé. Seuils de sécurité hémostatique si dosage réalisé : [AOD] ≤ 30 ng/mL ; anti-Xa HBPM ≤ 0,1 UI/mL ; anti-Xa fondaparinux ≤ 0,1 µg/mL (ou &lt; limite de quantification du laboratoire).</i>","style":"note"}]},{"title":"CPI, contentions élastiques & filtre cave","items":[[{"t":"section","text":"Compression pneumatique intermittente (CPI)","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Si AC contre-indiqués","style":"cell_b"},{"t":"p","html":"Il est recommandé d'utiliser la CPI si une thromboprophylaxie veineuse est indiquée mais que les anticoagulants sont contre-indiqués.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Très haut risque","style":"cell_b"},{"t":"p","html":"En cas de très haut risque thromboembolique veineux§, il est proposé d'associer la CPI en per- et post-opératoire à la thromboprophylaxie pharmacologique.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Déambulation","style":"cell_b"},{"t":"p","html":"Il est proposé que l'usage de la CPI ne retarde pas la reprise de la déambulation.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"§ Combinaison d'un FdR thromboembolique majeur lié au patient et d'une chirurgie à risque élevé.","style":"note"}],[{"t":"section","text":"Contentions élastiques graduées","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Non recommandées","style":"cell_b"},{"t":"p","html":"Les contentions élastiques graduées ne sont pas recommandées pour la thromboprophylaxie péri-opératoire, quel que soit le risque thromboembolique veineux.","style":"cell"},{"t":"chip","label":"1-"}]]}],{"t":"p","html":"<i>Essai GAPS (n=1858, ajout de contentions à une HBPM) : aucun bénéfice. Registre médico-économique (n=24273) : RR=0,999 (IC95% 0,998-1,000). Les contentions augmentent les lésions cutanées et les coûts sans réduire les ETEV.</i>","style":"note"},[{"t":"section","text":"Filtre cave","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Prévention primaire","style":"cell_b"},{"t":"p","html":"Il est proposé de ne pas poser de filtre cave pour la thromboprophylaxie veineuse péri-opératoire primaire.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Prévention secondaire — pose","style":"cell_b"},{"t":"p","html":"Il est proposé de discuter la mise en place d'un filtre cave optionnel en pré-opératoire d'une chirurgie à risque hémorragique lorsque celle-ci doit être réalisée moins d'un mois après une EP et/ou une TVP proximale des membres inférieurs.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Retrait","style":"cell_b"},{"t":"p","html":"Il est recommandé de programmer le retrait du filtre cave dès que le traitement anticoagulant curatif a pu être repris sans complication.","style":"cell"},{"t":"chip","label":"1+"}]]}]]},{"title":"Insuffisance rénale & obésité","items":[[{"t":"section","text":"Insuffisance rénale","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Adapter à la fonction rénale","style":"cell_b"},{"t":"p","html":"Il est recommandé d'adapter les modalités de thromboprophylaxie pharmacologique à la fonction rénale.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"IR sévère — 1re intention","style":"cell_b"},{"t":"p","html":"En cas d'insuffisance rénale sévère (DFG estimé 15-30 mL/min/1,73 m²), il est proposé d'utiliser les HBPM en première intention plutôt que l'HNF ou les AOD.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"IR sévère — schémas AMM","style":"cell_b"},{"t":"p","html":"Il est recommandé d'utiliser : enoxaparine 2000 UI x1/j SC si DFG 15-30 ; tinzaparine 4500 UI x1/j SC si DFG &gt; 20.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"IR terminale (DFG &lt;15)","style":"cell_b"},{"t":"p","html":"En cas d'insuffisance rénale terminale, il est recommandé d'utiliser la calciparine (HNF) 5000 UI x2/j SC, les autres thérapeutiques n'étant pas recommandées.","style":"cell"},{"t":"chip","label":"1+"}]]}],{"t":"p","html":"<b>Tableau — Thromboprophylaxie et fonction rénale</b> (reproduction verbatim du tableau-image source p.52)","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"DFG estimé (mL/min/1,73 m²)","style":"gridh"},{"t":"p","html":"&lt;15","style":"gridh"},{"t":"p","html":"15-20","style":"gridh"},{"t":"p","html":"20-30","style":"gridh"},{"t":"p","html":"30-50","style":"gridh"},{"t":"p","html":"&gt;50","style":"gridh"}],[{"t":"p","html":"HNF","style":"gridd"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"}],[{"t":"p","html":"tinzaparine","style":"gridd"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"}],[{"t":"p","html":"enoxaparine","style":"gridd"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"½ dose","style":"grid"},{"t":"p","html":"½ dose","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"}],[{"t":"p","html":"fondaparinux 2,5 mg","style":"gridd"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"}],[{"t":"p","html":"apixaban / rivaroxaban","style":"gridd"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"}],[{"t":"p","html":"dabigatran","style":"gridd"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"},{"t":"p","html":"","style":"grid"}]]},{"t":"p","html":"<i>En rouge : non recommandé par l'AMM ; en orange : non recommandé par le GIHP ; en vert : recommandé. Dabigatran 150 mg x1/j si DFG 30-50, contre-indiqué si DFG &lt;30. Apixaban/rivaroxaban : pas d'ajustement si DFG 15-30 mais données péri-opératoires très limitées ; contre-indiqués si DFG &lt;15. Fondaparinux 2,5 mg contre-indiqué si DFG &lt;50 (fondaparinux 1,5 mg non disponible en France).</i>","style":"note"},[{"t":"section","text":"Obésité et poids extrêmes","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Classe I-II (IMC 30-39)","style":"cell_b"},{"t":"p","html":"Chez les patients présentant une obésité de classe I ou II nécessitant une thromboprophylaxie pharmacologique, il est proposé d'utiliser un schéma posologique standard.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Classe III+ (IMC ≥40)","style":"cell_b"},{"t":"p","html":"Il est proposé d'utiliser : enoxaparine 4000 UI x2/j SC (ou 6000 UI x1/j ; 6000 UI x2/j réservé aux patients &gt;150 kg) ; daltéparine 5000 UI x2/j SC ; tinzaparine 75 UI/kg (poids réel) x1/j SC ; fondaparinux 5 mg x1/j SC ; apixaban 2,5 mg x2/j PO ; rivaroxaban 10 mg x1/j PO (peu d'expérience AOD si IMC &gt;50 ou poids &gt;150 kg).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Classe III + chirurgie à risque élevé","style":"cell_b"},{"t":"p","html":"Il est proposé d'associer une CPI à la thromboprophylaxie pharmacologique.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Chirurgie bariatrique","style":"cell_b"},{"t":"p","html":"Il est proposé de prescrire une thromboprophylaxie post-opératoire par HBPM ou fondaparinux pour une durée minimale de 10 jours.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Petit poids","style":"cell_b"},{"t":"p","html":"Chez les patients de petit poids, il est proposé d'adapter les schémas posologiques (risque d'accumulation et d'hémorragie).","style":"cell"},{"t":"chip","label":"2+"}]]}],{"t":"p","html":"<i>C'est l'IMC (et non le poids seul) qui guide la discussion de thromboprophylaxie chez l'obèse ; le poids guide l'adaptation posologique chez le patient de grande taille sans obésité. Seule la tinzaparine a une AMM d'ajustement au poids réel. Petit poids : ex. réduire l'enoxaparine à 2000 UI ; le RCP du fondaparinux déconseille son usage si poids &lt;50 kg. AOD : apixaban/rivaroxaban sans adaptation nécessaire à petit poids selon leur RCP ; données limitées pour le dabigatran.</i>","style":"note"}]},{"title":"Pédiatrie & patient de réanimation","items":[[{"t":"section","text":"Chirurgie pédiatrique","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Dès la puberté / 14 ans","style":"cell_b"},{"t":"p","html":"Il est proposé qu'à partir de la puberté ou de l'âge de 14 ans, la thromboprophylaxie pharmacologique réponde aux mêmes recommandations que chez l'adulte.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Avant la puberté / 14 ans","style":"cell_b"},{"t":"p","html":"Les experts suggèrent que la présence de plusieurs facteurs de risque thromboembolique veineux conduise à discuter au cas par cas le bénéfice-risque d'une thromboprophylaxie pharmacologique.","style":"cell"},{"t":"chip","label":"AE"}]]}],{"t":"p","html":"<i>Schémas proposés pour l'enfant &lt;40 kg autour de la puberté (non formellement évalués) : 50 UI/kg/j d'enoxaparine (1-2 injections/j) ou 50 UI/kg de tinzaparine x1/j. Risque hémorragique conséquent chez l'enfant (0,4-3% saignements majeurs, jusqu'à 21% mineurs). AOD sans AMM en prévention primaire pédiatrique (fin 2023).</i>","style":"note"},[{"t":"section","text":"Patient de réanimation","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Indication","style":"cell_b"},{"t":"p","html":"Il est recommandé d'administrer une thromboprophylaxie pharmacologique chez les patients de réanimation pour réduire les complications thromboemboliques veineuses.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"HBPM > HNF","style":"cell_b"},{"t":"p","html":"En l'absence d'insuffisance rénale terminale, il est recommandé de prescrire des HBPM à doses prophylactiques plutôt que de l'HNF.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Pas de monitorage anti-Xa","style":"cell_b"},{"t":"p","html":"Lors d'une thromboprophylaxie par HBPM, il est proposé de ne pas monitorer l'activité anti-Xa pour adapter les posologies.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Adapter les posologies","style":"cell_b"},{"t":"p","html":"Il est proposé d'adapter les posologies d'HBPM chez les patients de petits poids, les obèses de classe III et plus, et en cas d'insuffisance rénale sévère.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"IR sévère stable","style":"cell_b"},{"t":"p","html":"En cas d'insuffisance rénale sévère stable (DFG 15-30), il est proposé d'utiliser les HBPM en 1re intention selon les schémas AMM (enoxaparine 2000 UI x1/j si DFG 15-30 ; tinzaparine 4500 UI x1/j si DFG &gt;20).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"IR terminale","style":"cell_b"},{"t":"p","html":"En cas d'insuffisance rénale terminale (DFG &lt;15), il est recommandé d'utiliser la calciparine 5000 UI x2/j SC.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Pas de CPI systématique associée","style":"cell_b"},{"t":"p","html":"Il n'est pas recommandé d'associer systématiquement une CPI à une thromboprophylaxie pharmacologique.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"CPI si contre-indication","style":"cell_b"},{"t":"p","html":"La CPI est recommandée en cas de contre-indication à une thromboprophylaxie par anticoagulants, en particulier si risque hémorragique élevé.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Contentions non recommandées","style":"cell_b"},{"t":"p","html":"Les contentions élastiques graduées ne sont pas recommandées, quel que soit le risque thromboembolique veineux.","style":"cell"},{"t":"chip","label":"1-"}]]}]]},{"title":"Réanimation (méta-analyses), acide tranexamique & monitorage","items":[{"t":"section","text":"Patient de réanimation — méta-analyses (suite)","color":"navy"},{"t":"p","html":"<b>Tableau 1</b> — Méta-analyse en réseau HBPM vs HNF en réanimation","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Événement","style":"head_w"},{"t":"p","html":"N études","style":"head_w"},{"t":"p","html":"N patients","style":"head_w"},{"t":"p","html":"Odds ratio (IC95%)","style":"head_w"}],[{"t":"p","html":"TVP","style":"cell"},{"t":"p","html":"6","style":"cell"},{"t":"p","html":"5645","style":"cell"},{"t":"p","html":"0,78 (0,65 – 0,95)","style":"cell"}],[{"t":"p","html":"EP","style":"cell"},{"t":"p","html":"3","style":"cell"},{"t":"p","html":"4447","style":"cell"},{"t":"p","html":"0,67 (0,36 – 1,22)","style":"cell"}],[{"t":"p","html":"Hémorragie majeure","style":"cell"},{"t":"p","html":"4","style":"cell"},{"t":"p","html":"1002","style":"cell"},{"t":"p","html":"1,71 (0,49 – 5,95)","style":"cell"}],[{"t":"p","html":"TIH","style":"cell"},{"t":"p","html":"3","style":"cell"},{"t":"p","html":"4447","style":"cell"},{"t":"p","html":"0,38 (0,15 – 0,98)","style":"cell"}],[{"t":"p","html":"Mortalité totale","style":"cell"},{"t":"p","html":"2","style":"cell"},{"t":"p","html":"1408","style":"cell"},{"t":"p","html":"0,90 (0,68 – 1,18)","style":"cell"}]]},{"t":"p","html":"<b>Tableau 2</b> — Sous-groupe PROTECT : daltéparine vs HNF selon la fonction rénale (insuffisance rénale sévère, n=590)","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Événement","style":"head_w"},{"t":"p","html":"Daltéparine","style":"head_w"},{"t":"p","html":"HNF","style":"head_w"},{"t":"p","html":"Hazard ratio (IC85% *)","style":"head_w"}],[{"t":"p","html":"MTEV","style":"cell"},{"t":"p","html":"10,0 %","style":"cell"},{"t":"p","html":"6,4 %","style":"cell"},{"t":"p","html":"1,87 (0,96 – 3,63)","style":"cell"}],[{"t":"p","html":"Hémorragie majeure","style":"cell"},{"t":"p","html":"8,9 %","style":"cell"},{"t":"p","html":"11,0 %","style":"cell"},{"t":"p","html":"0,89 (0,51 – 1,53)","style":"cell"}]]},{"t":"p","html":"<i>* « IC85% » est bien l'intitulé imprimé dans le document source (vérifié par rendu visuel de la page — pas un artefact d'extraction texte), très probablement une coquille des auteurs pour IC95%. Non corrigé silencieusement, reproduit tel quel.</i>","style":"note"},{"t":"p","html":"<b>Tableau 3</b> — Méta-analyse de la CPI en réanimation","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Comparaison","style":"head_w"},{"t":"p","html":"Événement","style":"head_w"},{"t":"p","html":"n études / n patients","style":"head_w"},{"t":"p","html":"Risque relatif (IC95%)","style":"head_w"}],[{"t":"p","html":"CPI vs contrôle","style":"cell"},{"t":"p","html":"MTEV","style":"cell"},{"t":"p","html":"4 / 1120","style":"cell"},{"t":"p","html":"0,35 (0,18 – 0,68)","style":"cell"}],[{"t":"p","html":"CPI vs contrôle","style":"cell"},{"t":"p","html":"EP","style":"cell"},{"t":"p","html":"2 / 402","style":"cell"},{"t":"p","html":"0,17 (0,06 – 0,50)","style":"cell"}],[{"t":"p","html":"CPI + héparine vs héparine","style":"cell"},{"t":"p","html":"MTEV","style":"cell"},{"t":"p","html":"4 / 2777","style":"cell"},{"t":"p","html":"0,55 (0,24 – 1,27)","style":"cell"}],[{"t":"p","html":"CPI + héparine vs héparine","style":"cell"},{"t":"p","html":"EP","style":"cell"},{"t":"p","html":"3 / 2661","style":"cell"},{"t":"p","html":"0,72 (0,31 – 1,69)","style":"cell"}]]},[{"t":"section","text":"Acide tranexamique et thromboprophylaxie veineuse","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Pas de modification","style":"cell_b"},{"t":"p","html":"Il est recommandé de ne pas modifier les modalités de thromboprophylaxie en cas d'administration d'acide tranexamique.","style":"cell"},{"t":"chip","label":"1-"}]]}],{"t":"p","html":"<i>Essais randomisés et méta-analyses concordants : l'acide tranexamique n'augmente pas l'incidence des ETEV péri-opératoires (chirurgie générale, orthopédique, cardiaque, obstétrique, traumatologie), y compris lorsque l'initiation de l'AOD est repoussée au lendemain d'une chirurgie orthopédique majeure.</i>","style":"note"},[{"t":"section","text":"Monitorage biologique — surveillance du niveau d'anticoagulation","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Pas de mesure sous HBPM","style":"cell_b"},{"t":"p","html":"Il est proposé de ne pas mesurer l'activité anti-Xa au cours d'une thromboprophylaxie par HBPM.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Pas de mesure AOD/fondaparinux/HNF","style":"cell_b"},{"t":"p","html":"Les experts proposent de ne pas mesurer le niveau d'anticoagulation au cours d'une prophylaxie par AOD, fondaparinux ou HNF.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Poids extrêmes / IR","style":"cell_b"},{"t":"p","html":"Chez les patients de poids extrêmes et les insuffisants rénaux, il est proposé de ne pas mesurer le niveau d'anticoagulation.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Si hémorragie","style":"cell_b"},{"t":"p","html":"En cas d'hémorragie sous thromboprophylaxie (AOD, HBPM, HNF, fondaparinux), les experts suggèrent de déterminer le niveau d'anticoagulation pour estimer sa contribution à l'hémorragie et aider la prise en charge.*","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Procédure d'établissement","style":"cell_b"},{"t":"p","html":"Les experts suggèrent d'établir une procédure institutionnelle définissant le bon usage de la mesure du niveau d'anticoagulation (conditions de prélèvement, valeurs seuils) et la prise en charge.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"* Cf RFE 2024 SFMU/SFAR/GIHP/SFTH dédiée à la prise en charge des hémorragies sous anticoagulant.","style":"note"}],{"t":"p","html":"<i>Activités anti-Xa habituellement observées sous enoxaparine 1 injection/j : 0,2-0,5 UI/mL au pic (H4). Aucun essai randomisé n'a démontré le bénéfice d'une adaptation posologique guidée par l'anti-Xa pour réduire les complications ; variabilité inter-tests importante (CV 12-33% pour &lt;0,35 UI/mL).</i>","style":"note"},[{"t":"section","text":"Monitorage biologique — surveillance plaquettaire et risque de TIH","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Numération plaquettaire","style":"cell_b"},{"t":"p","html":"Il est proposé de surveiller la numération plaquettaire pour un dépistage précoce de TIH : sous HBPM, une à deux fois par semaine entre J4 et J14 puis une fois par semaine pendant un mois si le traitement est poursuivi ; sous HNF, deux à trois fois par semaine entre J4 et J14 puis une fois par semaine pendant un mois ; et en cas de survenue d'une thrombose malgré la thromboprophylaxie.","style":"cell"},{"t":"chip","label":"2+"}]]}]]},{"title":"TVP distale post-opératoire & Figure 2","items":[[{"t":"section","text":"Découverte d'une thrombose veineuse profonde distale post-opératoire","color":"navy"},null,{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Pas de dépistage systématique","style":"cell_b"},{"t":"p","html":"Il est recommandé de ne pas faire de dépistage systématique des TVP asymptomatiques post-opératoires.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Pas de traitement systématique","style":"cell_b"},{"t":"p","html":"Il est recommandé de ne pas traiter systématiquement les TVP distales isolées post-opératoires par un anticoagulant à dose curative.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Évaluer les risques","style":"cell_b"},{"t":"p","html":"En cas de TVP distale isolée post-opératoire, il est recommandé d'évaluer le risque d'extension thrombotique (TVPd bilatérale ou multiple, antécédent de MTEV, cancer actif) et le risque hémorragique (patient et procédure) pour décider des modalités thérapeutiques.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Sans FdR d'extension","style":"cell_b"},{"t":"p","html":"En l'absence de facteur de risque d'extension, il est proposé d'introduire ou poursuivre la thromboprophylaxie par anticoagulant pendant 35 jours, sans contrôle écho-Doppler.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"FdR extension + risque hémorragique faible","style":"cell_b"},{"t":"p","html":"Il est proposé d'introduire un traitement anticoagulant à dose curative pendant 6 à 12 semaines.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"FdR extension + risque hémorragique élevé","style":"cell_b"},{"t":"p","html":"Les experts proposent d'introduire ou poursuivre la thromboprophylaxie pendant 6 à 12 semaines (contrôle écho-Doppler possible à J7 ; passage à dose curative si le risque hémorragique diminue).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Anticoagulant contre-indiqué","style":"cell_b"},{"t":"p","html":"En cas de contre-indication à un traitement anticoagulant préventif, il est proposé de ne pas anticoaguler, de ne pas poser de filtre cave, et de contrôler l'écho-Doppler à J7 (recherche d'extension proximale).","style":"cell"},{"t":"chip","label":"2-"}]]}],{"t":"p","html":"<i>Les TVP distales (sous-poplitées, troncs jambiers et veines musculaires) représentent jusqu'à la moitié des TVP diagnostiquées, le plus souvent asymptomatiques (33-46% de dépistage systématique après PTG). Risque d'extension proximale/EP sans anticoagulant : 5-10% (jusqu'à 20% si cancer). Essai PROTHEGE : prophylaxie étendue à 35j réduit les complications des TVPd vs prophylaxie courte de 10j (extension/récidive 4,5% vs 14,8%, p&lt;0,001).</i>","style":"note"},{"t":"section","text":"Figure 2 (p.74) — Prise en charge d'une TVP distale post-opératoire","color":"teal-dark"},{"t":"p","html":"<i>Redessin structuré du diagramme source (image pure).</i>","style":"note"},{"t":"table","rows":[[{"t":"p","html":"TVP distale isolée post-opératoire — Risque d'extension thrombotique ? (TVPd bilatérale ou multiple >1 veine ; antécédent de MTEV ; cancer actif)","style":"flow_lbl"}]]},{"t":"table","rows":[[{"t":"p","html":"Absence de facteur de risque d'extension -> thromboprophylaxie par anticoagulant pendant 35 jours.","style":"body_sm"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"Présence d'un facteur de risque d'extension -> Risque hémorragique lié au patient ou à la procédure ?","style":"flow_lbl"}]]},{"t":"table","rows":[[{"t":"p","html":"Risque hémorragique FAIBLE -> traitement anticoagulant à dose curative pendant 6 à 12 semaines.","style":"body_sm"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"Risque hémorragique ÉLEVÉ -> thromboprophylaxie par anticoagulant pendant 6 à 12 semaines, ± écho-Doppler à J7, ± relais secondaire par traitement à dose curative si le risque diminue.","style":"body_sm"},{"t":"chip","label":"AE"}]]},{"t":"table","rows":[[{"t":"p","html":"Anticoagulant contre-indiqué -> pas de traitement anticoagulant, pas de filtre cave, contrôle écho-Doppler à J7 (extension proximale).","style":"body_sm"},{"t":"chip","label":"2-"}]]}]},{"title":"Figure de synthèse & sources","items":[{"t":"section","text":"Figure 3 (p.79) — Thromboprophylaxie post-opératoire : schéma de synthèse","color":"teal-dark"},{"t":"p","html":"<i>Redessin structuré du diagramme-image source (le plus utile du document : condense en un seul schéma la quasi-totalité des recommandations générales déjà détaillées dans cette fiche). La thromboprophylaxie après PTH/PTG fait l'objet de la Figure 1 dédiée (page précédente), non reprise ici.</i>","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Risque thromboembolique veineux de la chirurgie ?","style":"flow_lbl"}]]},{"t":"table","rows":[[{"t":"p","html":"FAIBLE + absence de FdR thromboembolique veineux du patient# -> pas de prophylaxie pharmacologique ni mécanique.","style":"body_sm"},{"t":"chip","label":"1+"}]]},{"t":"table","rows":[[{"t":"p","html":"FAIBLE + FdR patient# présent (1 majeur ou plusieurs mineurs) -> anticoagulant, durée minimum 7 jours.","style":"body_sm"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"ÉLEVÉ -> anticoagulant, durée fonction de la chirurgie (minimum 7 jours ; 4 semaines pour la chirurgie abdomino-pelvienne à risque élevé).","style":"body_sm"},{"t":"chip","label":"1+"}]]},{"t":"table","rows":[[{"t":"p","html":"Règles transversales (tous les cas)","style":"flow_lbl"}]]},{"t":"table","rows":[[{"t":"p","html":"Déambulation précoce et hydratation optimale, dans tous les cas.","style":"body_sm"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"Chirurgie programmée : anticoagulant à débuter en post-opératoire, entre H12 et H24 (entre H6 et H12 si risque thromboembolique veineux élevé lié au patient).","style":"body_sm"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"Associer anticoagulant + CPI si très haut risque thromboembolique veineux (ex. FdR majeur lié au patient + risque chirurgical élevé).","style":"body_sm"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"Il n'y a pas d'indication à la contention élastique graduée.","style":"body_sm"},{"t":"chip","label":"1-"}]]},{"t":"panel","tone":"default","content":[{"t":"p","html":"<b>Rappel — facteurs de risque thromboembolique veineux du patient# :</b> détail complet en Q2 (page 2 de cette fiche). Majeurs : ATCD personnel d'ETEV, thrombophilie majeure connue, cancer actif, obésité morbide (IMC ≥ 40). Modérés/mineurs : âge ≥ 75 ans, insuffisance cardiorespiratoire/BPCO, insuffisance rénale sévère, maladie inflammatoire chronique, œstrogènes, grossesse/post-partum, obésité classe I-II, alitement, déficit neurologique récent, immobilisation post-opératoire.","style":"body_sm"},null,{"t":"p","html":"<b>Rappel — fonction rénale (DFG &lt;30) :</b> enoxaparine 2000 UI x1/j si DFG 15-30 ; tinzaparine 4500 UI x1/j si DFG &gt;20 ; calciparine 5000 UI x2/j si DFG &lt;15 (tableau complet en Q11).","style":"body_sm"},null,{"t":"p","html":"<b>Rappel — obésité (IMC ≥ 40) :</b> HBPM (enoxaparine 4000 UI x2/j, ou 6000 UI x2/j si &gt;150 kg ; daltéparine 5000 UI x2/j ; tinzaparine 75 UI/kg x1/j) ou fondaparinux 5 mg x1/j ou AOD à posologie habituelle. IMC 30-39 : schémas posologiques standards (détail en Q12).","style":"body_sm"}]},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Prévention de la maladie thromboembolique veineuse péri-opératoire » — Recommandations Formalisées d'Experts du Groupe d'intérêt en Hémostase Péri-opératoire (GIHP), en collaboration avec la SFAR, la SFTH et la SFMV, endossées par la SFCD, la SFPT et le réseau INNOVTE. Actualisation des recommandations SFAR de 2011. Coordination : A. Godier, D. Lasne, G. Pernod, et al. ; 37 experts GIHP/SFTH/SFMV répartis en groupes de travail par question PICO.","style":"source"},{"t":"p","html":"<b>Version :</b> 16.5.2024. Validation SFAR le 30.04.2024, SFTH le 23.02.2024, SFVM en janvier 2024. Endossement SFCD (02/2024), SFPT (05/2024), réseau INNOVTE (12/2023).","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> GRADE, format PICO. Recommandation forte (1+/1-) si niveau de preuve global fort ; optionnelle (2+/2-) si modéré/faible ; avis d'experts (AE) en l'absence de littérature suffisante. Validation par vote (n=37) : accord fort si ≥70% pour et &lt;20% contre. Vérification exhaustive sur l'extraction texte complète (79 pages) : 100% des 77 recommandations retrouvées portent la mention d'accord « Fort », aucune exception — d'où l'absence de colonne « Accord » dans cette fiche (voir page 1).","style":"source"},{"t":"p","html":"<b>Couverture :</b> intégralité des 77 recommandations individuelles graduées des 14 questions PICO (21 sous-thèmes cliniques), transcrites ici en tableaux compacts thème/recommandation/grade. Les 3 figures (PTH/PTG p.16 ; TVP distale p.74 ; synthèse p.79 — images pures) sont redessinées en tableaux/panneaux structurés fidèles aux issues cliniques et grades imprimés sur les diagrammes originaux. Le tableau couleur « fonction rénale » (p.52, image pure) est reproduit verbatim cellule par cellule. Les tableaux des délais neuraxiaux (p.41) et des méta-analyses réanimation (p.63-64, Tableaux 1-3) sont reproduits verbatim. L'argumentaire complet et les références bibliographiques (~400 citations) ne sont pas repris : se référer au texte intégral.","style":"source"},{"t":"p","html":"<b>Double extraction :</b> un agent indépendant (contexte vierge, même texte source complet) a produit son propre inventaire exhaustif section par section ; le total de 77/77 recommandations et leur répartition par section ont été confirmés à l'identique, sans écart.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Il reprend l'intégralité des recommandations graduées et des tableaux/figures de la RFE source, mais ne remplace pas le texte intégral (argumentaire complet, ~400 références bibliographiques) et n'est ni édité ni validé par le GIHP, la SFAR, la SFTH ou la SFMV. En cas de doute, se référer au texte intégral et/ou à un avis spécialisé.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/prevention-de-la-maladie-thromboembolique-veineuse-peri-operatoire/';

insert into public.document_specialties (document_id, specialty_id)
