on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/pancreatite-aigue-grave-du-patient-adulte-en-soins-critiques/' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'pancreatite',
  card_json = $mgjson${"badge":"GRADE","title":"Pancréatite aigüe grave en soins critiques","short":"14 questions PICO réparties en 3 champs : évaluation et admission en soins critiques (critères de gravité, examens des 72 premières heures, surveillance de la pression intra-abdominale — Tableau 1 du score de Marshall modifié, Figure 1 de l'algorithme diagnostique, Annexe 1 des scores de risque BISAP/SIRS/APACHE/Ranson/Balthazar/CTSI) ; prise en charge à la phase initiale (hémodynamique, respiratoire, nutrition entérale/parentérale, CPRE, thérapeutiques non conventionnelles, antalgie) ; prise en charge des complications évolutives (antibioprophylaxie, diagnostic et drainage de la nécrose infectée, antibiothérapie curative, complications vasculaires, thrombose veineuse splanchnique). 24 recommandations + 4 questions sans recommandation possible.","society":"SFAR, en collaboration avec la SNFGE, la SFR, la SFNCM et la SFED","version":"2021 (validé CA SFAR 30/06/2021)","validated":"Coordonnateur d'experts : S. Jaber (Montpellier)","methodology":"GRADE® (1+/1-/2+/2-) + avis d'experts + absence de recommandation — actualise les recommandations SFAR/CNGOF 2001","pages":48,"section":"Réanimation"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"pancreatite","sections":[{"title":"Contexte, méthodologie & Champ 1 — Évaluation/admission","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> prise en charge du patient adulte de soins critiques (réanimation, surveillance continue, soins intensifs) présentant une pancréatite aigüe grave. RFE SFAR 2021, en collaboration avec la SNFGE, la SFR, la SFNCM et la SFED, actualisant les précédentes recommandations françaises (SFAR/CNGOF 2001). 14 questions PICO réparties en 3 champs, méthode GRADE® : <b>24 recommandations</b> formalisées (accord fort pour 100 % d'entre elles après 1 à 2 tours de cotation) + 4 questions pour lesquelles aucune recommandation n'a pu être émise faute de données.","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Méthodologie GRADE® :</b> qualité des preuves Haute/Modérée/Basse/Très basse → force de recommandation binaire, positive ou négative, Forte (<b>GRADE 1+/1-</b> : « il est recommandé/il n'est pas recommandé ») ou Faible (<b>GRADE 2+/2-</b> : « il est/n'est probablement pas recommandé »). Quand la méthode GRADE ne s'applique pas : <b>avis d'experts</b> (chip « AE »), validé à &gt;70 % d'accord. Quand aucune réponse n'a pu être apportée : <b>« absence de recommandation »</b> (chip « SR »). <b>Incohérence interne à la source, non résolue silencieusement :</b> le résumé français et l'abstract anglais du document annoncent tous deux « 8 recommandations de niveau GRADE 1+/-, 12 de niveau GRADE 2+/- » — chiffre qui correspond exactement au tally direct des 20 énoncés GRADE-tagués du corps du texte (6×1+, 2×1-, 6×2+, 6×2-). Mais la section « 2.2 Recommandations » du même document annonce l'inverse : « 9 GRADE 1+/-, 11 GRADE 2+/- ». Cette fiche retient le compte vérifié par tally direct (8/12), cohérent avec les deux résumés, sans trancher laquelle des deux mentions internes de la source est erronée.","style":"body_sm"}},{"t":"section","text":"Contexte et définitions","color":"navy"},{"t":"p","html":"Prévalence ≈ 15 000 cas/an en France. Dans 80-90 % des cas, pancréatite aigüe œdémateuse interstitielle, de gravité modérée. Dans 10-20 % des cas : forme grave, pouvant nécessiter une prise en charge en soins critiques. <b>Classification révisée d'Atlanta</b> : pancréatite peu grave (absence de défaillance d'organe et de complication locale/systémique), modérément grave (défaillance d'organe transitoire ou complication locale/exacerbation d'une maladie préexistante), <b>grave</b> (défaillance d'organe <b>persistante &gt; 48 h</b>). Complications locales : collections liquidiennes, nécrose pancréatique/péri-pancréatique, pseudokyste, hémorragie. Étiologies : lithiasique (40-50 %), alcool (20-30 %), hypercalcémie, hypertriglycéridémie, médicamenteuse, post-CPRE (2-20 %), indéterminée (10-25 %).","style":"body_sm"},{"t":"section","text":"CHAMP 1 — Évaluation et admission en soins critiques","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R1.1","style":"cell_b"},{"t":"p","html":"Décider de l'admission en soins critiques sur la présence d'une pancréatite aigüe grave (défaillance(s) d'organe(s) cardiovasculaire/respiratoire/rénale, avec ou sans nécrose infectée) ou jugée à risque de le devenir après évaluation multidisciplinaire — aucun score isolé ne peut à ce jour être recommandé pour cette décision.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R1.2.1","style":"cell_b"},{"t":"p","html":"En cas de doute diagnostique après anamnèse/examen clinique/lipasémie, ou en l'absence de réponse au traitement ou d'aggravation clinique : réaliser un scanner abdomino-pelvien le plus tôt possible pour confirmer le diagnostic positif.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R1.2.2","style":"cell_b"},{"t":"p","html":"Réaliser le plus rapidement possible : bilan hépatique (ASAT, ALAT, γGT, PAL, bilirubine), triglycéridémie, calcémie et échographie abdominale, pour préciser le diagnostic étiologique.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R1.3","style":"cell_b"},{"t":"p","html":"Chez le patient ventilé de façon invasive : monitorer la pression intra-abdominale pour diagnostiquer et traiter précocement une hypertension intra-abdominale (retrouvée chez plus de la moitié des patients, facteur de mortalité indépendant).","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"<b>Tableau 1 — Score modifié de Marshall</b> (définit les défaillances d'organe ; score ≥ 2 pour un organe = défaillance de cet organe)","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Organe","style":"head_w"},{"t":"p","html":"0","style":"head_w"},{"t":"p","html":"1","style":"head_w"},{"t":"p","html":"2","style":"head_w"},{"t":"p","html":"3","style":"head_w"},{"t":"p","html":"4","style":"head_w"}],[{"t":"p","html":"Poumon (PaO2/FiO2*)","style":"cell"},{"t":"p","html":">400","style":"cell"},{"t":"p","html":"301-400","style":"cell"},{"t":"p","html":"201-300","style":"cell"},{"t":"p","html":"101-200","style":"cell"},{"t":"p","html":"≤100","style":"cell"}],[{"t":"p","html":"Rein (créatininémie, µmol/L)","style":"cell"},{"t":"p","html":"≤134","style":"cell"},{"t":"p","html":"134-169","style":"cell"},{"t":"p","html":"170-310","style":"cell"},{"t":"p","html":"311-439","style":"cell"},{"t":"p","html":">439","style":"cell"}],[{"t":"p","html":"Cardiovasculaire (PAS, mmHg**)","style":"cell"},{"t":"p","html":">90","style":"cell"},{"t":"p","html":"<90, répond au\nremplissage","style":"cell"},{"t":"p","html":"<90, ne répond pas\nau remplissage","style":"cell"},{"t":"p","html":"<90, pH<7,3","style":"cell"},{"t":"p","html":"<90, pH<7,2","style":"cell"}]]},{"t":"p","html":"*Patient non ventilé : FiO2 estimée à 21 % (air ambiant), 25 % sous 2 L/min d'O2, <b>30 % sous 2 L/min d'O2 (sic — le texte source répète le même débit pour 25 % et 30 %, incohérence non résolue silencieusement ici)</b>, 40 % sous 6-8 L/min, 50 % sous 9-10 L/min. **Sans amines.","style":"note"},{"t":"p","html":"<b>Figure 1 — Éléments du diagnostic positif, étiologique, des modalités d'hospitalisation et de la surveillance précoce d'une pancréatite aigüe grave</b> (algorithme, transcrit fidèlement depuis la source — image pure page 46, aucune couche texte)","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"<b>Suspicion de pancréatite aigüe (PA) grave</b>","style":"flowbox"}]]},{"t":"table","rows":[[{"t":"p","html":"↓","style":"arrow"},{"t":"p","html":"↓","style":"arrow"}]]},{"t":"table","rows":[[{"t":"table","rows":[[{"t":"p","html":"<b>Diagnostic positif</b><br/>• Douleurs abdominales typiques<br/>• Lipasémie &gt;3N<br/>• Scanner abdomino-pelvien si : doute diagnostique, ou absence de réponse aux traitements et/ou aggravation clinique","style":"flowbox"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>Diagnostic étiologique</b> (le plus rapidement possible)<br/>• Bilan hépatique (ASAT, ALAT, γGT, PAL, bilirubine)<br/>• Triglycéridémie<br/>• Calcémie<br/>• Échographie abdominale","style":"flowbox"}]]}]]},{"t":"table","rows":[[{"t":"p","html":"↓","style":"arrow"},{"t":"p","html":"↓","style":"arrow"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>Diagnostic de sévérité</b><br/>• Défaillances d'organes<br/>• Évaluation multidisciplinaire du risque d'aggravation secondaire (Annexe 1), selon des critères clinico-biologiques et des critères radiologiques (scanner au moins 48-72 h après l'hospitalisation)","style":"flowbox"}]]},{"t":"table","rows":[[{"t":"p","html":"↓  OUI","style":"arrow"},{"t":"p","html":"NON  ↓","style":"arrow"}]]},{"t":"table","rows":[[{"t":"table","rows":[[{"t":"p","html":"<b>Surveillance renforcée en unité de soins critiques</b> (incluant monitorage de la pression intra-abdominale si possible)","style":"flowbox"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>Surveillance dans une unité conventionnelle</b>","style":"flowbox"}]]}]]}]},{"title":"Champ 2 — Prise en charge à la phase initiale","items":[{"t":"section","text":"CHAMP 2 — Prise en charge à la phase initiale","color":"navy"},{"t":"p","html":"<b>Hémodynamique</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R2.1","style":"cell_b"},{"t":"p","html":"Ne pas utiliser systématiquement une stratégie de remplissage vasculaire massif (3-5 mL/kg/h pendant les premières 24 h) : pas de bénéfice démontré sur la mortalité, et risque accru d'insuffisance rénale aigüe (méta-analyse, RR 2,17).","style":"cell"},{"t":"chip","label":"2-"}]]},{"t":"p","html":"<b>Respiratoire</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R2.2","style":"cell_b"},{"t":"p","html":"Ne pas utiliser de probiotiques par voie entérale pour réduire la mortalité ou les pneumonies associées aux soins (l'unique essai randomisé disponible montre une surmortalité et un excès d'ischémie mésentérique sous probiotiques).","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"—","style":"cell_b"},{"t":"p","html":"Aucune recommandation possible sur la ventilation non-invasive, l'oxygénothérapie à haut débit, la stratégie de ventilation mécanique invasive ou la stratégie de sédation pour prévenir les complications respiratoires (absence d'étude).","style":"cell"},{"t":"chip","label":"SR"}]]},{"t":"p","html":"<b>Nutrition</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R2.3","style":"cell_b"},{"t":"p","html":"Utiliser une nutrition entérale plutôt qu'une nutrition parentérale exclusive (réduction de mortalité démontrée par plusieurs méta-analyses, y compris dans les formes graves).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R2.4","style":"cell_b"},{"t":"p","html":"Ne pas introduire systématiquement une nutrition entérale précoce (24-48 premières heures) dans le seul but de réduire la mortalité, les infections ou les défaillances d'organes — bénéfice non démontré sur ces critères pris isolément.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"R2.5","style":"cell_b"},{"t":"p","html":"Ne pas recourir en première intention à une sonde naso-jéjunale pour améliorer la tolérance de la nutrition entérale (pas de différence vs sonde naso-gastrique) ; réserver la voie jéjunale à l'impossibilité de la voie gastrique.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"R2.6","style":"cell_b"},{"t":"p","html":"Ne pas privilégier les mélanges semi-élémentaires/élémentaires, ni l'immunonutrition entérale, par rapport à une nutrition entérale polymérique standard.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"R2.7","style":"cell_b"},{"t":"p","html":"En cas d'intolérance avérée ou de contre-indication à la nutrition entérale : ajouter de la glutamine IV (0,20 g/kg/j de L-glutamine) à la nutrition parentérale.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R2.8","style":"cell_b"},{"t":"p","html":"Ne pas utiliser d'antioxydants en complément de la nutrition entérale ou parentérale.","style":"cell"},{"t":"chip","label":"2-"}]]},{"t":"p","html":"<b>Prise en charge interventionnelle médico-chirurgicale en urgence</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R2.9","style":"cell_b"},{"t":"p","html":"Pancréatite biliaire : ne réaliser une CPRE en urgence que chez les patients avec angiocholite associée — pas de bénéfice démontré d'une CPRE systématique en l'absence d'angiocholite (essai APEC notamment).","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"<b>Thérapeutiques non conventionnelles</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R2.10","style":"cell_b"},{"t":"p","html":"Ne pas utiliser de thérapeutique médicamenteuse non conventionnelle (aucune des nombreuses molécules testées — aprotinine, gabexate, octréotide, somatostatine, lexipafant, etc. — ne réduit la mortalité).","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"R2.11","style":"cell_b"},{"t":"p","html":"Pancréatite hypertriglycéridémique en échec du traitement médical de 1<sup>re</sup> intention (fibrate, héparine + insuline) : envisager des échanges plasmatiques pour réduire rapidement une hypertriglycéridémie sévère (&gt;11,3 mmol/L) ou très sévère (&gt;22,4 mmol/L), objectif &lt;5,7 mmol/L.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Antalgie</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"—","style":"cell_b"},{"t":"p","html":"Aucune donnée ne permet de recommander un type d'analgésie particulier (morphiniques, anesthésiques locaux IV, AINS, paracétamol, péridurale) pour réduire la morbi-mortalité.","style":"cell"},{"t":"chip","label":"SR"}]]}]},{"title":"Champ 3 — Prise en charge des complications évolutives","items":[{"t":"section","text":"CHAMP 3 — Prise en charge des complications évolutives","color":"navy"},{"t":"p","html":"<b>Traitement anti-infectieux préventif</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R3.1","style":"cell_b"},{"t":"p","html":"Ne pas administrer de traitement anti-infectieux intraveineux préventif en l'absence d'infection documentée : pas de réduction démontrée de la mortalité, des infections de coulées de nécrose ni des infections extra-pancréatiques.","style":"cell"},{"t":"chip","label":"2-"}]]},{"t":"p","html":"<b>Diagnostic d'infection de nécrose pancréatique</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R3.2","style":"cell_b"},{"t":"p","html":"Ne pas se limiter à l'examen clinique et à la CRP : s'appuyer aussi sur la procalcitonine et la tomodensitométrie abdominale (air extra-digestif intra/extra-pancréatique) pour établir le diagnostic.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R3.3","style":"cell_b"},{"t":"p","html":"Ne pas réaliser de ponction à l'aiguille fine pour le diagnostic d'infection de nécrose en l'absence de signes cliniques de sepsis et/ou de scanner évocateur de surinfection (faux négatifs 20-25 %, risque de complications iatrogènes).","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Drainage de la nécrose pancréatique infectée</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R3.4","style":"cell_b"},{"t":"p","html":"Nécrose pancréatique infectée : réaliser un drainage, et ne pas se limiter à une antibiothérapie systémique seule.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R3.5.1","style":"cell_b"},{"t":"p","html":"Privilégier en première intention une approche graduée « mini-invasive » (endoscopique et/ou radiologique percutanée) pour le drainage, selon l'expertise locale et la localisation des coulées de nécrose.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R3.5.2","style":"cell_b"},{"t":"p","html":"En l'absence d'équipe d'endoscopie et/ou de radiologie interventionnelle entraînée localement au drainage mini-invasif : transférer le patient vers un centre expert.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Traitement anti-infectieux curatif</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R3.6.1","style":"cell_b"},{"t":"p","html":"Infection de coulée de nécrose : administrer une antibiothérapie probabiliste ciblant les entérobactéries résistantes, Enterococcus faecium, Pseudomonas aeruginosa et les levures (surinfections fongiques ≈30 % des cas).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"—","style":"cell_b"},{"t":"p","html":"Aucune recommandation possible sur la molécule précise à privilégier (diffusion pancréatique des antibiotiques mal établie).","style":"cell"},{"t":"chip","label":"SR"}],[{"t":"p","html":"R3.6.2","style":"cell_b"},{"t":"p","html":"Adapter secondairement l'antibiothérapie aux résultats microbiologiques (ponction percutanée, écho-endoscopie, drainage chirurgical, hémocultures) après avis pluridisciplinaire réanimation/gastro-entérologie/infectiologie, pour réduire le spectre et préserver l'écologie bactérienne.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Complications vasculaires</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Niveau","style":"head_w_c"}],[{"t":"p","html":"R3.7","style":"cell_b"},{"t":"p","html":"Complication hémorragique viscérale (rupture de pseudo-anévrysme le plus souvent, mortalité 34-52 %) : privilégier en priorité une technique de radiologie interventionnelle endovasculaire (moindre surmortalité qu'une chirurgie de sauvetage : 13 % vs 29 % dans une étude rétrospective).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"—","style":"cell_b"},{"t":"p","html":"Thrombose veineuse splanchnique (14-22 % des pancréatites aigües) : données insuffisantes pour statuer sur le rapport bénéfice/risque d'une anticoagulation préventive (facteurs de risque) ou curative (TVS avérée).","style":"cell"},{"t":"chip","label":"SR"}]]}]},{"title":"Annexe 1 — Scores de risque d'aggravation","items":[{"t":"section","text":"Annexe 1 — Critères et scores de risque d'aggravation","color":"navy"},{"t":"p","html":"Liste des critères et scores existants à prendre en compte pour juger du risque d'aggravation d'une pancréatite aigüe (aucun score isolé recommandé à ce jour — cf. R1.1). Reproduits intégralement depuis la source.","style":"body_sm"},{"t":"p","html":"<b>Critères biologiques</b> — CRP &gt; 150 mg/L dans les 72 h suivant l'admission. Autres proposés : urée sanguine &gt; 7 mmol/L, hématocrite &gt; 44 %, procalcitonine &gt; 3,8 ng/mL dans les 96 h, hyperlactatémie.","style":"body_sm"},{"t":"p","html":"<b>Score BISAP</b> ≥ 2 (1 point/critère) : urée &gt; 8,9 mmol/L · SIRS · altération de la conscience · âge &gt; 60 ans · épanchement pleural radiographique.","style":"body_sm"},{"t":"p","html":"<b>SIRS</b> (≥ 2 critères) : température &lt; 36 °C ou &gt; 38 °C · FC &gt; 90/min · FR &gt; 20/min ou PaCO2 &lt; 32 mmHg · leucocytes &gt; 12 000/mm³, &lt; 4 000/mm³ ou formes immatures circulantes &gt; 10 %.","style":"body_sm"},{"t":"p","html":"<b>Score APACHE</b> ≥ 8 (calculé à l'admission ou dans les 72 premières heures).","style":"body_sm"},{"t":"p","html":"<b>Score de Ranson</b> ≥ 3 (1 point/critère) — à l'admission : âge &gt; 55 ans, leucocytes &gt; 16 000/mm³, LDH &gt; 1,5N, ASAT &gt; 6N, glycémie &gt; 11 mmol/L ; entre l'admission et la 48<sup>e</sup> heure : chute de l'hématocrite &gt; 10 points, élévation de l'urée sanguine &gt; 1,8 mmol/L, calcémie &lt; 2 mmol/L, PaO2 &lt; 60 mmHg, chute des bicarbonates &gt; 4 mEq/L, séquestration liquidienne &gt; 6 L de perfusion en 48 h.","style":"body_sm"},{"t":"p","html":"<b>Critères radiologiques</b> (scanner réalisé à partir de la 48<sup>e</sup> heure)","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Score de Balthazar","style":"head_w"},{"t":"p","html":"Description","style":"head_w"}],[{"t":"p","html":"Grade A","style":"cell"},{"t":"p","html":"Pancréas normal","style":"cell"}],[{"t":"p","html":"Grade B","style":"cell"},{"t":"p","html":"Élargissement focal ou diffus du pancréas","style":"cell"}],[{"t":"p","html":"Grade C","style":"cell"},{"t":"p","html":"Pancréas hétérogène + densification de la graisse péri-pancréatique","style":"cell"}],[{"t":"p","html":"Grade D","style":"cell"},{"t":"p","html":"Coulée péri-pancréatique unique","style":"cell"}],[{"t":"p","html":"Grade E","style":"cell"},{"t":"p","html":"Coulées multiples, ou signes de surinfection (bulles de gaz)","style":"cell"}]]},{"t":"p","html":"Un score de Balthazar de haut grade, ou un <b>CT Severity Index (CTSI) ≥ 3</b> (prédit une morbi-mortalité ≈17 %), sont associés à la sévérité.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Aspects morphologiques","style":"head_w"},{"t":"p","html":"Pts","style":"head_w"},{"t":"p","html":"Étendue de la nécrose","style":"head_w"},{"t":"p","html":"Pts","style":"head_w"}],[{"t":"p","html":"Pancréas morphologiquement normal","style":"cell"},{"t":"p","html":"0","style":"cell"},{"t":"p","html":"0 % de la glande nécrosée","style":"cell"},{"t":"p","html":"0","style":"cell"}],[{"t":"p","html":"Augmentation de volume","style":"cell"},{"t":"p","html":"1","style":"cell"},{"t":"p","html":"< 30 % de la glande nécrosée","style":"cell"},{"t":"p","html":"2","style":"cell"}],[{"t":"p","html":"Infiltration de la graisse péripancréatique","style":"cell"},{"t":"p","html":"2","style":"cell"},{"t":"p","html":"30-50 % de la glande nécrosée","style":"cell"},{"t":"p","html":"4","style":"cell"}],[{"t":"p","html":"Une seule collection extrapancréatique","style":"cell"},{"t":"p","html":"3","style":"cell"},{"t":"p","html":"> 50 % de la glande nécrosée","style":"cell"},{"t":"p","html":"6","style":"cell"}],[{"t":"p","html":"Au moins deux collections, ou une collection\ncontenant du gaz","style":"cell"},{"t":"p","html":"4","style":"cell"},{"t":"p","html":"","style":"cell"},{"t":"p","html":"","style":"cell"}]]},{"t":"p","html":"Aspects morphologiques : valeur de 0 à 4. Étendue de la nécrose : valeur de 0 à 6. <b>CTSI = somme des deux valeurs.</b>","style":"note"},{"t":"p","html":"Fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend l'intégralité des 24 recommandations et des 4 questions sans recommandation possible, ainsi que le Tableau 1, la Figure 1 et l'Annexe 1 du texte source, mais ne remplace pas le texte intégral et n'est ni éditée ni validée par la SFAR, la SNFGE, la SFR, la SFNCM ou la SFED. En cas de doute, se référer au texte intégral et/ou à un avis spécialisé.","style":"source"}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/pancreatite-aigue-grave-du-patient-adulte-en-soins-critiques/';

