where d.source_url = 'https://sfar.org/securisation-des-procedures-a-risques-en-reanimation-risque-infectieux-exclu/' and s.slug in ('anesthesie_reanimation', 'medecine_intensive_reanimation')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/securisation-des-procedures-a-risques-en-reanimation-risque-infectieux-exclu/' and s.acronym in ('SRLF', 'SFAR')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/securisation-des-procedures-a-risques-en-reanimation-risque-infectieux-exclu/' and d.society_id is null and s.acronym = 'SRLF';
update public.documents set
  fiche_key = 'securisation_proc',
  card_json = $mgjson${"badge":"ACCORD","title":"Sécurisation des procédures à risques en réanimation","short":"Pratiques de sécurité (« safety practices ») en réanimation, risque infectieux explicitement exclu : taxonomie EI/EPR et indicateurs, épidémiologie, organisation structurelle et managériale (protocoles, culture sécurité), sécurisation du matériel/dispositifs médicaux, ventilation mécanique (intubation, trachéotomie, sevrage, extubation, VNI), procédures circulatoires (vasoactifs, cathéters artériels/veineux centraux/artériels pulmonaires), épuration extra-rénale, spécificités pédiatriques — plus une zone d'indécision explicite de 3 propositions (ni accord ni désaccord), disclosée comme catégorie distincte.","society":"SRLF / SFAR","version":"2008 (Ann Fr Anesth Reanim 2008;27:e43-e51)","validated":"Groupes d'experts de la SRLF et de la SFAR","methodology":"Accord fort/faible (méthode RAND/UCLA, pas de GRADE) + zone d'indécision explicite","pages":9,"section":"Réanimation"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"securisation_proc","sections":[{"title":"2008 — 8 champs, accord fort/faible + zone d'indécision","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ d'application :</b> pratiques de sécurité (« safety practices ») pour les patients de <b>réanimation</b> — <b>risque infectieux explicitement exclu</b> du champ de ce document (fait l'objet d'autres référentiels SFAR/SRLF/CLIN). Recommandations d'experts, adulte et enfant (Champs 1 à 7), spécificités pédiatriques regroupées au Champ 8.","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Méthodologie — un seul axe, pas de grade de preuve :</b> méthode SRLF-SFAR dérivée de la RAND/UCLA appropriateness method — chaque expert cote sur une échelle continue de 1 à 9 (1 = désaccord total, 9 = accord total) ; trois zones selon la position de la médiane : (1–3) désaccord, (4–6) indécision, (7–9) accord. L'accord (ou le désaccord) est dit <b>« fort »</b> si l'intervalle de la médiane reste à l'intérieur d'une des trois zones, <b>« faible »</b> dans le cas contraire. Aucun grade de preuve 1+/1-/2+/2- n'est utilisé. <b>Une zone d'indécision est explicitement identifiée par les auteurs</b> pour 3 propositions (reproduites en fin de fiche) — catégorie distincte, jamais reclassée en « fort » ou « faible ».","style":"body_sm"}},{"t":"table","rows":[[{"t":"chip","label":"Fort"},{"t":"p","html":"<b>Accord fort</b> — médiane des cotations (1–9) à l'intérieur d'une des trois zones.","style":"badge_head"},{"t":"chip","label":"Faible"},{"t":"p","html":"<b>Accord faible</b> — médiane empiétant sur une borne de zone.","style":"badge_head"}]]},{"t":"table","rows":[[{"t":"chip","label":"Indécision"},{"t":"p","html":"<b>Zone d'indécision</b> — médiane en zone 4–6, ni accord ni désaccord (3 propositions, cf. fin de fiche).","style":"badge_head"},{"t":"chip","label":"?"},{"t":"p","html":"<b>Non coté</b> — proposition sans tag d'accord dans le texte source (5 cas, Champ 3.1, disclosure).","style":"badge_head"}]]},{"t":"section","text":"Champ 1 — Sécurisation des soins et indicateurs : taxonomie générale","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"Un événement indésirable (EI) est une situation qui s'écarte des procédures ou résultats habituellement escomptés, potentiellement source de dommage ; inclut les erreurs humaines (procédures) et les EI patients (résultats).","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"L'erreur humaine est un écart par rapport à un objectif non atteint lors d'une séquence programmée d'activité mentale ou physique.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"Les événements porteurs de risque (EPR), définis par le décret sur l'accréditation des médecins des spécialités à risque, sont des EI à l'exclusion des EI graves.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"Un événement indésirable <b>patient</b> est une complication directement liée aux soins et non à la pathologie sous-jacente du patient.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"Un événement indésirable <b>grave</b> patient est une complication directement liée aux soins entraînant un risque vital, une prolongation de séjour, la nécessité de gestes invasifs, ou des séquelles invalidantes.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"Un EI ou un EPR doit être considéré comme <b>inévitable</b> lorsque les soins ont été délivrés conformément à l'état de l'art.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"Un EI ou un EPR doit être considéré comme <b>évitable ou possiblement évitable</b> lorsqu'on a mis en évidence une ou plusieurs erreurs médicales associées ou non à un ou plusieurs défauts système (structure, organisation, management), ou un ou plusieurs défauts système sans erreur médicale.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"En dehors des situations caricaturales, seule une analyse fine pourra distinguer les EI évitables de ceux qui ne le sont pas, en raison de l'importance des comorbidités comme facteurs de risque.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"Les procédures à risque pour le patient de réanimation sont principalement des procédures invasives.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"La sécurisation des procédures à risque est une démarche qui permet d'identifier et de traiter les différentes sources de risque afin de réduire au minimum le risque pour les patients.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EI / EPR","style":"cell_b"},{"t":"p","html":"Les procédures de sécurisation (« safety practices ») sont des procédures de soins et/ou structurelles/organisationnelles qui préviennent, diminuent la fréquence de survenue, ou atténuent les conséquences des erreurs et des EI.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Indicateurs","style":"cell_b"},{"t":"p","html":"La mise en place d'un indicateur nécessite au préalable d'avoir défini l'objectif de sécurisation des soins surveillé par cet indicateur.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Indicateurs","style":"cell_b"},{"t":"p","html":"Un indicateur doit être analysé systématiquement et de façon régulière.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Indicateurs","style":"cell_b"},{"t":"p","html":"En cas de variation d'un indicateur susceptible d'être le témoin d'un EPR, une analyse systémique doit être réalisée afin d'identifier les causes racines de l'EPR.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Indicateurs","style":"cell_b"},{"t":"p","html":"Un indicateur doit être acceptable, valide, pertinent, fiable et compréhensible.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Indicateurs","style":"cell_b"},{"t":"p","html":"Les indicateurs concernant la sécurisation d'une procédure de soins doivent être en nombre limité.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Champ 2 — Épidémiologie","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"Épidémiologie","style":"cell_b"},{"t":"p","html":"Il faut standardiser les définitions concernant les erreurs médicales, les EI et leur évitabilité.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Épidémiologie","style":"cell_b"},{"t":"p","html":"Les erreurs médicales et les EI patients doivent être classés en fonction de leur gravité.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Épidémiologie","style":"cell_b"},{"t":"p","html":"La standardisation de la méthode de recueil des erreurs médicales et des événements indésirables patients est nécessaire.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Épidémiologie","style":"cell_b"},{"t":"p","html":"Quelle que soit la méthode, il est recommandé que ce recueil soit non punitif, confidentiel et indépendant.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"Épidémiologie","style":"cell_b"},{"t":"p","html":"Le recueil régulier par la déclaration volontaire, bien que source de biais, permet de développer une culture sécurité.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Épidémiologie","style":"cell_b"},{"t":"p","html":"Il est recommandé de privilégier l'analyse des erreurs médicales et des EI patients évitables.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"Épidémiologie","style":"cell_b"},{"t":"p","html":"Il est important de pouvoir identifier indépendamment les erreurs des EI patients.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"Épidémiologie","style":"cell_b"},{"t":"p","html":"Il est important d'étudier les facteurs permettant la détection et la récupération de ces erreurs.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Champ 3 — Procédures de sécurisation structurelles et managériales","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"3.1 Structures","style":"cell_b"},{"t":"p","html":"Le service de réanimation doit comporter des chambres individuelles et des lits d'USC situés à proximité des lits de réanimation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.1 Structures","style":"cell_b"},{"t":"p","html":"Le service de réanimation doit pouvoir disposer de résultats biologiques fiables, obtenus rapidement et dont la traçabilité est assurée (pneumatique, biologie délocalisée).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.1 Structures","style":"cell_b"},{"t":"p","html":"Il existe une procédure chariot d'urgence.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.1 Structures","style":"cell_b"},{"t":"p","html":"Informatisation de l'unité de soins.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.1 Structures","style":"cell_b"},{"t":"p","html":"L'identitovigilance est assurée.","style":"cell"},{"t":"chip","label":"?"}],[{"t":"p","html":"3.1 Structures","style":"cell_b"},{"t":"p","html":"L'informatisation du dossier médical et de la prescription doit être développée.","style":"cell"},{"t":"chip","label":"?"}],[{"t":"p","html":"3.1 Structures","style":"cell_b"},{"t":"p","html":"La dispensation médicamenteuse est personnalisée.","style":"cell"},{"t":"chip","label":"?"}],[{"t":"p","html":"3.1 Structures","style":"cell_b"},{"t":"p","html":"Les résultats des examens biologiques et d'imagerie médicale sont disponibles dans le service.","style":"cell"},{"t":"chip","label":"?"}],[{"t":"p","html":"3.1 Structures","style":"cell_b"},{"t":"p","html":"Il existe une procédure partagée avec le plateau médico-technique pour la transmission des résultats urgents (par exemple : hyperkaliémie).","style":"cell"},{"t":"chip","label":"?"}],[{"t":"p","html":"3.2 Activité","style":"cell_b"},{"t":"p","html":"Il existe une relation entre le volume d'actes réalisés et la performance en termes de sécurité patient.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.2 Activité","style":"cell_b"},{"t":"p","html":"Lorsqu'une technique médicale n'est pas disponible localement, celle-ci doit faire l'objet d'une convention formalisée avec un service prestataire.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3 Organisation","style":"cell_b"},{"t":"p","html":"Le responsable médical du service et/ou du pôle doit être impliqué dans la gestion du recrutement du personnel soignant.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3 Organisation","style":"cell_b"},{"t":"p","html":"Les compétences médicales et paramédicales doivent être identiques en réanimation et en USC.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"3.3.1 Travail médical","style":"cell_b"},{"t":"p","html":"Si le médecin de garde ne fait pas partie de l'équipe médicale du service, un médecin de cette équipe doit pouvoir être consulté pendant la garde.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.1 Travail médical","style":"cell_b"},{"t":"p","html":"Il existe une procédure d'appel du médecin réanimateur (bip, téléphone…).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.1 Travail médical","style":"cell_b"},{"t":"p","html":"Il existe un programme de formation dans le service concernant les internes et les médecins de l'équipe.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.2 Travail soignant","style":"cell_b"},{"t":"p","html":"Il existe un cadre de santé de proximité dont l'activité est dédiée à la réanimation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.2 Travail soignant","style":"cell_b"},{"t":"p","html":"Les nouvelles IDE doivent bénéficier d'une période d'intégration d'un mois, faisant l'objet d'une traçabilité (livret d'intégration) ; la présence d'un infirmier tuteur est souhaitable durant cette période.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.2 Travail soignant","style":"cell_b"},{"t":"p","html":"Une attention particulière doit être portée sur les équipes de nuit, qui doivent bénéficier soit de formations spécifiques, soit de périodes de rotation de jour.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.2 Travail soignant","style":"cell_b"},{"t":"p","html":"Les transmissions entre équipes médicales et/ou soignantes doivent être formalisées.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.2 Travail soignant","style":"cell_b"},{"t":"p","html":"Il est nécessaire d'identifier, selon la dimension du service, un ou plusieurs agents responsables de la logistique (matériel, chariot d'urgence et de déplacement extérieur).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.2 Travail soignant","style":"cell_b"},{"t":"p","html":"Il est souhaitable que le service dispose d'outils permettant l'évaluation ponctuelle de la charge de travail.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.3 Protocoles","style":"cell_b"},{"t":"p","html":"L'organisation protocolisée est souhaitable ; les protocoles concernant les procédures de soins doivent être produits localement ou faire l'objet d'une appropriation locale s'il s'agit de protocoles extérieurs, et doivent faire l'objet de fréquents rappels (affiches, aide-mémoire de poche, informatique, staff).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.3 Protocoles","style":"cell_b"},{"t":"p","html":"Les procédures et/ou situations cliniques à risque doivent périodiquement faire l'objet de procédures de formation (prise en charge de l'arrêt cardiorespiratoire, de l'intubation difficile, tamponnade).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.3 Protocoles","style":"cell_b"},{"t":"p","html":"Ces situations doivent faire l'objet, a posteriori, de réunions de débriefing de l'ensemble de l'équipe médicale et paramédicale.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.3 Protocoles","style":"cell_b"},{"t":"p","html":"D'une manière générale, le service doit disposer de check-lists pour les procédures à risques reconnues et identifiées localement, a fortiori lorsqu'elles ont fait l'objet de recommandations par les sociétés savantes (SFAR/SRLF).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.3 Protocoles","style":"cell_b"},{"t":"p","html":"Le service doit disposer d'une procédure écrite de régulation d'admission des patients.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.3.3 Protocoles","style":"cell_b"},{"t":"p","html":"Le service doit disposer d'une procédure écrite de sortie des patients, comportant impérativement une fiche de liaison IDE et une synthèse médicale afin d'assurer la continuité des soins.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.4 Culture sécurité","style":"cell_b"},{"t":"p","html":"Le service de réanimation doit organiser périodiquement des réunions de morbi-mortalité, souhaitablement conformes aux recommandations des sociétés savantes (SFAR/SRLF).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.4 Culture sécurité","style":"cell_b"},{"t":"p","html":"Le service dispose d'une méthode de recueil des EI ; chaque service détermine, a priori, quels EI il va surveiller à partir de quels indicateurs et avec quel objectif.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.4 Culture sécurité","style":"cell_b"},{"t":"p","html":"Certaines procédures à risque doivent faire l'objet d'une réflexion bénéfice/risque dont la traçabilité est assurée dans le dossier patient.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.4 Culture sécurité","style":"cell_b"},{"t":"p","html":"Les audits de soins peuvent être intégrés dans l'évaluation des pratiques professionnelles (EPP) pour le personnel médical ; ils sont réalisés au mieux à partir des documents élaborés par les sociétés savantes (SFAR/SRLF).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.4 Culture sécurité","style":"cell_b"},{"t":"p","html":"Le service doit disposer d'indicateurs d'alerte d'épuisement professionnel (demandes de changement, absentéisme).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.4 Culture sécurité","style":"cell_b"},{"t":"p","html":"Il existe une procédure d'aide pour les agents en difficultés (raisons personnelles ou professionnelles).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.4 Culture sécurité","style":"cell_b"},{"t":"p","html":"Il existe une formalisation et une traçabilité dans le dossier du patient des décisions de limitation et d'arrêt des thérapeutiques actives et de toute décision éthique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.5 Tableau de bord","style":"cell_b"},{"t":"p","html":"Le service de réanimation tient un registre des refus d'admission indiquant les motifs.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.5 Tableau de bord","style":"cell_b"},{"t":"p","html":"Le service de réanimation dispose d'indicateurs de procédures et de résultats spécifiques concernant la sécurité des patients.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3.5 Tableau de bord","style":"cell_b"},{"t":"p","html":"Le service de réanimation dispose d'indicateurs de résultats permettant une comparaison interne ou externe.","style":"cell"},{"t":"chip","label":"Faible"}]]},{"t":"section","text":"Champ 4 — Procédures de sécurisation du matériel","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"4.1 Principes","style":"cell_b"},{"t":"p","html":"Les dispositifs médicaux (DM) induisent une série de risques de leur conception à leur mise au rebut, notamment le risque d'erreurs humaines qui doivent être maîtrisées.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.1 Principes","style":"cell_b"},{"t":"p","html":"D'une manière générale, les principaux éléments de sécurisation doivent reposer sur la formation des utilisateurs, l'entretien et la vérification des DM et l'application rigoureuse des règles de matériovigilance.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.1 Principes","style":"cell_b"},{"t":"p","html":"Une collaboration entre services cliniques et services biomédicaux est nécessaire.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.1 Principes","style":"cell_b"},{"t":"p","html":"Les différents acteurs intervenant dans la gestion des DM doivent être : un référent biomédical ingénieur par service (ou pôle) et/ou par type de matériel, un référent médical par service ou pôle, enfin un référent paramédical et/ou un technicien délocalisé par service ou pôle.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"4.1 Principes","style":"cell_b"},{"t":"p","html":"Il est recommandé de mettre en place une gestion informatisée du parc des DM.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.1 Principes","style":"cell_b"},{"t":"p","html":"Le suivi informatisé d'un DM doit notamment prendre en compte la date de réception, le numéro de série, le lieu de stockage, l'agenda de maintenance et de mise à niveau, la notification des pannes (type, fréquence et durée d'immobilisation), enfin la fréquence des défauts utilisateurs.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.2 Implantation","style":"cell_b"},{"t":"p","html":"Le cahier des charges définissant précisément le besoin qualitatif et quantitatif doit être établi en collaboration entre services cliniques et services biomédicaux.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.2 Implantation","style":"cell_b"},{"t":"p","html":"Il faut prendre en compte des éléments tels que : durée de garantie, contrat de maintenance, proximité et disponibilité du service après-vente.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.2 Implantation","style":"cell_b"},{"t":"p","html":"Les certificats de conformité aux textes réglementaires applicables à la classe du dispositif doivent être exigés.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.2 Implantation","style":"cell_b"},{"t":"p","html":"Avant implantation, il est recommandé d'effectuer un essai sur site en conditions réelles avec un panel représentatif d'utilisateurs pour identifier les situations locales spécifiques à risque.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.2 Implantation","style":"cell_b"},{"t":"p","html":"En cas de prêt de matériel, une fiche de mise à disposition doit être validée et signée par la société, les services cliniques et biomédicaux.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.3 Mise en service","style":"cell_b"},{"t":"p","html":"Il faut programmer et effectuer la formation des services cliniques et biomédicaux avant la réception du DM ; cette formation doit faire l'objet d'une traçabilité.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.3 Mise en service","style":"cell_b"},{"t":"p","html":"À la livraison, il faut vérifier que l'équipement correspond à l'intégralité de la commande (accessoires et consommables éventuels).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.3 Mise en service","style":"cell_b"},{"t":"p","html":"Le DM doit être inscrit à l'inventaire du service.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.3 Mise en service","style":"cell_b"},{"t":"p","html":"Si le DM est partagé par différents secteurs, il est recommandé de déterminer son périmètre fonctionnel (par exemple établissement d'une convention d'utilisation).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.4 Utilisation","style":"cell_b"},{"t":"p","html":"L'établissement de check-lists adaptées localement et à chaque type de matériel est recommandé pour vérifier un bon fonctionnement du DM avant chaque utilisation ; ces check-lists doivent faire l'objet d'une traçabilité permettant d'identifier au minimum l'opérateur, la date, le type de dysfonctionnement et préciser la liste des fonctionnalités non opérationnelles « bloquantes ».","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.4 Utilisation","style":"cell_b"},{"t":"p","html":"Si des check-lists de contrôle sont prévues par le constructeur et intégrées au logiciel du matériel, il faut les respecter et les compléter éventuellement par les check-lists locales.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.4 Utilisation","style":"cell_b"},{"t":"p","html":"Il faut rédiger une fiche d'alerte incidente pour tout dysfonctionnement, panne ou arrêt intempestif, information écran fausse.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.4 Utilisation","style":"cell_b"},{"t":"p","html":"Les maintenances préventives et curatives doivent être organisées par le service biomédical et faire l'objet de procédures écrites et d'une traçabilité.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.4 Utilisation","style":"cell_b"},{"t":"p","html":"Une procédure en cas de panne, adaptée à chaque type de matériel, doit être prévue par le service biomédical et comporter au minimum la disponibilité du matériel de suppléance et l'identification des intervenants à contacter 24 h/24 et 7 j/7.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.4 Utilisation","style":"cell_b"},{"t":"p","html":"Il est recommandé d'organiser des formations régulièrement pour les utilisateurs en cas de renouvellement des personnels, en cas de fréquence anormale du nombre de défauts utilisateurs ou lors de mise à niveau des matériels.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.4 Utilisation","style":"cell_b"},{"t":"p","html":"Il faut éviter de laisser le parc atteindre l'obsolescence en anticipant le remplacement du DM quand nécessaire (année de mise en service, nombre d'heures d'utilisation, concept dépassé et disparition des consommables).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4.4 Utilisation","style":"cell_b"},{"t":"p","html":"Lors de la réforme du DM, il faut retirer également les consommables pour éviter toute confusion avec d'autres DM de même catégorie.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Champ 5 — Sécurisation au cours de la ventilation mécanique","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"5.1 Intubation","style":"cell_b"},{"t":"p","html":"Chaque unité de réanimation doit disposer d'un chariot d'intubation dont la composition, vérifiée quotidiennement, est conforme aux recommandations de la conférence d'experts sur intubation difficile.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.1 Intubation","style":"cell_b"},{"t":"p","html":"Avant toute intubation en réanimation, il est recommandé de : scoper le patient et vérifier la présence du matériel nécessaire dans la chambre ; s'assurer du bon fonctionnement de l'aspiration et de la source d'oxygène (haut débit relié au ballon et au masque facial) ; vérifier le bon fonctionnement du respirateur auquel le patient sera branché immédiatement après l'intubation ; préoxygéner tous les patients avec une FiO2 à 1.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.1 Intubation","style":"cell_b"},{"t":"p","html":"S'il n'y a pas de contre-indications, un remplissage vasculaire est souhaitable.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.1 Intubation","style":"cell_b"},{"t":"p","html":"Deux opérateurs (deux médecins ou un médecin et une infirmière) doivent être présents systématiquement au moment de l'intubation.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.1 Intubation","style":"cell_b"},{"t":"p","html":"Si l'indication d'une sédation continue a été posée, celle-ci doit être préparée avant et administrée immédiatement après l'intubation.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.1 Intubation","style":"cell_b"},{"t":"p","html":"Il est préférable d'utiliser une lame métallique pour la laryngoscopie.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.1 Intubation","style":"cell_b"},{"t":"p","html":"Il faut assurer une traçabilité dans le dossier médical de toutes les intubations (en particulier difficiles).","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.1 Intubation","style":"cell_b"},{"t":"p","html":"En dehors des contre-indications, il faut utiliser l'induction à séquence rapide (ISR).","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.1 Intubation","style":"cell_b"},{"t":"p","html":"Le contrôle de la bonne position de la sonde d'intubation à l'aide d'un capnographe (EtCO2) doit être privilégié si le service en est doté.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.1 Intubation","style":"cell_b"},{"t":"p","html":"Les paramètres de la ventilation mécanique doivent être réadaptés à distance de l'intubation.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.2 Trachéotomie","style":"cell_b"},{"t":"p","html":"La trachéotomie doit être réalisée sous anesthésie générale avec curarisation appropriée.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.2 Trachéotomie","style":"cell_b"},{"t":"p","html":"Si la technique percutanée a été choisie, un fibroscope bronchique doit être utilisé.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.2 Trachéotomie","style":"cell_b"},{"t":"p","html":"Lorsque l'indication d'une trachéotomie percutanée a été posée, il faut s'assurer qu'un chirurgien (ORL si possible) puisse, en cas d'échec, réaliser en urgence une trachéotomie chirurgicale.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.2 Trachéotomie","style":"cell_b"},{"t":"p","html":"L'hémostase doit être vérifiée (TP &gt; 50 %, TCA &lt; 1,5 fois le témoin, plaquettes &gt; 50 000/mm³) et l'héparinothérapie standard curative interrompue de manière momentanée, avec respect d'un délai en cas d'HBPM.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.2 Trachéotomie","style":"cell_b"},{"t":"p","html":"Un plateau d'intubation doit être prêt en cas de difficultés, ainsi qu'une boîte chirurgicale si la technique percutanée a été choisie.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.2 Trachéotomie","style":"cell_b"},{"t":"p","html":"Le système d'aspiration murale avec canule d'aspiration stérile doit être vérifié.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.3 VM invasive","style":"cell_b"},{"t":"p","html":"La prévention de l'auto-extubation et de ses conséquences éventuelles nécessite : la présence d'un set complet d'intubation dont la vérification et la traçabilité dans un carnet de bord daté/signé est assurée quotidiennement ; la présence d'un protocole d'évaluation de la sédation et de la sevrabilité ; le repérage de la position des sondes après contrôle radiographique retranscrit lors des transmissions infirmières ; la surveillance de l'état cutané (escarres nez/bouche/oreilles) et l'adaptation des systèmes d'attaches.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.3 VM invasive","style":"cell_b"},{"t":"p","html":"La prévention des autres EI (pneumopathies nosocomiales notamment) nécessite : la surélévation de la tête du lit (&gt; 30°) ; des soins de bouche une fois par équipe ; une procédure d'aspiration propre (sonde à usage unique, port de gants) ; le contrôle radiographique de la sonde gastrique.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.3 VM invasive","style":"cell_b"},{"t":"p","html":"L'optimisation de la ventilation mécanique en termes de sécurité patient nécessite : la vérification de l'intégrité des tuyaux/circuits et de la présence d'eau dans les humidificateurs (une fois par équipe) ; la surveillance de la pression du ballonnet une fois par équipe, retranscrite sur la feuille de surveillance ; la présence permanente d'un système d'aspiration fonctionnel ; la prescription écrite au démarrage de la VM des conditions de ventilation (alarmes incluses), refaite à chaque changement de réglage.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"Le processus de sevrage doit être envisagé aussitôt que possible dans la prise en charge d'une IRA.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"Il est recommandé d'évaluer quotidiennement la sevrabilité sur des critères simples de stabilité respiratoire, hémodynamique et neurologique, et de réaliser une épreuve de sevrage en VS dès que ces critères sont remplis — les deux étapes essentielles à l'identification des patients susceptibles d'être sevrés.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"Les critères prédictifs de l'issue du sevrage ne doivent pas être attendus et/ou obtenus pour réaliser l'épreuve de sevrage.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"La tolérance clinique d'une épreuve de sevrage doit être considérée comme le meilleur test pour juger a priori des capacités de déventilation d'un patient.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"L'épreuve de sevrage doit être réalisée sur pièce en T (VS/T) ou en aide inspiratoire (AI) d'un niveau minimal de 7 cmH2O, avec ou sans PEP externe (≤ 5 cmH2O), pour une durée minimale de 30 minutes.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"Le succès de l'épreuve de sevrage doit faire procéder à l'extubation dans les suites immédiates, après avoir éliminé des facteurs d'échec d'extubation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"L'échec de l'épreuve de sevrage doit faire imposer d'en rechercher la ou les causes et leur éventuelle réversibilité.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"Chez le patient difficile ou potentiellement difficile à sevrer, la sécurisation du sevrage doit comprendre : la réalisation d'une épreuve de sevrage en AI ± PEP sur 120 minutes maximum ; la réalisation d'un gaz du sang artériel au cours ou en fin d'épreuve ; le recours à une stratégie de sevrage progressif privilégiant l'AI ± PEP dégressive.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"La VNI peut être utilisée comme technique de sevrage permettant l'extubation précoce chez les patients BPCO hypercapniques.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"Il peut être utile de mettre en place des protocoles de sevrage.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.4 Sevrage VM","style":"cell_b"},{"t":"p","html":"Il peut être utile d'utiliser des logiciels informatisés.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.5 Extubation","style":"cell_b"},{"t":"p","html":"Avant d'envisager une extubation, il faut évaluer la capacité du patient à tousser et à évacuer ses sécrétions.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.5 Extubation","style":"cell_b"},{"t":"p","html":"Il n'y a pas lieu de réaliser systématiquement un test de fuite lors de l'extubation des patients de réanimation.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.5 Extubation","style":"cell_b"},{"t":"p","html":"Le test de fuite est recommandé chez les patients à risque.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.5 Extubation","style":"cell_b"},{"t":"p","html":"Chez les patients à très haut risque, chez qui la réalisation d'une trachéotomie peut être difficile, il faut discuter la pertinence d'une extubation réalisée au bloc opératoire en présence d'un chirurgien ORL.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"La VNI doit représenter la stratégie ventilatoire sécuritaire pour la prise en charge de l'IRA hypercapnique des patients BPCO et de l'OAP cardiogénique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"Dans la prise en charge de l'IRA hypoxémique (cœur et poumons antérieurement sains), l'analyse du rapport bénéfices/risques doit prendre en compte le risque accru de mortalité en cas d'échec de la VNI.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"L'application de la VNI à l'IRA hypoxémique doit dans tous les cas être menée dans un milieu sécurisé de réanimation pour ne pas retarder le moment de l'intubation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"Quel que soit le type d'IRA (hypercapnique ou hypoxémique), les patients les plus graves sous VNI doivent être pris en charge et surveillés en réanimation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"La maîtrise de la VNI doit représenter un objectif de formation théorique et pratique des personnels médicaux et paramédicaux au sein des services de réanimation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"La pratique de la VNI implique une bonne connaissance des indications, des contre-indications et des facteurs prédictifs d'échec de la technique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"L'élaboration de protocoles de soins, propres au service, est recommandée pour favoriser l'implantation de la technique et ses résultats.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"Le matériel de VNI disponible (masques, ventilateurs, humidificateurs) doit être adapté à la pathologie et à la gravité des patients pris en charge.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"La sécurisation de la VNI passe par l'optimisation de ses modalités pratiques : choix d'un masque facial en première intention ; humidification des gaz inspirés (humidificateur chauffant si hypercapnie grave/intolérance) ; retrait du raccord annelé en cas d'IRA hypercapnique ; choix d'un ventilateur de réanimation chez les patients les plus à risque d'échec ; choix d'un mode à double niveau de pression en première intention hors OAP cardiogénique ; augmentation graduelle du niveau d'assistance jusqu'au réglage optimal ; réglage du trigger inspiratoire, de la pente de pressurisation, du niveau d'AI et du cyclage inspiration/expiration ; réglage adapté des alarmes du ventilateur et de la ventilation d'apnée.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"L'application continue de la VNI doit être privilégiée initialement jusqu'à une amélioration clinique et gazométrique franche, avant d'envisager un mode séquentiel (alternance VNI/VS).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"Les risques d'échec de la VNI doivent imposer une surveillance initiale rapprochée au cours des premières heures pour juger de la réponse à la technique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"La surveillance de la VNI doit être avant tout clinique, mais doit s'aider des gaz du sang, des paramètres et des courbes du ventilateur pour optimiser les réglages et la tolérance de la technique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"5.6 VNI","style":"cell_b"},{"t":"p","html":"En l'absence d'échec, l'arrêt de la VNI suppose au préalable une évaluation clinique et gazométrique de l'autonomie ventilatoire du patient en VS sur une période de 6 à 12 heures.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Champ 6 — « Procédures circulatoires » : vasoactifs et abords vasculaires","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"6.1 Vasoactifs","style":"cell_b"},{"t":"p","html":"Le rangement des drogues vasoactives doit tenir compte du risque de confusion entre différentes ampoules ; l'étiquetage des seringues doit être suffisamment explicite et clair pour éviter toute confusion.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.1 Vasoactifs","style":"cell_b"},{"t":"p","html":"Les médicaments vasoactifs doivent être administrés par voie intraveineuse et de façon continue grâce à une seringue pour perfusion continue.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.1 Vasoactifs","style":"cell_b"},{"t":"p","html":"La voie d'administration veineuse centrale doit toujours être privilégiée ; la voie périphérique est possible pour la dopamine et pour la dobutamine à faible dose (≤ 5 µg/kg/min) ; en urgence, en attente de l'insertion d'un cathéter veineux central, l'administration peut être débutée sur une voie veineuse périphérique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.1 Vasoactifs","style":"cell_b"},{"t":"p","html":"L'utilisation de pompes de perfusion munies de logiciels permettant le relais automatique des seringues contenant une drogue vasoactive doit être privilégiée.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.1 Vasoactifs","style":"cell_b"},{"t":"p","html":"Le raccord de la voie de perfusion des amines vasoactives à la voie de perfusion principale doit se faire par l'intermédiaire d'une tubulure de petit calibre et le plus près possible du patient.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.1 Vasoactifs","style":"cell_b"},{"t":"p","html":"Les systèmes utilisés pour le relais des seringues destinées à l'administration de drogues vasoactives doivent être munis d'une pré-alarme sonore pour la validation de la procédure automatique du relais.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.1 Vasoactifs","style":"cell_b"},{"t":"p","html":"Le relais des seringues doit faire l'objet d'une procédure de soins standardisée dans le service de réanimation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.1 Vasoactifs","style":"cell_b"},{"t":"p","html":"La dilution des drogues vasoactives doit faire l'objet d'une procédure de soins standardisée dans le service de réanimation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2 KT central","style":"cell_b"},{"t":"p","html":"Il faut utiliser du matériel entièrement transparent permettant d'identifier clairement les bulles présentes dans le circuit de cathétérisme central artériel ou veineux.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2 KT central","style":"cell_b"},{"t":"p","html":"Les connexions de la ligne de perfusion d'un cathéter central artériel ou veineux doivent utiliser un système à vis (type Luer-Lock).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2 KT central","style":"cell_b"},{"t":"p","html":"Les robinets de la ligne de perfusion d'un cathéter central artériel ou veineux doivent être clairement identifiés afin d'éviter le risque d'injections accidentelles sur cette ligne.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2 KT central","style":"cell_b"},{"t":"p","html":"Après l'ablation d'un cathéter central artériel ou veineux, il faut vérifier qu'il a été retiré dans son ensemble.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.1 KT artériel","style":"cell_b"},{"t":"p","html":"Un cathéter artériel ne doit pas être posé sur une artère terminale (artère humérale).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.1 KT artériel","style":"cell_b"},{"t":"p","html":"Les sites d'insertion possibles d'un cathéter artériel sont les artères radiales, fémorales et pédieuses.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.1 KT artériel","style":"cell_b"},{"t":"p","html":"La recherche d'une circulation collatérale palmaire par le test d'Allen est un préalable à la pose par voie radiale ; ce test peut être remplacé par le signal de pléthysmographie aux premiers et derniers doigts de la main.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.1 KT artériel","style":"cell_b"},{"t":"p","html":"Un cathéter artériel ne doit pas être inséré dans des prothèses vasculaires ; il faut rechercher régulièrement une ischémie du membre d'aval (retrait du cathéter et exploration/surveillance de la vascularisation en cas de signe d'ischémie) ; privilégier les cathéters de petite longueur (3 à 5 cm) pour la voie radiale.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.1 KT artériel","style":"cell_b"},{"t":"p","html":"Il faut utiliser un système de purge du cathéter artériel assurant un débit continu d'au minimum 2 mL/h, incluant la possibilité d'une purge manuelle.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.1 KT artériel","style":"cell_b"},{"t":"p","html":"Il n'y a pas d'argument pour pratiquer une anticoagulation systématique de la ligne artérielle.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.1 KT artériel","style":"cell_b"},{"t":"p","html":"Après l'ablation du cathéter artériel, il faut comprimer le point de ponction pendant quelques minutes jusqu'à l'arrêt de tout saignement.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.2 KT veineux central","style":"cell_b"},{"t":"p","html":"Le cathétérisme veineux central doit être effectué par ou avec l'aide d'un opérateur expérimenté.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.2 KT veineux central","style":"cell_b"},{"t":"p","html":"La voie sous-clavière doit être évitée en cas d'anomalie de l'hémostase, en cas d'hypoxémie sévère (PaO2/FiO2 &lt; 200) et en cas d'anomalie anatomique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.2 KT veineux central","style":"cell_b"},{"t":"p","html":"En cas d'anomalie importante de l'hémostase, la voie fémorale doit être préférée pour le cathétérisme veineux central.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.2 KT veineux central","style":"cell_b"},{"t":"p","html":"Lorsque la deuxième tentative de ponction veineuse a échoué, il est conseillé de changer de site, d'opérateur ou de technique (repérage ultrasonographique).","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"6.2.2 KT veineux central","style":"cell_b"},{"t":"p","html":"Le repérage ultrasonographique peut améliorer le taux de succès du cathétérisme veineux, surtout pour la voie jugulaire interne, sans augmenter le temps de cathétérisme.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.2 KT veineux central","style":"cell_b"},{"t":"p","html":"Un contrôle radiographique du thorax doit être effectué après la pose d'un cathéter veineux sous-clavier afin de rechercher l'absence de pneumothorax et de contrôler la bonne position du cathéter.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.2.2 KT veineux central","style":"cell_b"},{"t":"p","html":"Afin d'éviter toute érosion endovasculaire et effraction intra-péricardique, l'extrémité des cathéters veineux insérés dans le territoire cave supérieur doit être située au niveau de la carène ; en cas de mauvaise position, le cathéter doit être retiré de quelques centimètres.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"La sécurisation de la procédure de pose d'un cathéter veineux central s'applique à la pose du désilet préalable à l'insertion du cathéter artériel pulmonaire.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"L'utilisation du cathéter artériel pulmonaire est contre-indiquée par la présence d'une sonde d'entraînement intracardiaque.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"Lors de l'introduction du cathéter dans les cavités cardiaques, une surveillance permanente du rythme doit être effectuée afin de rechercher les troubles du rythme cardiaque.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"Un contrôle de la radiographie de thorax doit être effectué après l'insertion du cathéter artériel pulmonaire afin de vérifier sa position.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"Le dégonflement du ballonnet doit être systématiquement vérifié après que ce dernier a été utilisé.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"Le matériel et les médicaments nécessaires au traitement d'un trouble du rythme et d'un trouble conductif doivent être disponibles rapidement lors de la pose d'un cathéter artériel pulmonaire.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"Le cathéter artériel pulmonaire doit être maintenu en place le moins longtemps possible ; une durée maximale de trois jours est conseillée.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"La calibration du zéro de référence doit se faire au niveau de l'oreillette droite et sa recalibration doit s'effectuer régulièrement et en cas de doute sur les mesures de pression affichées.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"La mesure de SvO2 nécessite une calibration régulière par co-oxymétrie.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"Le contrôle radiographique quotidien de la position de la sonde n'est pas nécessaire ; en cas d'anomalie d'obtention du tracé, la radiographie de thorax de contrôle s'impose.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"6.3 KT artériel pulmonaire","style":"cell_b"},{"t":"p","html":"À l'ablation du cathéter artériel pulmonaire, il faut vérifier son intégrité.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Champ 7 — Sécurisation des procédures d'épuration extra-rénale","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"EER — Prescription","style":"cell_b"},{"t":"p","html":"La prescription d'une séance d'épuration extra-rénale (EER) intermittente ou continue doit comporter au minimum : la durée ; le type de membrane ; le débit de la pompe à sang ; le type et la posologie de l'anticoagulation du circuit extracorporel ; la perte hydrique horaire ou totale ; le débit de dialysat ; la composition du dialysat en sodium, potassium, calcium, soluté tampon et glucose ; enfin la température du dialysat.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Membrane","style":"cell_b"},{"t":"p","html":"La structure de la membrane utilisée pour la réalisation d'une EER doit être en cellulose modifiée ou synthétique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Filtration","style":"cell_b"},{"t":"p","html":"Au cours de l'EER (intermittente ou continue), la filtration à travers la membrane doit être gérée par un contrôle automatisé.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Filtration","style":"cell_b"},{"t":"p","html":"Au cours de l'hémofiltration, la fraction de filtration doit être surveillée en continu et la filtration doit être interrompue lors des situations à risque de chute du débit sanguin (nursing).","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"EER — Mise en route","style":"cell_b"},{"t":"p","html":"Avant toute mise en route d'une EER et en particulier pour l'hémofiltration, il est nécessaire de : s'assurer de l'absence de coudure du cathéter ; respecter les procédures de gestion des cathéters veineux centraux ; s'assurer de son bon positionnement dans le vaisseau (cliché thoracique) ; s'assurer de sa position adaptée au débit souhaité.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Cathéters","style":"cell_b"},{"t":"p","html":"La pose et l'entretien des cathéters doivent être conformes aux recommandations du CLIN concernant la prévention du risque infectieux au cours de la mise en place des cathéters veineux centraux.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Surveillance","style":"cell_b"},{"t":"p","html":"La surveillance d'une séance d'EER chez un patient de réanimation doit comporter au minimum : le monitorage continu de l'ECG et de la fréquence cardiaque ; la mesure rapprochée de la pression artérielle ; le recueil du ratio de filtration (techniques convectives), de la pression de retour veineux et de la pression transmembranaire ; une mesure pluriquotidienne de la température pour l'EER continue ; un bilan hydrique en fin de séance et chaque jour pour l'EER continue ; un ionogramme sanguin en fin de séance et toutes les 12 heures pour l'EER continue ; une évaluation quotidienne (et à chaque modification de posologie) de l'activité systémique de l'anticoagulant pour l'EER continue ; la mesure quotidienne de la gazométrie artérielle et à chaque changement du débit de restitution en bicarbonates au cours de l'hémofiltration continue.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Citrate","style":"cell_b"},{"t":"p","html":"Dans le cas particulier d'un traitement antithrombotique au citrate, il faut doser toutes les quatre heures en état stable le calcium ionisé.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"EER — Procédure","style":"cell_b"},{"t":"p","html":"La sécurisation de l'EER continue et intermittente nécessite, en sus de la surveillance clinique déjà décrite, la mise en place d'une procédure écrite, facilement disponible.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Procédure","style":"cell_b"},{"t":"p","html":"Cette procédure doit comporter, en sus de la surveillance déjà décrite, la description des techniques de montage et de purge du circuit extracorporel, des techniques de branchement et de débranchement, des paramètres de surveillance du circuit, et du choix de la composition des solutions pour dialyse et hémofiltration et de leur remplacement en cours de traitement.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Générateurs","style":"cell_b"},{"t":"p","html":"Une procédure de désinfection interne des générateurs entre les séances d'hémodialyse doit être mise en place.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Qualité de l'eau","style":"cell_b"},{"t":"p","html":"Les responsables d'un service de réanimation dans lequel sont réalisées des séances d'hémodialyse par un générateur fabriquant un dialysat à partir de l'eau de distribution publique doivent faire partie des acteurs impliqués dans le processus de gestion de la qualité de l'eau.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Qualité de l'eau","style":"cell_b"},{"t":"p","html":"Un tel service doit disposer d'une procédure d'alerte en cas de non-conformité chimique ou microbiologique de l'eau pour hémodialyse.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"EER — Qualité de l'eau","style":"cell_b"},{"t":"p","html":"La recherche d'un résidu de solution désinfectante dans le dialysat doit être systématique avant tout branchement d'une séance d'hémodialyse réalisée par un tel générateur.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Champ 8 — Spécificités pédiatriques","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"Tout service de réanimation pédiatrique devrait disposer d'un tableau de dilution des catécholamines précisant la correspondance entre le débit (mL/h) et la dose (µg/min).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"Le matériel de monitorage doit être doté d'alarmes adaptées à l'âge de l'enfant.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"Lorsqu'une voie fémorale a été mise en place dans un contexte d'urgence, son maintien doit être reconsidéré au bout de 48 heures.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"Les lignes de perfusion artérielle doivent toujours être raccordées à une tête de pression.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"Un matériel spécifique (pompes, tubulures et sondes), adapté et clairement identifié, doit être utilisé pour éviter le risque de confusion entre les perfusions (artérielles ou veineuses) et l'alimentation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"Une boîte d'intubation pédiatrique doit comporter des lames droites et des lames courbes de toutes les tailles existantes.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"L'usage de l'aspiration en système clos doit être strictement limité aux situations où le dérecrutement a des conséquences significatives et persistantes sur l'oxygénation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"Tout pôle de réanimation pédiatrique doit être équipé de masques de ventilation manuelle adaptés à la taille de l'enfant.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"Tout service de réanimation pédiatrique doit pouvoir réaliser des épurations extra-rénales.","style":"cell"},{"t":"chip","label":"Faible"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"Les techniques d'EER (cathéters, moniteur, volume extracorporel, débit) doivent être adaptées à la taille de l'enfant.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"La dialyse péritonéale est une méthode d'EER qui reste utilisable en réanimation pédiatrique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Pédiatrie","style":"cell_b"},{"t":"p","html":"Le maintien de l'expertise du personnel pédiatrique en technique d'EER fait partie d'une formation continue spécifique.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Zone d'indécision — 3 propositions (ni accord ni désaccord)","color":"amber"},{"t":"p","html":"Le texte source identifie explicitement ces trois propositions comme scorées par les experts dans la <b>zone d'indécision</b> (médiane 4–6, ni accord ni désaccord) — catégorie distincte, reproduite ici telle quelle plutôt que reclassée en « fort » ou « faible ».","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"Extubation","style":"cell_b"},{"t":"p","html":"L'administration de corticoïdes par voie IV au moins six heures avant l'extubation peut être proposée.","style":"cell"},{"t":"chip","label":"Indécision"}],[{"t":"p","html":"Extubation","style":"cell_b"},{"t":"p","html":"Si une extubation est prévue, il peut être proposé d'utiliser un guide échangeur pour faciliter la réintubation éventuelle.","style":"cell"},{"t":"chip","label":"Indécision"}],[{"t":"p","html":"Déplétion","style":"cell_b"},{"t":"p","html":"Lorsqu'il est réalisé une déplétion chez un patient à risque, il est nécessaire de mettre en place un monitorage de la précharge ventriculaire adapté aux conditions du patient.","style":"cell"},{"t":"chip","label":"Indécision"}]]},{"t":"p","html":"Fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend l'intégralité des propositions du texte source (y compris les propositions non cotées et la zone d'indécision, disclosées comme telles), mais ne remplace pas le texte intégral et n'est ni éditée ni validée par la SRLF ou la SFAR. En cas de doute, se référer au texte intégral et/ou à un avis spécialisé. Risque infectieux explicitement exclu du champ de ce document — voir les référentiels dédiés.","style":"source"}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/securisation-des-procedures-a-risques-en-reanimation-risque-infectieux-exclu/';

insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Prise-en-charge-des-sujets-en-etat-de-mort-encephalique-dans-loptique-dun-prelevement-dorganes.pdf' and s.slug in ('anesthesie_reanimation', 'medecine_intensive_reanimation')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Prise-en-charge-des-sujets-en-etat-de-mort-encephalique-dans-loptique-dun-prelevement-dorganes.pdf' and s.acronym in ('SFAR', 'SRLF')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Prise-en-charge-des-sujets-en-etat-de-mort-encephalique-dans-loptique-dun-prelevement-dorganes.pdf' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'mort_encephalique',
  card_json = $mgjson${"badge":"RAND/UCLA 1-9","title":"Mort encéphalique & prélèvement d'organes","short":"Prise en charge des sujets en état de mort encéphalique (ME) dans l'optique d'un prélèvement d'organes et de tissus : diagnostic clinique et paraclinique de la ME (EEG, angiographie, Doppler transcrânien), réanimation du donneur potentiel (hémodynamique, diabète insipide, cibles thérapeutiques, hémostase, infection, pédiatrie), critères d'évaluation et contre-indications par organe (cœur, poumon, foie, rein, pancréas, intestin, tissus), organisation du prélèvement (coordination hospitalière, PMO, donneurs à cœur arrêté/Maastricht). Cotation RAND/UCLA (médiane 1-9, 3 zones désaccord/indécision/accord) imprimée après la quasi-totalité des énoncés du texte source, y compris certains rappels de contexte non soumis au vote — disclosure de cette ambiguïté source dans la fiche.","society":"SFAR / SRLF / Agence de la biomédecine","version":"2005 (Ann Fr Anesth Réanim 2005;24:836-843)","validated":"Conférence d'experts Sfar/SRLF/Agence de la biomédecine","methodology":"Cotation RAND/UCLA (médiane 1-9, pas de GRADE) — zones désaccord (1-3) / indécision (4-6) / accord (7-9)","pages":8,"section":"Réanimation"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"mort_encephalique","sections":[{"title":"Introduction & méthodologie","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> prise en charge des sujets en état de mort encéphalique (ME) dans l'optique d'un prélèvement d'organes et de tissus. Conférence d'experts Sfar / Société de réanimation de langue française (SRLF) / Agence de la biomédecine, texte court publié le 15/06/2005 (Ann Fr Anesth Réanim 2005;24:836-843), faisant suite à un premier référentiel de 1998. <b>4 chapitres</b> : (1) la ME — historique, concept, diagnostic ; (2) prise en charge en réanimation du donneur potentiel ; (3) critères d'évaluation des organes et des tissus ; (4) organisation du prélèvement d'organes, présent et avenir.","style":"body"}},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Méthodologie de cotation — non-GRADE (RAND/UCLA) :</b> les recommandations nécessitant une validation ont été cotées individuellement par chaque expert sur une échelle de <b>1 à 9</b>. Le texte publie la <b>médiane</b> des cotations entre parenthèses. Trois zones : <b>1-3 « désaccord »</b>, <b>4-6 « indécision »</b>, <b>7-9 « accord »</b>. Quand la médiane tombe sur un demi-point (nombre pair de cotations), le texte l'imprime en notation décimale française — virgule au lieu du point — ex. « (8,5) » = médiane 8,5. Un audit indépendant a l'aveugle a vérifié cette lecture par grep exhaustif : le second chiffre après la virgule est <i>toujours</i> « 5 » sur les 11 occurrences du document, ce qui exclut l'hypothèse d'un extrême dissident cité (qui varierait). Chip à valeur unique « 8,5 », jamais scindé en deux nombres ni interprété comme un second vote.<br/><br/><b>Anomalie source disclosée :</b> ce même code entre parenthèses est imprimé après la quasi-totalité des énoncés du corps du texte, qu'il s'agisse d'une recommandation soumise au vote du jury ou d'un simple rappel de donnée de contexte/épidémiologique — le texte source (8 pages, sans liste de références numérotée séparée) ne distingue pas typographiquement les deux usages. Cette fiche reproduit fidèlement le chiffre imprimé, sous forme de chip coloré par zone, pour chaque énoncé qui en porte un — sans affirmer qu'il s'agit toujours d'un vote formel plutôt que d'un rappel bibliographique pour les rares passages purement descriptifs. Une seule occurrence de cotation « 6 » (indécision) existe dans tout le document ; toutes les autres cotations à un chiffre relevées sont 7, 8 ou 9 (accord). Les énoncés du texte source sans aucun chiffre entre parenthèses restent sans chip (« — ») : aucune cotation n'est inventée.","style":"body_sm"}},{"t":"section","text":"Légende des chips de cotation","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"9"},{"t":"p","html":"Zone « accord » (7-9)","style":"badge_head"},{"t":"chip","label":"6"},{"t":"p","html":"Zone « indécision » (4-6)","style":"badge_head"},{"t":"chip","label":"8,5"},{"t":"p","html":"Médiane à un demi-point (notation décimale « 8,5 »)","style":"badge_head"},{"t":"p","html":"—","style":"cell_c"},{"t":"p","html":"Aucun chiffre imprimé","style":"badge_head"}]]}]},{"title":"Chapitre 1 — Diagnostic de la mort encéphalique","items":[{"t":"section","text":"Chapitre 1 — La mort encéphalique : historique, concept et diagnostic","color":"navy"},{"t":"p","html":"Depuis sa description initiale en 1959, la ME a permis les prélèvements d'organes et/ou de tissus chez le cadavre à cœur battant. Les lois de bioéthique de 1994, révisées en 2004, ont posé les principes généraux du prélèvement (anonymat, gratuité, consentement) et élevé certaines modalités au rang de principes (diagnostic de la mort, sécurité sanitaire). Le décret d'application de 1996 impose que le diagnostic de ME repose sur les données de l'examen clinique confirmé par un examen complémentaire. <i>(Contexte historique/légal — aucun chiffre de cotation imprimé pour ce paragraphe.)</i>","style":"note"},{"t":"p","html":"Les enquêtes d'incidence de la ME en France et dans d'autres pays l'évaluent à 7-13 % des décès en réanimation et en soins intensifs, soit 3 300 à 3 800 donneurs potentiels par an estimés. Le codage systématique de la ME dans le PMSI (Z005 : examen d'un donneur éventuel d'organes et de tissus ; Z528 : donneur d'organes et de tissus) permettrait d'estimer en continu le nombre de donneurs potentiels (8). La ME est définie comme la destruction irréversible de l'ensemble des fonctions cérébrales chez un sujet à cœur battant, conséquence d'un arrêt complet de la circulation cérébrale : les organes restent fonctionnels si la réanimation est adaptée, mais la destruction encéphalique supprime la commande centrale de la respiration et la régulation de l'homéostasie circulatoire, thermique et endocrinienne (arrêt respiratoire, hypotension, hypothermie, diabète insipide).","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"1.1","style":"cell_b"},{"t":"p","html":"Une anamnèse cohérente complète et un examen clinique neurologique sans ambiguïté sont essentiels pour porter le diagnostic de ME ; ces éléments doivent être consignés par écrit.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"1.2","style":"cell_b"},{"t":"p","html":"Élimination systématique des facteurs confondants cliniques : hypothermie (température centrale &lt; 35 °C), imprégnation médicamenteuse ou toxique susceptible d'interférer avec l'examen clinique.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"1.3","style":"cell_b"},{"t":"p","html":"En l'absence de facteurs confondants, l'examen neurologique doit observer un coma non réactif (Glasgow à 3) associé à l'abolition des réflexes du tronc cérébral et de la ventilation spontanée.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"1.4","style":"cell_b"},{"t":"p","html":"Épreuve d'hypercapnie sous oxygénothérapie efficace contrôlée par SpO2 (après ventilation en normocapnie) : atteindre en apnée une PaCO2 proche de 60 mmHg pour affirmer l'absence de mouvements respiratoires.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"1.5","style":"cell_b"},{"t":"p","html":"Dans l'optique du don, le diagnostic clinique de ME doit être confirmé par un examen complémentaire exigé par la loi : soit deux EEG nuls et non réactifs pendant 30 minutes, effectués à 4 heures d'intervalle, soit une angiographie cérébrale objectivant l'arrêt de perfusion des 4 axes.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"1.6","style":"cell_b"},{"t":"p","html":"La vélocimétrie Doppler transcrânienne n'a pas de valeur réglementaire pour le diagnostic de ME. Non invasive et répétable au lit du malade, elle est prédictive de ME avec une spécificité de 100 % et une sensibilité d'environ 90 % en visualisant un flux oscillant systolodiastolique (arrêt circulatoire cérébral).","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"1.7","style":"cell_b"},{"t":"p","html":"Quand l'examen clinique est compatible avec la ME, l'examen Doppler peut permettre d'évoquer de manière rapide et précoce le diagnostic d'arrêt circulatoire cérébral.","style":"cell"},{"t":"chip","label":"7"}],[{"t":"p","html":"1.7b","style":"cell_b"},{"t":"p","html":"Cela permet la mise en route sans retard des procédures réglementaires de confirmation de ME et peut raccourcir le délai entre la mort et le prélèvement.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"1.8","style":"cell_b"},{"t":"p","html":"L'EEG (silence électrocérébral, amplitude &lt; 5 µV) est le test de confirmation de ME prévu par la réglementation, à condition d'exclure l'influence de la sédation ou de troubles métaboliques.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"1.8b","style":"cell_b"},{"t":"p","html":"Avant d'utiliser les deux EEG comme moyen paraclinique, il convient de s'assurer que les dosages sanguins/urinaires ne décèlent aucun médicament du SNC à dose susceptible d'interférer avec l'interprétation de l'EEG — non coté dans le texte source.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"1.8c","style":"cell_b"},{"t":"p","html":"L'hypothermie modérée (température voisine de 30 °C) n'empêche pas l'interprétation de l'EEG.","style":"cell"},{"t":"chip","label":"7"}],[{"t":"p","html":"1.8d","style":"cell_b"},{"t":"p","html":"Cependant, en l'absence de donnée confirmant ce fait en contexte de ME, une hypothermie entre 30 et 35 °C peut gêner l'attestation de nullité de l'EEG — non coté dans le texte source.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"1.9","style":"cell_b"},{"t":"p","html":"Les potentiels évoqués (PE), intéressants chez les patients sédatés, n'ont pas de valeur réglementaire en France pour la confirmation de ME.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"1.10","style":"cell_b"},{"t":"p","html":"L'angiographie cérébrale (voie artérielle ou veineuse) est la seconde méthode de confirmation prévue par la réglementation. L'angioscanner par voie veineuse est recommandé comme moyen de confirmation de l'arrêt circulatoire encéphalique.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"1.11","style":"cell_b"},{"t":"p","html":"Le compte rendu écrit de l'examen électrophysiologique ou de l'angiographie doit être signé immédiatement par un médecin qualifié.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"1.12","style":"cell_b"},{"t":"p","html":"En cas de ME clinique, adapter sans délai les méthodes de réanimation et contacter la coordination hospitalière (« donneur potentiel »).","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"1.12b","style":"cell_b"},{"t":"p","html":"La décision d'amener le sujet au prélèvement relève du médecin du donneur (absence d'opposition, absence de contre-indication générale) ; la décision de prélever tel ou tel organe relève uniquement du médecin transplanteur, via la coordination hospitalière.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"1.13","style":"cell_b"},{"t":"p","html":"L'accompagnement de la famille doit respecter et prendre en compte ses convictions religieuses et différences culturelles ; la qualité de l'accueil des familles et des proches est déterminante pour l'acceptation ou le refus du don.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"1.14","style":"cell_b"},{"t":"p","html":"Les entretiens doivent se dérouler dans un local décent, permettant de faire asseoir les participants et de préserver l'intimité et la confidentialité.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"1.14b","style":"cell_b"},{"t":"p","html":"Ils interviennent après confirmation paraclinique de la ME et assurance par la coordination de la faisabilité des prélèvements.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"1.14c","style":"cell_b"},{"t":"p","html":"Objectifs de l'entretien (non cotés dans le texte source) : annoncer le décès ; informer sur la ME, le don et sa finalité ; rechercher le refus de prélèvement exprimé du vivant du défunt.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"1.15","style":"cell_b"},{"t":"p","html":"L'entretien doit au mieux être mené à deux (le réanimateur et un membre de la coordination hospitalière), qui doivent se présenter à la famille.","style":"cell"},{"t":"chip","label":"9"}]]}]},{"title":"Chapitre 2 — Réanimation du donneur (hémodynamique)","items":[{"t":"section","text":"Chapitre 2 — Prise en charge en réanimation du donneur potentiel","color":"navy"},{"t":"p","html":"L'instabilité hémodynamique au cours de la ME est fréquente et multifactorielle (disparition du contrôle sympathique, phénomènes inflammatoires, ischémie-reperfusion, troubles hormonaux, hypothermie) ; elle induit un dysfonctionnement cardiaque, parfois réversible, dans 40 % des cas. Le diabète insipide, fréquent, est secondaire à un déficit de production d'ADH. La dysfonction antéhypophysaire (baisse des hormones thyroïdiennes et du cortisol) est bien établie chez l'animal, sa responsabilité dans l'altération de la fonction myocardique restant controversée chez l'homme.","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"2.1","style":"cell_b"},{"t":"p","html":"Reconnaissance précoce de l'instabilité hémodynamique afin de permettre des mesures thérapeutiques immédiates. Conditionnement minimal de tout donneur potentiel : électrocardioscope, oxymétrie de pouls, cathétérisme de l'artère radiale (si possible gauche ou aux membres supérieurs), voie veineuse profonde, surveillance de la température centrale, sondage vésical.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"2.2","style":"cell_b"},{"t":"p","html":"Il n'existe pas de signe clinique spécifique de l'hypovolémie au cours de la ME ; elle doit être dépistée précocement. Bien que non validée en contexte de ME, l'utilisation de critères dynamiques de réponse au remplissage vasculaire (lever de jambe passif, variabilité respiratoire de la pression artérielle, du flux aortique ou du diamètre de la veine cave supérieure en échocardiographie Doppler) est recommandée.","style":"cell"},{"t":"chip","label":"8,5"}],[{"t":"p","html":"2.3","style":"cell_b"},{"t":"p","html":"Le dépistage de la dysfonction myocardique repose sur l'échocardiographie Doppler, qui permet une meilleure prise en charge du donneur tout en évaluant la qualité du greffon cardiaque éventuel.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"2.4","style":"cell_b"},{"t":"p","html":"L'intérêt des marqueurs biologiques (créatinine kinase et fraction MB, troponine Ic, BNP/ProBNP) pour la reconnaissance d'une dysfonction myocardique est encore mal connu au cours de la ME.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"2.5","style":"cell_b"},{"t":"p","html":"En cas de défaillance cardiocirculatoire non contrôlée, le recours à une technique d'exploration hémodynamique (échocardiographie, cathétérisme cardiaque droit, Doppler œsophagien, système Picco…), laissé au choix de l'opérateur, est recommandé.","style":"cell"},{"t":"chip","label":"9"}]]}]},{"title":"Chapitre 2 — Objectifs thérapeutiques","items":[{"t":"section","text":"Objectifs thérapeutiques recommandés — donneur potentiel","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Paramètre","style":"head_w"},{"t":"p","html":"Cible","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"Pression artérielle moyenne","style":"cell_b"},{"t":"p","html":"65 à 100 mmHg","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"Diurèse","style":"cell_b"},{"t":"p","html":"1 à 1,5 ml/kg/h","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"Température centrale","style":"cell_b"},{"t":"p","html":"35,5 à 38 °C","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"PaO2","style":"cell_b"},{"t":"p","html":"&gt; 80 mmHg","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"Hémoglobine","style":"cell_b"},{"t":"p","html":"&gt; 7 g/dl","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"Lactate artériel","style":"cell_b"},{"t":"p","html":"normal","style":"cell"},{"t":"chip","label":"7"}]]},{"t":"p","html":"En parallèle, surveiller l'apparition/l'évolution d'un diabète insipide par évaluation régulière du bilan entrées-sorties, de la densité urinaire et des ionogrammes sanguins et urinaires (9).","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"2.6","style":"cell_b"},{"t":"p","html":"Remplissage vasculaire (RV) modéré : cristalloïdes ou colloïdes indifféremment ; au-delà de 3 000 ml, utiliser les colloïdes plutôt que les cristalloïdes.","style":"cell"},{"t":"chip","label":"7,5"}],[{"t":"p","html":"2.7","style":"cell_b"},{"t":"p","html":"Le contrôle précoce du diabète insipide permet d'éviter un RV massif, délétère pour un éventuel prélèvement pulmonaire ; compléter par des transfusions sanguines et traitements substitutifs si besoin.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"2.8","style":"cell_b"},{"t":"p","html":"Le recours aux vasopresseurs, si nécessaire, repose en première intention sur la noradrénaline.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"2.9","style":"cell_b"},{"t":"p","html":"Traitement du diabète insipide : précoce, par desmopressine intraveineuse en fonction de la diurèse et, si nécessaire, compensation de la diurèse par un soluté adapté à l'osmolalité sanguine.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"2.10","style":"cell_b"},{"t":"p","html":"En cas de dysfonction myocardique : adjonction d'un inotrope (dobutamine) ou remplacement de la noradrénaline par de l'adrénaline.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"2.10b","style":"cell_b"},{"t":"p","html":"Certaines études montrent que l'hormonothérapie substitutive (hormone thyroïdienne, cortisol et arginine-vasopressine) apporterait un bénéfice hémodynamique chez le donneur et sur la qualité des greffons.","style":"cell"},{"t":"chip","label":"7"}],[{"t":"p","html":"2.10c","style":"cell_b"},{"t":"p","html":"De plus, l'arginine-vasopressine pourrait permettre une réduction des besoins en catécholamines.","style":"cell"},{"t":"chip","label":"6"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Pas de recommandation forte :</b> ces deux constats portent les cotations les plus basses de tout le document (« 7 » et « 6 » — cette dernière est l'unique occurrence d'une cotation en zone « indécision » relevée dans le texte source). Le texte source précise explicitement que des études complémentaires prospectives sont nécessaires avant d'apporter une recommandation forte sur l'utilisation de l'hormonothérapie substitutive.","style":"body_sm"}}]},{"title":"Chapitre 2 — Poumon, hémostase, infection, pédiatrie","items":[{"t":"section","text":"Optimisation pulmonaire, hémostase, infection, pédiatrie","color":"navy"},{"t":"p","html":"Tous les donneurs d'organes sont des donneurs potentiels de poumon ; l'optimisation de la prise en charge d'un donneur limite peut améliorer la fonction pulmonaire au moment du prélèvement.","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Ventilation (visée prélèvement pulmonaire)","style":"head_w"},{"t":"p","html":"Objectif","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"PaCO2","style":"cell_b"},{"t":"p","html":"35 à 40 mmHg","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"PaO2 (FiO2 minimale)","style":"cell_b"},{"t":"p","html":"80 à 100 mmHg","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"PEP","style":"cell_b"},{"t":"p","html":"minimale, ≈ 5 cmH2O","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"Rapport PaO2/FiO2","style":"cell_b"},{"t":"p","html":"contrôle régulier, avant transfert au bloc","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"Manœuvres de recrutement alvéolaire","style":"cell_b"},{"t":"p","html":"recommandées","style":"cell"},{"t":"chip","label":"8,5"}]]},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"2.11","style":"cell_b"},{"t":"p","html":"L'intérêt du scanner thoracique systématique n'a pas été évalué dans cette indication, mais le suivi radiologique thoracique peut anticiper les mesures correctives en cas de dégradation.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"2.12","style":"cell_b"},{"t":"p","html":"Fibroscopie bronchique systématique si un prélèvement pulmonaire est envisagé (identification d'une cause réversible de dégradation de l'hématose). Une positivité de l'examen bactériologique direct ne contre-indique pas le prélèvement pulmonaire, en l'absence de pneumonie — non coté dans le texte source.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"2.13","style":"cell_b"},{"t":"p","html":"La connaissance de la flore bactérienne du donneur oriente l'antibiothérapie prophylactique et curative des receveurs en cas de pneumonie bactérienne postopératoire précoce.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"2.14","style":"cell_b"},{"t":"p","html":"Les perturbations de l'hémostase (CIVD, fibrinolyse, fibrinogénolyse) sont fréquentes au cours de la ME et sont liées à l'atteinte cérébrale.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"2.15","style":"cell_b"},{"t":"p","html":"Exploration de l'hémostase — 1er groupe de dosages : TP, TCA, fibrinogène, facteur V, plaquettes.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"2.16","style":"cell_b"},{"t":"p","html":"Exploration de l'hémostase — 2e groupe de dosages : D-dimères, complexes solubles.","style":"cell"},{"t":"chip","label":"7"}]]},{"t":"table","rows":[[{"t":"p","html":"Hémostase — seuils minimaux à maintenir","style":"head_w"},{"t":"p","html":"Cible","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"Plaquettes","style":"cell_b"},{"t":"p","html":"&gt; 50 G/l","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"Fibrinogène","style":"cell_b"},{"t":"p","html":"&gt; 1 g/l","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"TP / TCA","style":"cell_b"},{"t":"p","html":"TP &gt; 40 % et TCA ratio &lt; 1,5","style":"cell"},{"t":"chip","label":"8"}]]},{"t":"p","html":"La desmopressine augmente le taux de vWF et de facteur VIII ainsi que l'agrégabilité plaquettaire : action procoagulante, proagrégante et profibrinolytique. <i>(Constat pharmacologique — sans chiffre imprimé.)</i>","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"2.17","style":"cell_b"},{"t":"p","html":"L'acceptabilité du donneur atteint d'affection bactérienne ou fongique reste controversée. Prélèvements bactériologiques standards (hémocultures, urocultures, prélèvements bronchiques) systématiques ; recherche précoce d'une documentation bactérienne pulmonaire, technique laissée au praticien.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"2.18","style":"cell_b"},{"t":"p","html":"Une infection avérée chez le donneur potentiel n'est pas une contre-indication formelle au prélèvement si l'agent pathogène est isolé et un traitement efficace instauré depuis au moins 24-48 h.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"2.18b","style":"cell_b"},{"t":"p","html":"Chaque situation nécessite une évaluation du bénéfice/risque, notamment pour les germes à tropisme vasculaire.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"2.18c","style":"cell_b"},{"t":"p","html":"En cas de prélèvement de poumons ou cœur-poumons : antibiothérapie par amoxicilline-acide clavulanique 1 g/8 h.","style":"cell"},{"t":"chip","label":"8"}]]},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Particularités pédiatriques :</b> le nombre de prélèvements d'organes chez l'enfant est faible en France (40 en 2003). Le diagnostic de ME chez le très jeune enfant repose sur des critères différents de ceux de l'adulte : chez le nouveau-né &lt; 7 jours et le prématuré, l'interprétation de l'examen clinique et de l'EEG étant très difficile, le recours à l'angiographie est le plus souvent nécessaire. Entre 7 jours et 2 mois : 2 examens cliniques et 2 EEG séparés de 48 h. Entre 2 mois et 1 an : 2 examens cliniques et 2 EEG séparés de 24 h, sauf ischémie-anoxie cérébrale (observation plus longue recommandée). Au-delà d'un an, les critères sont ceux de l'adulte. La réanimation d'un enfant en ME repose sur les mêmes principes que chez l'adulte, en adaptant les posologies au poids et les paramètres hémodynamiques à l'âge.","style":"body_sm"}}]},{"title":"Chapitre 3 — Critères organes : général & cœur","items":[{"t":"section","text":"Chapitre 3 — Critères d'évaluation des organes et des tissus","color":"navy"},{"t":"p","html":"Les critères de prélèvement évoluent avec l'expérience des équipes de greffe, ce qui a déjà permis d'étendre les prélèvements à des donneurs dits « limites ». Il est recommandé, pour tout donneur potentiel, de réaliser dès que possible et pour chaque organe un bilan précis clinique et paraclinique.","style":"note"},{"t":"section","text":"3.1 — Critères communs à tous les organes","color":"grey"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"3.1.1","style":"cell_b"},{"t":"p","html":"Contre-indications réglementaires (sécurité sanitaire) : ESB ou maladie équivalente, infection par le VIH, le VHC ou le VHB, tuberculose active, syphilis — diverses dérogations validées ou en cours de discussion (notamment VHB et syphilis).","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.1.2","style":"cell_b"},{"t":"p","html":"Contre-indications médicales : cancers avérés ou métastasés (exception possible pour certaines tumeurs cérébrales).","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.1.3","style":"cell_b"},{"t":"p","html":"Évaluation au cas par cas du rapport risque/bénéfice : maladies de système, allergies, la plupart des intoxications, infections bactériennes, donneurs âgés.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.1.4","style":"cell_b"},{"t":"p","html":"Données morphologiques requises pour chaque organe : si un scanner cérébral est pratiqué pour confirmer la ME, réaliser en même temps une tomodensitométrie thoraco-abdominale.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}]]},{"t":"section","text":"3.2 — Prélèvement cardiaque","color":"grey"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"3.2.1","style":"cell_b"},{"t":"p","html":"L'examen clinique et l'anamnèse ne sont pas suffisamment sensibles/spécifiques pour l'évaluation du greffon ; évaluer la fonction et la structure du cœur par échographie transthoracique, complétée au moindre doute par une échographie transœsophagienne.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.2.2","style":"cell_b"},{"t":"p","html":"Les anomalies ECG isolées (sus/sous-décalage ST, inversion de l'onde T, allongement du QT) ne sont pas à prendre en compte ; les arythmies ventriculaires répétitives sans anomalie hydroélectrolytique évidente sont en revanche de mauvais pronostic.","style":"cell"},{"t":"chip","label":"7,5"}],[{"t":"p","html":"3.2.3","style":"cell_b"},{"t":"p","html":"L'absence de coronarographie au-delà de 55 ans ne doit pas être une contre-indication au prélèvement.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.2.4","style":"cell_b"},{"t":"p","html":"L'utilisation de catécholamines n'est plus en soi une contre-indication au prélèvement cardiaque ; il est actuellement impossible de définir une dose seuil.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.2.5","style":"cell_b"},{"t":"p","html":"Devant une altération de la fonction systolique chez un patient &lt; 55 ans sans facteur de risque cardiopathique : réanimation agressive avant de décréter le cœur non prélevable.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.2.6","style":"cell_b"},{"t":"p","html":"Dans ce cas, il est recommandé de pratiquer une nouvelle échographie cardiaque après chaque ajustement thérapeutique.","style":"cell"},{"t":"chip","label":"7"}],[{"t":"p","html":"3.2.7","style":"cell_b"},{"t":"p","html":"Contre-indications absolues (7 des 8 critères cotés « 9 » ; voir 3.2.8 pour le 8<sup>e</sup>) : intoxication au CO (taux &gt; 20 %), arythmies ventriculaires graves, infarctus du myocarde documenté (quelle que soit l'ancienneté), malformation cardiaque non corrigée, tumeur cardiaque, hypokinésie globale (FEVG &lt; 0,3), lésions sévères en coronarographie.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.2.8","style":"cell_b"},{"t":"p","html":"Contre-indication absolue supplémentaire : hypoxémie sévère (SaO2 &lt; 80 %).","style":"cell"},{"t":"chip","label":"7,5"}]]}]},{"title":"Chapitre 3 — Poumon & foie","items":[{"t":"section","text":"3.3 — Prélèvement pulmonaire","color":"grey"},{"t":"p","html":"Compte tenu de la rareté des prélèvements pulmonaires, il est particulièrement recommandé de tenir compte de l'évolution des critères.","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"3.3.1","style":"cell_b"},{"t":"p","html":"Antécédents respiratoires chroniques/tabagisme et examen clinique détaillé sont indispensables mais insuffisants pour la sélection pulmonaire ; évaluation régulière de l'hématose et de l'imagerie recommandée.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.3.2","style":"cell_b"},{"t":"p","html":"La durée de ventilation n'est plus un critère de non-prélèvement, mais une analyse au cas par cas des conditions de ventilation et de colonisation des voies aériennes est indispensable.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.3.3","style":"cell_b"},{"t":"p","html":"Une radiographie ou un scanner thoracique normal est un excellent critère de prélèvement.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.3.4","style":"cell_b"},{"t":"p","html":"Optimiser la ventilation mécanique avant d'utiliser les critères d'imagerie et d'hématose.","style":"cell"},{"t":"chip","label":"8,5"}],[{"t":"p","html":"3.3.5","style":"cell_b"},{"t":"p","html":"L'utilisation de catécholamines n'est plus un critère de non-prélèvement.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.3.6","style":"cell_b"},{"t":"p","html":"Contre-indications absolues : âge du donneur &gt; 70 ans ; opacités alvéolaires bilatérales non réversibles après fibroaspiration/déplétion hydrosodée/optimisation ventilatoire ; rapport PaO2/FiO2 &lt; 250 après optimisation.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.3.7","style":"cell_b"},{"t":"p","html":"Contre-indication absolue supplémentaire, non cotée dans le texte source : antécédents de maladie respiratoire chronique non réversible.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.3.8","style":"cell_b"},{"t":"p","html":"Contre-indication absolue supplémentaire : ischémie froide &gt; 8 heures.","style":"cell"},{"t":"chip","label":"8"}]]},{"t":"section","text":"3.4 — Prélèvement hépatique","color":"grey"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"3.4.1","style":"cell_b"},{"t":"p","html":"La bonne qualité du greffon fourni par certains donneurs de 80 ans ou plus a été largement démontrée.","style":"cell"},{"t":"chip","label":"8,5"}],[{"t":"p","html":"3.4.2","style":"cell_b"},{"t":"p","html":"Le diabète et l'HTA ne sont pas en soi des contre-indications ; l'éthylisme chronique ne contre-indique pas le prélèvement si le foie est macroscopiquement normal et sans altération biologique majeure ; une anomalie aiguë de la biologie hépatique (cytolyse) ne contre-indique pas non plus.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.4.3","style":"cell_b"},{"t":"p","html":"Une natrémie &gt; 170 mmol/l peut être une contre-indication au prélèvement hépatique.","style":"cell"},{"t":"chip","label":"7"}],[{"t":"p","html":"3.4.4","style":"cell_b"},{"t":"p","html":"Les infections virales nécessitent une attention particulière (tropisme hépatique) mais ne contre-indiquent pas systématiquement le prélèvement.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.4.5","style":"cell_b"},{"t":"p","html":"Imagerie hépatique et abdominale indispensable (échographie et/ou scanner) pour rechercher stéatose ou tumeur parenchymateuse.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.4.6","style":"cell_b"},{"t":"p","html":"Biopsie hépatique indiquée en cas de maladie inflammatoire de l'intestin, ou d'obésité morbide.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.4.7","style":"cell_b"},{"t":"p","html":"Biopsie hépatique également indiquée lorsque le foie est macroscopiquement douteux.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.4.8","style":"cell_b"},{"t":"p","html":"La stéatose microvésiculaire, même massive, ne contre-indique pas le prélèvement.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.4.9","style":"cell_b"},{"t":"p","html":"La stéatose macro-vacuolaire peut contre-indiquer la greffe au-delà de 30-60 %, selon le degré d'urgence de la transplantation.","style":"cell"},{"t":"chip","label":"7,5"}],[{"t":"p","html":"3.4.10","style":"cell_b"},{"t":"p","html":"En cas de doute, la décision relève de l'équipe de transplantation.","style":"cell"},{"t":"chip","label":"9"}]]}]},{"title":"Chapitre 3 — Rein & pancréas","items":[{"t":"section","text":"3.5 — Prélèvement rénal","color":"grey"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"3.5.1","style":"cell_b"},{"t":"p","html":"L'âge du donneur, même très avancé, n'est pas une contre-indication ; la qualité du greffon devra être analysée au vu des comorbidités, des problèmes survenus en réanimation et du temps d'ischémie froide, à réduire au maximum.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.5.2","style":"cell_b"},{"t":"p","html":"Une HTA de plus de dix ans est à prendre en compte pour la décision de prélèvement.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.5.3","style":"cell_b"},{"t":"p","html":"Examens indispensables : créatininémie, ECBU, étude du sédiment urinaire, imagerie rénale (échographie ou scanner).","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.5.4","style":"cell_b"},{"t":"p","html":"Le taux de créatininémie à l'admission (ou les jours précédents) et le calcul de la clairance par la formule de Cockcroft sont des critères déterminants de la qualité du greffon.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.5.5","style":"cell_b"},{"t":"p","html":"Une hématurie/protéinurie modérées ou une insuffisance rénale aiguë apparue en réanimation ne contre-indiquent pas le prélèvement.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.5.5b","style":"cell_b"},{"t":"p","html":"Un arrêt cardiaque &lt; 30 minutes ou une instabilité hémodynamique, même sous fortes doses de catécholamines, ne contre-indiquent pas non plus le prélèvement — non coté dans le texte source.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.5.6","style":"cell_b"},{"t":"p","html":"Limiter la multiplication des actes d'imagerie avec opacification vasculaire (impact des produits de contraste iodés chez le donneur).","style":"cell"},{"t":"chip","label":"7,5"}],[{"t":"p","html":"3.5.7","style":"cell_b"},{"t":"p","html":"Contre-indications : clairance de la créatinine &lt; 30 ml/min, glomérulosclérose &gt; 50 %, lésions athéromateuses majeures.","style":"cell"},{"t":"chip","label":"9"}]]},{"t":"section","text":"3.6 — Prélèvement pancréatique","color":"grey"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"3.6.1","style":"cell_b"},{"t":"p","html":"Pancréas total : âge du donneur &lt; 45 ans, sauf traumatisé sans antécédent (jusqu'à 55 ans).","style":"cell"},{"t":"chip","label":"7,5"}],[{"t":"p","html":"3.6.1b","style":"cell_b"},{"t":"p","html":"Îlots de Langerhans : âge entre 18 et 70 ans, meilleur résultat au-delà de 50 ans — non coté dans le texte source.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.6.1c","style":"cell_b"},{"t":"p","html":"Double greffe rein-pancréas : IMC préférentiellement &lt; 27 — non coté dans le texte source.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.6.2","style":"cell_b"},{"t":"p","html":"Un taux d'amylase égal au double de la norme ne contre-indique pas le prélèvement.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.6.2b","style":"cell_b"},{"t":"p","html":"Une imagerie pancréatique est recommandée avant le prélèvement — non cotée dans le texte source.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.6.3","style":"cell_b"},{"t":"p","html":"L'instabilité hémodynamique et l'arrêt cardiaque sont des facteurs de risque de pancréatite aiguë et de thrombose des vaisseaux pancréatiques chez le receveur ; une héparinothérapie pourrait être maintenue/envisagée pour prévenir les microthromboses du greffon.","style":"cell"},{"t":"chip","label":"7"}],[{"t":"p","html":"3.6.4","style":"cell_b"},{"t":"p","html":"Durée de séjour en réanimation avant prélèvement : ne devrait pas dépasser 5 jours (discussion au cas par cas au-delà) — non coté dans le texte source.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.6.4b","style":"cell_b"},{"t":"p","html":"Ischémie froide : &lt; 8 h pour les îlots de Langerhans, &lt; 18 h pour le pancréas total.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.6.5","style":"cell_b"},{"t":"p","html":"L'aspect macroscopique du pancréas au bloc opératoire est le critère final déterminant pour le prélèvement.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}]]}]},{"title":"Chapitre 3 — Intestin & tissus","items":[{"t":"section","text":"3.7 — Prélèvement intestinal","color":"grey"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"3.7.1","style":"cell_b"},{"t":"p","html":"Pas de limite inférieure d'âge pour les donneurs pédiatriques. Greffe isolée d'intestin : poids du donneur &lt; 4 fois celui du receveur ; greffe combinée foie-intestin : ratio &lt; 2.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.7.2","style":"cell_b"},{"t":"p","html":"Une laparotomie antérieure ne contre-indique pas le prélèvement.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.7.3","style":"cell_b"},{"t":"p","html":"Des antécédents de maladie chronique de l'intestin contre-indiquent le prélèvement.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.7.4","style":"cell_b"},{"t":"p","html":"Greffes combinées foie + intestin : transaminases &lt; 3 fois la normale et γ-GT normales.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.7.5","style":"cell_b"},{"t":"p","html":"Un arrêt cardiaque prolongé et/ou une instabilité hémodynamique contre-indiquent le prélèvement (risque d'ischémie mésentérique).","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.7.5b","style":"cell_b"},{"t":"p","html":"De même, l'utilisation d'adrénaline/noradrénaline au-delà de 2 µg/kg/min doit faire contre-indiquer le prélèvement.","style":"cell"},{"t":"chip","label":"7,5"}],[{"t":"p","html":"3.7.6","style":"cell_b"},{"t":"p","html":"Une hypernatrémie au moment du prélèvement est associée à un taux élevé de perte de greffons.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}]]},{"t":"section","text":"3.8 — Prélèvements de tissus","color":"grey"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"3.8.1","style":"cell_b"},{"t":"p","html":"Nombreux tissus prélevables : cornées, membranes amniotiques, os massifs, tissus mous de l'appareil locomoteur, vaisseaux, valves cardiaques, peau. Prélèvements réalisables lors d'un PMO ou à la morgue ; organisation toujours gérée par la coordination hospitalière. Pas de limite d'âge pour le donneur.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.8.2","style":"cell_b"},{"t":"p","html":"Contrôle qualité de chaque greffon réalisé par la banque de tissus qui le réceptionne.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"3.8.3","style":"cell_b"},{"t":"p","html":"Les antécédents de cancer solide ne contre-indiquent pas le prélèvement de cornée.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.8.3b","style":"cell_b"},{"t":"p","html":"Les infections virales ne sont pas une contre-indication systématique au prélèvement de tissus.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"3.8.4","style":"cell_b"},{"t":"p","html":"Les échantillons sanguins prélevés après le décès pour la sécurité sanitaire doivent être centrifugés au plus vite pour éviter les erreurs d'interprétation ; au mieux, récupérer du sang pré-mortem au laboratoire de l'hôpital.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"3.8.5","style":"cell_b"},{"t":"p","html":"Il est souhaitable de développer les réseaux de prélèvement et les échanges interbanques de tissus, notamment pour les cornées.","style":"cell"},{"t":"chip","label":"9"}]]}]},{"title":"Chapitre 4 — Organisation du prélèvement","items":[{"t":"section","text":"Chapitre 4 — Organisation du prélèvement d'organes : présent et avenir","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"4.1","style":"cell_b"},{"t":"p","html":"Le prélèvement d'organes et de tissus est une activité médicale dans laquelle tous les centres hospitaliers doivent s'inscrire, organisée sur l'unité de coordination hospitalière selon des procédures écrites respectant les recommandations de l'Agence de la biomédecine.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"4.2","style":"cell_b"},{"t":"p","html":"L'unité de coordination hospitalière doit être structurée et visible, individualisant les tâches respectives de chacun.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.3","style":"cell_b"},{"t":"p","html":"Critères d'évaluation de l'activité hospitalière : exhaustivité du recueil des comas graves ; appel systématique et précoce de la coordination dès que le diagnostic de ME est envisagé ; appel au service de régulation et d'appui dès l'intention de prélever ; intégration réelle du prélèvement dans l'activité chirurgicale d'urgence ; qualité de la tenue du dossier de coordination.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.4","style":"cell_b"},{"t":"p","html":"La coordination hospitalière vérifie la qualité de la restitution du corps, accompagne la famille dans les démarches et reste disponible pour un suivi ultérieur des proches.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.5","style":"cell_b"},{"t":"p","html":"Au niveau national, l'Agence de la biomédecine valide les critères de sélection et garantit la sécurité sanitaire des greffons ; au niveau inter-régional (SRA), elle valide la procédure de prélèvement, participe à la qualification des greffons, et les répartit/attribue selon la réglementation.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"4.6","style":"cell_b"},{"t":"p","html":"La prise en charge peropératoire du sujet en ME doit être effectuée par un médecin qualifié en anesthésie-réanimation ; le transport entre réanimation et bloc opératoire est une période à risque maximum — sujet monitoré, accompagné par une équipe médicalisée.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.7","style":"cell_b"},{"t":"p","html":"L'utilisation d'analgésiques et de myorelaxants chez un sujet en ME est justifiée.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.8","style":"cell_b"},{"t":"p","html":"La prise en charge instituée en réanimation doit être maintenue en période peropératoire, avec mise en place d'un monitorage supplémentaire si l'état hémodynamique l'exige ; les règles de transfusion et d'apport de produits sanguins restent valables en période peropératoire.","style":"cell"},{"t":"chip","label":"9"}]]}]},{"title":"Chapitre 4 — PMO : chronologie & traçabilité","items":[{"t":"section","text":"Prélèvement multi-organes (PMO) — organisation pratique","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"4.9","style":"cell_b"},{"t":"p","html":"Tout participant à un PMO doit avoir un comportement consensuel, courtois, et veiller à une bonne coordination entre équipes ; le chirurgien doit avoir été formé spécifiquement à la technique du PMO.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.10","style":"cell_b"},{"t":"p","html":"Le PMO est une urgence chirurgicale qui ne doit passer qu'après les urgences hémorragiques et obstétricales ; il est recommandé de l'effectuer dans une salle dédiée avec une équipe spécifique, sans perturber les autres activités chirurgicales.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.11","style":"cell_b"},{"t":"p","html":"Veiller à ce que l'installation du malade convienne à toutes les équipes chirurgicales.","style":"cell"},{"t":"chip","label":"9"}]]},{"t":"p","html":"<b>Chronologie du PMO (telle que décrite par le texte source) :</b>","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"4.12","style":"cell_b"},{"t":"p","html":"Aucun geste à fort risque hémorragique (canulation aortique, contrôle de l'aorte cœliaque, canulation de la VCI) ne doit être réalisé tant que les différentes équipes ne sont pas prêtes à clamper — non coté dans le texte source.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"4.13","style":"cell_b"},{"t":"p","html":"Pour raccourcir au maximum la durée d'ischémie froide des prélèvements à visée immunologique, faire parvenir au laboratoire au moins 3 ganglions de bonne qualité (0,5 cm de diamètre) le plus tôt possible.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.14","style":"cell_b"},{"t":"p","html":"Prélèvements sanguins/tissulaires pour tests immunologiques et sérologies réglementaires (typage HLA, cross-matches) : le plus tôt possible, résultats rendus en urgence — sans attendre la confirmation de ME ni l'accord des proches.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.15","style":"cell_b"},{"t":"p","html":"Conditionnement des organes : immersion dans un liquide de préservation à 4 °C, triple emballage stérile, placés dans la glace, accompagnés d'un tube de sang à température ambiante pour vérification ultime du groupe sanguin.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.16","style":"cell_b"},{"t":"p","html":"Pas de consensus sur la solution de conservation des organes à utiliser ; les solutions de type extracellulaire sont à privilégier. Utiliser la même solution de conservation pour le prélèvement simultané des viscères intra-abdominaux.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.17","style":"cell_b"},{"t":"p","html":"Pendant toute la durée de l'ischémie froide, la température de conservation des greffons doit être strictement maintenue entre 2 et 4 °C.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"4.18","style":"cell_b"},{"t":"p","html":"Prélèvement bactériologique et mycologique du liquide de conservation systématique avant l'implantation de chaque greffon.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.19","style":"cell_b"},{"t":"p","html":"Avant toute transplantation rénale ou pancréatique, le cross-match doit être réalisé en urgence.","style":"cell"},{"t":"chip","label":"9"}],[{"t":"p","html":"4.20","style":"cell_b"},{"t":"p","html":"Avant tout prélèvement à des fins thérapeutiques, qualification des organes par recherche d'infection : VIH, VHB, VHC, HTLV, CMV, EBV, syphilis, toxoplasmose — l'appariement peut ne pas tenir compte du statut sérologique du receveur selon l'infection détectée, avec situations dérogatoires selon l'organe et l'urgence.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}]]}]},{"title":"Chapitre 4 — Cœur arrêté & sources","items":[{"t":"section","text":"Donneurs à cœur arrêté (Maastricht)","color":"grey"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation / constat du jury","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"4.21","style":"cell_b"},{"t":"p","html":"Dans certains pays, les prélèvements sur donneurs à cœur arrêté ont augmenté significativement le nombre de transplantations ; avec des critères de sélection stricts des donneurs et des receveurs, cette technique procure aux équipes entraînées des résultats de survie et de fonction des greffons rénaux comparables aux prélèvements sur donneurs à cœur battant.","style":"cell"},{"t":"chip","label":"8"}],[{"t":"p","html":"4.22","style":"cell_b"},{"t":"p","html":"La pose de la sonde de Gillot, l'exsanguination et la réfrigération du donneur potentiel ont été approuvées par le comité d'éthique de l'Agence de la biomédecine, qui considère ces gestes possibles dès le constat du décès et dans l'attente de l'entrevue avec la famille.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"4.23","style":"cell_b"},{"t":"p","html":"Les prélèvements à cœur arrêté supposent des aménagements réglementaires en cours de développement et ne concerneront pas les donneurs relevant de la catégorie III (arrêt de soins) de la classification de Maastricht.","style":"cell"},{"t":"p","html":"—","style":"cell_c"}],[{"t":"p","html":"4.24","style":"cell_b"},{"t":"p","html":"Le choix de ce type de prélèvement nécessite une organisation médicale et paramédicale spécifique.","style":"cell"},{"t":"chip","label":"8"}]]},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Prise en charge des sujets en état de mort encéphalique dans l'optique d'un prélèvement d'organes », conférence d'experts Sfar (G. Boulard, T. Pottecher) / SRLF (P. Guiot, A. Tenaillon) / Agence de la biomédecine, texte court, Ann Fr Anesth Réanim 2005;24:836-843, disponible sur internet le 15/06/2005. Fait suite à un premier référentiel Sfar/EfG/Société française de transplantation de 1998.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> cotation RAND/UCLA, médiane sur échelle 1-9 (zones désaccord 1-3 / indécision 4-6 / accord 7-9), parfois imprimée en notation décimale française à un demi-point (ex. « 8,5 »). Voir encart méthodologie et légende, page 1.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/prise-en-charge-des-sujets-en-etat-de-mort-encephalique-dans-loptique-dun-prelevement-dorganes/","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Il reprend l'intégralité des recommandations et constats gradués des 4 chapitres de la conférence d'experts, mais ne remplace pas le texte intégral (argumentaire complet, références bibliographiques) et n'est ni édité ni validé par la Sfar, la SRLF ou l'Agence de la biomédecine. Texte de 2005 : se référer également, en complément, aux procédures locales de coordination hospitalière et aux évolutions réglementaires et pratiques plus récentes (catégories de Maastricht, critères d'organes), et à un avis spécialisé/à la coordination hospitalière en cas de doute.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Prise-en-charge-des-sujets-en-etat-de-mort-encephalique-dans-loptique-dun-prelevement-dorganes.pdf';

