update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/anesthesie-du-sujet-age-lexemple-de-fracture-de-lextremite-superieure-du-femur/' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'sujet_age_esf',
  card_json = $mgjson${"badge":"GRADE 1/2 + AE","title":"Anesthésie du sujet âgé — exemple de la FESF","short":"Prise en charge périopératoire du sujet âgé, prenant pour modèle la fracture de l'extrémité supérieure du fémur (FESF) : évaluation préopératoire (cardiovasculaire, cognitive, rénale), programme spécifique orthogériatrique et chirurgie ambulatoire, gestion des traitements confusiogènes et de l'anxiété préopératoire, délai d'intervention (48h), monitorage (hémodynamique, PAM, température), techniques et agents anesthésiques, prévention et traitement de la confusion postopératoire, analgésie postopératoire (bloc fémoral/iliofascial). 26 recommandations, 8 questions.","society":"SFAR / SOFCOT / SFGG / SFPC — RFE 2017","version":"2017 (publiée 2019, Anesth Reanim. 2019;5:122-138)","validated":"Validé par le Conseil d'administration de la SFAR le 29/06/2017","methodology":"GRADE 1+/1-/2+/2- + avis d'experts (AE), avec accord Delphi/GRADE Grid fort/faible imprimé séparément","pages":17,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"sujet_age_esf","sections":[{"title":"Introduction, méthodologie & légende","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> prise en charge périopératoire du patient âgé, en prenant pour <b>modèle</b> une des interventions les plus fréquentes chez le sujet âgé — la <b>fracture de l'extrémité supérieure du fémur (FESF)</b> — pour rédiger des recommandations concrètes et gradées. Plus de 65 000 FESF/an en France (jusqu'à 150 000/an projetés en 2050) ; mortalité 3,9 % à l'hospitalisation, 24 % à 6 mois. 3 profils de personnes âgées distingués par les experts, à âge identique : les « vigoureux/robustes » (vieillissement réussi, peu de comorbidités), les « fragiles » (réserves diminuées, haut risque en cas d'évènement intercurrent) et les « dépendants-polypathologiques » (l'essentiel de la population dite gériatrique). RFE commune SFAR, SOFCOT (orthogériatrie), SFGG et SFPC, 8 questions, <b>26 recommandations</b>.","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Méthodologie GRADE® — deux axes indépendants, imprimés côte à côte :</b> (1) la <b>force</b> — qualité des preuves classée haute/modérée/basse/très basse, aboutissant à un énoncé toujours binaire positif/négatif et fort/faible : <b>1+/1-</b> (« il faut faire / ne pas faire ») ou <b>2+/2-</b> (« il faut probablement faire / ne pas faire ») ; ou un <b>avis d'experts</b> quand aucune méta-analyse ne permettait d'appliquer GRADE en totalité (revue systématique puis vote, validé si ≥ 70 % d'accord). (2) l'<b>accord</b> du vote d'experts (méthode Delphi/GRADE Grid) : « accord fort » par défaut (≥ 70 %) ; <b>seuls 2 items sur 26 portent la mention « accord faible »</b> (R1.4 et R5.1), signalée par un texte entre parenthèses plutôt que par un second chip inventé.<br/><br/><b>Disclosure — bug d'extraction PDF corrigé :</b> le texte brut extrait du PDF source affiche « GRADE 2<i>S</i> » pour 3 recommandations (R5.1, R6.1, R8.1) — artefact de police du PDF qui substitue la lettre « S » au tiret « − ». Vérifié par rendu visuel à 200 dpi : le texte réellement imprimé est bien « GRADE 2− »/« GRADE 1− », corrigé ici en conséquence, jamais laissé tel quel.<br/><br/><b>Disclosure — incohérence interne au document source</b> (vérifiée par rendu visuel, non une erreur d'extraction) : R3.3 et R3.4 sont formulées négativement (« il ne faut probablement pas… ») mais imprimées « GRADE 2+ », alors que la Méthodologie du document définit elle-même 2+ = « il faut probablement faire » et 2- = « il faut probablement ne pas faire ». Le tag imprimé fait foi (chippé « 2+ » tel quel) ; l'incohérence n'est pas corrigée silencieusement.","style":"body_sm"}},{"t":"section","text":"Légende des grades","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"p","html":"Il faut faire","style":"badge_head"},{"t":"chip","label":"1-"},{"t":"p","html":"Il ne faut pas faire","style":"badge_head"},{"t":"chip","label":"2+"},{"t":"p","html":"Il faut probablement faire","style":"badge_head"},{"t":"chip","label":"2-"},{"t":"p","html":"Il ne faut probablement pas faire","style":"badge_head"},{"t":"chip","label":"AE"},{"t":"p","html":"Avis d'experts","style":"badge_head"}]]}]},{"title":"Q1-Q2 — Évaluation préopératoire & programme spécifique","items":[{"t":"section","text":"Question 1 — Prise en charge préopératoire des patients","color":"navy"},{"t":"p","html":"<b>Risque cardiovasculaire, fonctions cognitives, fonction rénale</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.1","style":"cell_b"},{"t":"p","html":"Il faut réaliser un score de Lee classique pour évaluer le risque cardiovasculaire. Sa VPN reste &gt; 98 % quel que soit l'âge pour les patients peu à risque (RCRI = 1, 63 % des patients de plus de 85 ans dans une étude danoise de 257 342 patients) — pas d'examen complémentaire inutile chez eux ; sa VPP pour prédire une complication cardiaque postopératoire augmente avec l'âge (jusqu'à 6,5 % si &gt; 85 ans et RCRI &gt; 1).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R1.2","style":"cell_b"},{"t":"p","html":"Pour un score de Lee de classe I, l'ECG est suffisant. Pour une classe &gt; I, chirurgie à risque majeur et capacité à l'effort difficilement évaluable par l'interrogatoire : il faut probablement affiner le risque postopératoire par le dosage de biomarqueurs et/ou un test cardiopulmonaire.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R1.3","style":"cell_b"},{"t":"p","html":"Évaluer le risque de confusion ou de troubles cognitifs postopératoires en repérant en préopératoire une plainte cognitive, des troubles de l'humeur et/ou une maladie neurodégénérative (interrogatoire ciblé ; le 6-CIT, rapide [3 min], a une bonne sensibilité/spécificité comparé au MMSE [15 min]).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.4","style":"cell_b"},{"t":"p","html":"Évaluer probablement la fonction rénale en préopératoire selon 2 situations : situation stable et chirurgie programmée (RFE 2012 examens préinterventionnels) ; insuffisance rénale aiguë (RFE 2015 IRA périopératoire). Interrompre les antihypertenseurs au long cours 48-72 h autour de la chirurgie pour éviter une hypovolémie source d'IRA iatrogène. <i>(accord faible)</i>","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"section","text":"Question 2 — Programme spécifique & chirurgie ambulatoire","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R2.1","style":"cell_b"},{"t":"p","html":"Prise en charge multidisciplinaire spécialisée périopératoire associant urgentistes, anesthésistes-réanimateurs, chirurgiens, gériatres, pharmaciens et soignants, afin d'améliorer le devenir postopératoire des patients âgés opérés en chirurgie orthopédique — 46/58 (79 %) des études d'évaluation orthogériatrique rapportent un bénéfice ; plusieurs recommandations internationales (NICE, AAOS, AAGBI, New Zealand Guidelines, SIGN, Clinical Excellence Commission australienne) convergent vers ce modèle.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R2.2","style":"cell_b"},{"t":"p","html":"Privilégier la chirurgie ambulatoire chez le patient âgé quel que soit son âge — semble ne pas augmenter, voire diminuer, les complications postopératoires (dysfonction cognitive, morbidité cardiorespiratoire), à condition d'optimiser la période peropératoire (hémodynamique, respiratoire, thermorégulation) ; surveillance postopératoire du globe vésical et de la douleur particulièrement importante.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Q3 — Traitements confusiogènes & anxiété","items":[{"t":"section","text":"Question 3 — Traitements confusiogènes & anxiété préopératoire","color":"navy"},{"t":"p","html":"<b>Gestion des traitements pouvant engendrer une confusion postopératoire</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R3.1","style":"cell_b"},{"t":"p","html":"Identifier les médicaments à risque de confusion postopératoire (benzodiazépines à demi-vie longue, antidépresseurs tricycliques et IMAO B, antihistaminiques, neuroleptiques, morphiniques — mépéridine et tramadol notamment) et alléger les traitements anticholinergiques et sédatifs, si possible via une conciliation médicamenteuse. Ne pas prescrire <i>de novo</i> un de ces produits devant un trouble dysthymique/psycho-comportemental ; préférer alors une benzodiazépine à demi-vie courte ou un IRS/IRS-NA. Ne pas sevrer brutalement un traitement chronique.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"<b>Évaluation et prise en charge de l'anxiété préopératoire</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R3.2","style":"cell_b"},{"t":"p","html":"Utiliser probablement une échelle objective et validée — Amsterdam Preoperative Anxiety and Information Scale (APAIS, 6 items) ou Hospital Anxiety and Depression Scale (HADS) — pour mesurer l'anxiété préopératoire : l'hétéro-évaluation par le soignant est peu efficiente (chirurgiens et anesthésistes surestiment notablement l'anxiété du patient).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R3.3","style":"cell_b"},{"t":"p","html":"Pour l'anxiolyse, il ne faut probablement pas utiliser d'agent médicamenteux — nombreuses approches non pharmacologiques efficaces (information/éducation, hypnose, écoute musicale).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R3.4","style":"cell_b"},{"t":"p","html":"Lorsqu'une prémédication pharmacologique est envisagée, il ne faut probablement pas administrer d'hydroxyzine (ANSM : risques anticholinergiques — confusion, tachycardie, hypotension, rétention urinaire), de gabapentine ni de prégabaline (données insuffisantes pour conclure).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R3.5","style":"cell_b"},{"t":"p","html":"Si une prémédication médicamenteuse est requise, il faut probablement privilégier une benzodiazépine ou apparenté à demi-vie courte — l'âge &gt; 60 ans et/ou une prémédication majorent le risque de complications respiratoires postopératoires ; poursuivre un traitement chronique par benzodiazépine pour éviter un syndrome de sevrage.","style":"cell"},{"t":"chip","label":"2+"}]]}]},{"title":"Q4-Q5 — Délai d'intervention & monitorage","items":[{"t":"section","text":"Question 4 — Délai d'intervention de la FESF","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R4.1","style":"cell_b"},{"t":"p","html":"Réaliser la chirurgie d'une FESF dans les <b>48 heures</b> suivant l'admission du patient afin de réduire la mortalité postopératoire — une méta-analyse de 35 études (191 873 patients) montre qu'une chirurgie précoce réduit la mortalité (OR 0,74 [0,67 ; 0,81]) ; retarder la chirurgie reste prudent pour les patients ayant des situations pathologiques instables.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"<b>TABLEAU I</b> — Délai d'intervention des FESF (proportion de patients opérés dans les 24 h, par étude)","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Référence","style":"head_w"},{"t":"p","html":"Proportion opérée dans les 24 h","style":"head_w"}],[{"t":"p","html":"Siegmeth et al., 2005","style":"cell"},{"t":"p","html":"74 %","style":"cell"}],[{"t":"p","html":"Smektala et al., 2005","style":"cell"},{"t":"p","html":"64 %","style":"cell"}],[{"t":"p","html":"MacKenzie et al., 2006","style":"cell"},{"t":"p","html":"60 %","style":"cell"}],[{"t":"p","html":"Beringer et al., 1996","style":"cell"},{"t":"p","html":"57 %","style":"cell"}],[{"t":"p","html":"Bottle et al., 2006","style":"cell"},{"t":"p","html":"56 %","style":"cell"}],[{"t":"p","html":"Boddaert et al., 2014","style":"cell"},{"t":"p","html":"&gt; 50 %","style":"cell"}],[{"t":"p","html":"Charalambous et al., 2003","style":"cell"},{"t":"p","html":"44 %","style":"cell"}],[{"t":"p","html":"Parker et al., 1992","style":"cell"},{"t":"p","html":"34 %","style":"cell"}]]},{"t":"section","text":"Question 5 — Monitorage","color":"navy"},{"t":"p","html":"<b>Hémodynamique, pression artérielle, oxygénation cérébrale</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R5.1","style":"cell_b"},{"t":"p","html":"Il ne faut probablement pas réaliser de monitorage systématique du débit cardiaque pour diriger le remplissage vasculaire peropératoire chez les patients âgés présentant une FESF — une méta-analyse Cochrane récente conclut à l'absence de preuve d'amélioration du devenir avec ces stratégies d'optimisation. Chez les patients à risque accru de complications de par leurs comorbidités, il reste recommandé de titrer le remplissage en se guidant sur le volume d'éjection systolique (RFE SFAR 2013). <i>(accord faible)</i>","style":"cell"},{"t":"chip","label":"2-"}]]},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R5.2","style":"cell_b"},{"t":"p","html":"Maintenir probablement la pression artérielle moyenne peropératoire au-dessus d'un seuil correspondant à <b>70 % de la PAM de référence</b> mesurée avant l'intervention, d'autant plus que le patient présente des facteurs de risque de complications postopératoires — plus de 50 définitions de l'hypotension existent dans la littérature, sans seuil commun établi ; le seuil de PAM est préféré à la PAS (moins sujette aux distorsions de mesure).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R5.3","style":"cell_b"},{"t":"p","html":"Traiter probablement sans délai toute hypotension peropératoire chez le sujet âgé afin de limiter le risque de complications rénales ou myocardiques.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R5.4","style":"cell_b"},{"t":"p","html":"Il ne faut probablement pas utiliser en routine, chez le sujet âgé, un monitorage de l'oxygénation cérébrale (spectroscopie proche infrarouge, rSO<sub>2</sub>) pour des chirurgies ne présentant pas de risque neurologique spécifique — littérature de (très) faible qualité, essentiellement observationnelle, méthodologies hétérogènes.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"<b>Température centrale</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R5.5","style":"cell_b"},{"t":"p","html":"Monitorer la température centrale de tout sujet âgé opéré afin de détecter et prévenir les conséquences de l'hypothermie — vasoconstriction et frissons moins efficaces avec le vieillissement, seuil vasoconstricteur abaissé d'environ 1 °C entre 60-80 ans vs 30-50 ans ; les recommandations générales sur l'hypothermie périopératoire de l'adulte s'appliquent tout particulièrement au sujet âgé.","style":"cell"},{"t":"chip","label":"1+"}]]}]},{"title":"Q6-Q7 — Techniques anesthésiques & confusion postopératoire","items":[{"t":"section","text":"Question 6 — Techniques et agents anesthésiques","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R6.1","style":"cell_b"},{"t":"p","html":"Il ne faut pas privilégier une technique d'anesthésie (AG vs ALR) pour diminuer la mortalité après chirurgie de la FESF — aucune étude prospective randomisée ne permet de trancher ; études rétrospectives contradictoires ; la mortalité postopératoire est probablement multifactorielle, l'anesthésie jouant un rôle à court terme mais pas à moyen/long terme.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"R6.2","style":"cell_b"},{"t":"p","html":"Lors d'une anesthésie générale, effectuer une titration avec des agents anesthésiques de courte durée d'action, à des doses adaptées à la pharmacologie du patient âgé et à un monitorage de la profondeur de l'anesthésie — pharmacocinétique/pharmacodynamique des hypnotiques et morphiniques modifiées par le vieillissement (pas les curares) ; induction progressive par titration (propofol ~1 mg/kg lentement, ou AIVOC modèle de Schnider) ; seul l'étomidate prévient avec certitude l'hypotension à l'induction ; rémifentanil particulièrement utile (clairance réduite, sensibilité aux morphiniques augmentée) ; sugammadex peut éviter l'anticholinergique après rocuronium ; protoxyde d'azote souvent mal toléré, à éviter.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R6.3","style":"cell_b"},{"t":"p","html":"Réduire, ou titrer, les doses d'anesthésiques locaux lors d'une rachianesthésie pour réduire les hypotensions peropératoires — pharmacocinétique et pharmacodynamique des anesthésiques locaux modifiées par le vieillissement ; une rachianesthésie titrée (cathéter) réduit les épisodes hypotensifs versus une injection unique ; monitorer la profondeur de la sédation associée pour éviter une sédation trop profonde.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"section","text":"Question 7 — Décompensations cognitives postopératoires","color":"navy"},{"t":"p","html":"<b>Syndrome confusionnel postopératoire :</b> trouble aigu de la vigilance, fréquent (incidence 26-52 % après prothèse totale de hanche), associé à une surmortalité, un risque de déclin cognitif/fonctionnel, un allongement de séjour et des coûts accrus. Facteurs prédisposants majeurs : altération des fonctions cognitives, déficience visuelle/auditive, déshydratation. Diagnostic : DSM-V ou Confusion Assessment Method (CAM) ; intensité évaluée par la Memorial Delirium Assessment Scale (MDAS).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R7.1","style":"cell_b"},{"t":"p","html":"Mettre probablement en place un programme de prévention non médicamenteuse de la confusion postopératoire, favorisant la ré-afférentation sensorielle, l'orientation temporo-spatiale, le rythme veille-sommeil, et contrôlant hydratation, douleur et iatrogénie — le programme non pharmacologique « Elder Life Program » (ELP) diminue l'incidence (15,5 % vs 9,9 %) et la durée du syndrome confusionnel en médecine ; une consultation gériatrique dans les 48 h préop ou 24 h postop réduit l'incidence (50 % vs 32 %) et l'intensité des épisodes chez les patients de plus de 65 ans.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R7.2","style":"cell_b"},{"t":"p","html":"En cas de confusion, identifier probablement les facteurs favorisants, rechercher et traiter une cause directe pour en limiter l'intensité et la durée — traitement associant prise en charge de la cause directe, mesures de prévention, et usage minimum de psychotropes sédatifs (uniquement en cas de trouble du comportement mettant en danger le patient et/ou son entourage).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R7.3","style":"cell_b"},{"t":"p","html":"Administrer probablement une benzodiazépine à demi-vie courte ou un neuroleptique de dernière génération en cas d'anxiété majeure ou de trouble du comportement, pour limiter le danger induit pour le patient et/ou son entourage.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R7.4","style":"cell_b"},{"t":"p","html":"N'utiliser la contention physique qu'en dernier recours et pour une durée la plus courte possible, réévaluée à court terme.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Q8 — Analgésie postopératoire & sources","items":[{"t":"section","text":"Question 8 — Analgésie postopératoire","color":"navy"},{"t":"p","html":"Les recommandations SFAR 2016 sur la douleur postopératoire (déjà couvertes dans ce corpus) s'appliquent au sujet âgé ; ne sont repris ici que quelques points complémentaires propres au patient âgé avec FESF. Morphine : reste l'agent de choix, à condition d'un protocole personnalisé tenant compte de la fonction rénale (risque d'événement indésirable sévère avec une stratégie « aveugle », 1511 patients, White et al.), au mieux via une PCA si le patient comprend son fonctionnement. Néfopam déconseillé chez le sujet âgé (effets anticholinergiques, ANSM). Paracétamol : dose maximale 3 g/j si poids &lt; 50 kg, 2 g/j si poids ≤ 33 kg (ANSM).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R8.1","style":"cell_b"},{"t":"p","html":"Il ne faut probablement pas infiltrer en intra-articulaire et/ou en sous-cutané avec des anesthésiques locaux en cas de chirurgie après fracture du col fémoral et/ou d'arthroplastie de hanche — analgésie obtenue inconstante, dépendante de la technique ; une méta-analyse (756 patients d'arthroplastie de hanche) ne montre pas d'effet analgésique en période postopératoire immédiate en cas de stratégie multimodale associée.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"R8.2","style":"cell_b"},{"t":"p","html":"Réaliser probablement un bloc fémoral ou iliofascial pour assurer l'analgésie en cas de FESF — une revue Cochrane (17 études, 888 patients) montre une diminution des scores de douleur et de la consommation d'antalgiques de secours, sans complication majeure ni surrisque d'événement indésirable ; le bénéfice est plus net lors de la mobilisation de la hanche qu'au repos, et le taux de confusion postopératoire est atténué chez les patients à risque moyen (pas chez les patients à risque élevé).","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Recommandation sur l'anesthésie du sujet âgé : l'exemple de fracture de l'extrémité supérieure du fémur » — RFE commune Société française d'anesthésie et de réanimation (SFAR), Société française de chirurgie orthopédique (SOFCOT/orthogériatrie), Société française de gériatrie et gérontologie (SFGG), Société française de pharmacie clinique (SFPC). Coordonnateur : Frédéric Aubrun. Anesth Reanim. 2019;5:122-138, doi 10.1016/j.anrea.2018.12.002. Texte validé par le Conseil d'administration de la SFAR le 29/06/2017.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> GRADE® — force (1+/1-/2+/2- ou avis d'experts) et accord du vote Delphi/GRADE Grid (fort ≥ 70 % par défaut ; faible pour 2 items sur 26, disclosés en texte) imprimés côte à côte sur chaque tag — voir disclosure méthodologique en page 1 (bug d'extraction PDF corrigé par vérification visuelle ; incohérence source-interne sur R3.3/R3.4 signalée, non résolue silencieusement).","style":"source"},{"t":"p","html":"<b>Couverture :</b> cette fiche reprend l'intégralité des 26 recommandations (R1.1-R8.2) réparties sur les 8 questions du texte (évaluation préopératoire, programme spécifique et chirurgie ambulatoire, gestion des traitements confusiogènes et de l'anxiété, délai d'intervention avec le Tableau I, monitorage, techniques et agents anesthésiques, décompensations cognitives postopératoires, analgésie postopératoire). Comité d'organisation, groupe de lecture et les 178 références bibliographiques (pages 13-17 de la source) ne sont pas retranscrits (sans contenu clinique actionnable au-delà de ce que l'argumentaire cite déjà).","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement — document de 2017/2019 :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend l'intégralité des 26 recommandations du texte source, mais ne remplace pas le texte intégral (argumentaire complet, 178 références bibliographiques) et n'est ni éditée ni validée par la SFAR, la SOFCOT, la SFGG ou la SFPC. Les recommandations elles-mêmes portent spécifiquement sur la fracture de l'extrémité supérieure du fémur (FESF), modèle choisi par les experts pour illustrer la prise en charge périopératoire du sujet âgé en général — se référer en complément aux recommandations SFAR sur la douleur postopératoire (2016), les examens préinterventionnels (2012) et l'insuffisance rénale aiguë périopératoire (2015), déjà couvertes dans ce corpus, et à un avis gériatrique/anesthésique spécialisé en cas de doute.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/anesthesie-du-sujet-age-lexemple-de-fracture-de-lextremite-superieure-du-femur/';

insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/bris-dentaires-perianesthesiques/' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/bris-dentaires-perianesthesiques/' and s.acronym in ('SFAR', 'SFSCMF')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/bris-dentaires-perianesthesiques/' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'bris_dentaires',
  card_json = $mgjson${"badge":"Accord fort","title":"Bris dentaires périanesthésiques","short":"Prévention et conduite à tenir devant un bris dentaire périanesthésique : facteurs prédictifs (consultation préanesthésique, traçabilité, information du patient), prévention au bloc opératoire (choix du protocole, matériel de contrôle des voies aériennes, protection dentaire sur mesure, surveillance péri- et postopératoire), et conduite à tenir devant un bris dentaire constaté (prise en charge immédiate, traçabilité, déclaration, information du patient). 31 propositions, dont 5 addenda pédiatriques.","society":"SFAR / Adarpef / SFSCMF — RFE 2012","version":"2012 (Ann Fr Anesth Reanim 2012;31:272-275)","validated":"Validé par les comités des référentiels cliniques et le CA de la SFAR","methodology":"Pas de GRADE — accord fort global (vote du groupe de travail), sans distinction individuelle entre propositions","pages":4,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"bris_dentaires","sections":[{"title":"Introduction, méthodologie & légende","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> prévention et conduite à tenir devant un bris dentaire périanesthésique — RFE commune SFAR, Association des anesthésistes réanimateurs pédiatriques d'expression française (Adarpef), Société française de stomatologie et chirurgie maxillo-faciale (SFSCMF). Texte court, <b>31 propositions</b> réparties sur 3 chapitres / 10 questions : facteurs prédictifs de bris dentaires (consultation préanesthésique, traçabilité, information du patient), prévention au bloc opératoire (choix du protocole, matériel de contrôle des voies aériennes, protection dentaire, surveillance péri- et postopératoire), conduite à tenir devant un bris dentaire constaté (prise en charge immédiate, traçabilité, déclaration, information du patient).","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Méthodologie :</b> ce document ne comporte <b>aucun système GRADE</b> (pas de tag « GRADE », pas de suffixe 1+/2+ nulle part dans le texte). La source imprime <b>une seule mention de force, globale</b>, immédiatement après l'introduction : « Toutes les propositions ont reçu un accord fort lors des votes par le groupe de travail. » Il n'existe donc pas de distinction fort/faible entre propositions individuelles — chaque proposition est chippée « Fort » de façon uniforme (extension locale de la légende de ce site, jamais un GRADE numérique inventé). La formulation verbale de chaque proposition (« il faut » / « il faut probablement » / « il ne faut probablement pas » / « il ne faut pas ») est reprise telle quelle depuis la source ; elle reflète une nuance de rédaction, pas une force de vote distincte formellement définie par le document.","style":"body_sm"}},{"t":"section","text":"Légende","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"Fort"},{"t":"p","html":"Toutes les 31 propositions du texte ont reçu un <b>accord fort</b> lors du vote du groupe de travail — seule mention de force imprimée par la source, globale et non individuelle (voir disclosure méthodologique ci-dessous).","style":"badge_head"}]]}]},{"title":"Chapitre 1 — Facteurs prédictifs","items":[{"t":"section","text":"Chapitre 1 — Facteurs prédictifs de bris dentaires","color":"navy"},{"t":"p","html":"<b>Q1 — Spécificités de la consultation préanesthésique</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"1","style":"cell_b"},{"t":"p","html":"Rechercher les critères d'intubation difficile et de ventilation au masque difficile.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"2","style":"cell_b"},{"t":"p","html":"Rechercher lors de l'interrogatoire les facteurs de risque de bris dentaires : existence de prothèses, de restaurations (dent naturelle antérieure restaurée par résine composite ou facette collée — élément très fragile) et de traitement orthodontique, de mobilité des dents et des prothèses, ou d'antécédents traumatiques ou parodontaux.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"3","style":"cell_b"},{"t":"p","html":"Insérer probablement des questions relatives à l'état buccodentaire dans un questionnaire rempli par le patient en vue de la consultation d'anesthésie.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"4","style":"cell_b"},{"t":"p","html":"Porter une attention particulière aux incisives supérieures et inférieures, notamment en cas de dent isolée lors de la consultation d'anesthésie.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<b>Q2 — Traçabilité des signes cliniques prédictifs</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"5","style":"cell_b"},{"t":"p","html":"Consigner les signes prédictifs d'intubation et de ventilation au masque difficile dans le compte rendu de la consultation d'anesthésie.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"6","style":"cell_b"},{"t":"p","html":"Consigner de façon compréhensible (schéma dentaire simplifié conseillé) les signes relatifs à l'état dentaire sur le dossier d'anesthésie.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<b>Q3 — Classes de risque & conduite à tenir de prévention</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"7","style":"cell_b"},{"t":"p","html":"Informer le patient du risque dentaire, et lui suggérer en cas de risque identifié une prise en charge par un odonto-stomatologiste avec panoramique dentaire. Chez un patient à risque avec traitement en cours ou prévu, évoquer le report d'intervention chirurgicale ou des soins dentaires dans l'information sur le rapport bénéfice-risque.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"8","style":"cell_b"},{"t":"p","html":"Il ne faut probablement pas adresser systématiquement le patient chez le dentiste et/ou le stomatologue dans les autres cas.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Proposition enfant :</b> chez l'enfant, en cas de traitement orthodontique en cours limitant l'ouverture de bouche (type bielle de Herbst fixe), ou présentant un obstacle au niveau du tiers antérieur du palais (grilles antilangue, antisuccion) avec un risque de bris et d'inhalation et/ou de matériel pouvant être abîmé au cours de l'acte chirurgical intrabuccal (bistouri électrique, ouvre-bouche), il faut probablement demander un avis spécialisé (possibilité de suspendre le traitement ou de démonter le dispositif) en dehors d'un contexte d'urgence.","style":"body_sm"}},{"t":"p","html":"<b>Q4 — Traçabilité de l'information donnée au patient</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"9","style":"cell_b"},{"t":"p","html":"Informer oralement et remettre un document au cours d'une consultation d'anesthésie précisant que les traumatismes dentaires sont possibles au cours de toute anesthésie. La preuve de cette information doit être consignée dans le dossier d'anesthésie, au moins pour les patients avec risque de bris dentaire identifié.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"10","style":"cell_b"},{"t":"p","html":"La note d'information remise au patient doit lui recommander de signaler toute prothèse ou toute fragilité dentaire particulière, notamment au niveau des incisives supérieures et inférieures.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Proposition enfant :</b> en cas d'accès aux voies aériennes potentiellement difficile chez un enfant, informer les parents du risque de luxation accidentelle d'une dent temporaire ou d'une dent définitive immature.","style":"body_sm"}}]},{"title":"Chapitre 2 — Au bloc opératoire","items":[{"t":"section","text":"Chapitre 2 — Au bloc opératoire","color":"navy"},{"t":"p","html":"<b>Q5 — Prévention lors du choix du protocole d'anesthésie & traçabilité</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"11","style":"cell_b"},{"t":"p","html":"Au vu de l'ensemble des risques évalués, proposer une stratégie de prise en charge anesthésique dans le dossier.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"12","style":"cell_b"},{"t":"p","html":"Pour améliorer la qualité des soins et la gestion du risque, mettre en place une stratégie d'équipe pour diminuer l'incidence des bris dentaires.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"13","style":"cell_b"},{"t":"p","html":"En cas de risque de bris dentaire identifié, favoriser la pratique de l'anesthésie locorégionale dans le cadre de l'analyse bénéfice/risque.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"14","style":"cell_b"},{"t":"p","html":"Obtenir un relâchement musculaire optimal pour faciliter les conditions d'intubation trachéale.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Proposition enfant :</b> chez l'enfant entre 3 et 14 ans, rechercher avant l'induction de l'anesthésie une éventuelle dent temporaire devenue mobile depuis la consultation d'anesthésie, en vérifier l'état aux différents temps périopératoires (après l'intubation jusqu'à la sortie de la salle de soins postinterventionnels) et tracer l'information dans le dossier.","style":"body_sm"}},{"t":"p","html":"<b>Q6 — Matériel de contrôle des voies aériennes supérieures</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"15","style":"cell_b"},{"t":"p","html":"En cas d'intubation et/ou de ventilation au masque difficile prévue, tenir compte de l'état dentaire dans la stratégie de contrôle des voies aériennes supérieures.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"16","style":"cell_b"},{"t":"p","html":"En cas de risque identifié de bris dentaire et en l'absence de difficulté de ventilation au masque, il ne faut probablement pas utiliser systématiquement une canule oropharyngée.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"17","style":"cell_b"},{"t":"p","html":"Avoir probablement recours à des solutions alternatives à une canule oropharyngée pour la prévention de la morsure de la sonde (compresses roulées).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"18","style":"cell_b"},{"t":"p","html":"En cas de risque identifié de bris dentaire, le contrôle des voies aériennes doit être assuré par un opérateur expérimenté.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"19","style":"cell_b"},{"t":"p","html":"Si une anesthésie générale est décidée et que l'indication s'y prête, privilégier probablement le choix d'un dispositif supraglottique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"20","style":"cell_b"},{"t":"p","html":"Si une intubation de la trachée est indiquée, utiliser probablement une lame de laryngoscope type Macintosh métallique pour une intubation par laryngoscopie conventionnelle.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"21","style":"cell_b"},{"t":"p","html":"Après discussion avec le patient et pour limiter le risque de bris dentaire, recommander probablement l'utilisation d'une protection dentaire (gouttière) — tenir compte, dans son choix, de l'épaisseur du dispositif qui peut rendre l'accès aux voies aériennes plus difficile.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"22","style":"cell_b"},{"t":"p","html":"Si l'utilisation d'une gouttière est retenue, recommander probablement une gouttière sur mesure plutôt qu'une gouttière standard, et tracer l'information « incité à fournir un protège-dents sur mesure » dans le dossier (délai de réalisation et coût pour le patient, libre d'accepter ou de refuser).","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Proposition enfant :</b> chez l'enfant, utiliser une lame de laryngoscope dont la taille est la mieux adaptée à sa morphologie, notamment en présence de dents fragilisées (maladie carieuse précoce). En période néonatale, éviter d'exercer une pression avec la lame du laryngoscope au niveau de la gencive du maxillaire supérieur — risque d'altération/lésion des germes dentaires ou de déplacement de germes.","style":"body_sm"}},{"t":"p","html":"<b>Q7 — Surveillance péri- et postopératoire de l'état dentaire</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"23","style":"cell_b"},{"t":"p","html":"Pour les patients présentant un risque dentaire identifié, tracer probablement l'absence de dommage dentaire directement visible lié à l'anesthésie.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"24","style":"cell_b"},{"t":"p","html":"En cas de risque de bris dentaire élevé, l'extubation trachéale doit probablement être réalisée par un opérateur expérimenté chez un patient complètement réveillé, sans curarisation résiduelle, et avec une ventilation spontanée efficace.","style":"cell"},{"t":"chip","label":"Fort"}]]}]},{"title":"Chapitre 3 — Conduite à tenir & sources","items":[{"t":"section","text":"Chapitre 3 — Conduite à tenir devant un bris dentaire","color":"navy"},{"t":"p","html":"<b>Q8 — Que faire en cas de bris dentaire ?</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"25","style":"cell_b"},{"t":"p","html":"Si une luxation complète (dent totalement sortie de son alvéole) d'une dent définitive est constatée, la remettre probablement en place rapidement ou la conserver dans du sérum physiologique ou, si disponible, dans une Hank's Balanced Salt Solution (HBSS — conservation dans un milieu isotonique au desmodonte à température ambiante), et demander un avis spécialisé dans le plus bref délai.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"26","style":"cell_b"},{"t":"p","html":"En cas de bris dentaire constaté : prendre en charge une éventuelle complication (inhalation ou ingestion, radiographie thoracique éventuelle) et la traiter ; conserver si possible la dent ou ce qu'il en reste dans du sérum physiologique ; conserver les prothèses descellées et les restaurations.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Proposition enfant :</b> chez l'enfant, il ne faut pas réimplanter une dent temporaire en cas de luxation complète.","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"27","style":"cell_b"},{"t":"p","html":"Au décours d'un traumatisme dentaire : proposer un avis spécialisé avec panoramique dentaire ; établir un constat descriptif et factuel des lésions dans le dossier du patient (sans opinion ni jugement personnel) ; informer le patient rapidement, noter sa réaction et ses réponses ; garder pour soi-même un aide-mémoire détaillé et conserver les photocopies du dossier complet.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"28","style":"cell_b"},{"t":"p","html":"Prendre probablement des photographies des lésions et les conserver.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"29","style":"cell_b"},{"t":"p","html":"En cas de dommage constaté par le patient ultérieurement sans avoir été constaté en périopératoire : le patient doit être reçu par le professionnel ou un représentant de l'établissement de santé pour être informé sur les causes et circonstances du dommage, dans les 15 jours suivant la découverte du dommage ou la demande du patient ; récupérer un éventuel panoramique antérieur à l'acte anesthésique ; prévoir un avis spécialisé.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<b>Q9 — Déclaration de bris dentaire</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"30","style":"cell_b"},{"t":"p","html":"Le praticien doit effectuer, selon son mode d'activité, une déclaration de bris dentaire auprès de son assurance civile professionnelle, ou du service qualité / gestion des évènements indésirables (ou service de contentieux) de son établissement.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<b>Q10 — Documents et information à remettre au patient</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"N°","style":"head_w_c"},{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Accord","style":"head_w_c"}],[{"t":"p","html":"31","style":"cell_b"},{"t":"p","html":"Apporter une information claire au patient, l'accompagner et lui fournir : les coordonnées du service qualité et relation avec les usagers de son établissement ; la radio panoramique effectuée en postopératoire ; les coordonnées du dentiste ou stomatologue ayant constaté l'incident.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<i>Le groupe de travail suggère que les propositions 1, 2, 3, 6, 9, 11 et 23 puissent faire l'objet d'une évaluation des pratiques professionnelles (EPP).</i>","style":"note"},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Bris dentaires périanesthésiques : texte court » — RFE commune Société française d'anesthésie et de réanimation (SFAR), Association des anesthésistes réanimateurs pédiatriques d'expression française (Adarpef), Société française de stomatologie et chirurgie maxillo-faciale (SFSCMF). K. Nouette-Gaulain, F. Lenfant, D. Jacquet Francillon, A. Belbachir, et al. Ann Fr Anesth Reanim 2012;31:272-275, doi 10.1016/j.annfar.2012.01.003. Disponible sur Internet le 24 février 2012.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> pas de système GRADE — propositions rédigées par un groupe d'experts, validées par les comités des référentiels cliniques et le CA de la SFAR ; « toutes les propositions ont reçu un accord fort lors des votes par le groupe de travail » (mention globale, non individuelle — voir disclosure méthodologique en page 1).","style":"source"},{"t":"p","html":"<b>Couverture :</b> cette fiche reprend l'intégralité des 31 propositions numérotées du texte court, réparties sur les 3 chapitres / 10 questions (facteurs prédictifs, prévention au bloc opératoire, conduite à tenir devant un bris dentaire constaté), ainsi que les 5 encarts « Proposition enfant » pédiatriques. Comité d'organisation, déclaration d'intérêts et formulaires d'accompagnement (EPP, diaporama pédagogique, déclaration de bris dentaire — disponibles sur cfar.org / sfar.org) ne sont pas retranscrits (sans contenu clinique actionnable au-delà de ce que la fiche cite déjà).","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement — document de 2012 :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend l'intégralité des 31 propositions du texte source, mais ne remplace pas le texte intégral (argumentaire complet, principales références) et n'est ni éditée ni validée par la SFAR, l'Adarpef ou la SFSCMF. En cas de bris dentaire constaté, utiliser le formulaire de déclaration disponible sur sfar.org et l'joindre au dossier du malade ; en cas de doute, se référer au texte intégral et/ou à un avis spécialisé (odonto-stomatologiste, chirurgien maxillo-facial).","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/bris-dentaires-perianesthesiques/';

insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/reactualisation-de-la-recommandation-sur-la-douleur-postoperatoire/' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/reactualisation-de-la-recommandation-sur-la-douleur-postoperatoire/' and s.acronym in ('SFAR')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/reactualisation-de-la-recommandation-sur-la-douleur-postoperatoire/' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'douleur_reactualisation_2016',
  card_json = $mgjson${"badge":"17 recos","title":"Douleur postopératoire — réactualisation 2016","short":"Réactualisation 2016 de la RFE SFAR sur la douleur postopératoire : complète (ne remplace pas) la RFE 2008 sur des questions non traitées ou des recommandations modifiées. Évaluation de la DPO (échelles enfant/patient non communicant, dépistage DCPC/DN4), thérapeutiques médicamenteuses systémique/orale (AINS, oxycodone, lidocaïne IV, dexaméthasone, kétamine, gabapentinoïdes), et anesthésie locale/locorégionale postopératoire (cathéters périnerveux/péridural/infiltration). 17 recommandations formalisées.","society":"SFAR — RFE 2016","version":"2016 (Anesth Reanim. 2016;2:421-430)","validated":"Texte validé par le conseil d'administration de la Sfar le 17/06/2016","methodology":"GRADE® (1+/1-/2+/2- ou avis d'experts) + vote Delphi/GRADE Grid (accord fort/faible)","pages":4,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"douleur_reactualisation_2016","sections":[{"title":"Introduction, méthodologie & légende","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> cette réactualisation 2016 de la SFAR ne remplace PAS la RFE 2008 « Prise en charge de la douleur postopératoire chez l'adulte et l'enfant » (déjà couverte par une fiche distincte de ce corpus) : elle la <b>complète</b> sur des questions non traitées en 2008, ou <b>modifie</b> certaines recommandations 2008 à la lumière de nouvelles données de la littérature. Groupe de 14 experts SFAR, méthode GRADE®. Trois grands champs : évaluation de la DPO chez l'adulte et l'enfant (dont le monitorage de l'analgésie), thérapeutiques médicamenteuses par voies systémique et orale, anesthésie locale et locorégionale postopératoire.","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Méthodologie GRADE® :</b> qualité des preuves en 4 catégories (haute, modérée, basse, très basse) ; formulation finale toujours binaire — <b>forte</b> : il faut/ne faut pas faire (GRADE 1+ ou 1−) ; <b>faible</b> : il faut probablement/probablement pas faire (GRADE 2+ ou 2−). Vote Delphi/GRADE Grid : accord fort si ≥ 70 % des participants d'accord. Quand aucune méta-analyse ne permettait d'appliquer GRADE en totalité, un <b>avis d'experts</b> était proposé, validé si ≥ 70 % d'accord. <b>17 recommandations formalisées</b> au total ; accord fort obtenu pour 14 d'entre elles (accord faible pour 3, signalé en italique inline).","style":"body_sm"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>⚠ Divergence source-interne disclosée</b> (non résolue silencieusement) : l'introduction de la source annonce elle-même « 11 [recommandations] fortes, 3 [...] faibles et, pour 3 recommandations, [...] un avis d'experts » (11+3+3 = 17). Le recompte exhaustif, tag par tag, des 17 recommandations imprimées individuellement (R1.1-R1.5, R3.1-R3.9, R4.1-R4.3 — aucun R2.x n'existe, voir note ci-dessous) donne <b>10× GRADE 1+/1− (fortes), 4× GRADE 2+/2− (faibles) et 3× avis d'experts</b> (10+4+3 = 17 également, mais 10 fortes et non 11). Aucun grade individuel n'a été deviné ou réassigné pour faire correspondre les deux comptages ; les 17 tags imprimés individuellement font foi dans cette fiche.","style":"body_sm"}},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Absence de recommandation formalisée — question du monitorage :</b> la question « quelles méthodes permettent de monitorer l'analgésie au bloc opératoire et en postopératoire immédiat ? » n'a abouti à AUCUNE recommandation formalisée (pupillométrie, index de nociception ANI, surgical pleth index SPI : évaluation correcte de la balance analgésie-nociception sous anesthésie générale, mais aucune preuve que ce monitorage réduise la douleur ou la consommation d'antalgiques postopératoires) — disclosure explicite de la source elle-même (« Absence de recommandation », imprimé tel quel), reproduite ici plutôt que silencieusement omise. C'est pourquoi la numérotation des recommandations passe directement de R1.5 à R3.1 : la question 2 (monitorage) ne porte aucun numéro Rx.","style":"body_sm"}},{"t":"section","text":"Légende des grades","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"p","html":"Il faut faire","style":"badge_head"},{"t":"chip","label":"1-"},{"t":"p","html":"Il ne faut pas faire","style":"badge_head"},{"t":"chip","label":"2+"},{"t":"p","html":"Il faut probablement faire","style":"badge_head"},{"t":"chip","label":"2-"},{"t":"p","html":"Il ne faut probablement pas faire","style":"badge_head"},{"t":"chip","label":"AE"},{"t":"p","html":"Avis d'experts","style":"badge_head"}]]}]},{"title":"1 — Évaluation de la douleur en périopératoire","items":[{"t":"section","text":"1 — Évaluation de la douleur en périopératoire","color":"navy"},{"t":"p","html":"<b>Quand et pourquoi évaluer ? Bénéfice sur les conséquences postopératoires/chronicisation</b>","style":"cell_b"},{"t":"p","html":"L'identification des patients vulnérables implique un suivi attentif avec une stratégie thérapeutique multimodale, comportant si possible une analgésie locorégionale et l'administration d'agents antihyperalgésiques. Facteurs chirurgicaux de risque de douleur chronique post-chirurgicale (DCPC) : type de chirurgie (thoracotomie, chirurgie mammaire, sternotomie, prélèvement de crête iliaque), reprises chirurgicales, douleurs préopératoires préexistantes, durée de chirurgie > 3 h. Facteurs psychologiques : anxiété, stress, dépression, catastrophisme — l'échelle APAIS (Amsterdam Preoperative Anxiety and Information Scale) permettrait de prédire la transition de la DPO aiguë à chronique. Une douleur neuropathique précoce devra être accompagnée d'un traitement adapté ; le résultat d'un dépistage positif devra être communiqué au patient, au chirurgien et au médecin traitant.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.1","style":"cell_b"},{"t":"p","html":"En période préopératoire, il est recommandé d'identifier les patients les plus vulnérables à la douleur (à risque de développer une douleur postopératoire sévère et/ou une DCPC), en recherchant la présence d'une douleur préopératoire y compris en dehors du site opératoire, la consommation d'opiacés au long court, des facteurs chirurgicaux et psychiques tels que l'anxiété ou la dépression. <i>Avis d'experts, accord fort.</i>","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.2","style":"cell_b"},{"t":"p","html":"Il est probablement recommandé d'utiliser l'échelle Amsterdam Preoperative Anxiety and Information Scale (APAIS) pour rechercher une anxiété et/ou un besoin d'information en période préopératoire. <i>Avis d'experts, accord fort.</i>","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.3","style":"cell_b"},{"t":"p","html":"Il est recommandé d'identifier les facteurs de risques postopératoires de chronicisation de la DPO en recherchant une intensité élevée de la DPO à l'aide d'une échelle numérique (EN), une prolongation inhabituelle de la DPO, une douleur neuropathique précoce (échelle DN4), des signes d'anxiété et/ou de dépression. <i>Avis d'experts, accord fort.</i>","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Échelles de douleur chez l'enfant de moins de 7 ans et chez le patient non communicant</b>","style":"cell_b"},{"t":"p","html":"Nouveau-nés : échelles EDIN, DAN, NFCS utilisables mais non validées en postopératoire ; FLACC utilisable à partir de 2 mois ; EVENDOL validée uniquement en préhospitalier/urgences ; l'EVA doit être présentée verticalement à l'enfant. Patient non communicant : FLACC modifiée-handicap (naissance à 18 ans, 5 items comportementaux) ; ALGOPLUS (score ≥ 2/5 : sensibilité 87 %, spécificité 80 %).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.4","style":"cell_b"},{"t":"p","html":"Il est recommandé d'utiliser une échelle d'autoévaluation à partir de l'âge de 5 ans (échelle des visages). À défaut, il est recommandé d'utiliser l'échelle FLACC pour l'hétéroévaluation de la douleur postopératoire chez l'enfant de moins de 7 ans. <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R1.5","style":"cell_b"},{"t":"p","html":"Chez le patient non communiquant, il est probablement recommandé d'utiliser une échelle d'hétéroévaluation FLACC modifiée-handicap chez l'enfant et ALGOPLUS chez le vieillard. <i>(accord faible — tag imprimé « 1+ » par la source malgré la formulation « probablement recommandé », reproduit tel quel, non corrigé en 2+.)</i>","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"<b>Surveillance des patients sous opioïdes en structure de soins conventionnels</b>","style":"cell_b"},{"t":"p","html":"Les modalités de surveillance (voie SC, ACP, péridurale) restent celles des conférences de consensus 1997/1999, non modifiées. Terrains à risque identifiés depuis : âge > 70 ans, naïveté aux opiacés, obésité morbide (IMC > 35), maladie respiratoire, SAOS, insuffisance hépatique/rénale, douleur intense cessant subitement, association à des dépresseurs du SNC (benzodiazépines, barbituriques, antidépresseurs, antiémétiques, antihistaminiques), alcool/drogues illicites, troubles neuromusculaires, voie périmédullaire. Une surveillance clinique plus fréquente et/ou un monitorage non invasif (saturométrie, capnographie en SSPI) sont probablement suggérés chez ces patients à risque — <b>aucune recommandation formalisée nouvelle</b> sur ce point (rappels méthodologiques uniquement).","style":"body_sm"},{"t":"p","html":"<b>Monitorage de l'analgésie au bloc opératoire et en postopératoire immédiat</b>","style":"cell_b"},{"t":"p","html":"Pupillométrie, index de nociception (ANI), surgical pleth index (SPI) : évaluation correcte de la balance analgésie-nociception sous anesthésie générale, mais pas de preuve qu'un tel monitorage réduise la douleur postopératoire ou la consommation d'antalgiques. Chez le patient éveillé, corrélation partielle avec les scores d'auto/hétéroévaluation, sans preuve de supériorité en postopératoire immédiat ; aucune étude chez le patient « non communicant ».","style":"body_sm"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Absence de recommandation formalisée</b> — imprimé tel quel par la source (x2) pour cette question.","style":"body_sm"}}]},{"title":"2 — Thérapeutiques médicamenteuses systémique/orale","items":[{"t":"section","text":"2 — Thérapeutiques médicamenteuses par voies systémique et orale","color":"navy"},{"t":"p","html":"<b>AINS sélectifs (ISCOX2) et non sélectifs (AINS-NS)</b>","style":"cell_b"},{"t":"p","html":"Associés à la morphine : amélioration des scores de douleur, épargne morphinique significative, réduction des NVPO et de la durée de l'iléus (niveau de preuve élevé, 15 études dont 2 méta-analyses pour les AINS-NS, 25 études dont 1 méta-analyse pour les ISCOX2). Risque rénal : contre-indiqués si clairance créatinine < 50 mL/min. Risque thrombotique : bien démontré pour les ISCOX2 ; pour les AINS-NS, 2 études rétrospectives (10 873 et 1309 patients) sans risque cardiovasculaire surajouté retrouvé. Risque hémorragique : les AINS utilisés en France (kétoprofène, ibuprofène) n'augmentent pas le risque hémorragique postopératoire, y compris après amygdalectomie ; vigilance chez les patients sous anticoagulants (étude sur 8000 patients : risque de saignement x2,5 si AINS + anticoagulant curatif).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R3.1","style":"cell_b"},{"t":"p","html":"Il est recommandé d'associer un AINS non sélectif (AINS-NS) ou un inhibiteur sélectif des cyclo-oxygénases de type 2 (ISCOX2) à la morphine en l'absence de contre-indication à l'usage de l'AINS. <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R3.2","style":"cell_b"},{"t":"p","html":"Il n'est pas recommandé d'utiliser un inhibiteur des cyclo-oxygénases de type 2 (ISCOX2) chez les patients ayant des antécédents athéro-thrombotiques artériels (AOMI, AVC, IDM). <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"R3.3","style":"cell_b"},{"t":"p","html":"Les AINS-NS ne sont probablement pas recommandés chez les patients ayant des antécédents athéro-thrombotiques artériels (AOMI, AVC, IDM) au-delà de 7 jours de traitement. <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"R3.4","style":"cell_b"},{"t":"p","html":"Il n'est pas recommandé d'associer des AINS-NS à un traitement anticoagulant à dose curative. <i>(accord faible)</i>","style":"cell"},{"t":"chip","label":"1-"}]]},{"t":"p","html":"<b>Oxycodone, opiacés forts, lidocaïne IV, corticoïdes</b>","style":"cell_b"},{"t":"p","html":"Oxycodone : efficacité clinique équivalente à la morphine (ratio 1/1 en IV, 1/2 par voie orale — 5 mg oxycodone = 10 mg sulfate de morphine). Lidocaïne IV : propriétés analgésiques, antihyperalgésiques et anti-inflammatoires ; dose 1-2 mg/kg en bolus puis 1-2 mg/kg/h en continu. Dexaméthasone : corticoïde le plus étudié en prémédication, dose recommandée 8 mg chez l'adulte (0,15 mg/kg chez l'enfant).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R3.5","style":"cell_b"},{"t":"p","html":"Il est recommandé de prescrire un opiacé fort (morphine ou oxycodone), préférentiellement par voie orale, en cas de douleurs postopératoires sévères ou insuffisamment calmées par les antalgiques des paliers inférieurs, et ceci quel que soit l'âge. <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R3.6","style":"cell_b"},{"t":"p","html":"Il est probablement recommandé d'administrer de la lidocaïne en intraveineux et en continu à la dose d'1 à 2 mg/kg en bolus intraveineux suivi de 1 à 2 mg/kg/h, chez les patients adultes opérés d'une chirurgie majeure (abdomino-pelvienne, rachidienne) et ne bénéficiant pas d'une analgésie périnerveuse ou péridurale concomitante, dans le but de diminuer la douleur postopératoire et d'améliorer la réhabilitation. <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R3.7","style":"cell_b"},{"t":"p","html":"Il est probablement recommandé d'administrer la dexaméthasone IV à la dose de 8 mg pour diminuer la douleur postopératoire. <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"<b>Kétamine, magnésium, gabapentinoïdes</b>","style":"cell_b"},{"t":"p","html":"Kétamine à faible dose (0,5 mg/kg max après induction, entretien 0,125-0,25 mg/kg/h, arrêt 30 min avant la fin de la chirurgie) : réduit l'intensité de la douleur aiguë sur 24h, la consommation de morphine (~15 mg/24h) et les NVPO (niveau de preuve modéré) ; réduit l'incidence de la DCPC à 3 mois de 30 % (niveau de preuve bas). Prolongation postopératoire : accroît le risque d'hallucinations sans bénéfice analgésique majoré. Magnésium : non recommandé (niveau de preuve insuffisant). Gabapentine/prégabaline en prémédication : réduisent douleur/consommation morphinique/NVPO sur 24h, mais aucun effet sur la DCPC (niveau de preuve élevé), risque de sédation/vertiges/troubles visuels ; bénéfice net surtout en chirurgie lourde pronociceptive (arthroplasties, rachis, amputations).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R3.8","style":"cell_b"},{"t":"p","html":"En peropératoire, l'administration de faible dose de kétamine chez un patient sous anesthésie générale est recommandée dans les deux situations suivantes : (a) chirurgie à risque de douleur aiguë intense ou pourvoyeuse de DCPC ; (b) patients vulnérables à la douleur, en particulier sous opioïdes au long cours ou présentant une toxicomanie aux opiacés. <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R3.9","style":"cell_b"},{"t":"p","html":"L'utilisation systématique des gabapentinoïdes en périopératoire n'est pas recommandée pour la prise en charge de la DPO. <i>(accord faible)</i>","style":"cell"},{"t":"chip","label":"1-"}]]}]},{"title":"3 — ALR postopératoire & sources","items":[{"t":"section","text":"3 — Anesthésie locale et locorégionale postopératoire","color":"navy"},{"t":"p","html":"<b>Cathétérisme périnerveux, péridural et paravertébral</b>","style":"cell_b"},{"t":"p","html":"Intérêt confirmé d'un cathéter périnerveux en cas de risque de douleur postopératoire modérée à sévère, notamment chirurgie prothétique de l'épaule (interscalénique) et du genou (fémoral) : efficacité analgésique prolongée, épargne opioïde, réduction des NVPO, amélioration du sommeil et de la satisfaction — mais aucune preuve d'effet sur la chronicisation de la douleur. Risque de mobilisation du cathéter (5-25 %). Cathéter fémoral : bloc moteur pouvant favoriser les chutes et gêner la réhabilitation précoce après prothèse de genou. Cathéter interscalénique : parésie diaphragmatique à prendre en compte en cas de pathologie respiratoire. <b>Aucune recommandation formalisée nouvelle</b> sur ce point — la source imprime « Absence de recommandation » séparément pour le cathétérisme périnerveux ET pour le cathétérisme péridural/paravertébral (2 mentions distinctes, rappels méthodologiques uniquement).","style":"body_sm"},{"t":"p","html":"<b>Cathéter d'infiltration du site opératoire</b>","style":"cell_b"},{"t":"p","html":"De nombreux protocoles d'infiltration sont proposés comme alternative aux cathéters nerveux périphériques, mais leur efficacité est moindre après la 24<sup>e</sup> heure. Doses maximales d'anesthésiques locaux pour la première injection chez un adulte jeune ASA 1 :","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Agent","style":"head_w"},{"t":"p","html":"Dose maximale (mg/kg)","style":"head_w_c"}],[{"t":"p","html":"Lidocaïne adrénalinée","style":"cell"},{"t":"p","html":"7","style":"cell_c"}],[{"t":"p","html":"Mépivacaïne","style":"cell"},{"t":"p","html":"5","style":"cell_c"}],[{"t":"p","html":"Lévobupivacaïne","style":"cell"},{"t":"p","html":"3","style":"cell_c"}],[{"t":"p","html":"Ropivacaïne","style":"cell"},{"t":"p","html":"3","style":"cell_c"}]]},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w_c"},{"t":"p","html":"Recommandation (texte condensé, fidèle à la source)","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R4.1","style":"cell_b"},{"t":"p","html":"Il est recommandé de rester en deçà des doses maximales toxiques d'anesthésiques locaux, en particulier pour les infiltrations périprothétiques orthopédiques et lors d'association d'infiltrations cicatricielles et de cathéters périnerveux analgésiques. <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R4.2","style":"cell_b"},{"t":"p","html":"En cas de laparotomie (laparotomie, césarienne et lombotomie) et en l'absence d'analgésie périmédullaire, il est probablement recommandé de proposer la mise en place d'un cathéter cicatriciel pour infiltration continue. <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R4.3","style":"cell_b"},{"t":"p","html":"Il n'est pas recommandé de réaliser une infiltration analgésique au moyen d'un cathéter intra-articulaire en raison du risque toxique des anesthésiques locaux sur le cartilage (toxicité directe sur les chondrocytes). <i>Accord fort.</i>","style":"cell"},{"t":"chip","label":"1-"}]]},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Réactualisation de la recommandation sur la douleur postopératoire » — Recommandations formalisées d'experts, Société française d'anesthésie et de réanimation (SFAR). F. Aubrun, K. Nouette Gaulain, D. Fletcher, A. Belbachir, H. Beloeil, M. Carles, et al. Anesth Reanim. 2016;2:421-430, doi 10.1016/j.anrea.2016.09.006. Texte validé par le conseil d'administration de la Sfar le 17/06/2016, disponible sur Internet le 31 octobre 2016.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> GRADE® — 17 recommandations formalisées (R1.1-R1.5, R3.1-R3.9, R4.1-R4.3 ; pas de R2.x, la question du monitorage de l'analgésie n'ayant abouti à aucune recommandation formalisée). Divergence source-interne sur le décompte agrégé forte/faible/avis d'experts — voir disclosure méthodologique en page 1.","style":"source"},{"t":"p","html":"<b>Couverture :</b> cette fiche reprend l'intégralité des 17 recommandations formalisées et de leurs argumentaires cliniques sur les 3 champs traités (évaluation de la DPO, thérapeutiques médicamenteuses systémique/orale, anesthésie locale et locorégionale postopératoire), y compris le tableau des doses maximales d'anesthésiques locaux. Comité d'organisation, groupe d'experts, groupe de lecture et les 66 références bibliographiques ne sont pas retranscrits (sans contenu clinique actionnable au-delà de ce que l'argumentaire cite déjà).","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement — document de 2016 :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend l'intégralité des 17 recommandations du texte source, mais ne remplace pas le texte intégral (argumentaire complet, 66 références bibliographiques) et n'est ni éditée ni validée par la SFAR. Ce texte COMPLÈTE (ne remplace pas) la RFE 2008 sur la douleur postopératoire, déjà couverte séparément dans ce corpus — se référer aux deux fiches pour une vue complète du sujet, et à un avis spécialisé en cas de doute.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/reactualisation-de-la-recommandation-sur-la-douleur-postoperatoire/';

insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/protection-oculaire-en-anesthesie-et-reanimation/' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade', 'medecine_intensive_reanimation')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/protection-oculaire-en-anesthesie-et-reanimation/' and s.acronym in ('SFAR', 'SFO', 'SRLF')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/protection-oculaire-en-anesthesie-et-reanimation/' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'protection_oculaire',
  card_json = $mgjson${"badge":"GRADE 1/2 + AE","title":"Protection oculaire en anesthésie et réanimation","short":"Prévention des complications oculaires liées à une perte de conscience prolongée : lésions cornéennes en anesthésie (occlusion palpébrale par bandes adhésives, lubrifiants pour les chirurgies à risque, formation des équipes) et en réanimation (dépistage à la fluorescéine, gel aqueux/chambres humides), et prévention des lésions rétiniennes par occlusion de l'artère centrale de la rétine et neuropathies optiques ischémiques aiguës (têtières adaptées, contrôle de la compression oculaire, position, hémodynamique en chirurgie du rachis). 12 recommandations, 3 chapitres.","society":"SFAR / SFO / SRLF — RFE 2016","version":"2016 (Anesth Reanim. 2016, ANREA-135)","validated":"Validé par le Conseil d'administration de la SFAR le 14/03/2016","methodology":"GRADE 1+/2+ + avis d'experts — disclosure d'une incohérence source-interne sur le décompte total des recommandations (« 10 » annoncé vs 12 recomptées)","pages":9,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"protection_oculaire","sections":[{"title":"Introduction, méthodologie & légende","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> prévention des complications oculaires liées à une perte de conscience prolongée (anesthésie ou réanimation) — toujours susceptibles de passer inaperçues puisque le patient ne peut pas manifester sa baisse de vision ou sa douleur. <b>Lésions de surface</b> (kératopathies, ulcères, liées à la malocclusion palpébrale) : les plus fréquentes, le plus souvent mineures et régressives, détectables par un œil rouge. <b>Accidents vasculaires</b> (occlusion de l'artère centrale de la rétine [OACR] par compression du globe, neuropathies optiques ischémiques aiguës [NOIA]) : se manifestent uniquement par une baisse de vision indolore, potentiellement définitive et bilatérale — l'OACR est le plus souvent unilatérale, les NOIA fréquemment bilatérales. RFE commune SFAR, Société française d'ophtalmologie (SFO), SRLF, <b>12 recommandations</b> sur 3 chapitres.","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Méthodologie GRADE® :</b> force 1+/2+ (« il faut/probablement faire ») ou <b>avis d'experts</b> quand aucune méta-analyse ne permettait d'appliquer GRADE en totalité (revue systématique puis vote, validé si ≥ 70 % d'accord). L'« Accord FORT » du vote de relecture Delphi n'est imprimé explicitement, individuellement, qu'à côté des 3 recommandations gradées GRADE (R1.1, R1.6, R2.2) — jamais réimprimé à côté des 9 avis d'experts individuels. Le paragraphe de synthèse méthodologique affirme néanmoins qu'« un accord fort a été obtenu pour la totalité des recommandations » après le tour de cotation — lu ici comme s'appliquant aux 12 recommandations, sans réinventer un tag individuel pour les 9 restantes.<br/><br/><b>Disclosure — incohérence interne au document source</b> (vérifiée par recomptage exhaustif, non devinée) : le paragraphe de méthodologie affirme un total de <b>« 10 recommandations »</b>, mais sa propre répartition annoncée dans la même phrase (1 forte + 2 faibles + 9 avis d'experts) totalise <b>12</b> — et un recomptage programmatique du corps du texte confirme exactement <b>12 recommandations numérotées</b> (R1.1 à R3.4 : 1× GRADE 1+, 2× GRADE 2+, 9× avis d'experts). Les deux chiffres imprimés par la source (« 10 » d'ouverture vs « 12 » par addition et par comptage du corps du texte) sont disclosés tels quels ; aucun n'est deviné « juste ».","style":"body_sm"}},{"t":"section","text":"Légende des grades","color":"navy"},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"p","html":"Il faut faire","style":"badge_head"},{"t":"chip","label":"2+"},{"t":"p","html":"Il faut probablement faire","style":"badge_head"},{"t":"chip","label":"AE"},{"t":"p","html":"Avis d'experts","style":"badge_head"}]]}]},{"title":"Chapitres 1-2 — Lésions cornéennes","items":[{"t":"section","text":"Chapitre 1 — Prévention des lésions cornéennes en anesthésie","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.1","style":"cell_b"},{"t":"p","html":"Pour prévenir les lésions cornéennes lors d'une anesthésie générale, une <b>occlusion palpébrale systématique par bandes adhésives seules</b> est recommandée — supérieure ou équivalente aux autres méthodes (pommades, lubrifiants aqueux type méthylcellulose ou gel visqueux, lunettes de protection, lentilles hydrophiles, suture palpébrale, pansements hydrogel ou bio-occlusifs), avec moins d'effets indésirables. La simple fermeture manuelle de l'œil s'accompagne d'une incidence plus élevée de lésions cornéennes (10 % sur 300 « yeux », dont 90 % dans le groupe fermeture manuelle contre 6,6 % dans le groupe bandes adhésives).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R1.2","style":"cell_b"},{"t":"p","html":"En dehors d'une induction en séquence rapide, l'occlusion palpébrale est recommandée dès la perte du réflexe ciliaire et avant l'intubation trachéale, afin de réduire le risque de lésions traumatiques de la cornée par un traumatisme direct (montres, badges, stéthoscopes, laryngoscope).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.3","style":"cell_b"},{"t":"p","html":"Il est recommandé d'obtenir l'occlusion complète de l'œil en apposant jointivement la paupière supérieure et inférieure et de vérifier régulièrement l'efficacité de cette occlusion — une formation obligatoire sur ce point a permis de diviser par 3 l'incidence des lésions de cornée dans une étude de cohorte avant/après.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.4","style":"cell_b"},{"t":"p","html":"Pour les chirurgies à risque (tête et cou, procédure en position ventrale ou latérale), il est probablement recommandé d'utiliser des lubrifiants aqueux sans conservateur et en unidose (méthylcellulose ou gel visqueux) en association à l'occlusion par bandes adhésives — alternative : pansements bio-occlusifs transparents sans lubrifiant.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.5","style":"cell_b"},{"t":"p","html":"Pour les chirurgies à risque, il est recommandé de <b>ne pas utiliser les pommades grasses</b> — la méthylcellulose produit moins d'effets indésirables que les pommades à base de paraffine. Les positions ventrale/latérale et les chirurgies céphaliques/cervicales sont des facteurs de risque ; la durée d'anesthésie n'en est pas un, indépendamment.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.6","style":"cell_b"},{"t":"p","html":"La mise en place, au sein des structures, d'un programme de formation et d'un protocole de prévention est probablement recommandée pour réduire l'incidence des lésions cornéennes sous anesthésie générale.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"section","text":"Chapitre 2 — Prévention des lésions cornéennes en réanimation","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R2.1","style":"cell_b"},{"t":"p","html":"Chez les patients à risque (intubés-ventilés, sédatés ou à faible niveau de conscience), il faut probablement dépister les lésions cornéennes par un <b>test à la fluorescéine</b> (ophtalmoscope à lumière bleu-cobalt) — la majorité des lésions sont punctiformes, invisibles à l'œil nu, mais peuvent évoluer vers un ulcère de cornée avec séquelles visuelles. Incidence en réanimation : 8,6 % à 60 % selon les études, pic dans la première semaine d'admission. La sensibilité du dépistage par des réanimateurs formés est proche de celle des ophtalmologistes.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.2","style":"cell_b"},{"t":"p","html":"Chez les patients de réanimation intubés-ventilés, il faut probablement utiliser du <b>gel aqueux ou des chambres humides</b> plutôt que des larmes artificielles — une méta-analyse de 7 études prospectives randomisées (n = 343 à 701 selon l'unité d'analyse) montre une réduction du risque de lésions avec la chambre humide par rapport aux larmes artificielles (RR 0,13 ; IC95 % 0,05-0,35), mais la chambre humide n'est pas supérieure au gel (RR 0,81 ; IC95 % 0,51-1,29). Données insuffisantes sur l'occlusion palpébrale, associée ou non à une lubrification.","style":"cell"},{"t":"chip","label":"2+"}]]}]},{"title":"Chapitre 3 — Lésions rétiniennes & sources","items":[{"t":"section","text":"Chapitre 3 — Prévention des lésions rétiniennes (OACR & NOIA)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R3.1","style":"cell_b"},{"t":"p","html":"Pour prévenir la compression directe du globe oculaire et les OACR en chirurgie du rachis en décubitus ventral (d'autant plus que la durée est longue), il est probablement recommandé d'utiliser des <b>têtières adaptées</b> garantissant l'absence de compression directe du globe (tête en position neutre, têtière à prise osseuse directe type Mayfield, ou coussin spécialement découpé permettant de contrôler les globes sans contact ni manipulation du patient).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R3.2","style":"cell_b"},{"t":"p","html":"Il est probablement recommandé de <b>contrôler l'absence de toute compression extrinsèque</b> de la sphère oculaire tout au long de l'intervention. Dans le registre ASA des pertes de vision peropératoires, toutes les OACR (n = 10) étaient unilatérales, aucune n'avait eu de cadre de Mayfield et 70 % présentaient les stigmates d'un traumatisme externe du globe — les têtières « en fer à cheval » peuvent, en cas de déplacement, contribuer à une compression oculaire et une OACR.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R3.3","style":"cell_b"},{"t":"p","html":"Dans la chirurgie de longue durée en décubitus ventral, il est probablement recommandé de préférer un léger proclive à une position de Trendelenburg, pour limiter la pression intraoculaire — le décubitus ventral majore le risque de compression en augmentant la PIO, d'autant plus marqué si associé à un Trendelenburg ; une inclinaison proclive de 10° réduit ce risque.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R3.4","style":"cell_b"},{"t":"p","html":"En chirurgie du rachis hémorragique de longue durée, pour prévenir les NOIA, il est probablement recommandé de <b>limiter l'hypotension artérielle, l'anémie sévère et l'hypovolémie</b>, d'autant plus que le patient est à risque (obésité, sexe masculin, HTA, facteur de risque vasculaire) — le nerf optique ne dispose pas d'une autorégulation aussi efficace que le cerveau ; dans le registre ASA, au moins un facteur de risque vasculaire était présent dans 82 % des cas malgré des patients souvent ASA 1. Facteurs de risque indépendants confirmés en chirurgie du rachis : sexe masculin, obésité, cadre de Wilson (compression abdominale), durée d'intervention longue, faible pourcentage de colloïde dans le remplissage.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Protection oculaire en anesthésie et réanimation » — RFE commune Société française d'anesthésie et de réanimation (SFAR), Société française d'ophtalmologie (SFO), Société de réanimation de langue française (SRLF). Coordonnatrice d'experts : Hawa Keita-Meyer. H. Keita, J-M Devys, J. Ripart, M. Frost, I. Cochereau, F. Boutin, C. Guérin, D. Fletcher, V. Compère. Anesth Reanim. 2016 (ANREA-135), doi 10.1016/j.anrea.2016.05.002. Texte validé par le Conseil d'administration de la SFAR le 14/03/2016.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> GRADE® (1+/2+ ou avis d'experts) ; « Accord FORT » du vote Delphi imprimé individuellement pour les 3 items gradés GRADE, affirmé globalement pour l'ensemble des 12 recommandations par le paragraphe de synthèse — voir disclosure méthodologique en page 1 sur l'incohérence \"10\" vs \"12\" recommandations.","style":"source"},{"t":"p","html":"<b>Couverture :</b> cette fiche reprend l'intégralité des 12 recommandations (R1.1-R3.4) réparties sur les 3 chapitres (prévention des lésions cornéennes en anesthésie, en réanimation, prévention des lésions rétiniennes par OACR/NOIA), avec leurs argumentaires. Comité d'organisation, groupe de lecture, les 40 références bibliographiques et les Annexes 1-2 (tableaux de synthèse des preuves GRADE étude par étude — plan d'expérience, hétérogénéité, biais, RR/WMD) ne sont pas retranscrits : purement méthodologiques/bibliographiques, sans recommandation clinique propre au-delà de ce que chaque argumentaire résume déjà.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement — document de 2016 :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend l'intégralité des 12 recommandations du texte source, mais ne remplace pas le texte intégral (argumentaire complet, 40 références bibliographiques, Annexes 1-2) et n'est ni éditée ni validée par la SFAR, la SFO ou la SRLF. En cas de doute, se référer au texte intégral et/ou à un avis ophtalmologique spécialisé.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/protection-oculaire-en-anesthesie-et-reanimation/';

insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://www.has-sante.fr/upload/docs/application/pdf/2019-07/fm_ponction_lombaire.pdf' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade', 'medecine_d_urgence')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://www.has-sante.fr/upload/docs/application/pdf/2019-07/fm_ponction_lombaire.pdf' and s.acronym in ('HAS')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://www.has-sante.fr/upload/docs/application/pdf/2019-07/fm_ponction_lombaire.pdf' and d.society_id is null and s.acronym = 'HAS';
update public.documents set
  fiche_key = 'ponction_lombaire',
  card_json = $mgjson${"badge":"Fiche mémo","title":"Ponction lombaire — prévention et prise en charge des effets indésirables","short":"Fiche mémo HAS : indications et contre-indications formelles (hypertension intracrânienne, infections au point de ponction, thrombopénie < 50 G/L, troubles de l'hémostase) de la ponction lombaire, modalités de réalisation (aiguille atraumatique ≤22G avec introducteur, asepsie, formation), effets indésirables — syndrome post-PL (céphalée orthostatique, signes d'alerte de complication grave), hématomes, infections — traitement par blood-patch, et spécificités pédiatriques (choix de l'aiguille, angle, analgésie). Pas de système GRADE : synthèse de la littérature sans cotation d'accord.","society":"HAS — Fiche mémo 2019","version":"Juin 2019","validated":"Haute Autorité de Santé","methodology":"Fiche mémo — synthèse de la littérature, sans système GRADE ni cotation d'accord","pages":7,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"ponction_lombaire","sections":[{"title":"Messages clés, indications & contre-indications","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> prévention et prise en charge des effets indésirables de la ponction lombaire (PL), acte diagnostique ou thérapeutique fréquent, invasif, réalisable par tout médecin. La PL est à risque d'événements indésirables (exceptionnellement graves) et d'échecs dont la majorité serait évitable — d'où l'importance de connaître l'anatomie, les contre-indications, la technique, le matériel et la prévention de ces effets indésirables.","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Méthodologie :</b> cette « fiche mémo » HAS est une <b>synthèse de la littérature</b> — elle ne comporte <b>aucun système GRADE</b> et <b>aucune cotation d'accord</b> (ni 1+/2+, ni « accord fort/faible »), à la différence des RFE/RBP à vote gradué du reste de ce corpus. Les recommandations sont donc restituées ici sous forme de messages clés et de tableaux thématiques, sans chip de force — aucune gradation n'est inventée.","style":"body_sm"}},{"t":"section","text":"Messages clés","color":"navy"},{"t":"p","html":"&bull; La PL est un acte médical indispensable et très fréquent.<br/>&bull; Le refus explicite ou présumé du patient et les contre-indications formelles (hypertension intracrânienne, infections au point de ponction, thrombopénie sévère) doivent être pris en considération avant toute PL.<br/>&bull; Les complications graves sont exceptionnelles.<br/>&bull; Le syndrome post-PL est l'effet indésirable le plus fréquent. S'il n'est habituellement pas grave, il est invalidant et engendre des coûts personnel, social et financier.<br/>&bull; Il est recommandé d'utiliser une aiguille atraumatique « à extrémité non tranchante », avec introducteur, quelle que soit l'indication de la PL réalisée, chez l'adulte comme en pédiatrie.<br/>&bull; Il est recommandé aux médecins de se former à la pratique du geste de la PL, ainsi qu'à l'utilisation des aiguilles atraumatiques avec introducteur, et de se faire accompagner pour la réalisation des premières PL sur le patient, aussi souvent que nécessaire.<br/>&bull; Le respect des règles de procédure et l'utilisation des aiguilles atraumatiques diminuent significativement l'incidence des effets indésirables et le recours au blood-patch.<br/>&bull; Le blood-patch est le traitement le plus performant du syndrome post-PL, mais c'est un acte invasif qui peut être responsable de complications iatrogènes, exceptionnellement graves.<br/>&bull; Le repos forcé au lit et l'hyperhydratation n'ont pas d'indication.<br/>&bull; La PL et le blood-patch sont des gestes invasifs avec risque d'accident d'exposition au sang : les aiguilles doivent être collectées dans un conteneur prévu à cet effet.","style":"body_sm"},{"t":"section","text":"Dans quels cas une ponction lombaire peut être réalisée","color":"navy"},{"t":"p","html":"Les indications évoluent constamment avec le développement des connaissances et des techniques. Les indications suivantes sont listées à titre indicatif et de manière non exhaustive.","style":"note"},{"t":"p","html":"<b>Indications diagnostiques</b>","style":"cell_b"},{"t":"p","html":"&bull; suspicion d'infection du système nerveux central (bactérienne, virale, parasitaire) ;<br/>&bull; survenue d'une céphalée brutale et/ou atypique (hémorragie méningée, thrombophlébite, dissection vasculaire, etc.) ;<br/>&bull; suspicion d'une méningite carcinomateuse ou d'un syndrome paranéoplasique ;<br/>&bull; bilan de maladies inflammatoires affectant le système nerveux central (sclérose en plaques, sarcoïdose, vascularite, encéphalite auto-immune, etc.) ;<br/>&bull; bilan d'une neuropathie aiguë ou chronique (syndrome de Guillain-Barré, neuropathie périphérique, etc.) ;<br/>&bull; maladies neurodégénératives (maladie d'Alzheimer, sclérose latérale amyotrophique, maladie à corps de Lewy, etc.) ;<br/>&bull; mesure de pression du liquide cérébro-spinal (LCS) en cas de suspicion de troubles de la cinétique du LCS (hydrocéphalie à pression normale, hypertension intracrânienne idiopathique).","style":"body_sm"},{"t":"p","html":"<b>Indications thérapeutiques</b>","style":"cell_b"},{"t":"p","html":"&bull; ponction lombaire évacuatrice : hydrocéphalie à pression normale, après interventions neurochirurgicales ;<br/>&bull; rachianesthésie ;<br/>&bull; recherche clinique.","style":"body_sm"},{"t":"section","text":"Dans quels cas une ponction lombaire ne doit pas être réalisée","color":"red"},{"t":"p","html":"Outre le refus explicite ou présumé du patient, les contre-indications formelles sont les suivantes.","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Détail","style":"head_w"}],[{"t":"p","html":"Hypertension intracrânienne","style":"cell_b"},{"t":"p","html":"Risque d'engagement cérébral (processus expansif intracrânien, malformation d'Arnold-Chiari) — la normalité d'un examen neurologique minutieux permet de se passer de l'imagerie.","style":"cell"}],[{"t":"p","html":"Infections au point de ponction","style":"cell_b"},{"t":"p","html":"Contre-indication formelle.","style":"cell"}],[{"t":"p","html":"Thrombopénie sévère","style":"cell_b"},{"t":"p","html":"Nombre de plaquettes inférieur à 50 G/L (50 000/mm³). Pour certaines pathologies (thrombopénie gestationnelle, purpura thrombopénique immunologique), une thrombopénie stable ≥ 30 G/L peut être tolérée ; à l'inverse, une thrombopénie évolutive non stabilisée nécessite une évaluation pluridisciplinaire du rapport bénéfice/risque.","style":"cell"}],[{"t":"p","html":"Troubles de la coagulation ou traitements modifiant l'hémostase","style":"cell_b"},{"t":"p","html":"L'hématome péridural ou sous-arachnoïdien après une PL est exceptionnel, presque toujours lié à un ou plusieurs facteurs de risque : traitement anticoagulant à dose thérapeutique ou antiplaquettaire (sauf aspirine et AINS), trouble congénital ou acquis de la coagulation/hémostase primaire, ponction difficile/traumatique ou rachis pathologique (ex. spondylarthrite ankylosante). En urgence : antagoniser le traitement anticoagulant si possible, ou substituer le déficit en facteurs de coagulation (ex. hémophilie) si nécessaire.","style":"cell"}]]}]},{"title":"Modalités de réalisation","items":[{"t":"section","text":"Modalités de réalisation de la ponction lombaire","color":"navy"},{"t":"panel","tone":"default","content":{"t":"p","html":"La PL doit être réalisée dans le cadre d'une hospitalisation (sa réalisation ne justifie pas, à elle seule, une hospitalisation de plus de 24 heures).","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Détail","style":"head_w"}],[{"t":"p","html":"Installation du patient","style":"cell_b"},{"t":"p","html":"Le choix de la position assise ou allongée est laissé à l'appréciation du médecin et du patient.","style":"cell"}],[{"t":"p","html":"Détermination du point de ponction","style":"cell_b"},{"t":"p","html":"Niveaux corrects : espaces interépineux L3-L4, L4-L5 et L5-S1. Il est recommandé de ponctionner en dessous de la ligne horizontale tracée entre les crêtes iliaques (la détermination de l'espace à ponctionner est en pratique plus difficile que classiquement décrit). En cas de difficulté, la PL peut être réalisée sous imagerie (radioscopie, échographie).","style":"cell"}],[{"t":"p","html":"Asepsie","style":"cell_b"},{"t":"p","html":"Règles d'asepsie chirurgicale à respecter absolument — pour le patient : désinfection cutanée en deux temps (antiseptique alcoolique) + champ stérile ; pour le médecin : désinfection des mains (solution hydro-alcoolique), masque facial, gants stériles.","style":"cell"}],[{"t":"p","html":"Anesthésie locale","style":"cell_b"},{"t":"p","html":"Un patch d'anesthésique local peut être proposé en dehors de l'urgence (délai d'1 heure). Dans les cas prévisibles de ponction difficile, une anesthésie locale peut être envisagée.","style":"cell"}],[{"t":"p","html":"Réalisation de la ponction","style":"cell_b"},{"t":"p","html":"Quelle que soit l'indication, la technique reste identique. Il est recommandé d'utiliser une aiguille atraumatique « à extrémité non tranchante », diamètre maximal 22 Gauge (code couleur noir — plus la Gauge est élevée, plus l'aiguille est fine). L'introducteur fourni avec l'aiguille est indispensable pour franchir la peau. Il est recommandé aux médecins de se former à son utilisation.","style":"cell"}],[{"t":"p","html":"Réintroduction du mandrin","style":"cell_b"},{"t":"p","html":"Il est recommandé de réintroduire complètement le mandrin dans l'aiguille avant de la retirer.","style":"cell"}],[{"t":"p","html":"Prélèvements","style":"cell_b"},{"t":"p","html":"L'incidence des syndromes post-PL immédiats augmente pour un volume prélevé supérieur à 30 mL.","style":"cell"}],[{"t":"p","html":"Prévention des accidents d'exposition au sang","style":"cell_b"},{"t":"p","html":"La PL est un geste invasif avec risque d'accident d'exposition au sang : les aiguilles doivent être collectées dans un conteneur à disposition et prévu à cet effet.","style":"cell"}]]},{"t":"p","html":"<b>Formation</b>","style":"cell_b"},{"t":"p","html":"La PL nécessite une bonne connaissance de l'anatomie mais aussi de la pratique du geste. La formation pratique par simulation est recommandée :","style":"body_sm"},{"t":"p","html":"&bull; avant tout premier geste (formation généralement assurée pendant les études médicales sur les plateformes de simulation universitaires) ;<br/>&bull; pour tout médecin dans le cadre de la mise à jour des conditions de pratique ;<br/>&bull; pour tout médecin ayant réalisé peu ou pas de PL ;<br/>&bull; dans le cadre de l'accréditation des médecins et des équipes.","style":"body_sm"},{"t":"p","html":"Après formation par simulation, il est recommandé que le médecin soit accompagné pour la réalisation des premières PL sur le patient aussi souvent que nécessaire.","style":"body_sm"}]},{"title":"Effets indésirables & blood-patch","items":[{"t":"section","text":"Effets indésirables de la ponction lombaire","color":"navy"},{"t":"p","html":"La PL est parfois responsable d'effets indésirables : syndrome post-PL (syndrome d'hypotension intracrânienne), hématomes, infections, douleurs lombaires, voire paraplégie ou décès de manière très exceptionnelle.","style":"body_sm"},{"t":"p","html":"<b>Syndrome post-PL</b>","style":"cell_b"},{"t":"p","html":"Secondaire à une fuite persistante de LCS, se caractérise par une céphalée orthostatique. Apparaît habituellement dans les 2 à 4 jours après une PL (mais parfois plus tardive), apyrétique, partiellement ou totalement soulagée par le décubitus dorsal. Classiquement bilatérale, occipitale, occipito-frontale ou diffuse, irradiant dans la nuque, le dos et parfois aux épaules. Parfois isolée, elle est habituellement accompagnée d'un cortège variable de signes : nausées et vomissements ; signes auditifs ou visuels (hypoacousie, rarement hyperacousie, diplopie par atteinte de la VIe paire — la photophobie fait partie du tableau clinique classique). Un syndrome post-PL atypique, ou dont la symptomatologie se modifie, nécessite un avis spécialisé. Il existe des cas exceptionnels de syndrome post-PL sans céphalée (ex. vertiges ou troubles auditifs isolés).","style":"body_sm"},{"t":"p","html":"L'incidence peut être minorée par des mesures simples : l'utilisation d'aiguilles atraumatiques la diminue significativement en incidence et intensité (incidence < 10 % avec aiguilles atraumatiques, contre jusqu'à 35 % avec des aiguilles traumatiques).","style":"body_sm"},{"t":"panel","tone":"crit","content":{"t":"p","html":"<b>Signes d'alerte de complications graves</b> — après une PL, l'apparition de signes cliniques nouveaux doit conduire à une prise en charge diagnostique et thérapeutique en urgence : fièvre ; signe neurologique (syndrome complet ou incomplet de la queue-de-cheval, diplopie, déficit sensitif et/ou moteur, trouble de conscience, confusion, crise d'épilepsie, coma, etc.) ; modification du caractère postural de la céphalée post-PL. La baisse de l'acuité visuelle doit faire évoquer une autre étiologie car il s'agit d'une complication exceptionnelle.","style":"body"}},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Détail","style":"head_w"}],[{"t":"p","html":"Hématomes","style":"cell_b"},{"t":"p","html":"Très exceptionnels, périmédullaires ou intracrâniens. Favorisés par les troubles de la coagulation, les traitements modifiant l'hémostase et les ponctions multiples. Quelle que soit la localisation : urgence diagnostique et thérapeutique nécessitant une imagerie et un avis spécialisé.","style":"cell"}],[{"t":"p","html":"Infections","style":"cell_b"},{"t":"p","html":"Exceptionnelles, liées au non-respect des règles d'asepsie : méningite, abcès au point de ponction, spondylodiscite, etc.","style":"cell"}],[{"t":"p","html":"Douleurs lombaires","style":"cell_b"},{"t":"p","html":"Possibles après PL, habituellement banales.","style":"cell"}]]},{"t":"section","text":"Blood-patch","color":"navy"},{"t":"p","html":"Le blood-patch consiste en l'injection de sang autologue (du patient lui-même) dans l'espace péridural pour colmater la brèche méningée. Il s'agit du <b>traitement le plus efficace</b> en cas de non-guérison spontanée du syndrome post-PL dans les 48 à 72 heures.","style":"body"},{"t":"p","html":"Le blood-patch doit être envisagé après échec des traitements non invasifs et réalisé :","style":"body_sm"},{"t":"p","html":"&bull; dans des conditions d'asepsie chirurgicale, par un médecin expérimenté ;<br/>&bull; au cours d'une hospitalisation (sa réalisation ne justifie pas, à elle seule, une hospitalisation de plus de 24 heures) ;<br/>&bull; possiblement en hôpital de jour, en garantissant un temps de surveillance et de décubitus pour le patient d'au moins 2 heures.","style":"body_sm"},{"t":"p","html":"En cas d'inefficacité immédiate ou de récidive à distance, un <b>2e blood-patch</b> est possible ; mais <b>pas de 3e blood-patch sans imagerie</b> (IRM et avis spécialisé). Comme la PL, c'est un geste invasif avec risque d'accident d'exposition au sang : les aiguilles doivent être collectées dans un conteneur prévu à cet effet.","style":"body_sm"}]},{"title":"Pédiatrie & sources","items":[{"t":"section","text":"Spécificités pédiatriques","color":"navy"},{"t":"p","html":"Le syndrome post-PL existe chez l'enfant et doit faire l'objet d'une prévention. Le taux de succès de la PL chez l'enfant est lié à plusieurs facteurs : positionnement de l'enfant, choix de l'aiguille, analgésie.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Détail","style":"head_w"}],[{"t":"p","html":"Installation","style":"cell_b"},{"t":"p","html":"Nourrisson : position assise sans flexion de hanche et sans flexion de nuque — dégage le plus large espace intervertébral avec la meilleure tolérance hémodynamique. Enfant : position assise ou allongée, comme chez l'adulte.","style":"cell"}],[{"t":"p","html":"Choix de l'aiguille","style":"cell_b"},{"t":"p","html":"Aiguilles atraumatiques « à extrémité non tranchante », 22 à 27 Gauge, recommandées en 1ère intention (certaines s'utilisent sans introducteur — 22, 24, 25 G — d'autres avec introducteur — 22, 25, 27 G). Formation recommandée à l'utilisation des aiguilles atraumatiques avec introducteur. L'usage des aiguilles traumatiques à biseau tranchant doit rester exceptionnel.","style":"cell"}],[{"t":"p","html":"Angle de pénétration","style":"cell_b"},{"t":"p","html":"Angle permettant d'accéder le plus efficacement au LCS : compris entre 50° et 60°. Un repérage échographique (lorsqu'il est disponible) permet un taux de succès plus important.","style":"cell"}],[{"t":"p","html":"Analgésie","style":"cell_b"},{"t":"p","html":"Point clé de la réussite du geste. Options disponibles : crème anesthésiante lidocaïne + prilocaïne, à appliquer 1 heure avant (hors urgence), quel que soit l'âge (sauf prématuré < 37 SA d'âge post-conceptionnel) ; sérum glucosé 30 % per os chez le nourrisson jusqu'à 6 mois ; inhalation d'un mélange équimolaire oxygène/protoxyde d'azote (MEOPA), à tout âge ; traitements anxiolytiques et antalgiques intra-rectaux ou morphiniques per os pour une PL programmée ou des antécédents de vécu douloureux.","style":"cell"}]]},{"t":"p","html":"<b>Syndrome post-PL chez l'enfant</b>","style":"cell_b"},{"t":"p","html":"Présentation clinique identique à celle de l'adulte, incidence de 2 à 15 % selon les études. Chez le nourrisson, le diagnostic reste difficile en l'absence de critère diagnostique spécifique.","style":"body_sm"},{"t":"p","html":"<b>Prévention du syndrome post-PL</b>","style":"cell_b"},{"t":"p","html":"L'utilisation d'aiguilles atraumatiques chez l'enfant diminue l'incidence du syndrome post-PL, mais nécessite une formation des médecins. En cas d'utilisation d'aiguilles traumatiques, les éléments suivants sont associés à un risque moindre chez l'enfant : aiguille de petit diamètre (22 Gauge et plus) ; position du biseau parallèle à l'axe du rachis ; réintroduction du mandrin avant retrait de l'aiguille. <b>Il n'y a pas d'indication à l'alitement strict après la PL chez l'enfant.</b>","style":"body_sm"},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Prise en charge du syndrome post-PL chez l'enfant :</b> en cas de syndrome post-PL avéré, le traitement conservateur est recommandé en première intention (antalgiques). Le repos au lit n'est pas obligatoire ; l'efficacité de l'hyperhydratation n'est pas prouvée. Comme chez l'adulte, le seul traitement ayant montré son efficacité en cas de syndrome post-PL persistant et/ou sévère est le blood-patch (les indications du blood-patch chez l'enfant restent rares).","style":"body_sm"}},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Prévention et prise en charge des effets indésirables pouvant survenir après une ponction lombaire » — Fiche mémo, Haute Autorité de Santé (HAS).","style":"source"},{"t":"p","html":"<b>Version :</b> Juin 2019.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> fiche mémo — synthèse de la littérature, sans système GRADE ni cotation d'accord (aucun tag 1+/2+/AE, aucune mention d'accord fort/faible dans le texte source). Recommandations de pratique présentées sous forme de messages clés et de recommandations narratives.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://www.has-sante.fr/upload/docs/application/pdf/2019-07/fm_ponction_lombaire.pdf","style":"source"},{"t":"p","html":"<b>Couverture :</b> cette fiche reprend l'intégralité des 7 pages de la fiche mémo source : messages clés, indications et contre-indications, modalités de réalisation, effets indésirables et signes d'alerte, blood-patch, spécificités pédiatriques.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend l'intégralité de la fiche mémo source, mais ne remplace pas le texte intégral et n'est ni éditée ni validée par la HAS. En cas de doute ou de situation clinique complexe (échec de PL, syndrome post-PL atypique, suspicion d'hématome ou d'infection), se référer au texte intégral et/ou à un avis spécialisé.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://www.has-sante.fr/upload/docs/application/pdf/2019-07/fm_ponction_lombaire.pdf';

insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/anesthesie-pour-amygdalectomie-chez-lenfant/' and s.slug in ('anesthesie_reanimation', 'pediatrie', 'infirmierere_anesthesiste_iade')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/anesthesie-pour-amygdalectomie-chez-lenfant/' and s.acronym in ('SFAR')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/anesthesie-pour-amygdalectomie-chez-lenfant/' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'amygdalectomie_enfant',
  card_json = $mgjson${"badge":"Grade A-C + Accord","title":"Anesthésie pour amygdalectomie chez l'enfant","short":"Conférence d'experts texte court, 5 questions : évaluation préopératoire (bilan hémostase, gestion d'une IVAS, retentissement du SAOS), prise en charge anesthésique (induction, apports hydroélectrolytiques règle 4-2-1, contrôle des voies aériennes par sonde à ballonnet), soins postopératoires (surveillance SSPI, reprise alimentaire, analgésie — morphine IV en 1ère ligne, AINS déconseillés), complications (hémorragie 0,5-3 %, NVPO 40-70 %), et conditions de l'ambulatoire. Deux systèmes de cotation combinés (Grade A/B/C selon la preuve + Accord RAND/UCLA fort/faible).","society":"SFAR / Adarpef / Carorl — Conférence d'experts 2005","version":"2005","validated":"Comité des Référentiels de la Sfar","methodology":"Conférence d'experts — Grade A/B/C (niveau de preuve) + Accord RAND/UCLA modifié (fort/faible) selon la proposition","pages":8,"section":"Pédiatrie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"amygdalectomie_enfant","sections":[{"title":"Méthodologie, légende & Q1 — Évaluation préopératoire","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Champ :</b> prise en charge anesthésique péri-opératoire de l'enfant opéré pour amygdalectomie (avec ou sans adénoïdectomie). En France, l'anesthésie ORL représente 12 % des actes (3e rang après orthopédie et chirurgie digestive) ; sur ~670 000 anesthésies ORL annuelles, 17 % le sont pour amygdalectomie. L'anesthésie ORL représente 25 % des actes chez les moins de 1 an, 64 % chez les 1-4 ans, 28 % chez les 5-14 ans. Malgré les progrès, il persiste une morbi-mortalité non négligeable.","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Méthodologie :</b> ce document combine <b>deux systèmes de cotation</b> — des propositions fondées sur la littérature (Grade A/B/C selon le niveau de preuve) et des propositions validées par cotation RAND/UCLA modifiée des experts en l'absence de preuve suffisante (« Accord fort » ou « Accord faible »). Chaque proposition du texte source porte l'un ou l'autre de ces deux tags, jamais les deux à la fois — reproduit tel quel, sans fusionner les deux échelles.","style":"body_sm"}},{"t":"section","text":"Légende des cotations","color":"navy"},{"t":"table","rows":[[{"t":"table","rows":[[{"t":"chip","label":"A"},{"t":"chip","label":"B"},{"t":"chip","label":"C"},{"t":"p","html":"<b>Niveaux de preuve (Grade A/B/C)</b> — fondés sur la littérature (A : ≥2 études de niveau I ; B : 1 étude de niveau I ; C : étude(s) de niveau II). Aucune proposition D ou E dans ce texte.","style":"badge_head"}]]}],[null],[{"t":"table","rows":[[{"t":"chip","label":"Fort"},{"t":"chip","label":"Faible"},{"t":"p","html":"<b>Accord RAND/UCLA modifié (1-9)</b> — cotation individuelle des experts en l'absence de preuve suffisante : « Accord fort » (intervalle borné dans une seule zone) ou « Accord faible » (intervalle empiétant sur une borne).","style":"badge_head"}]]}]]},{"t":"section","text":"Question 1 — Évaluation préopératoire et préparation à la chirurgie","color":"navy"},{"t":"p","html":"<b>1.1 — Objectifs et modalités de la consultation d'anesthésie, information sur le risque</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"La consultation d'anesthésie en prévision d'une amygdalectomie a deux buts essentiels : l'évaluation des risques inhérents à l'acte et l'information du patient et de ses parents.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"L'évaluation des risques repose sur l'interrogatoire des parents et si possible de l'enfant, ainsi que sur l'examen clinique de l'enfant.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Les risques respiratoires et hémorragiques doivent faire l'objet d'une attention et d'une information particulières.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Le risque respiratoire est majoré en cas de syndrome d'apnée obstructive du sommeil (SAOS) grave.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"L'information s'adresse à la fois à l'enfant et aux parents, et doit être adaptée au degré de compréhension de chacun.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<b>1.2 — Bilan préopératoire</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"L'évaluation préopératoire du risque hémorragique repose sur un interrogatoire précis à la recherche d'antécédents personnels et/ou familiaux suggérant une anomalie de l'hémostase, et sur un examen clinique recherchant une symptomatologie hémorragique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"En cas d'antécédents personnels ou familiaux d'hémorragie connus ou suspectés, ou lorsque l'évaluation préopératoire ne peut être considérée comme fiable (notamment chez l'enfant de moins de 3 ans), une étude de l'hémostase doit être réalisée.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Les résultats de cette étude initiale, s'ils restent anormaux après contrôle, doivent être discutés avec un spécialiste de l'hémostase afin de déterminer l'opportunité d'une étude plus approfondie.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Si des examens d'hémostase sont prescrits, le temps de céphaline avec activateur et la numération plaquettaire sont les tests les plus utiles.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Chez l'enfant de plus de 3 ans, lorsque l'évaluation clinique préopératoire ne dépiste pas de risque hémorragique anormal, l'étude systématique de l'hémostase ne s'impose pas.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<b>1.3 — Gestion d'une infection des voies aériennes supérieures (IVAS) avant amygdalectomie</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"L'amygdalectomie majore le risque de complications respiratoires du fait de la localisation du site chirurgical sur les voies aériennes supérieures.","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"Ces complications respiratoires contribuent à générer une morbidité dénuée de réelle gravité si l'anesthésiste est expérimenté dans ce contexte.","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"L'IVAS entraîne une fréquence accrue de complications respiratoires telles que désaturation et pause respiratoire.","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"L'IVAS entraîne une augmentation de la fréquence des bronchospasmes lorsque l'enfant est intubé.","style":"cell"},{"t":"chip","label":"A"}]]},{"t":"p","html":"<b>1.4 — Critères de report d'intervention en cas d'IVAS</b>","style":"cell_b"},{"t":"p","html":"L'intervention est différée si l'enfant présente <i>[Accord fort]</i> :","style":"body_sm"},{"t":"p","html":"&bull; des signes spastiques bronchiques ;<br/>&bull; une laryngite ;<br/>&bull; une température supérieure à 38 °C.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"En cas de report d'intervention, le délai de re-programmation est d'au moins trois semaines.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<b>1.5 — Conséquences du syndrome d'apnée du sommeil (SAOS) sur la prise en charge anesthésique</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"Le SAOS représente environ deux tiers des indications d'amygdalectomie.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Les enfants concernés ont le plus souvent moins de 5 ans.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"En l'absence de critères de gravité, le SAOS ne modifie habituellement pas la prise en charge anesthésique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Les formes graves de SAOS sont plus fréquentes chez le jeune enfant et en cas de dysmorphie faciale ou de pathologies associées.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Les formes graves de SAOS nécessitent une évaluation préopératoire du retentissement cardio-pulmonaire, et justifient une surveillance postopératoire d'au moins 24 heures dans une structure de type SSPI ou surveillance continue.","style":"cell"},{"t":"chip","label":"Fort"}]]}]},{"title":"Q2 — Prise en charge anesthésique","items":[{"t":"section","text":"Question 2 — Prise en charge anesthésique des enfants programmés","color":"navy"},{"t":"p","html":"<b>2.1 — Prise en charge anesthésique des patients</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"Les règles de jeûne habituelles, adaptées à l'âge de l'enfant, doivent être appliquées.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"En dehors des syndromes obstructifs graves, une prémédication anxiolytique est utile.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Les structures de prise en charge et le matériel utilisé doivent être conformes aux recommandations de la Sfar et de l'Adarpef.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"La surveillance peropératoire repose sur un monitorage conforme aux recommandations de la Sfar.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"L'anesthésie générale lors de l'amygdalectomie a pour but d'assurer une composante hypnotique suffisante pour éviter la mémorisation peropératoire, et une composante analgésique efficace.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"L'induction par inhalation est la modalité la plus fréquente.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"L'induction intraveineuse est parfois préférée chez les grands enfants ou en cas de syndrome obstructif sévère.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"L'entretien de l'anesthésie est souvent assuré par un agent halogéné associé à un morphinique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Les apports hydroélectrolytiques peropératoires reposent sur l'utilisation d'un soluté isotonique en sel, pouvant contenir une faible concentration de glucose et perfusé à un débit adapté à l'âge de l'enfant.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Débit de perfusion — règle des 4-2-1 : 4 mL/kg/h pour les 10 premiers kg, + 2 mL/kg/h pour les 10 kg suivants, + 1 mL/kg/h pour les 10 kg suivants (soit 65 mL/h pour un enfant de 25 kg par exemple).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Il est recommandé d'utiliser un dispositif médical de contrôle du débit de perfusion.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"L'administration peropératoire de dexaméthasone est recommandée car elle réduit l'incidence des NVPO et le délai avant la reprise alimentaire.","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"L'administration d'une antibioprophylaxie peropératoire n'a pas démontré son intérêt, et ne s'impose donc pas systématiquement.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<b>2.2 — Modalités de contrôle des voies aériennes</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"L'amygdalectomie chez l'enfant requiert une anesthésie générale balancée impliquant une protection des voies aériennes.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Le contrôle optimal des voies aériennes est assuré par une sonde d'intubation trachéale à ballonnet.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"L'extubation est réalisée, en présence d'un médecin anesthésiste, au réveil complet de l'enfant, déterminé par l'ouverture des yeux à la demande.","style":"cell"},{"t":"chip","label":"Fort"}]]}]},{"title":"Q3 — Soins postopératoires","items":[{"t":"section","text":"Question 3 — Organisation des soins postopératoires","color":"navy"},{"t":"p","html":"<b>3.1 — Modalités de surveillance postopératoire</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"La surveillance en SSPI doit être systématique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"En plus de la surveillance habituelle, le dépistage et le traitement éventuel des complications respiratoires et hémorragiques est indispensable.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"La surveillance en SSPI peut être prolongée chez les jeunes enfants opérés dans un contexte de SAOS grave.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"La sortie de SSPI est autorisée après vérification des critères habituels (respiration, état hémodynamique, conscience, douleur, NVPO) et vérification de l'absence de saignement pharyngé par le chirurgien.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<b>3.2 — Perfusion postopératoire, reprise des boissons et de l'alimentation</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"Les apports hydroélectrolytiques postopératoires reposent sur un soluté isotonique en sel, pouvant contenir une faible concentration de glucose.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"La perfusion est poursuivie jusqu'à la reprise efficace des boissons.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"En raison du risque hémorragique, la reprise de l'alimentation s'effectue 6 heures après la fin de l'intervention ; la reprise des liquides clairs est possible dès la 2e heure.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Un régime alimentaire spécifique n'a pas fait la preuve de sa supériorité par rapport à une alimentation libre après amygdalectomie.","style":"cell"},{"t":"chip","label":"C"}]]},{"t":"p","html":"<b>3.3 — Modalités de l'analgésie postopératoire</b>","style":"cell_b"},{"t":"p","html":"La douleur post-amygdalectomie est considérée comme une douleur forte à composante inflammatoire, durant en moyenne 8 jours (maximum les 3 premiers jours). <i>[Accord fort]</i>","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"L'évaluation et le traitement de la douleur doivent être systématiques, y compris à domicile.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"L'utilisation du paracétamol doit être large, quasi-systématique ; les voies IV et orale sont les plus fiables.","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Seule la morphine est efficace en monothérapie, administrée par voie IV en SSPI ; elle est considérée comme l'antalgique de référence. Les autres analgésiques doivent être utilisés en association et en tenant compte de leur délai d'action.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"La posologie de la morphine doit être réduite en cas de SAOS grave.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Les antalgiques du palier II en association avec le paracétamol peuvent prendre le relais de la morphine IV. Leur administration par voie orale doit être débutée dès que possible.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Les AINS non sélectifs ne sont pas recommandés car ils peuvent s'associer à une augmentation de la fréquence des reprises chirurgicales pour saignement.","style":"cell"},{"t":"chip","label":"Faible"}]]}]},{"title":"Q4 — Complications postopératoires","items":[{"t":"section","text":"Question 4 — Complications postopératoires et prise en charge","color":"navy"},{"t":"p","html":"<b>4.1 — Principales complications postopératoires</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"Les principales complications primaires (avant la 24e heure) sont : les complications respiratoires, l'hémorragie et les nausées et vomissements.","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Les principaux facteurs de risque de complications respiratoires sont : la gravité du SAOS et l'importance de la désaturation artérielle préopératoire.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Chez les patients atteints de SAOS, 70 % des complications respiratoires majeures surviennent dans la première heure postopératoire, alors que les complications mineures surviennent habituellement avant la 6e heure.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"L'hémorragie postopératoire survient chez 0,5 à 3 % des patients.","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"80 % des hémorragies primaires surviennent avant la 6e heure.","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Environ 25 % des hémorragies postopératoires vont nécessiter une reprise chirurgicale.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Les patients nécessitant une reprise chirurgicale pour hémostase doivent être considérés comme ayant l'estomac plein et justifient une induction en séquence rapide.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"<b>4.2 — Nausées et vomissements postopératoires (NVPO)</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"Après amygdalectomie, on observe des nausées et vomissements chez 40 à 70 % des patients.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"L'utilisation peropératoire de protoxyde d'azote ne modifie pas l'incidence des NVPO.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Les NVPO sont moins fréquentes après injection peropératoire de propofol.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"L'administration prophylactique IV de sétron réduit significativement l'incidence des NVPO après amygdalectomie chez l'enfant.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"La dexaméthasone réduit significativement l'incidence des NVPO, et potentialise l'efficacité des sétrons.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Des protocoles de prise en charge des NVPO doivent être prévus et accessibles en SSPI.","style":"cell"},{"t":"chip","label":"Fort"}]]}]},{"title":"Q5 — Ambulatoire & sources","items":[{"t":"section","text":"Question 5 — Conditions requises pour l'amygdalectomie en ambulatoire","color":"navy"},{"t":"p","html":"La réalisation de l'amygdalectomie en ambulatoire est possible si <i>[Accord fort]</i> :","style":"body_sm"},{"t":"p","html":"&bull; l'enfant est âgé de plus de 3 ans ;<br/>&bull; il n'existe pas de comorbidité majorant notamment le risque respiratoire ;<br/>&bull; il n'existe pas d'anomalie de l'hémostase ;<br/>&bull; il n'existe pas de syndrome d'apnée du sommeil grave ;<br/>&bull; les critères habituels de proximité et d'entourage familial sont satisfaits ;<br/>&bull; et sous réserve d'un consensus entre le chirurgien, l'anesthésiste et les parents.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"L'intervention doit être réalisée le plus tôt possible dans la matinée afin de permettre la sortie après une surveillance postopératoire de 6 heures.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"La gestion anesthésique doit privilégier la prévention des NVPO, et l'anticipation peropératoire de l'analgésie postopératoire.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Le relais antalgique oral devrait être débuté avant la sortie du patient.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"Il est recommandé de remettre aux parents un document avec les coordonnées de la personne à contacter en cas de difficultés, ainsi que l'ordonnance d'antalgiques de sortie.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"p","html":"La sortie de l'enfant est autorisée après la 6e heure postopératoire, si les critères suivants sont réunis <i>[Accord fort]</i> :","style":"body_sm"},{"t":"p","html":"&bull; absence de saignement au niveau des loges amygdaliennes, confirmée par le chirurgien ;<br/>&bull; absence de douleur ;<br/>&bull; absence de NVPO ;<br/>&bull; accord signé du chirurgien et de l'anesthésiste.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Proposition","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"Un suivi téléphonique du patient à domicile à la 24e heure est souhaitable, car il améliore la qualité de la prise en charge.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Anesthésie pour amygdalectomie chez l'enfant » — Conférence d'experts, texte court. Société française d'anesthésie et de réanimation (SFAR), Association des anesthésistes réanimateurs pédiatriques d'expression française (Adarpef), Club de l'anesthésie réanimation en ORL (Carorl). Secrétaire : Pr I. Constant ; Président : Pr G. Orliaguet.","style":"source"},{"t":"p","html":"<b>Version :</b> 2005 (dépôt légal novembre 2006).","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> Conférence d'experts — deux systèmes de cotation combinés : niveaux de preuve (Grade A/B/C selon la littérature) et cotation RAND/UCLA modifiée (« Accord fort/faible ») pour les propositions sans preuve suffisante — voir disclosure méthodologique en page 1.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/wp-content/uploads/2015/10/2a_SFAR_TEXTE-COURT_Anesthesie-pour-amygdalectomie-chez-lenfant.pdf","style":"source"},{"t":"p","html":"<b>Couverture :</b> cette fiche reprend l'intégralité des 5 questions / 12 sous-questions du texte court (évaluation préopératoire, prise en charge anesthésique, soins postopératoires, complications, ambulatoire).","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement — document de 2005 :</b> ce document est une fiche de synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend l'intégralité des propositions du texte source, mais ne remplace pas le texte intégral (argumentaire complet, références bibliographiques) et n'est ni éditée ni validée par la SFAR, l'Adarpef ou le Carorl. Les pratiques ayant pu évoluer depuis 2005, se référer en cas de doute au texte intégral, aux recommandations plus récentes le cas échéant, et/ou à un avis spécialisé.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/anesthesie-pour-amygdalectomie-chez-lenfant/';

