where d.source_url = 'https://sfar.org/prise-en-charge-anesthesique-peri-procedurale-dune-revascularisation-cerebrale-par-thrombectomie/' and s.acronym in ('SFAR', 'ANARLF', 'SFNR', 'SFNV', 'GFHT')
