on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/pratique-des-anesthesies-locales-et-locoregionales-par-des-medecins-non-specialises-en-anesthesie-reanimation/' and s.acronym in ('SFAR', 'SFMU')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/pratique-des-anesthesies-locales-et-locoregionales-par-des-medecins-non-specialises-en-anesthesie-reanimation/' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'alr_non_specialiste',
  card_json = $mgjson${"badge":"Grades A-E","title":"AL/ALR par médecins non spécialisés — urgences","short":"Conférence d'experts, texte court, SFAR/Samu de France/SFMU, 2002 (Ann Fr Anesth Réanim 2004;23:167-176) : pratique de l'anesthésie locale (AL) et locorégionale (ALR) par des médecins de l'urgence non spécialisés en anesthésie-réanimation (SAU, urgences préhospitalières) — exclut l'anesthésie « chirurgicale » et les ALR périmédullaires/blocs du tronc. 34 énoncés individuellement gradés (grille EBM Niveaux I-V / Grades A-E, source non numérotée Rx.y — référencement synthétique §<sous-section> disclosed) : pharmacologie/toxicité des AL (dont Tableau 4 posologies et Tableau 3 toxicité neurologique), indications/techniques (AL topique, infiltration, blocs des membres — fémoral/iliofascial, pied, main — et de la face), sédation/analgésie associées, précautions/surveillance/monitorage (Tableau 5 complications), particularités en milieu difficile et chez l'enfant, formation requise.","society":"SFAR / Samu de France / SFMU","version":"2002","validated":"Conférence d'experts (Ann Fr Anesth Réanim 2004;23:167-176)","methodology":"Conférence d'experts, grille EBM Niveaux de preuve I-V / Grades A-E — formulation narrative, aucune numérotation Rx.y native dans la source","pages":10,"section":"Urgences"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"alr_non_specialiste","sections":[{"title":"Pharmacologie, toxicité, blocs, précautions & sources","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Résumé :</b> conférence d'experts encadrant la pratique de l'anesthésie locale (AL) et locorégionale (ALR) par des <b>médecins de l'urgence non spécialisés en anesthésie-réanimation</b> (structures d'accueil des urgences, urgences préhospitalières). Exclut explicitement l'anesthésie « chirurgicale » (bloc opératoire, compétence exclusive des anesthésistes-réanimateurs), les ALR périmédullaires (rachianesthésie, péridurale) et les blocs du tronc/intercostaux/paravertébraux/interpleuraux/multibloc laryngé. S'applique uniquement lorsque le même praticien réalise à la fois l'AL/ALR et l'acte d'urgence.","style":"body"}},{"t":"section","text":"Méthodologie & niveaux de preuve","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Niveau de preuve","style":"head_w_c"},{"t":"p","html":"Définition (Tableau 1 source)","style":"head_w_c"}],[{"t":"p","html":"I","style":"cell"},{"t":"p","html":"Études aléatoires, faible risque de faux positifs (α) et faux négatifs (β) — puissance élevée (β = 5-10 %).","style":"cell"}],[{"t":"p","html":"II","style":"cell"},{"t":"p","html":"Risque α élevé, ou faible puissance.","style":"cell"}],[{"t":"p","html":"III","style":"cell"},{"t":"p","html":"Études non aléatoires, sujets « contrôlés » contemporains.","style":"cell"}],[{"t":"p","html":"IV","style":"cell"},{"t":"p","html":"Études non aléatoires, sujets « contrôlés » non contemporains.","style":"cell"}],[{"t":"p","html":"V","style":"cell"},{"t":"p","html":"Études de cas, avis d'experts.","style":"cell"}]]},{"t":"table","rows":[[{"t":"p","html":"Grade","style":"head_w_c"},{"t":"p","html":"Définition (Tableau 2 source)","style":"head_w"}],[{"t":"chip","label":"A"},{"t":"p","html":"Deux (ou plus) études de niveau I.","style":"cell"}],[{"t":"chip","label":"B"},{"t":"p","html":"Une étude de niveau I.","style":"cell"}],[{"t":"chip","label":"C"},{"t":"p","html":"Étude(s) de niveau II.","style":"cell"}],[{"t":"chip","label":"D"},{"t":"p","html":"Étude(s) de niveau III.","style":"cell"}],[{"t":"chip","label":"E"},{"t":"p","html":"Étude(s) de niveau IV ou V.","style":"cell"}]]},{"t":"section","text":"Question 1 — Propriétés et risques des anesthésiques locaux (AL)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Détail","style":"head_w"}],[{"t":"p","html":"Familles","style":"cell_b"},{"t":"p","html":"Aminoesters (procaïne, tétracaïne — pratiquement plus utilisés en Europe) et aminoamides (lidocaïne, mépivacaïne, bupivacaïne, ropivacaïne, articaïne).","style":"cell"}],[{"t":"p","html":"Puissance faible","style":"cell_b"},{"t":"p","html":"Lidocaïne, prilocaïne, mépivacaïne : délai d'action court (5-10 min selon le site), durée d'action 1h30-2h.","style":"cell"}],[{"t":"p","html":"Puissance élevée","style":"cell_b"},{"t":"p","html":"Ropivacaïne, bupivacaïne : délai d'action plus long (10-20 min), durée d'action 2h30-3h30.","style":"cell"}],[{"t":"p","html":"Pharmacocinétique","style":"cell_b"},{"t":"p","html":"Liaison protéique importante pour tous les amides ; acidose, hypoventilation et âge extrême (<1 an ou très avancé) diminuent la fixation protéique et augmentent la toxicité systémique. Métabolisme hépatique exclusif (cytochrome P450) — risque de surdosage en cas de bas débit cardiaque (insuffisance cardiaque, choc mal compensé, bêta-bloquants, ventilation mécanique). Solutions adrénalinées : ralentissent l'absorption systémique, augmentent la durée du bloc.","style":"cell"}],[{"t":"p","html":"Ordre du pic d'absorption (décroissant)","style":"cell_b"},{"t":"p","html":"Scalp/infiltration autres territoires (gros volumes, risque de pic précoce, enfant particulièrement exposé) > anesthésie topique ORL/respiratoire (résorption très rapide) > bloc intercostal (absorption dès 6-10 min) > blocs fémoral/iliofascial.","style":"cell"}],[{"t":"p","html":"Prudence","style":"cell_b"},{"t":"p","html":"Réinjections d'anesthésiques locaux, même espacées : risque toxique des doses cumulées. Chez l'enfant de moins d'un an : caractéristiques physiologiques imposant un usage particulier.","style":"cell"}]]},{"t":"section","text":"Toxicité des anesthésiques locaux","color":"red"},{"t":"p","html":"<b>Toxicité locale :</b> la lidocaïne notamment est toxique pour le nerf, mais cette toxicité ne se manifeste que lors de rachianesthésies (hors champ de ce texte) ou d'injection intraneurale accidentelle. <b>Mécanismes systémiques :</b> injection accidentelle intravasculaire (d'où la nécessité de vérifier l'absence de reflux et d'injecter lentement), dose unique trop élevée, ou doses cumulées trop importantes.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§2.1.3.2","style":"cell_b"},{"t":"p","html":"Toxicité neurologique centrale (prodromes puis convulsions, coma avec dépression cardiorespiratoire au stade ultime — Tableau 3) : le traitement doit être rapide — arrêt de l'injection, oxygénation et contrôle des voies aériennes, voire administration parentérale d'anticonvulsivants.","style":"cell"},{"t":"chip","label":"D"}]]},{"t":"table","rows":[[{"t":"p","html":"Toxicité neurologique — Tableau 3","style":"head_w_c"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"Aspects cliniques","style":"cell"},{"t":"p","html":"Crise généralisée tonicoclonique (type grand mal, avec troubles neurovégétatifs : tachycardie, HTA, mydriase, sudation) ; état de mal épileptique ; crises partielles complexes possibles ; attaques de panique/sensation de mort imminente (décharges hippocampiques).","style":"cell"}],[{"t":"p","html":"Prodromes","style":"cell"},{"t":"p","html":"Signes subjectifs : paresthésies, fourmillements des extrémités, céphalées en casque ou frontales, goût métallique dans la bouche, malaise général avec angoisse, étourdissement, sensation ébrieuse, vertiges, logorrhée, hallucinations visuelles ou auditives, bourdonnements d'oreille. Signes objectifs : pâleur, tachycardie, irrégularité respiratoire, nausées/vomissements, confusion voire absence, empâtement de la parole, nystagmus, fasciculations des lèvres/langue. <i>Attention : peuvent être masqués par une prémédication sédative.</i>","style":"cell"}],[{"t":"p","html":"Conduite à tenir","style":"cell"},{"t":"p","html":"Arrêt de l'injection, décubitus dorsal, matériel de ventilation préparé (ballon autoremplisseur à valve unidirectionnelle sur source d'oxygène).","style":"cell"}]]},{"t":"p","html":"Tous les anesthésiques locaux sont capables d'induire des accidents convulsifs. Le rapport des toxicités neurologiques de la bupivacaïne, de la ropivacaïne et de la lidocaïne est d'environ 4 ; 3 ; 1, correspondant au rapport de puissance approximatif de ces agents.","style":"note"},{"t":"p","html":"<b>Toxicité cardiaque :</b> aux concentrations toxiques (&gt;2-3 µg/ml), la bupivacaïne ralentit la conduction intraventriculaire (élargissement du QRS), avec risque de tachycardie ventriculaire, torsades de pointes ou bradycardie extrême — l'accident cardiotoxique peut précéder les prodromes neurologiques avec la bupivacaïne. Hypoxie, acidose, hypothermie et désordres électrolytiques (hyponatrémie sévère, hyperkaliémie) majorent le risque.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§2.1.3.2","style":"cell_b"},{"t":"p","html":"En cas d'arrêt cardiaque toxique lié aux anesthésiques locaux, aucun médicament anti-arythmique habituellement préconisé dans l'arrêt cardiaque ne doit être utilisé.","style":"cell"},{"t":"chip","label":"D"}],[{"t":"p","html":"§2.1.3.2","style":"cell_b"},{"t":"p","html":"La ropivacaïne (réputée moins cardiotoxique que la bupivacaïne à dose égale) est une alternative intéressante à la bupivacaïne, dans les rares cas où un agent de longue durée d'action est requis.","style":"cell"},{"t":"chip","label":"D"}]]},{"t":"p","html":"<i>Prévention :</i> plus que la dose-test adrénalinée, l'injection lente, fractionnée avec maintien du contact verbal représente la meilleure prévention.","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Détail","style":"head_w"}],[{"t":"p","html":"Allergies","style":"cell_b"},{"t":"p","html":"Exceptionnelles pour les anesthésiques locaux amides ; dans les rares cas avérés, le conservateur des solutions adrénalinées (métabisulfite) est plus souvent en cause que l'anesthésique local lui-même.","style":"cell"}],[{"t":"p","html":"Méthémoglobinémie","style":"cell_b"},{"t":"p","html":"Cyanose, dyspnée, tachycardie, céphalées, vertiges, hypoxémie. Chez le nouveau-né/nourrisson : possible jusqu'à 3h après prilocaïne (exceptionnellement lidocaïne). La crème Emla® contient de la prilocaïne mais n'expose pas à ce risque si utilisée selon le Tableau 4. <b>Traitement :</b> bleu de méthylène IV, 1 à 5 mg/kg.","style":"cell"}],[{"t":"p","html":"Adjuvants (vasoconstricteurs)","style":"cell_b"},{"t":"p","html":"Les solutions adrénalinées contiennent un stabilisant (métabisulfite, allergisant possible) ; le passage intravasculaire rapide de l'adrénaline peut causer une HTA/malaise étiqueté à tort « allergie ».","style":"cell"}],[{"t":"p","html":"Contre-indications absolues","style":"cell_b"},{"t":"p","html":"Allergie avérée à la classe (ou à un excipient) ; porphyrie pour la lidocaïne et la ropivacaïne ; traitement par IMAO de première génération ; blocs dans les régions à circulation terminale (pénis, face, doigts, orteils) pour les solutions adrénalinées.","style":"cell"}],[{"t":"p","html":"Contre-indications relatives","style":"cell_b"},{"t":"p","html":"Cardiopathies ischémiques mal compensées ; thyréotoxicose.","style":"cell"}]]},{"t":"p","html":"<i>Aspects pratiques (§2.2) :</i> pour minimiser les risques de toxicité systémique, il faut impérativement limiter les doses injectées, utiliser des solutions adrénalinées en l'absence de contre-indications (blocs de la face, interdigitaux et pénien), et préférer les agents les moins toxiques.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Agent","style":"head_w_c"},{"t":"p","html":"Présentation","style":"head_w_c"},{"t":"p","html":"Indications","style":"head_w_c"},{"t":"p","html":"Posologie maximum*","style":"head_w_c"}],[{"t":"p","html":"Lidocaïne","style":"cell"},{"t":"p","html":"0,5 ; 1 et 2 % sans adrénaline","style":"cell"},{"t":"p","html":"Infiltration, bloc périphérique (de préférence 0,5 % adrénalinée)","style":"cell"},{"t":"p","html":"300 mg adulte / 5 mg/kg enfant (sans adrénaline) ; 500 mg adulte / 6-7 mg/kg enfant (avec adrénaline 1/200 000)","style":"cell"}],[{"t":"p","html":"Xylocaïne® 5 % nébuliseur","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Laryngoscopie","style":"cell"},{"t":"p","html":"10-25 pulvérisations (adulte) ; 2 pulv./10 kg (enfant)","style":"cell"}],[{"t":"p","html":"Xylocaïne® 5 % naphtazoline","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Anesthésie/vasoconstriction muqueuses, endoscopie ORL","style":"cell"},{"t":"p","html":"25 pulvérisations, 5-8 ml (adulte) ; 0,1 ml/kg (enfant &gt;6 ans)","style":"cell"}],[{"t":"p","html":"Xylocaïne® visqueuse 2 %","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Anesthésie buccale","style":"cell"},{"t":"p","html":"2-3 ml (adulte), absorption variable","style":"cell"}],[{"t":"p","html":"Xylocaïne® gel urétral 2 %","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Anesthésie urétrale","style":"cell"},{"t":"p","html":"1 tube (adulte), absorption variable","style":"cell"}],[{"t":"p","html":"Crème Emla® (tube 30 g)","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Ne pas laisser &gt;20 min au contact des muqueuses ou d'une plaie","style":"cell"},{"t":"p","html":"30 g (adulte)","style":"cell"}],[{"t":"p","html":"Crème Emla® (tube 5 g)","style":"cell"},{"t":"p","html":"—","style":"cell"},{"t":"p","html":"Ne pas laisser &gt;20 min au contact des muqueuses ou d'une plaie","style":"cell"},{"t":"p","html":"10 g (adulte, muqueuses) ; 0,15 g/kg (enfant)","style":"cell"}],[{"t":"p","html":"Mépivacaïne","style":"cell"},{"t":"p","html":"1 et 2 %","style":"cell"},{"t":"p","html":"Infiltration / bloc périphérique","style":"cell"},{"t":"p","html":"200 mg (infiltration) / 400 mg (bloc périphérique), adulte","style":"cell"}],[{"t":"p","html":"Ropivacaïne","style":"cell"},{"t":"p","html":"0,2 ; 0,75 et 1 %","style":"cell"},{"t":"p","html":"Infiltration, bloc périphérique","style":"cell"},{"t":"p","html":"150 mg adulte ; 2,5-3 mg/kg enfant &gt;12 ans","style":"cell"}]]},{"t":"p","html":"* Colonne « Posologie maximum » gradée <b>D</b> dans le texte source (Tableau 4). Infiltration : dose maximale lidocaïne 200 mg. Les présentations contenant un conservateur sont signalées comme telles dans le texte source.","style":"note"},{"t":"section","text":"Question 2 — Indications, contre-indications et méthodes de l'AL et de l'ALR","color":"navy"},{"t":"p","html":"<b>3.1 Anesthésie locale (AL)</b> — topique (muqueuses/peau) ou par infiltration.","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Détail","style":"head_w"}],[{"t":"p","html":"Muqueuses","style":"cell_b"},{"t":"p","html":"Analgésie efficace des muqueuses saines (nez, bouche, gorge, arbre trachéobronchique, œsophage, appareil génito-urinaire) par lidocaïne ou crème Emla® (≤20 min sur les muqueuses). Indications : traitement symptomatique de la douleur buccale/œsophagienne/hémorroïdaire (lidocaïne à ne pas poursuivre au retour à domicile — risque de convulsion, voire de décès) ; AL de contact avant explorations instrumentales (stomatologie, laryngoscopie, fibroscopie œso-gastrique) ; AL de surface avant infiltration ou geste douloureux ; AL nasale avant geste invasif ; AL avant exploration urologique ou infiltration des muqueuses génitales. <i>Risque :</i> suppression du réflexe de protection des voies aériennes supérieures — éviter toute alimentation solide/liquide pendant 4h après anesthésie des muqueuses du carrefour aérodigestif supérieur. Les gels peuvent induire une réaction positive aux tests antidopage.","style":"cell"}],[{"t":"p","html":"Peau (Emla®)","style":"cell_b"},{"t":"p","html":"Mélange lidocaïne 2,5 %/prilocaïne 2,5 %, sous pansement occlusif ≥1h, durée d'action 1-2h, anesthésie sur 5 mm de profondeur maximum. Indications : peau saine avant ponctions/abords vasculaires, ponction lombaire ou ALR ; avant chirurgie cutanée superficielle (incluant paraphimosis) ; avant détersion mécanique des ulcères veineux. Utilisable sur peau lésée à doses réduites. Éviter le contact oculaire.","style":"cell"}],[{"t":"p","html":"Corps étrangers auriculaires","style":"cell_b"},{"t":"p","html":"Anesthésie du conduit auditif externe et de la membrane tympanique indiquée pour l'ablation en urgence. La perforation tympanique est une contre-indication.","style":"cell"}],[{"t":"p","html":"Œil douloureux","style":"cell_b"},{"t":"p","html":"Instillation d'1-2 gouttes d'oxybuprocaïne (Novesine® 0,2 %) pour examiner sans douleur. <b>Ne pas poursuivre</b> : risque de lésions cornéennes graves par suppression de la sensibilité de la cornée.","style":"cell"}]]},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.1.2.2","style":"cell_b"},{"t":"p","html":"L'utilisation de l'Emla® n'est pas contre-indiquée chez l'enfant de moins de trois mois.","style":"cell"},{"t":"chip","label":"B"}]]},{"t":"p","html":"<b>Anesthésie par infiltration</b> — d'installation plus rapide que la topique mais nécessitant plus de produit ; pour les plaies étendues, la dose totale peut approcher la dose toxique.","style":"h2"},{"t":"p","html":"<b>Choix de l'agent :</b> lidocaïne et mépivacaïne recommandées. La bupivacaïne n'a pas d'AMM pour cette indication (cardiotoxicité, cf. Question 1). Solutions adrénalinées recommandées sauf contre-indications (face, doigts).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.1.3.2","style":"cell_b"},{"t":"p","html":"Pour diminuer la douleur de l'injection : aiguilles de petit calibre, solutions réchauffées, injection intradermique régulière et lente dans les berges de la plaie et de proche en proche (technique également requise pour prévenir le risque septique en peau saine si la plaie est contaminée, et éviter l'injection intravasculaire).","style":"cell"},{"t":"chip","label":"B"}]]},{"t":"p","html":"<i>Choix de la technique (§3.1.4) :</i> les méthodes sont associables (topique + ALR, topique + infiltration, ALR + infiltration complémentaire). Une surface opératoire étendue fait préférer une technique locorégionale (risque de toxicité systémique des grands volumes en infiltration). Le risque de distorsion des berges d'une plaie complexe fait préférer une anesthésie topique ou une ALR.","style":"note"},{"t":"section","text":"3.2 Blocs locorégionaux (ALR)","color":"navy"},{"t":"p","html":"Les ALR périmédullaires (rachianesthésie, péridurale), les blocs du tronc, intercostaux, paravertébraux, interpleuraux et le multibloc laryngé sortent explicitement du cadre de ces recommandations (efficacité variable, iatrogénie potentielle). Les blocs périphériques, sans retentissement général (hémodynamique, ventilatoire, neurologique central), sont bien adaptés à l'urgence.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.2","style":"cell_b"},{"t":"p","html":"Deux situations se prêtent, de manière schématique, à la mise en œuvre d'une ALR dans le cadre de ces recommandations : les traumatismes des membres et les traumatismes de la face.","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"§3.2","style":"cell_b"},{"t":"p","html":"Le seul bloc qui, de manière consensuelle, semble adapté à l'urgence extrahospitalière est le bloc du nerf fémoral.","style":"cell"},{"t":"chip","label":"D"}]]},{"t":"p","html":"<b>3.2.1 Contraintes et spécificités de l'urgence</b>","style":"h2"},{"t":"p","html":"Le contexte de l'urgence ne dispense pas de dresser par écrit un inventaire précis et exhaustif des lésions. Contre-indications classiques à respecter : infection locale, troubles majeurs de l'hémostase, exceptionnelle allergie aux anesthésiques locaux.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.2.1","style":"cell_b"},{"t":"p","html":"Il est indispensable, avant tout bloc, de consigner par écrit les données de l'examen neurologique (motricité, sensibilité) de la zone considérée.","style":"cell"},{"t":"chip","label":"E"}],[{"t":"p","html":"§3.2.1","style":"cell_b"},{"t":"p","html":"L'interrogatoire, lorsqu'il est possible, doit rechercher une anomalie constitutionnelle ou acquise de l'hémostase (un bilan biologique d'hémostase systématique n'est pas utile).","style":"cell"},{"t":"chip","label":"E"}],[{"t":"p","html":"§3.2.1","style":"cell_b"},{"t":"p","html":"Avant la réalisation d'une ALR (bloc fémoral ou iliofascial), un niveau élevé de douleur, spontanée ou induite par une éventuelle mobilisation du malade, justifie une analgésie première par voie systémique.","style":"cell"},{"t":"chip","label":"E"}]]},{"t":"section","text":"3.2.2 ALR et traumatismes des membres","color":"navy"},{"t":"p","html":"<b>Bloc du nerf fémoral / bloc iliofascial</b>","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.2.2.1","style":"cell_b"},{"t":"p","html":"Le bloc du nerf fémoral pour fracture de la diaphyse fémorale est la technique d'ALR la plus répandue et la plus éprouvée en urgence, procurant de manière prévisible une analgésie d'excellente qualité, chez l'enfant comme chez l'adulte, pour l'urgence pré- et intrahospitalière.","style":"cell"},{"t":"chip","label":"A"}]]},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.2.2.1","style":"cell_b"},{"t":"p","html":"Indications : analgésie pour fracture de diaphyse fémorale ainsi que pour les plaies du genou — permettent, dans d'excellentes conditions d'analgésie, la mobilisation et le transport, la réalisation de clichés radiographiques, et la mise d'une attelle après pose éventuelle d'une broche de traction.","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"§3.2.2.1","style":"cell_b"},{"t":"p","html":"Ces blocs sont partiellement efficaces pour la prise en charge analgésique des fractures des extrémités supérieure ou inférieure du fémur.","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"§3.2.2.1","style":"cell_b"},{"t":"p","html":"Le bloc iliofascial doit être recommandé comme la technique de référence dans le cadre de l'urgence et permet de s'affranchir de l'utilisation d'un neurostimulateur.","style":"cell"},{"t":"chip","label":"A"}]]},{"t":"p","html":"<i>Méthode :</i> patient en décubitus dorsal, point de ponction à la jonction 1/3 moyen-1/3 externe du ligament inguinal (arcade crurale) ; l'aiguille à biseau court franchit le fascia lata puis le fascia iliaca (deux ressauts successifs) avant l'injection dans l'espace iliofascial.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.2.2.1","style":"cell_b"},{"t":"p","html":"Avec cette technique, le taux de succès est de 88 % pour le nerf fémoral (crural), de 90 % pour le nerf cutané latéral (fémorocutané), et de 38 % pour le nerf obturateur — le bloc « 3 en 1 » échappe souvent au territoire obturateur (partie inféro-interne de la cuisse, adducteurs).","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"§3.2.2.1","style":"cell_b"},{"t":"p","html":"Des volumes de 0,3 à 0,4 ml/kg de lidocaïne à 1 % sont suffisants chez l'adulte pour anesthésier les trois branches du plexus lombaire — le recours à des volumes plus importants n'améliore pas la qualité du bloc.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"§3.2.2.1","style":"cell_b"},{"t":"p","html":"Chez l'enfant, à défaut d'information précise sur le poids, le volume de lidocaïne 1 % peut être estimé à 1 ml/année d'âge (ropivacaïne non validée dans cette indication).","style":"cell"},{"t":"chip","label":"C"}]]},{"t":"p","html":"<i>Délai :</i> l'analgésie débute entre la 5e et la 15e minute selon l'anesthésique local ; dès le bloc installé, le membre doit être immobilisé pour ne pas risquer un déplacement des fragments et une lésion vasculonerveuse secondaire alors que le signal d'alarme « douleur » a disparu.","style":"note"},{"t":"p","html":"<b>Blocs du pied</b>","style":"h2"},{"t":"p","html":"Patient en décubitus dorsal, jambe et cuisse fléchies, pied reposant à plat sur la table. Nerfs fibulaire superficiel (musculocutané) et sural, par injection sous-cutanée au niveau de la cheville, à quatre travers de doigt au-dessus de la pointe de la malléole latérale. Autres blocs, moins utilisés : nerf tibial (tibial postérieur), rameau calcanéen médial du nerf tibial postérieur (nerf calcanéen interne), fibulaire profond (nerf tibial antérieur).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.2.2.2","style":"cell_b"},{"t":"p","html":"Les blocs du pied sont proposés pour la prise en charge de plaies du pied.","style":"cell"},{"t":"chip","label":"D"}]]},{"t":"p","html":"<b>Blocs du membre supérieur</b> — seuls les blocs tronculaires périphériques sont retenus (lidocaïne 1 % non adrénalinée, 3-4 ml/bloc).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Détail","style":"head_w"}],[{"t":"p","html":"Nerf médian","style":"cell_b"},{"t":"p","html":"Face antérieure du poignet, dans le canal carpien, entre les tendons des muscles fléchisseur radial du carpe (grand palmaire) et long palmaire (petit palmaire) — injection après franchissement du rétinaculum des fléchisseurs (ligament annulaire).","style":"cell"}],[{"t":"p","html":"Nerf radial","style":"cell_b"},{"t":"p","html":"Avant-bras en position neutre, colonne du pouce en abduction et extension ; ligne transversale de 3 cm tracée à l'angle supérieur de la tabatière anatomique, 3 ml d'anesthésique local infiltrés en sous-cutané sur cette ligne.","style":"cell"}],[{"t":"p","html":"Nerf ulnaire","style":"cell_b"},{"t":"p","html":"Pli de flexion tracé sur un poignet en extension ; point marqué 2-3 cm au-dessus, au bord médial interne du muscle fléchisseur ulnaire du carpe (cubital antérieur).","style":"cell"}]]},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.2.2.3","style":"cell_b"},{"t":"p","html":"Ces blocs tronculaires périphériques permettent l'exploration et la suture de plaies n'intéressant qu'un ou deux territoires de la main.","style":"cell"},{"t":"chip","label":"D"}]]},{"t":"p","html":"<b>Bloc de la gaine des fléchisseurs</b> — particulièrement intéressant pour les gestes courts sur les 2e-4e doigts (sutures de plaies, excision partielle ou reposition d'ongles, extraction de corps étranger, réduction de luxation interphalangienne, incision d'abcès). Aiguille introduite avec un angle de 45° au niveau du pli cutané de flexion métacarpophalangien ; le tendon fléchisseur est repéré par des mouvements de flexion au niveau de la tête du métacarpien correspondant ; la bonne position de l'aiguille dans la gaine tendineuse est attestée par sa verticalisation lors des mouvements de flexion — une injection sans résistance prouve que la solution est dans la gaine du tendon (lidocaïne non adrénalinée).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.2.2.3","style":"cell_b"},{"t":"p","html":"Cette technique doit être adoptée en lieu et place de l'ancienne technique d'anesthésie des nerfs collatéraux des doigts — relativement douloureuse et incriminée dans la survenue d'ischémie par compression d'artérioles terminales.","style":"cell"},{"t":"chip","label":"B"}]]},{"t":"section","text":"3.2.3 ALR et traumatismes de la face","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.2.3","style":"cell_b"},{"t":"p","html":"Les blocs de la face devraient supplanter au service d'accueil des urgences les traditionnelles anesthésies locales de la face, où l'on finit par infiltrer des volumes excessifs d'anesthésique local pour suturer des plaies aux berges devenues succulentes.","style":"cell"},{"t":"chip","label":"E"}],[{"t":"p","html":"§3.2.3","style":"cell_b"},{"t":"p","html":"L'anesthésie tronculaire de la face représente une alternative de choix à l'anesthésie générale, chez des malades à l'estomac plein, pour sutures de plaies multiples de la face.","style":"cell"},{"t":"chip","label":"D"}]]},{"t":"table","rows":[[{"t":"p","html":"Bloc","style":"head_w_c"},{"t":"p","html":"Nerf (origine)","style":"head_w_c"},{"t":"p","html":"Zone anesthésiée","style":"head_w_c"}],[{"t":"p","html":"Supra-orbitaire + supratrochléaire","style":"cell"},{"t":"p","html":"Nerf frontal, branche du nerf ophtalmique (V1) — foramen supra-orbitaire, à l'aplomb de la pupille","style":"cell"},{"t":"p","html":"Front (jusqu'à la suture coronale) et paupières supérieures, si bilatéral","style":"cell"}],[{"t":"p","html":"Infra-orbitaire","style":"cell"},{"t":"p","html":"Nerf infra-orbitaire, branche du nerf maxillaire (V2) — foramen infra-orbitaire, voie orale ou externe","style":"cell"},{"t":"p","html":"Joue et hémilèvre supérieure","style":"cell"}],[{"t":"p","html":"Mentonnier","style":"cell"},{"t":"p","html":"Nerf mentonnier, branche du nerf mandibulaire (V3) — foramen mentonnier, voie buccale ou transcutanée","style":"cell"},{"t":"p","html":"Menton et lèvre inférieure","style":"cell"}]]},{"t":"section","text":"3.3 Sédation associée & 3.4 Analgésie associée","color":"navy"},{"t":"p","html":"Certains cas d'agitation peuvent nécessiter une sédation pour faciliter la réalisation du bloc. Aucune étude ne rapporte de majoration du risque de lésion nerveuse liée à la ponction lorsqu'une sédation légère est associée (niveau n'empêchant ni la paresthésie-signal d'alarme, ni le contact verbal). Sédation par voie IV périphérique, surveillance clinique et instrumentale (scope, oxymètre, PNI) obligatoire.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§3.3","style":"cell_b"},{"t":"p","html":"L'échec partiel ou total d'un bloc ne constitue en aucun cas l'indication d'une sédation.","style":"cell"},{"t":"chip","label":"E"}],[{"t":"p","html":"§3.3","style":"cell_b"},{"t":"p","html":"Un score de Ramsay égal à 2 (patient coopérant, orienté et tranquille) est l'objectif souhaité — l'utilisation de médicaments facilement antagonisables est un gage de sécurité. Le midazolam (anxiolyse et amnésie), en titration par bolus de 0,5 à 1 mg, est la benzodiazépine la mieux adaptée à l'urgence (variabilité interindividuelle importante) ; les autres hypnotiques sont inadaptés à la sédation de complément d'une ALR en urgence.","style":"cell"},{"t":"chip","label":"E"}],[{"t":"p","html":"§3.3","style":"cell_b"},{"t":"p","html":"Le risque de dépression respiratoire est majoré par l'association à un morphinique.","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"§3.3","style":"cell_b"},{"t":"p","html":"L'association d'un morphinique à la sédation d'une ALR doit donc être évitée.","style":"cell"},{"t":"chip","label":"E"}],[{"t":"p","html":"§3.4","style":"cell_b"},{"t":"p","html":"La morphine est l'opiacé de référence pour assurer une analgésie préalable ou de complément (bolus initial 0,05 mg/kg IV, puis bolus titrés de 2-3 mg toutes les 5 min) — les opiacés agonistes partiels ne sont pas recommandés.","style":"cell"},{"t":"chip","label":"D"}],[{"t":"p","html":"§3.4","style":"cell_b"},{"t":"p","html":"Le mélange équimolaire oxygène-protoxyde d'azote (MEOPA), par son action sédative et analgésique, peut également être utilisé en complément d'une ALR.","style":"cell"},{"t":"chip","label":"E"}]]},{"t":"section","text":"Question 3 — Précautions, surveillance et monitorage","color":"navy"},{"t":"p","html":"<b>4.1 Complications</b> — outre la syncope vagale, la toxicité systémique et les réactions anaphylactiques (Tableau 5 ci-dessous), deux autres types de complications sont décrits dans le texte source : les <b>complications neurologiques périphériques</b> (traumatisme ou lésion ischémique par compression — le bloc moteur/sensitif peut masquer un traumatisme initial ou secondaire lié à un défaut d'immobilisation, un syndrome de loge, etc. ; une lésion neurologique préalable doit être recherchée, diagnostiquée et consignée par écrit avant l'ALR) et les <b>complications septiques</b> (favorisées par une antisepsie insuffisante ou une infection à proximité du point d'infiltration).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Complication — Tableau 5","style":"head_w_c"},{"t":"p","html":"Prévention","style":"head_w_c"},{"t":"p","html":"Signes cliniques / paracliniques (risque évolutif)","style":"head_w_c"},{"t":"p","html":"Traitement","style":"head_w_c"}],[{"t":"p","html":"Syncope vagale","style":"cell"},{"t":"p","html":"Éviter milieu confiné/surchauffé ; décubitus dorsal","style":"cell"},{"t":"p","html":"Sueurs, malaise, pâleur, bradycardie (ECG), hypotension (PNI) → risque d'arrêt cardiaque","style":"cell"},{"t":"p","html":"Arrêt de la stimulation douloureuse, décubitus dorsal, surélévation des membres inférieurs, stimulation du patient ; oxygène 100 % ; atropine IV 20 µg/kg ; recherche d'une cause déclenchante","style":"cell"}],[{"t":"p","html":"Réactions anaphylactiques","style":"cell"},{"t":"p","html":"Interrogatoire : recherche de réactions allergiques connues aux AL (éviction des produits en cause)","style":"cell"},{"t":"p","html":"Signes cutanés (érythème, urticaire), respiratoires (bronchospasme, gêne laryngée), tachycardie (ECG), hypotension (PNI), hypoxie (SpO2) → risque d'arrêt cardiaque","style":"cell"},{"t":"p","html":"Arrêt de l'injection ; antihistaminique ; oxygène 100 % ; si hypotension grave : voie veineuse + adrénaline titrée ; réanimation de l'arrêt cardiaque si besoin","style":"cell"}],[{"t":"p","html":"Toxicité systémique des AL","style":"cell"},{"t":"p","html":"Respect des doses maximales ; limitation des doses ; test d'aspiration avant et pendant l'injection ; injection fractionnée, lente ; maintien du contact verbal","style":"cell"},{"t":"p","html":"Bourdonnement d'oreille, hyperacousie, dysesthésies péribuccales, goût métallique, sensation de malaise, logorrhée ; convulsions (ECG : QRS élargi, tachycardie ventriculaire) ; troubles cardiaques : tachycardie, bradycardie (PNI : hypotension) → coma, arrêt cardiaque","style":"cell"},{"t":"p","html":"Arrêt de l'injection ; oxygène 100 % (éviter l'hypercapnie) ; anticomitial IV ; traitement symptomatique du coma et de l'arrêt cardiaque ; <b>aucun antiarythmique</b> en cas de troubles du rythme","style":"cell"}]]},{"t":"section","text":"4.2 Mesures de précaution","color":"teal-dark"},{"t":"p","html":"• L'opérateur doit avoir été formé pour la technique choisie.","style":"body_sm"},{"t":"p","html":"• C'est au médecin réalisant l'acte d'évaluer le rapport bénéfice-risque pour le patient.","style":"body_sm"},{"t":"p","html":"• Le choix de la technique dépend de l'indication, des comorbidités, des circonstances de survenue des lésions et de l'avis du patient.","style":"body_sm"},{"t":"p","html":"• Information et recherche du consentement, chaque fois que possible.","style":"body_sm"},{"t":"p","html":"• Neurostimulateur (recommandé pour les blocs distaux — poignet, chevilles) : maintenance et vérification avant chaque utilisation.","style":"body_sm"},{"t":"p","html":"• Installation confortable du patient ; règles d'asepsie strictement appliquées.","style":"body_sm"},{"t":"p","html":"• Procédures de sécurité contre les erreurs (conditionnements spécifiques, étiquetage des seringues).","style":"body_sm"},{"t":"p","html":"• Contact verbal maintenu pendant la réalisation de l'AL/ALR.","style":"body_sm"},{"t":"p","html":"• Aiguilles à biseau court recommandées.","style":"body_sm"},{"t":"p","html":"• Prévention de la toxicité systémique : connaissance/respect des doses maximales, dose la plus faible possible, test d'aspiration avant et répété pendant l'injection, injection lente et fractionnée, recherche de tachycardie/HTA pendant l'injection de solutions adrénalinées.","style":"body_sm"},{"t":"p","html":"• La recherche de paresthésie est fortement déconseillée.","style":"body_sm"},{"t":"p","html":"• Une douleur fulgurante pendant la procédure impose l'arrêt immédiat de l'injection.","style":"body_sm"},{"t":"p","html":"• Respect des délais d'installation de l'analgésie ; l'échec ne peut être envisagé qu'au-delà de ces délais (attention au risque de doses cumulées).","style":"body_sm"},{"t":"p","html":"• Traçabilité écrite complète (patient, techniques, agents, déroulement, événements, suivi) — une fiche spécifique peut être utilisée.","style":"body_sm"},{"t":"p","html":"• Chaîne de soins organisée : procédures communes avec les anesthésistes-réanimateurs, procédure d'appel d'un praticien en recours.","style":"body_sm"},{"t":"section","text":"4.3 Monitorage","color":"teal-dark"},{"t":"p","html":"Le monitorage cardiorespiratoire (scope, pression non invasive, SpO2) doit être disponible sans délai. Le choix des moyens de surveillance (installés avant le geste) dépend des doses d'anesthésique local, du type d'ALR, du geste (durée…), des comorbidités et de l'état du patient. En cas de sédation associée : voie veineuse périphérique et monitorage cardiorespiratoire d'emblée. Le matériel de réanimation pour la prise en charge des complications doit être immédiatement disponible, et le médecin formé à son utilisation.","style":"body_sm"},{"t":"section","text":"Question 4 — Particularités des AL/ALR en milieu difficile et chez l'enfant","color":"navy"},{"t":"p","html":"<b>Milieu difficile</b> (sauvetage individuel ou collectif — montagne, mer, transports en commun…) : les règles de sécurité et de formation des personnels sont particulièrement importantes. Problèmes spécifiques : conditions précaires d'évaluation et de réalisation (sécurité, hygiène, climat), durées de prise en charge, conséquences du relevage/transport, hypothermie, afflux massif de victimes ou inadéquation entre le nombre d'équipes médicales et le nombre de patients, impossibilité de monitorage. La nécessité d'une analgésie efficace et précoce ne doit pas être remise en question du seul fait que le milieu est difficile.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§Milieu diff.","style":"cell_b"},{"t":"p","html":"Toutes les techniques d'anesthésie locale préconisées dans ces recommandations peuvent être utilisées sous couvert des règles habituelles de sécurité — le bloc iliofascial doit être largement diffusé dans ce contexte, en particulier en cas d'afflux de victimes.","style":"cell"},{"t":"chip","label":"E"}],[{"t":"p","html":"§Milieu diff.","style":"cell_b"},{"t":"p","html":"Dans certains cas particuliers (patient incarcéré, victime en milieu périlleux…), une analgésie préalable par voie intraveineuse peut s'avérer nécessaire, mais ne contre-indique pas la réalisation ultérieure de l'ALR.","style":"cell"},{"t":"chip","label":"E"}]]},{"t":"p","html":"<b>5.1 Particularités chez l'enfant</b> — l'AL est régulièrement indiquée aux urgences (exploration/suture de plaie) ; les anesthésies tronculaires se limitent aux blocs fémoral/iliofascial (fractures de fémur) et aux blocs tronculaires au poignet (traumatologie de la main).","style":"h2"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"§5.1","style":"cell_b"},{"t":"p","html":"Chez l'enfant de moins d'un an, la pharmacologie des anesthésiques locaux diffère fondamentalement de l'adulte (immaturité des métabolismes hépatique et rénal, diminution de certaines protéines plasmatiques), majorant le risque d'accumulation et de toxicité ; seule la lidocaïne est recommandée, à dose rapportée au poids corporel.","style":"cell"},{"t":"chip","label":"D"}],[{"t":"p","html":"§5.1","style":"cell_b"},{"t":"p","html":"Comme chez l'adulte, le maintien du contact verbal est essentiel.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"§5.1","style":"cell_b"},{"t":"p","html":"Les solutions associant de la cocaïne aux anesthésiques locaux doivent être évitées en raison de leurs dangers.","style":"cell"},{"t":"chip","label":"D"}],[{"t":"p","html":"§5.1","style":"cell_b"},{"t":"p","html":"Le mélange équimoléculaire oxygène-protoxyde d'azote est utilisable chez l'enfant de plus de quatre ans, en respectant ses contre-indications habituelles.","style":"cell"},{"t":"chip","label":"C"}]]},{"t":"p","html":"<i>Pratique :</i> AL par Emla® ou infiltration (aiguille la plus fine possible) ; conditions de monitorage/accès veineux identiques à l'adulte. Une sédation est souvent nécessaire chez l'enfant — rechercher au préalable une hypovolémie pouvant se masquer en agitation isolée ; objectif de sédation consciente par titration.","style":"note"},{"t":"section","text":"Question 5 — Formation nécessaire","color":"teal-dark"},{"t":"p","html":"L'AL fait partie de la formation universitaire initiale du médecin. La pratique de techniques d'ALR par des médecins non anesthésistes-réanimateurs, dans le contexte de la médecine d'urgence, peut se concevoir à condition de respecter la réglementation et les recommandations de la SFAR, et après avoir bénéficié d'une formation reconnue, théorique et pratique, notamment au bloc opératoire. Cela implique :","style":"body_sm"},{"t":"p","html":"• Une formation théorique et pratique initiale encadrée par des médecins anesthésistes-réanimateurs.","style":"body_sm"},{"t":"p","html":"• Une formation médicale continue accréditée.","style":"body_sm"},{"t":"p","html":"• L'élaboration de procédures et de cahiers de protocoles, intégrés dans une approche globale du patient en situation d'urgence (soins préhospitaliers, SAU, bloc opératoire — sans interférer avec une technique d'anesthésie nécessaire à l'acte chirurgical).","style":"body_sm"},{"t":"p","html":"• La mise en place de ces protocoles et procédures.","style":"body_sm"},{"t":"p","html":"• La mise en place des moyens cliniques et biomédicaux de surveillance, de suppléance et de sécurité.","style":"body_sm"},{"t":"p","html":"• La vérification du matériel avant chaque usage.","style":"body_sm"},{"t":"p","html":"• La rédaction d'une fiche de surveillance (produits utilisés, variables de surveillance en fonction du temps).","style":"body_sm"},{"t":"p","html":"• Une information au patient (ou à défaut à l'accompagnant) sur la procédure utilisée et les consignes de surveillance en cas de sortie.","style":"body_sm"},{"t":"p","html":"• L'évaluation régulière des pratiques.","style":"body_sm"},{"t":"p","html":"Conformément aux règles déontologiques, les praticiens doivent connaître les indications et les contre-indications des anesthésiques locaux et des techniques, acquérir l'expérience de leur utilisation et disposer des moyens, en particulier de surveillance, pour les mettre en œuvre. Ces connaissances doivent être régulièrement actualisées.","style":"note"},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Pratique des anesthésies locales et locorégionales par des médecins non spécialisés en anesthésie-réanimation, dans le cadre des urgences » — Conférence d'experts, texte court, Société française d'anesthésie et de réanimation (SFAR), Samu de France, Société francophone de médecine d'urgence (SFMU), 2002. Publié Ann Fr Anesth Réanim 2004;23:167-176.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> conférence d'experts, grille EBM Niveaux de preuve I-V / Grades A-E — voir détail en page 1.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/wp-content/uploads/2016/01/2_AFAR_Pratique-des-anesthesies-locales-et-locoregionales-par-des-medecins-non-specialises-en-anesthesie-reanimation-dans-le-cadre-des-urgences.pdf","style":"source"},{"t":"p","html":"<b>Couverture :</b> intégralité des 34 énoncés gradés individuellement (Questions 1-5) et des 5 tableaux du texte source (niveaux de preuve, grades, toxicité neurologique, posologie des AL, gestion des complications) — voir convention de référencement §<i>sous-section</i> disclosée en page 1 (source non numérotée Rx.y).","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement — texte de 2002 :</b> cette fiche de synthèse indépendante reprend l'intégralité des recommandations du texte source, mais ne le remplace pas et n'est ni éditée ni validée par la SFAR. Se référer aux protocoles locaux du service d'urgence et au texte intégral (y compris ses références bibliographiques [1]-[11], non reprises ici) pour toute décision clinique.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/pratique-des-anesthesies-locales-et-locoregionales-par-des-medecins-non-specialises-en-anesthesie-reanimation/';

