update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2a_AFAR_Techniques-analgesiques-locoregionales-et-douleur-chronique.pdf' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'alr_douleur_chronique',
  card_json = $mgjson${"badge":"GRADE","title":"ALR et douleur chronique","short":"RFE SFAR 2013 (Ann Fr Anesth Réanim 32 (2013) 275-284) — première recommandation francophone sur la place des techniques d'analgésie locorégionale (ALR) dans la douleur chronique. Méthode GRADE standard. 43 énoncés au total sur 6 champs (médicaments, algies craniofaciales, douleurs abdomino-pelviennes, douleurs neuropathiques des membres [SDRC, amputation], douleurs cancéreuses, gestion des cathéters au long cours) : 33 recommandations réellement gradées (1+/1-/2+/2-/avis d'experts), 9 énoncés où la source déclare explicitement qu'aucune recommandation n'est possible faute de données (disclosed, distingués d'un grade négatif), et 1 énoncé permissif non gradé explicitement par la source. Pathologies rachidiennes explicitement exclues (objet d'une recommandation séparée multi-spécialités).","society":"SFAR","version":"2013","validated":"Recommandations Formalisées d'Experts, SFAR","methodology":"GRADE (qualité des preuves à 4 catégories, force forte/faible par vote Delphi) + avis d'experts + 9 énoncés « aucune recommandation possible » distincts d'un grade négatif (disclosed, voir fiche)","pages":10,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"alr_douleur_chronique","sections":[{"title":"Méthodologie & médicaments (R1)","items":[{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Résumé :</b> Recommandations Formalisées d'Experts SFAR (2013) sur la place des techniques d'analgésie locorégionale (ALR) dans la douleur chronique — aucune recommandation francophone n'existait auparavant sur ce sujet. Six champs : médicaments utilisés, algies craniofaciales, douleurs abdomino-pelviennes, douleurs neuropathiques des membres (SDRC, amputation), douleurs cancéreuses, gestion des cathéters au long cours. Pathologies rachidiennes explicitement exclues de cette RFE (objet d'une recommandation multi-spécialités séparée).","style":"body"}},{"t":"p","html":"Méthode GRADE — analyse systématique de la littérature (2001-2011) par 23 experts. Critère principal : amélioration fonctionnelle / qualité de vie (à défaut, niveau de douleur et consommation d'antalgiques). La littérature sur l'ALR en douleur chronique est globalement de faible niveau méthodologique — la force des recommandations est donc très variable selon le thème.","style":"body_sm"},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"chip","label":"1-"},{"t":"chip","label":"2+"},{"t":"chip","label":"2-"},{"t":"chip","label":"AE"},{"t":"chip","label":"0/"},{"t":"chip","label":"NG"},{"t":"p","html":"<b>GRADE</b> — 1+/1- : forte (« il faut »/« il ne faut pas ») ; 2+/2- : faible (« il est possible »/« il n'est pas recommandé ») ; <b>AE</b> : avis d'experts (vraie recommandation, sans évaluation quantifiée) ; <b>0/</b> : la source déclare explicitement qu'<b>aucune recommandation n'est possible</b> faute de données (n'est PAS un grade négatif) ; <b>NG</b> : énoncé permissif de la source sans grade ni avis d'experts explicitement accolé (1 occurrence, disclosed).","style":"badge_head"}]]},{"t":"section","text":"R1 — Médicaments utilisés en ALR pour douleur chronique","color":"navy"},{"t":"p","html":"<b>Voie périmédullaire et intrathécale</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Traiter des douleurs prolongées non cancéreuses réfractaires aux traitements antalgiques conventionnels bien conduits, ou en cas d'intolérance/absence d'alternative, par administration continue intrathécale ou péridurale d'anesthésique local (aucun anesthésique local privilégié par la littérature).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Ne pas utiliser la kétamine ni le midazolam par voie périmédullaire, en raison de l'absence de données toxicologiques.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Clonidine par voie périmédullaire : en l'absence de données, aucune recommandation n'est possible.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Utiliser la morphine en administration intrathécale chez des patients douloureux chroniques, en cas d'échec des thérapies conventionnelles après sélection rigoureuse.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Ne pas réaliser d'injection péridurale de corticoïdes pour douleur post-zostérienne.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Réaliser une injection péridurale de corticoïdes en cas de radiculalgie résistante au traitement médical et physiothérapique bien conduit, pour un soulagement à court terme (réitérable si le patient est répondeur).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Utiliser le ziconotide par voie intrathécale en première intention dans les douleurs chroniques réfractaires, notamment à composante neuropathique prédominante — titration lente, dose initiale faible (1 mg/j) ; association à la morphine possible.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"<b>Voie périnerveuse / ALR intraveineuse (ALRIV)</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Blocs sympathiques par administration répétée d'anesthésiques locaux, en douleur chronique non-SDRC (adulte et enfant) : en l'absence de données, aucune recommandation n'est possible.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Blocs somatiques par administration intermittente d'anesthésiques locaux, en douleur chronique non-SDRC (adulte et enfant) : en l'absence de données, aucune recommandation n'est possible.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Ne pas utiliser corticoïdes ni morphiniques lors d'un bloc nerveux périphérique (somatique ou sympathique) en douleur chronique, adulte et enfant (absence d'efficacité démontrée).","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Utiliser une injection locale de corticoïdes en cas de canal carpien symptomatique.","style":"cell"},{"t":"chip","label":"2+"}]]}]},{"title":"Algies craniofaciales & douleurs abdomino-pelviennes (R2-R3)","items":[{"t":"section","text":"R2 — Algies craniofaciales","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Ne pas faire de bloc du nerf grand occipital (GNO) en cas de céphalées quotidiennes chroniques ne répondant pas au traitement médical — possible toutefois en dernier recours après échec de tous les traitements bien conduits (avis d'experts), maximum 4 blocs itératifs aux anesthésiques locaux.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Bloc du GNO dans la céphalée de tension : en l'absence de données, aucune recommandation n'est possible.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Réaliser un blood-patch (injection péridurale de sang autologue) en cas de céphalées secondaires à une hypotension intracrânienne (primaire ou secondaire) ne répondant pas au traitement médical — plusieurs blood-patches possibles (jusqu'à 4).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Faire un bloc du GNO en cas de céphalées secondaires à une hypotension intracrânienne iatrogène ne répondant pas à l'algorithme proposé, ou en cas de contre-indication au blood-patch — énoncé par la source sans grade ni avis d'experts explicitement accolé (disclosed, voir méthodologie).","style":"cell"},{"t":"chip","label":"NG"}],[{"t":"p","html":"Réaliser un bloc du GNO (nerf d'Arnold) en cas de céphalées cervicogéniques.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Réaliser un bloc du GNO (nerf d'Arnold) en cas d'algie vasculaire de la face ne répondant pas aux traitements spécifiques bien conduits.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Blocs sphéno-palatins dans l'algie vasculaire de la face rebelle aux traitements validés (oxygénothérapie, sumatriptan, vérapamil) ou mal tolérés : en l'absence de données, aucune recommandation n'est possible.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Réaliser un bloc d'une ou plusieurs branches terminales du nerf trijumeau (V1/V2/V3) dans la névralgie de la face rebelle à la carbamazépine ou mal tolérée.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"R3 — Douleurs abdomino-pelviennes","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"En cas de douleur pelvi-périnéale chronique, pratiquer à titre diagnostique des infiltrations d'anesthésiques locaux sur le système somatique et sympathique pelvien, avec une technique de repérage adaptée et fiable, associée à une prise en charge globale.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Infiltrations à visée thérapeutique (et non diagnostique) sur le système nerveux somatique ou sympathique pelvien : en l'absence de données, aucune recommandation n'est possible.","style":"cell"},{"t":"chip","label":"0/"}]]}]},{"title":"Douleurs neuropathiques des membres (R4)","items":[{"t":"section","text":"R4 — Douleurs neuropathiques des membres","color":"navy"},{"t":"p","html":"<b>Syndrome douloureux régional complexe (SDRC)</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Répéter un bloc sympathique avec anesthésiques locaux dans le traitement d'un SDRC, si le bénéfice analgésique et fonctionnel a été testé et persiste en cours de traitement (aucune recommandation possible sur le choix de l'anesthésique local, le rythme ou le nombre de blocs, faute de données).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Ne pas pratiquer de bloc locorégional intraveineux (ALRIV), quel que soit l'agent médicamenteux, pour le traitement d'un SDRC.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Réaliser une analgésie locorégionale continue par cathéter périnerveux pour le traitement des SDRC, en cas d'échec des autres traitements.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Traiter un SDRC avec une ALR centrale ou périphérique chez l'enfant, en cas de résistance aux traitements systémiques conventionnels bien menés.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Pratiquer des blocs itératifs du ganglion stellaire pour le traitement des SDRC du membre supérieur chez les patients répondeurs (aucune recommandation possible sur le rythme ou le nombre de blocs).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Pratiquer des blocs sensitivo-moteurs continus par cathéters pour faciliter la rééducation fonctionnelle, en cas de résistance aux traitements systémiques bien conduits et aux traitements par blocs sympathiques.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Toujours associer aux blocs sympathiques et/ou sensitivo-moteurs des traitements adaptés intensifs de rééducation fonctionnelle lors du traitement des CRPS des membres.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Mettre en place une stimulation médullaire lors du traitement des CRPS des membres, en cas de résistance à la kinésithérapie, aux traitements systémiques bien conduits et aux traitements par blocs sympathiques (aucune recommandation possible sur le choix chirurgical ou percutané de la technique de pose).","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"<b>Amputation</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Réaliser une analgésie locorégionale chez les patients amputés (adultes et enfants) — procure une analgésie postopératoire de qualité et diminue l'incidence des douleurs du moignon.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Les données actuelles ne permettent pas de privilégier une modalité d'ALR à une autre (analgésie périmédullaire, bloc tronculaire ou plexique) ; privilégier toutefois les blocs analgésiques périphériques, en raison de l'absence d'effets secondaires généraux (notamment hémodynamiques) par rapport aux blocs périmédullaires.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Douleurs cancéreuses, cathéters au long cours & sources (R5-R6)","items":[{"t":"section","text":"R5 — Douleurs cancéreuses","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Réaliser précocement un bloc neurolytique splanchnique ou du plexus cœliaque chez les patients porteurs d'un cancer du pancréas, pour réduire la douleur, la consommation de morphiniques et leurs effets indésirables.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Réaliser un bloc neurolytique du plexus hypogastrique chez les patients présentant des douleurs importantes en rapport avec un cancer du petit bassin.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Autres blocs neurolytiques (impar, lombaire, thoracique) chez le patient cancéreux : en l'absence de données, aucune recommandation n'est possible.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Réaliser une analgésie intrathécale dans les douleurs chroniques cancéreuses réfractaires malgré un traitement antalgique bien conduit selon les recommandations de l'OMS, et chez les patients ayant des effets indésirables graves aux traitements antalgiques.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Analgésie péridurale dans la douleur chronique cancéreuse réfractaire : sauf symptomatologie localisée chez un patient à espérance de vie courte, aucune recommandation n'est possible.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Ne pas utiliser de cathéters externalisés.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Mettre en place une pompe implantée, si la survie du patient est estimée à au moins trois mois.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"La morphine est le traitement de référence par voie intrathécale ; les anesthésiques locaux, la clonidine et le ziconotide peuvent être utilisés en association.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Chez l'enfant atteint de cancer, traiter des douleurs prolongées réfractaires aux traitements antalgiques conventionnels bien conduits (ou en cas d'intolérance), par des techniques d'ALR centrales ou périphériques adaptées au type de douleur.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"section","text":"R6 — Gestion des cathéters d'ALR au long cours","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Durée, intérêt des fenêtres thérapeutiques, mode de sevrage d'un cathéter locorégional au long cours : en l'absence de données, aucune recommandation n'est possible.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Envisager le recours à l'analgésie péridurale dès lors que l'administration de produit analgésique prévisible est inférieure à trois mois — le cathéter peut alors être tunnélisé et relié à distance à un site sous-cutané et une pompe programmable.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Ne pas utiliser de cathéter péridural au-delà de trois mois, en raison du risque de cloisonnement et du risque infectieux — un cathéter intrathécal relié à un dispositif totalement implantable peut alors être mis en place.","style":"cell"},{"t":"chip","label":"2-"}]]},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Techniques analgésiques locorégionales et douleur chronique » — Recommandations Formalisées d'Experts (RFE), Société française d'anesthésie et de réanimation (SFAR). Auteurs : H. Beloeil (Rennes, auteur correspondant), É. Viel (Nîmes), M.-L. Navez (Saint-Étienne), D. Fletcher (Garches), D. Peronnet (Mâcon). Groupe de travail : A. Muller, E. Bures, P. Martin, P. Rault, F. Adam, I. Nègre, D. Dupoiron, J.-M. Pellat, P. Zetlaoui, C. Dadure, F. Veyckemans, P. Marec-Berard, T. Riant, C. Baude, J.-P. Estèbe, A. Belbachir, V. Martinez.","style":"source"},{"t":"p","html":"<b>Version :</b> Ann Fr Anesth Réanim 32 (2013) 275-284. doi:10.1016/j.annfar.2013.02.021.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> GRADE standard (qualité des preuves à 4 catégories, force forte/faible par vote Delphi) — voir légende en page 1 pour les 2 catégories supplémentaires disclosed (« 0/ » : aucune recommandation possible ; « NG » : énoncé non gradé explicitement, 1 occurrence).","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/wp-content/uploads/2015/10/2a_AFAR_Techniques-analgesiques-locoregionales-et-douleur-chronique.pdf","style":"source"},{"t":"p","html":"<b>Couverture :</b> intégralité des 33 recommandations réellement gradées + les 9 énoncés « aucune recommandation possible » + le 1 énoncé non gradé (43 au total), sur les 6 champs de la RFE. Pathologies rachidiennes explicitement exclues par la source elle-même (objet d'une recommandation séparée multi-spécialités). Argumentaire scientifique (études, pourcentages, méta-analyses) volontairement non transcrit au-delà des éléments qui changent la pratique. Annexes (tableaux d'analyse de la littérature, non publiées dans le texte mais sur sfar.org) non couvertes par cette fiche.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement — document de 2013 :</b> cette fiche de synthèse indépendante reprend l'intégralité des recommandations et énoncés du texte source, mais ne le remplace pas et n'est ni éditée ni validée par la SFAR. Les pratiques et disponibilités thérapeutiques (ex. ziconotide) ayant pu évoluer depuis 2013, se référer à un avis spécialisé et aux recommandations actualisées avant toute décision.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2a_AFAR_Techniques-analgesiques-locoregionales-et-douleur-chronique.pdf';

insert into public.documents (title, doc_type, publication_date, source_url, original_language)
values ('Prévention des infections nosocomiales en réanimation – transmission croisée et nouveau-né exclus', 'CC', '2009-01-01', 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Prevention-des-infections-nosocomiales-en-reanimation-transmission-croisee-et-nouveau-ne-exclus.pdf', 'non_renseigne')
