update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Prevention-des-infections-nosocomiales-en-reanimation-transmission-croisee-et-nouveau-ne-exclus.pdf' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'infections_nosocomiales_rea',
  card_json = $mgjson${"badge":"Sans cotation","title":"Prévention des infections nosocomiales en réanimation","short":"5e Conférence de Consensus SFAR/SRLF (2008/2009) — transmission croisée et nouveau-né explicitement exclus du champ. Le texte s'inspire de GRADE mais n'imprime jamais de symbole : force portée par la locution verbale elle-même (« il faut »/« il faut probablement »), transcrite ici en chips 1+/1-/2+/2- (correspondance explicitement énoncée par la source) + un chip « 0/ » pour les 3 énoncés où le jury déclare explicitement ne pouvoir se prononcer faute de données. Cinq questions : épidémiologie et définitions (critères diagnostiques CTINILS des pneumopathies, infections urinaires, bactériémies, ILC, ISO ; épidémiologie REA Raisin 2006), organisation architecturale, impact de l'antibiothérapie (désescalade, durée, rotation/mélange), préventions spécifiques (PAVM, infection urinaire, cathéters, site opératoire, Clostridium difficile), stratégie globale.","society":"SFAR / SRLF","version":"2008 (en ligne 2009)","validated":"5e Conférence de Consensus, Président du jury : J. Duranteau","methodology":"Inspirée de GRADE, formulée en locutions verbales plutôt qu'en symboles imprimés — voir légende dans la fiche","pages":9,"section":"Réanimation"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"infections_nosocomiales_rea","sections":[{"title":"Épidémiologie, définitions & organisation architecturale (Q1-Q2)","items":[{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Résumé :</b> 5e Conférence de Consensus SFAR/SRLF (2008/2009) sur la prévention des infections nosocomiales (IN) en réanimation adulte et pédiatrique — transmission croisée et nouveau-né explicitement exclus du champ (traités par d'autres textes). Cinq questions : épidémiologie et définitions, organisation architecturale, impact de l'antibiothérapie, préventions spécifiques (poumon, cathéter, urine, site opératoire, autres), stratégie globale.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"chip","label":"1-"},{"t":"chip","label":"2+"},{"t":"chip","label":"2-"},{"t":"chip","label":"0/"},{"t":"p","html":"<b>Force</b> — cette conférence de consensus n'imprime jamais de symbole GRADE ; les chips ci-dessous sont une transcription directe des locutions du texte, que la source associe elle-même à la distinction GRADE forte/faible. <b>1+</b> = « il faut »/recommandé (fort, positif) ; <b>1-</b> = « il ne faut pas »/non recommandé (fort, négatif) ; <b>2+</b> = « il faut probablement » (faible, positif) ; <b>2-</b> = « il ne faut (probablement) pas » (faible, négatif) ; <b>0/</b> = le jury déclare explicitement qu'aucune position n'est possible (absence de donnée) — n'est PAS un grade négatif.","style":"badge_head"}]]},{"t":"section","text":"Q1 — Épidémiologie et définitions","color":"navy"},{"t":"p","html":"Une infection nosocomiale (IN) en réanimation se définit comme une infection contractée en réanimation, absente et non en incubation à l'admission, avec un délai d'au moins 48h entre l'admission et l'état infectieux. En 2006, prévalence France IN réa adulte : 22,4 % (InVS) ; taux d'attaque global 15 % (réseau REA Raisin). Les pneumopathies nosocomiales sont les IN les plus fréquentes chez l'adulte.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"Surveiller la survenue des IN dans les unités de réanimation (taux d'attaque, taux d'incidence, écologie bactérienne).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Pour les IN prises en compte par les réseaux français (pneumopathies, infections urinaires, bactériémies, infections liées aux cathéters), utiliser les critères diagnostiques du CTINILS, compatibles avec le réseau européen HELICS ICU.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"<b>Critères diagnostiques clés</b> (Encadrés 1-5 de la source, condensés — seuils numériques préservés verbatim)","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Type","style":"head_w"},{"t":"p","html":"Critères / seuils clés","style":"head_w"}],[{"t":"p","html":"Pneumopathie","style":"cell_b"},{"t":"p","html":"Signes radiologiques + fièvre >38°C ou leucopénie (<4000/mm³)/hyperleucocytose (>12 000/mm³) + signes respiratoires. Documentation microbiologique fortement recommandée : LBA >10<super>4</super> UFC/mL, brosse de Wimberley >10<super>3</super> UFC/mL, PDP >10<super>3</super> UFC/mL (cas 1) ; bactériologie quantitative sécrétions bronchiques >10<super>6</super> UFC/mL sans ATB antérieure (cas 2) ; méthodes alternatives — hémocultures, culture pleurale, histologie (cas 3). Cas 4/5 (sans critère quantitatif ou microbiologique) = pneumonie possible/clinique.","style":"cell"}],[{"t":"p","html":"Infection urinaire","style":"cell_b"},{"t":"p","html":"Signe clinique (fièvre >38°C, impériosité, pollakiurie, brûlure mictionnelle, douleur sus-pubienne) + sans sondage : leucocyturie ≥10<super>4</super>/mL et uroculture ≥10<super>3</super> microorg./mL (≤2 espèces) ; avec sondage (en cours ou <7j) : uroculture ≥10<super>5</super> microorg./mL (≤2 espèces).","style":"cell"}],[{"t":"p","html":"Bactériémie","style":"cell_b"},{"t":"p","html":"Au moins 1 hémoculture positive justifiée cliniquement ; pour les germes saprophytes/commensaux (staph. coagulase-négative, Bacillus spp., Corynebacterium spp., etc.), 2 hémocultures positives au même germe, prélevées à des moments différents (délai max 48h).","style":"cell"}],[{"t":"p","html":"Infection liée au cathéter (ILC)","style":"cell_b"},{"t":"p","html":"CVC : bactériémie/fongémie dans les 48h encadrant le retrait + culture positive du site/CVC ≥10<super>3</super> UFC/mL, ou hémocultures centrale/périphérique positives au même germe (ratio >5 ou délai différentiel >2h). Sans bactériémie : culture CVC ≥10<super>3</super> UFC/mL + purulence de l'orifice (ILC locale) ou régression des signes généraux sous 48h après ablation (ILC générale).","style":"cell"}],[{"t":"p","html":"Infection du site opératoire (ISO)","style":"cell_b"},{"t":"p","html":"Superficielle : dans les 30 jours, écoulement purulent, ou germe + polynucléaires à l'examen direct, ou ouverture par le chirurgien + signe inflammatoire. Profonde : dans les 30 jours (1 an si implant/prothèse), écoulement purulent d'un drain sous-aponévrotique, ou déhiscence/ouverture + fièvre >38°C ou douleur localisée, avec documentation microbiologique.","style":"cell"}]]},{"t":"p","html":"<b>Tableau 1 — Épidémiologie descriptive des IN en réanimation adulte</b> (réseau REA Raisin 2006, taux pour 100 patients ou 1000 jours d'exposition, reproduit verbatim).","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Indicateur","style":"head_w_c"},{"t":"p","html":"Pneumonies","style":"head_w_c"},{"t":"p","html":"IU","style":"head_w_c"},{"t":"p","html":"Bactériémies","style":"head_w_c"},{"t":"p","html":"ILC (CVC)","style":"head_w_c"}],[{"t":"p","html":"Incidence globale / 100 patients","style":"cell_b"},{"t":"p","html":"8,52","style":"cell_c"},{"t":"p","html":"6,46","style":"cell_c"},{"t":"p","html":"3,42","style":"cell_c"},{"t":"p","html":"1,30","style":"cell_c"}],[{"t":"p","html":"Attaque spécifique / 100 patients exposés","style":"cell_b"},{"t":"p","html":"13,49","style":"cell_c"},{"t":"p","html":"7,82","style":"cell_c"},{"t":"p","html":"3,42","style":"cell_c"},{"t":"p","html":"2,18","style":"cell_c"}],[{"t":"p","html":"Incidence / 1000 jours d'exposition","style":"cell_b"},{"t":"p","html":"16,17","style":"cell_c"},{"t":"p","html":"7,94","style":"cell_c"},{"t":"p","html":"3,27","style":"cell_c"},{"t":"p","html":"1,86","style":"cell_c"}]]},{"t":"section","text":"Q2 — Organisation architecturale","color":"navy"},{"t":"p","html":"Question centrée sur le lien entre architecture et prévention des IN (circulaire DHOS/SDO n°2003/413 du 27 août 2003).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"Répartir les lits en sous-unités, pour une meilleure sectorisation des patients et professionnels en cas d'épidémie.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Prévoir des chambres individuelles d'au moins 20 m² (lien avec la prévention des IN non formellement démontré, mais recommandé par le Jury dans le cadre d'une stratégie globale).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Un seul point d'eau par chambre est probablement suffisant (la qualité d'eau recommandée étant identique pour l'hygiène des mains et la toilette du patient) — le Jury nuance ainsi la circulaire qui en recommande deux.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Le point d'eau doit être équipé d'une vasque large et profonde, de forme arrondie et sans aspérité, dépourvue de trop-plein, avec une commande autre que manuelle et un col de cygne démontable fixé au mur ; le matériau des surfaces doit répondre aux textes réglementaires.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Ne pas recommander de filtre antibactérien sur le point d'eau si la qualité de l'eau est maîtrisée.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Une porte à commande autre que manuelle est souhaitable, en tenant compte des conséquences pour le patient (sécurité, isolement).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"À l'occasion d'une restructuration, prévoir un traitement d'air adapté : patients à haut risque aspergillaire — surpression 15 Pa, ≥20 volumes d'air/heure, filtre HEPA (ou système portable à défaut) ; patients à risque aéroporté — dépression 2,5 Pa, ~12 volumes/heure, extraction directe vers l'extérieur.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Utiliser de l'eau stérile pour toutes les situations de soins à risque ; réserver l'eau chaude sanitaire à la toilette, au nettoyage du matériel et à l'entretien des locaux.","style":"cell"},{"t":"chip","label":"1+"}]]}]},{"title":"Antibiothérapie, PAVM & infection urinaire (Q3-Q4)","items":[{"t":"section","text":"Q3 — Impact de l'antibiothérapie sur la prévention des IN","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"Appliquer la désescalade antibiotique (réévaluation systématique entre H24 et H72 selon les résultats microbiologiques) pour prévenir l'émergence de germes résistants.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Appliquer également la désescalade pour prévenir les IN elles-mêmes ; si l'infection n'est pas confirmée, interrompre l'antibiothérapie plutôt que la maintenir.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Pour les PAVM, réduire la durée de traitement antibiotique de 15 à 8 jours, en dehors des infections à bacilles Gram négatif non fermentants (Pseudomonas, Acinetobacter, Stenotrophomonas).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"En contexte épidémique, mettre en place une politique restrictive d'utilisation des antibiotiques, avec séniorisation de la prescription et collaboration avec un référent en antibiothérapie.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Ne pas recommander la rotation programmée (cycling) des antibiotiques en usage courant, en raison du risque d'émergence de résistance.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"En situation épidémique, utiliser probablement la rotation en cycles courts d'un mois maximum.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Le mélange programmé (mixing) d'antibiothérapie sur patients consécutifs : le jury ne peut se prononcer sur son intérêt dans la prévention des IN (données actuelles insuffisantes).","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Mettre en place une stratégie de rationalisation de l'antibiothérapie (désescalade, durée, gestion des épidémies à BMR) — réduit l'émergence de résistances, la survenue d'IN et le coût du traitement. Recommandations identiques chez l'enfant.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"section","text":"Q4 — Préventions spécifiques : infections pulmonaires (PAVM)","color":"navy"},{"t":"p","html":"PAVM précoces (≤5 jours d'intubation, germes communautaires) vs. tardives (>5 jours, flore hospitalière).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"Ne pas recommander l'antibioprophylaxie systématique après l'intubation (diminue les PAVM précoces mais sans effet sur la mortalité, les PAVM tardives ou la durée de ventilation).","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"Recommander probablement la décontamination naso- et oropharyngée par solution antiseptique (rapport bénéfice/risque favorable).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Ne pas recommander l'utilisation d'un antibiotique local (seul ou associé à l'antiseptique) — efficacité non démontrée.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"La décontamination digestive sélective (DDS) associée à une antibiothérapie systémique peut probablement être recommandée (diminue PAVM et mortalité) ; ne pas la recommander dans les unités à forte prévalence de SARM ou entérocoques résistants à la vancomycine (surveillance renforcée de l'écologie bactérienne requise).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Chez l'enfant, la DDS seule ne peut pas être recommandée (efficacité non prouvée).","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Ne pas recommander l'antibiothérapie inhalée/en instillation trachéale, ni les peptides antimicrobiens, dans la prévention des PAVM.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Utiliser un algorithme de sédation-analgésie pour réduire la durée de ventilation mécanique (adulte et enfant) ; une procédure prévenant les extubations non programmées est recommandée.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Privilégier la ventilation non invasive dans ses indications reconnues (bénéfice sur l'incidence des PAVM, notamment chez le patient BPCO).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Utiliser probablement l'intubation orotrachéale plutôt que nasotrachéale pour diminuer la survenue de sinusites (lien non formellement démontré).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Chez le nourrisson (sinus maxillaires non pneumatisés avant 6-8 ans, et la voie orale augmente le risque de micro-inhalations et d'extubation accidentelle), l'intubation nasotrachéale doit être recommandée.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Maintenir la pression du ballonnet des sondes entre 25 et 30 cmH2O, pour limiter les micro-inhalations tout en préservant la muqueuse trachéale (20-25 cmH2O chez l'enfant avec sonde à ballonnet).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Chez l'enfant, utiliser probablement des sondes à ballonnet (protection possible contre les micro-inhalations, sans majoration du risque d'œdème sous-glottique) ; l'aspiration sous-glottique n'est pas applicable en dessous de 10 ans faute de dispositif adapté.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Privilégier une sonde d'intubation à aspiration sous-glottique (réduit probablement l'incidence des PAVM précoces), en aspiration discontinue plutôt que continue.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Éviter le décubitus dorsal strict sauf indication particulière ; privilégier une position proclive d'au moins 30°.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Ne pas recommander le système clos d'aspiration trachéale dans le seul objectif de prévenir les PAVM.","style":"cell"},{"t":"chip","label":"1-"}]]},{"t":"p","html":"<i>Sans effet démontré sur l'incidence des PAVM (ni recommandés ni déconseillés pour cet objectif précis) : sondes imprégnées d'antiseptiques, trachéotomie précoce, lit rotatif, systèmes d'humidification des gaz inspirés, décubitus ventral, nutrition entérale ; la prévention anti-ulcéreuse n'augmente pas l'incidence des PAVM.</i>","style":"note"},{"t":"section","text":"Q4 — Infection urinaire","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"Ne pas rechercher systématiquement une bactériurie chez les patients asymptomatiques porteurs d'un cathéter vésical.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"En cas de bactériurie asymptomatique, ne pas changer systématiquement la sonde urinaire (risque de bactériémie) ; peu d'arguments pour une antibiothérapie systémique lors d'un changement de sonde.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Discuter systématiquement l'indication du sondage urinaire et en limiter la durée au strict nécessaire (évaluation quotidienne).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Ne pas recommander l'utilisation de sondes imprégnées (antiseptiques, antibiotiques, argent) — aucune efficacité supérieure démontrée ; aucun système de drainage fermé complexe n'a montré de supériorité sur un système semi-ouvert.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Ne pas recommander l'irrigation vésicale par antibiotique/antiseptique ni l'adjonction d'un antimicrobien dans le système clos.","style":"cell"},{"t":"chip","label":"1-"}]]}]},{"title":"Cathéters, site opératoire, C. difficile, stratégie globale & sources (Q4-Q5)","items":[{"t":"section","text":"Q4 — Infections liées aux cathéters (ILC)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"Ne pas recommander l'utilisation systématique de cathéters imprégnés d'antiseptiques/antibiotiques (coût élevé, risque de sélection de BMR/levures) ; ils peuvent trouver leur indication dans les unités où l'incidence d'ILC reste élevée malgré les autres mesures.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Utiliser une solution antiseptique alcoolique (chlorhexidine ou povidone iodée) pour la préparation cutanée ; proscrire les solutions aqueuses.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Insérer les cathéters en territoire cave supérieur plutôt qu'inférieur (risque accru d'ILC en territoire cave inférieur) ; encadrer ce geste par un médecin expérimenté.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Ne pas refaire le pansement plus d'une fois toutes les 72 heures, sauf souillure ou perte d'étanchéité ; les lignes de perfusion peuvent n'être changées que tous les 3-4 jours ; changer les tubulures après chaque transfusion ou quotidiennement lors de perfusion d'émulsions lipidiques.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Ne pas recommander (efficacité non démontrée) : antibioprophylaxie à l'insertion, pommade antibiotique, filtres antibactériens, boîtiers protecteurs, changement systématique du cathéter à intervalle régulier.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Chez l'enfant, les données sont insuffisantes pour recommander la tunnélisation systématique des cathéters fémoraux (réduit la colonisation mais pas les infections), ni l'utilisation de patch cutané à la chlorhexidine (dermites rapportées).","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Chez l'enfant de moins de 30 mois, utiliser la chlorhexidine alcoolique (povidone iodée répétée contre-indiquée, risque d'hypothyroïdie).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Ne pas recommander les verrous antibiotiques ni l'imprégnation antibiotique systématique des cathéters.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"Il n'y a pas de preuve qu'une prophylaxie antithrombotique prévienne la survenue d'ILC (le jury ne peut se prononcer sur les cathéters imprégnés d'héparine, données insuffisantes).","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Recommander le site radial pour les cathéters artériels (études observationnelles).","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"section","text":"Q4 — Infection du site opératoire (ISO) & autres","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"Antibioprophylaxie périopératoire, patient communautaire admis en réanimation pour être opéré : respecter les règles habituelles.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Antibioprophylaxie périopératoire, patient déjà hospitalisé et devant être opéré : tenir probablement compte de l'écologie bactérienne de l'unité et/ou de la colonisation du patient.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Antibioprophylaxie périopératoire, patient déjà sous antibiothérapie et devant être opéré : poursuivre l'antibiothérapie en cours (l'antibioprophylaxie devrait tenir compte du traitement en cours, du site opéré et de l'écologie bactérienne de l'unité).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Le contrôle glycémique peut probablement être recommandé pour prévenir les ISO en chirurgie cardiaque spécifiquement (données insuffisantes pour les autres mesures en réanimation : décontamination naso-oropharyngée, type de pansement, oxygénothérapie, contrôle de la température).","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"p","html":"<b>Infection digestive à Clostridium difficile</b> — diarrhée ou mégacolon toxique sans autre cause, avec toxine A/B dans les selles ou colite pseudomembraneuse ; incidence faible (<5 %), favorisée par clindamycine, céphalosporines, fluoroquinolones.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"Éradiquer les spores par désinfection du matériel et nettoyage des surfaces par solutions chlorées ; le lavage des mains au savon doux reste nécessaire (les solutions hydroalcooliques n'éliminent pas les spores).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Ne pas traiter de façon préventive les patients sous antibiotiques ou porteurs asymptomatiques.","style":"cell"},{"t":"chip","label":"1-"}]]},{"t":"p","html":"<i>Chez l'enfant, les colites à C. difficile sont exceptionnelles — la majorité des IN digestives pédiatriques est due au Rotavirus, dont les seules mesures préventives sont celles de la transmission croisée (hors champ de cette conférence).</i>","style":"note"},{"t":"section","text":"Q5 — Stratégie globale","color":"navy"},{"t":"p","html":"Le respect du ratio réglementaire des effectifs soignants est un prérequis fondamental à toute stratégie de prévention.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"Utiliser une stratégie globale de prévention des ILC et des PAVM (adulte et enfant) — combine surveillance épidémiologique, programme d'éducation multidisciplinaire, mesures générales et spécifiques.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Généraliser probablement cette stratégie globale aux autres IN (infection urinaire, ISO), malgré l'absence de données spécifiques les concernant.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Intégrer un réseau régional ou national de surveillance des IN.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Mettre en place un programme de formation et d'éducation de tous les acteurs de soin aux règles d'hygiène et procédures spécifiques, avec pratiques standardisées et diffusées à l'ensemble des équipes.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Respecter les bonnes pratiques d'hygiène hospitalière de base (asepsie, port de gants, lavage des mains), associées à des précautions additionnelles selon le contexte (isolement, masque) ; limiter l'exposition aux dispositifs invasifs par évaluation quotidienne de leur indication.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"Le contrôle glycémique permet probablement de limiter la survenue d'IN, dans le cadre d'une politique de bon usage des antibiotiques (restriction, désescalade, limitation des durées).","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Prévention des infections nosocomiales en réanimation (transmission croisée et nouveau-né exclus) » — 5e Conférence de Consensus, SFAR/SRLF, jeudi 20 novembre 2008. Président du jury : J. Duranteau (Le Kremlin-Bicêtre). Membres du jury : R. Amathieu, C. Guérin, P. Guiot, C. Guitton, C. Ichai, N. Kermarrec, C. Lejus, F. Lesage, J. Mantz, P.-F. Perrigault, C. Schwebel, M. Sirodot. Comité d'organisation : E. L'Her (président).","style":"source"},{"t":"p","html":"<b>Version :</b> Ann Fr Anesth Réanim 28 (2009) 912-920, en ligne le 31/10/2009. doi:10.1016/j.annfar.2009.09.007.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> inspirée de GRADE, formulée en locutions verbales (« il faut »/« il faut probablement ») plutôt qu'en symboles imprimés — voir légende en page 1.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Prevention-des-infections-nosocomiales-en-reanimation-transmission-croisee-et-nouveau-ne-exclus.pdf","style":"source"},{"t":"p","html":"<b>Couverture :</b> intégralité des recommandations des 5 questions. Transmission croisée et nouveau-né explicitement exclus du champ par la source elle-même (traités par d'autres textes). Encadrés diagnostiques condensés en tableaux de référence (seuils numériques préservés) plutôt que retranscrits en prose intégrale.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement — document de 2008/2009 :</b> cette fiche de synthèse indépendante reprend l'intégralité des recommandations du texte source, mais ne le remplace pas et n'est ni éditée ni validée par la SFAR/SRLF. Les pratiques de prévention des infections nosocomiales ayant pu évoluer depuis 2009, se référer à un avis spécialisé et aux recommandations actualisées avant toute décision.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Prevention-des-infections-nosocomiales-en-reanimation-transmission-croisee-et-nouveau-ne-exclus.pdf';

insert into public.documents (title, doc_type, publication_date, source_url, original_language)
values ('Recommandations de bonnes pratiques cliniques sur la nutrition périopératoire', 'RFE', '2011-01-01', 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Nutrition-artificielle-perioperatoire-en-chirurgie-programmee-de-ladulte.pdf', 'non_renseigne')
on conflict (source_url) do nothing;
insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Nutrition-artificielle-perioperatoire-en-chirurgie-programmee-de-ladulte.pdf' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Nutrition-artificielle-perioperatoire-en-chirurgie-programmee-de-ladulte.pdf' and s.acronym in ('SFAR', 'SFNEP')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Nutrition-artificielle-perioperatoire-en-chirurgie-programmee-de-ladulte.pdf' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'nutrition_perioperatoire',
  card_json = $mgjson${"badge":"Avis d'experts","title":"Nutrition périopératoire (chirurgie programmée)","short":"Actualisation 2010 SFAR/SFNEP de la Conférence de Consensus 1994 sur la nutrition artificielle périopératoire — étendue à la prise en charge nutritionnelle globale (orale + assistance) de l'adulte en chirurgie programmée. Distinct de la fiche « Nutrition artificielle en réanimation » (SFAR/SRLF/SFNEP RFE 2014, patients de réanimation). Méthode avis d'experts non formalisée, rédigée selon les déclinaisons de force Sfar/GRADE (fort/faible) explicitement définies par la source. 71 recommandations numérotées (R1-R71) sur 6 champs : évaluation de l'état nutritionnel (facteurs de risque, seuils diagnostiques de dénutrition, grade nutritionnel GN1-4), nutrition pré- et postopératoire, pharmaconutrition (immunonutrition, glutamine, oméga-3), obésité et chirurgie (dont bariatrique), diabète. Tableaux 3-6 (protocoles croisés GN × sous-groupe) condensés en synthèse — portée partielle disclosed.","society":"SFAR / SFNEP","version":"2010 (publié 2011)","validated":"Actualisation de la Conférence de Consensus 1994","methodology":"Avis d'experts non formalisée, rédigée selon les déclinaisons de force Sfar/GRADE (fort/faible) — voir légende dans la fiche","pages":9,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"nutrition_perioperatoire","sections":[{"title":"Méthodologie, évaluation nutritionnelle & nutrition préopératoire (§1-2)","items":[{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Résumé :</b> Actualisation 2010 (SFAR/SFNEP) de la Conférence de Consensus 1994 sur la nutrition artificielle périopératoire, étendue à la prise en charge nutritionnelle globale (alimentation orale et assistance nutritionnelle) de l'adulte en chirurgie programmée. 71 recommandations sur 6 champs : évaluation de l'état nutritionnel, nutrition pré- et postopératoire, pharmaconutrition, obésité et chirurgie, diabète.","style":"body"}},{"t":"p","html":"Assistance nutritionnelle = nutrition entérale (sonde) ou parentérale (cathéter) — les compléments nutritionnels oraux ne sont pas considérés comme une assistance nutritionnelle. Nutrition précoce = débutée dans les 24 premières heures après la chirurgie.","style":"body_sm"},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"chip","label":"1-"},{"t":"chip","label":"2+"},{"t":"chip","label":"2-"},{"t":"chip","label":"Def."},{"t":"p","html":"<b>Force</b> — méthode « avis d'experts » non formalisée, rédigée selon les déclinaisons Sfar/GRADE explicitement définies par la source. <b>1+</b> = « il faut faire »/recommandé (fort) ; <b>1-</b> = « il ne faut pas faire »/non recommandé (fort) ; <b>2+</b> = « il est possible/probable de faire » (faible) ; <b>2-</b> = « il est possible/probable de ne pas faire » (faible) ; <b>Def.</b> = énoncé définitionnel/descriptif de la source (seuil diagnostique, constat), sans verbe modal directif propre.","style":"badge_head"}]]},{"t":"section","text":"1 — Évaluation de l'état nutritionnel périopératoire","color":"navy"},{"t":"p","html":"La dénutrition préopératoire est un facteur de risque indépendant de complications postopératoires (infections, retard de cicatrisation, mortalité, durée de séjour, coûts).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"R1. Les facteurs pouvant induire une dénutrition doivent être recherchés (Tableau 1).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R2. Tout patient présentant au moins un facteur de risque de dénutrition doit bénéficier d'une évaluation de son état nutritionnel.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R3. L'évaluation nutritionnelle doit comporter la mesure du poids actuel, l'estimation de la perte de poids par rapport au poids habituel et le calcul de l'IMC.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R4. La mesure de l'albuminémie peut être utile en cas de difficulté de l'évaluation nutritionnelle.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R5. En cas de chirurgie majeure, la mesure de l'albuminémie en préopératoire est probablement recommandée.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R6. Un patient est considéré à risque de dénutrition s'il présente au moins un des facteurs de risque du Tableau 1.","style":"cell"},{"t":"chip","label":"Def."}],[{"t":"p","html":"R7. Un patient est considéré dénutri (dénutrition cliniquement pertinente) s'il présente au moins un critère : IMC ≤18,5 (ou <21 si >70 ans) ; ou perte de poids récente ≥10 % ; ou albuminémie <30 g/L indépendamment de la CRP.","style":"cell"},{"t":"chip","label":"Def."}],[{"t":"p","html":"R8. En chirurgie digestive non oncologique, le seuil d'albuminémie pourrait être fixé à 35 g/L pour définir une dénutrition pertinente.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R9. En chirurgie cardiaque, un patient peut être considéré dénutri s'il a un IMC ≤24, ou une perte de poids ≥10 % en 6 mois, ou une albuminémie <37 g/L.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R10. Un patient est très sévèrement dénutri (risque de syndrome de renutrition) s'il présente un IMC <13, ou un amaigrissement >20 % en 3 mois, ou des apports oraux négligeables ≥15 jours.","style":"cell"},{"t":"chip","label":"Def."}],[{"t":"p","html":"R11. Prendre en compte l'état nutritionnel, les facteurs de risque et le risque chirurgical via une stratification du risque global (grade nutritionnel, GN — Tableau 2).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R12. Une recherche systématique des facteurs de risque de dénutrition, et si nécessaire une évaluation de l'état nutritionnel, doivent être réalisées en préopératoire par l'équipe médicochirurgicale.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R13. Intégrer les résultats de l'évaluation nutritionnelle et du risque nutritionnel dans le dossier du patient.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R14. Quand l'évaluation nutritionnelle n'a pas été faite en amont, elle doit être réalisée au cours de la consultation d'anesthésie.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R15. La stratification du grade nutritionnel doit être mentionnée dans le rapport de consultation d'anesthésie.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"p","html":"<b>Tableau 1 — Facteurs de risque de dénutrition pré- et postopératoire</b> (reproduit verbatim).","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Facteurs de risque","style":"head_w"}],[{"t":"p","html":"Liés au patient (comorbidités)","style":"cell_b"},{"t":"p","html":"Âge >70 ans ; cancer ; hémopathie maligne ; sepsis ; pathologie chronique digestive ; insuffisance d'organe (respiratoire, cardiaque, rénale, intestinale, pancréatique, hépatique) ; pathologie neuromusculaire et polyhandicap ; diabète ; syndrome inflammatoire ; VIH/sida ; antécédent de chirurgie digestive majeure (grêle court, pancréatectomie, gastrectomie, chirurgie bariatrique) ; syndrome dépressif, troubles cognitifs, démence, syndrome confusionnel.","style":"cell"}],[{"t":"p","html":"Symptômes persistants","style":"cell_b"},{"t":"p","html":"Dysphagie ; nausée/vomissement/satiété précoce ; douleur ; diarrhée ; dyspnée.","style":"cell"}],[{"t":"p","html":"Liés à un traitement (traitement à risque)","style":"cell_b"},{"t":"p","html":"Traitement à visée carcinologique (chimiothérapie, radiothérapie) ; corticothérapie >1 mois ; polymédication >5 traitements.","style":"cell"}]]},{"t":"p","html":"<b>Tableau 2 — Stratification du risque nutritionnel (grade nutritionnel, GN)</b> (reproduit verbatim).","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Grade","style":"head_w"},{"t":"p","html":"Définition","style":"head_w"}],[{"t":"p","html":"GN 1","style":"cell_b"},{"t":"p","html":"Patient non dénutri, pas de facteur de risque de dénutrition, chirurgie sans risque élevé de morbidité.","style":"cell"}],[{"t":"p","html":"GN 2","style":"cell_b"},{"t":"p","html":"Patient non dénutri, ET (présence d'au moins un facteur de risque de dénutrition OU chirurgie à risque élevé de morbidité).","style":"cell"}],[{"t":"p","html":"GN 3","style":"cell_b"},{"t":"p","html":"Patient dénutri, chirurgie sans risque élevé de morbidité.","style":"cell"}],[{"t":"p","html":"GN 4","style":"cell_b"},{"t":"p","html":"Patient dénutri, chirurgie à risque élevé de morbidité.","style":"cell"}]]},{"t":"section","text":"2 — Nutrition préopératoire","color":"navy"},{"t":"p","html":"Un support nutritionnel préopératoire n'est pas recommandé en routine — réservé aux patients selon leur grade nutritionnel (GN).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"R16. Tout patient GN 2 ou 3 doit probablement bénéficier d'une prise en charge nutritionnelle préopératoire : conseils diététiques et compléments nutritionnels (GN 2) ; compléments, nutrition entérale ou parentérale (GN 3).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R17. Tout patient GN 4 doit recevoir une assistance nutritionnelle préopératoire (entérale ou parentérale) d'au moins 7 à 10 jours.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R18. Quand une assistance nutritionnelle préopératoire est indiquée, privilégier la nutrition entérale si le tube digestif est fonctionnel — la nutrition parentérale n'est alors pas recommandée.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R19. Chez la personne âgée, les stratégies nutritionnelles préopératoires sont les mêmes que chez le sujet plus jeune ; la surveillance doit probablement être plus rapprochée (mauvaise adaptation à la dénutrition, résistance à la renutrition).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R20. La prise en charge nutritionnelle postopératoire doit être anticipée ; le bilan préopératoire doit permettre de prévoir le type d'assistance nutritionnelle et la voie d'abord (sonde, stomie, voie veineuse).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R21. Lors de chirurgie majeure sus-mésocolique, choisir en préopératoire la voie d'abord digestive (sonde transanastomotique, sonde de stomie) permettant de débuter précocement une nutrition entérale.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R22. En chirurgie oncologique ORL (notamment avec radiothérapie combinée), la gastrostomie prethérapeutique, posée avant le traitement oncologique, est probablement la technique de choix.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R23. Chez les patients sans risque de régurgitation, le jeûne préopératoire ne doit pas excéder 2 à 3 heures pour les liquides clairs et 6 heures pour un repas léger.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R24. Chez les patients sans risque de régurgitation, la prise de liquides clairs sucrés (glucose ou maltodextrines) jusqu'à 2 heures avant la prémédication est probablement recommandée.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R25. L'état nutritionnel d'un patient opéré en urgence doit être évalué si possible avant l'intervention, sinon dans les 48 premières heures postopératoires.","style":"cell"},{"t":"chip","label":"1+"}]]}]},{"title":"Nutrition postopératoire & pharmaconutrition (§3-4)","items":[{"t":"section","text":"3 — Nutrition postopératoire (dont urgence)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"R26. Reprendre le plus rapidement possible (24 premières heures) une alimentation orale selon la tolérance du patient, sauf contre-indication chirurgicale.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R27. Chez les patients non dénutris (GN 1-2), la durée d'une assistance nutritionnelle postopératoire, quand elle est requise, ne doit pas être inférieure à 7 jours.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R28. Chez un patient non dénutri (GN 1-2), instaurer une assistance nutritionnelle quand les apports postopératoires sont <60 % des besoins depuis 7 jours.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R29. Chez les patients non dénutris (GN 1-2), instaurer probablement une assistance nutritionnelle précoce si les apports prévisibles seront <60 % des besoins durant les 7 jours postopératoires.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R30. Instaurer, dès les 24 premières heures postopératoires, un support nutritionnel chez les patients dénutris (GN 3-4), qu'ils aient reçu ou non un support préopératoire.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R31. La prise en charge nutritionnelle postopératoire d'un patient opéré en urgence n'est pas différente de celle recommandée pour la chirurgie programmée.","style":"cell"},{"t":"chip","label":"Def."}],[{"t":"p","html":"R32. Fracture de l'extrémité supérieure du fémur chez la personne âgée : atteindre 30-40 kcal/kg/j et 1,2-1,5 g de protéines/kg/j ; prescrire des compléments nutritionnels oraux jusqu'à la sortie de rééducation (nutrition entérale si échec/impossibilité de la voie orale) ; prescrire de la vitamine D à 800-1200 UI/j (prévention des chutes et fractures).","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"section","text":"4 — Place de la pharmaconutrition en périopératoire","color":"navy"},{"t":"p","html":"Pharmaconutrition (immunonutrition) : arginine, glutamine, micronutriments, acides gras oméga-3, nucléotides — utilisés pour leur effet sur l'inflammation/l'immunité/la cicatrisation, pas seulement nutritionnel.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"R33. En chirurgie digestive oncologique programmée (dénutri ou non), prescrire en préopératoire pendant 5 à 7 jours un mélange nutritif digestif contenant une association de pharmaconutriments efficace.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R34. Chez le patient non dénutri (GN 2) en chirurgie digestive oncologique programmée, ne pas prescrire de pharmaconutrition en postopératoire.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"R35. Chez le patient dénutri (GN 4) en chirurgie digestive oncologique programmée, poursuivre en postopératoire la pharmaconutrition digestive.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R36. En chirurgie carcinologique ORL, prescrire probablement une pharmaconutrition selon les mêmes modalités qu'en digestif (études encore insuffisantes pour confirmer un bénéfice identique).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R37. En chirurgie cardiaque (pontage coronaire), il n'est probablement pas recommandé de prescrire des pharmaconutriments (bénéfice sur les complications non établi).","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"R38. Ne pas prescrire de pharmaconutriments contenant de l'arginine chez le patient septique ou hémodynamiquement instable.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"R39. En chirurgie programmée non compliquée, il n'est probablement pas recommandé de prescrire systématiquement de la glutamine en périopératoire.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"R40. En cas de complications postopératoires majeures, prescrire de la glutamine IV à forte dose (0,2-0,4 g/kg/j, soit 0,3-0,6 g/kg/j de dipeptide de glutamine).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R41. Un support enrichi en oméga-3 (≥0,1 g/kg/j) est probablement recommandé en postopératoire d'une chirurgie abdominale majeure programmée.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R42. En l'absence de données en chirurgie, la prescription de micronutriments à dose pharmacologique en périopératoire n'est pas recommandée.","style":"cell"},{"t":"chip","label":"1-"}]]}]},{"title":"Obésité & chirurgie (§5)","items":[{"t":"section","text":"5 — Obésité et chirurgie","color":"navy"},{"t":"p","html":"Obésité : IMC ≥30 ; obésité morbide : IMC ≥40.","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"R43. La surcharge pondérale (IMC ≥25) et l'obésité modérée (IMC 30-35) ne sont pas des facteurs de risque de mortalité postopératoire, mais l'obésité est associée à un risque accru de complications mineures et à une hospitalisation prolongée.","style":"cell"},{"t":"chip","label":"Def."}],[{"t":"p","html":"R44. Pour la chirurgie bariatrique, l'obésité morbide avec IMC >50-55 est probablement associée à une surmortalité postopératoire.","style":"cell"},{"t":"chip","label":"Def."}],[{"t":"p","html":"R45. Le patient obèse est un patient potentiellement dénutri.","style":"cell"},{"t":"chip","label":"Def."}],[{"t":"p","html":"R46. Chez l'obèse, une perte de poids involontaire avant chirurgie est un facteur de risque de complication indépendant de la corpulence.","style":"cell"},{"t":"chip","label":"Def."}],[{"t":"p","html":"R47. S'assurer que les besoins protéiques sont couverts chez le sujet âgé obèse en préopératoire (1,2-1,5 g/kg/j).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R48. Dépister (fer sérique, ferritine) et corriger la carence en fer, plus fréquente chez l'obèse, en préopératoire.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R49. Prévenir le risque de carence en vitamine B1 chez l'obèse en cas de perfusion de sérum glucosé ou de troubles digestifs (apport de thiamine orale ou parentérale).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R50. Un ajustement de la supplémentation en vitamine B12 est probablement nécessaire après chirurgie entraînant une malabsorption (gastrectomie, résection iléale).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R51. En cas d'amaigrissement avant un acte chirurgical, un bilan nutritionnel (hypoalbuminémie, carences en vitamines B1/B9/B12/C/A/D/E) est souhaitable.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R52. Les régimes restrictifs entraînant une perte de masse maigre ne sont pas recommandés, notamment chez l'obésité commune (IMC 30-40) ou le sujet âgé obèse.","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"R53. Une perte de poids volontaire préopératoire n'est pas recommandée dans les jours/semaines précédant un geste chirurgical (aucune preuve de bénéfice).","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"R54. Si une perte de poids est nécessaire pour faciliter le geste opératoire (ex. cure d'éventration), une phase de stabilisation pondérale d'au moins 15 jours est probablement nécessaire.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R55. Avant chirurgie bariatrique, le régime restrictif et/ou la perte de poids préopératoire n'est pas recommandée (ne modifie ni mortalité, ni complications, ni perte de poids à long terme).","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"R56. Pour estimer les besoins protéino-énergétiques périopératoires de l'obèse, utiliser probablement le poids normalisé (IMC théorique de 25 à 30).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R57. Ne pas utiliser le poids dit « idéal ».","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R58. Le sujet obèse doit probablement recevoir un apport protéique postopératoire élevé (~1,5 g/kg de poids normalisé/j).","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R59. Il n'est probablement pas recommandé de prescrire une alimentation hypocalorique chez l'obèse en postopératoire.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"R60. Après chirurgie bariatrique, comme après toute chirurgie viscérale, une reprise alimentaire précoce est recommandée.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R61. Après chirurgie bariatrique, la reprise alimentaire doit se faire progressivement en texture et en quantité, selon les protocoles établis par l'équipe.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R62. Après chirurgie bariatrique, privilégier les aliments riches en protéines — apport minimal recommandé de 60 g/j.","style":"cell"},{"t":"chip","label":"1+"}]]}]},{"title":"Diabète, protocoles types & sources (§6-7)","items":[{"t":"section","text":"6 — Nutrition périopératoire chez le diabétique","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Force","style":"head_w_c"}],[{"t":"p","html":"R63. Le patient diabétique est un patient à haut risque de dénutrition.","style":"cell"},{"t":"chip","label":"Def."}],[{"t":"p","html":"R64. En préopératoire, le diagnostic de dénutrition chez le sujet âgé doit faire rechercher systématiquement une hyperglycémie.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R65. Couvrir les besoins protéino-énergétiques du patient diabétique et optimiser en conséquence son traitement antidiabétique.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R66. Malgré un risque accru de carences vitaminiques chez le diabétique, aucune supplémentation spécifique n'est actuellement recommandée en périopératoire (besoins couverts par une alimentation variée).","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"R67. En l'absence de données suffisantes, la prise de liquides clairs sucrés jusqu'à 2 heures avant la prémédication n'est probablement pas recommandée chez le patient diabétique.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"R68. L'utilisation de compléments nutritionnels oraux ou produits de nutrition entérale spécifiques pour diabétique (index glycémique faible) facilite probablement l'équilibre glycémique — l'adaptation des doses d'insuline reste l'élément primordial.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R69. La gastroparésie (plus fréquente chez le diabétique) ne doit pas être un frein à la nutrition entérale.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R69 (suite). Elle justifie probablement de contrôler les résidus gastriques, d'utiliser des prokinétiques et de mettre en place une sonde post-pylorique, notamment en cas de gastroparésie grave.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"R70. Les apports en glucides doivent être adaptés aux besoins énergétiques du patient ; un contrôle du débit de perfusion est recommandé.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"R71. L'insuline est le traitement de choix en cas d'hyperglycémie sous nutrition parentérale ; instaurer l'insulinothérapie selon des modalités précises et des protocoles validés (anticiper la baisse/l'arrêt de l'insulinothérapie à l'arrêt de la nutrition parentérale, risque d'hypoglycémie).","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"section","text":"7 — Protocoles nutritionnels types (Tableaux 3-6, synthèse)","color":"navy"},{"t":"p","html":"Les Tableaux 3 à 6 de la source déclinent les recommandations ci-dessus en protocoles opérationnels par grade nutritionnel (GN 1 à 4) et sous-groupe (obésité morbide, diabétique, personne âgée). Ce contenu recoupe largement R1-R71 déjà couverts intégralement ci-dessus ; seuls les éléments numériques qui n'apparaissent nulle part ailleurs sont repris ici (portée partielle disclosed, voir méthodologie).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Détail","style":"head_w"}],[{"t":"p","html":"Hydro-électrolytique standard (GN 1-3, en l'absence d'alimentation orale)","style":"cell_b"},{"t":"p","html":"1,5 à 2,5 L/24h de solution glucosée à 5 % (75-125 g de glucose) + 50-100 mmol de NaCl/24h + 40-80 mmol de KCl/24h.","style":"cell"}],[{"t":"p","html":"Assistance nutritionnelle — formule entérale","style":"cell_b"},{"t":"p","html":"25-30 kcal/kg/j dont 1,2-1,5 g/kg de protéines ; si sonde naso-gastrique, utiliser une sonde Charrière 10 silicone ou polyuréthane (pas de sonde de Salem).","style":"cell"}],[{"t":"p","html":"Assistance nutritionnelle — formule parentérale","style":"cell_b"},{"t":"p","html":"25-30 kcal/kg/j dont 0,20-0,25 g d'azote/kg/j, avec électrolytes (50-100 mmol NaCl/24h + 40-80 mmol KCl/24h), vitamines et oligoéléments.","style":"cell"}],[{"t":"p","html":"Glutamine IV (complications postopératoires graves)","style":"cell_b"},{"t":"p","html":"0,3 g/kg/j, sans dépasser 21 jours de traitement.","style":"cell"}],[{"t":"p","html":"GN 4 — dénutrition très sévère (IMC <13, amaigrissement >20 % en 3 mois, apports oraux négligeables ≥15 jours)","style":"cell_b"},{"t":"p","html":"Nutrition préopératoire d'au moins 21 jours ; renutrition très progressive débutant à 10 kcal/kg/j avec augmentation progressive sur une semaine ; ajout systématique quotidien de thiamine (200-300 mg), phosphore (0,3-0,6 mmol/kg), magnésium (0,2 mmol/kg IV ou 0,4 mmol/kg per os), potassium (2-4 mmol/kg), vitamines et oligoéléments, avec évaluation biologique quotidienne.","style":"cell"}],[{"t":"p","html":"GN 4 — chirurgie carcinologique digestive","style":"cell_b"},{"t":"p","html":"Complément nutritif oral immunomodulateur (type Oral Impact®) : 3 briquettes/jour pendant 5-7 jours avant le geste (utiliser la forme entérale si la voie orale est impossible).","style":"cell"}]]},{"t":"section","text":"Sources et traçabilité","color":"grey"},{"t":"p","html":"<b>Document source :</b> « Recommandations de bonnes pratiques cliniques sur la nutrition périopératoire. Actualisation 2010 de la conférence de consensus de 1994 sur la nutrition artificielle périopératoire en chirurgie programmée de l'adulte » — SFAR / Société francophone de nutrition clinique et métabolisme (SFNEP). Coordonnateurs : C. Chambrier (Lyon), F. Sztark (Bordeaux). Organisateur délégué : S. Pierre (Toulouse). Groupe d'experts : X. Alacoque, P. Bachmann, J. Berre, I. Bourdel-Marchasson, D. Caldari, P. Chardon, V. Colomb, P. Coti-Bertrand, D. Francon, É. Paillaud, A. Petit, N. Peretti, M.-A. Piquet, D. Quillot, M. Raucoules-Aimé, A. Raynaud-Simon, P. Senesse, R. Thibault, J.-F. Zazzo.","style":"source"},{"t":"p","html":"<b>Version :</b> Ann Fr Anesth Réanim 30 (2011) 381-389 (paru initialement dans Nutrition Clinique et Métabolisme 2010;24:145-156). doi:10.1016/j.annfar.2011.01.014.","style":"source"},{"t":"p","html":"<b>Méthodologie :</b> avis d'experts non formalisée, rédigée selon les déclinaisons de force Sfar/GRADE (voir légende en page 1).","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Nutrition-artificielle-perioperatoire-en-chirurgie-programmee-de-ladulte.pdf","style":"source"},{"t":"p","html":"<b>Couverture :</b> intégralité des 71 recommandations numérotées (R1-R71). Tableaux 3-6 (protocoles croisés GN × sous-groupe) condensés en tableau de synthèse des seuls éléments numériques absents de R1-R71 — portée partielle disclosed, voir méthodologie.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement — document de 2010/2011 :</b> cette fiche de synthèse indépendante reprend l'intégralité des 71 recommandations du texte source, mais ne le remplace pas et n'est ni éditée ni validée par la SFAR/SFNEP. Les produits, dosages et disponibilités ayant pu évoluer depuis 2010, se référer à un avis spécialisé et aux recommandations actualisées avant toute décision.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Nutrition-artificielle-perioperatoire-en-chirurgie-programmee-de-ladulte.pdf';

insert into public.documents (title, doc_type, publication_date, source_url, original_language)
values ('Prise en charge de l’interruption volontaire de grossesse jusqu’à 14 semaines', 'RFE', '2010-01-01', 'https://sfar.org/wp-content/uploads/2015/10/2_ANAES_Prise-en-charge-de-l-interruption-volontaire-de-grossesse-jusqu-a-14-semaines.pdf', 'non_renseigne')
on conflict (source_url) do nothing;
insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_ANAES_Prise-en-charge-de-l-interruption-volontaire-de-grossesse-jusqu-a-14-semaines.pdf' and s.slug in ('anesthesie_reanimation', 'gynecologie_obstetrique', 'sage_femme_maieuticienne')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_ANAES_Prise-en-charge-de-l-interruption-volontaire-de-grossesse-jusqu-a-14-semaines.pdf' and s.acronym in ('ANAES', 'HAS')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_ANAES_Prise-en-charge-de-l-interruption-volontaire-de-grossesse-jusqu-a-14-semaines.pdf' and d.society_id is null and s.acronym = 'ANAES';
update public.documents set
  fiche_key = 'ivg_14sa',
  card_json = $mgjson${"badge":"ANAES A/B/C","title":"Prise en charge de l'IVG jusqu'à 14 semaines","short":"ANAES, mars 2001 (mise à jour partielle déc. 2010 par la HAS pour l'IVG médicamenteuse uniquement — non incluse ici, voir avertissement dans la fiche). Organisation des structures, accueil, consultations pré-IVG, choix de la technique (chirurgicale ou médicamenteuse) et du mode d'anesthésie selon l'âge gestationnel, prise en charge de la douleur, prévention des complications infectieuses et de l'incompatibilité Rhésus, suites et suivi post-IVG. Grille ANAES à 3 niveaux (A/B/C) ; 8 énoncés gradés explicitement, le reste relevant de l'accord professionnel (AP) par défaut selon la convention du texte source. Disclosure : le PDF source signale des passages modifiés en 2010 « en rouge », information de couleur non récupérable à l'extraction texte — non résolue silencieusement, voir la fiche.","society":"ANAES / HAS","version":"mars 2001 (màj partielle déc. 2010)","validated":"ANCIC, ANSFL, CNGE, CNGOF, planning familial, Fédération Française de Psychiatrie, SFAR, SFMG, SFTG","methodology":"Grille ANAES A/B/C (grade A/B/C explicite) + accord professionnel (AP) par défaut — voir légende dans la fiche","pages":4,"section":"Obstétrique"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"ivg_14sa","sections":[{"title":"Méthodologie, organisation, consultations, techniques, douleur, prévention, suites & sources","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Résumé :</b> recommandations ANAES (mars 2001) pour la prise en charge de l'IVG jusqu'à 14 semaines d'aménorrhée (SA), dans le cadre légal. Organisation des structures et de l'accueil, information et consultations pré-IVG, choix de la technique (chirurgicale ou médicamenteuse) et du mode d'anesthésie selon l'âge gestationnel, prise en charge de la douleur, prévention des complications infectieuses et de l'incompatibilité Rhésus, suites et suivi post-IVG.","style":"body"}},{"t":"panel","tone":"default","content":{"t":"p","html":"<b>⚠ Périmètre — IVG médicamenteuse exclue de cette fiche :</b> le document source lui-même indique que ses recommandations sur l'IVG par <b>méthode médicamenteuse</b> sont remplacées par les recommandations HAS de <b>décembre 2010</b> (non incluses dans le PDF source, donc non reprises ici). Le PDF signale aussi que les passages de mars 2001 modifiés en 2010 apparaissent « en rouge » dans le document original — une information de couleur qui n'est <b>pas récupérable</b> lors de l'extraction du texte (limite technique, disclosed et non résolue silencieusement, cf. règle 5 du projet). Cette fiche reproduit fidèlement le texte tel qu'il apparaît dans le PDF source (donc déjà partiellement amendé, sans qu'on puisse distinguer 2001 de 2010) et porte principalement sur la <b>technique chirurgicale</b> et les éléments communs aux deux méthodes. Pour l'IVG médicamenteuse, se référer impérativement aux recommandations HAS 2010.","style":"body_sm"}},{"t":"section","text":"Méthodologie — grille ANAES","color":"navy"},{"t":"p","html":"Grille à 3 niveaux : <b>grade A</b> (essais comparatifs randomisés de forte puissance, méta-analyses, analyses de décision bien menées) ; <b>grade B</b> (essais randomisés de faible puissance, études comparatives non randomisées bien menées, études de cohortes) ; <b>grade C</b> (études cas-témoins, séries de cas). « En l'absence de précision, les recommandations proposées correspondent à un <b>accord professionnel</b> » (citation littérale du texte source) — chip <b>AP</b> dans cette fiche. La grande majorité des recommandations de ce document sont non graduées (AP) ; seuls 8 énoncés portent un grade A/B/C explicite (détaillés ci-après).","style":"body_sm"},{"t":"table","rows":[[{"t":"chip","label":"A"},{"t":"chip","label":"B"},{"t":"chip","label":"C"},{"t":"chip","label":"AP"},{"t":"p","html":"<b>Grille ANAES</b> — <b>A</b> : preuve scientifique établie (essais randomisés de forte puissance, méta-analyses) ; <b>B</b> : présomption scientifique (essais randomisés de faible puissance, cohortes) ; <b>C</b> : niveau de preuve moindre (cas-témoins, séries de cas) ; <b>AP</b> : accord professionnel (absence de précision de grade dans le texte source).","style":"badge_head"}]]},{"t":"section","text":"I-II. Structures de prise en charge, accueil et organisation","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"}],[{"t":"p","html":"Nombre de structures","style":"cell_b"},{"t":"p","html":"En nombre suffisant par département pour un accueil correct et rapide de toutes les demandes ; fonctionnement chaque semaine, sans interruption, toute l'année. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Jusqu'à 12 SA (84 j)","style":"cell_b"},{"t":"p","html":"Structure intégrée à un établissement avec service de gynécologie-obstétrique, ou en convention avec un plateau technique permettant de prendre en charge l'ensemble des complications de l'IVG. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Au-delà de 12 SA","style":"cell_b"},{"t":"p","html":"Prise en charge dans une structure disposant d'un plateau technique chirurgical, désignée et connue de tous les centres d'accueil du département. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Équipement","style":"cell_b"},{"t":"p","html":"Chaque centre d'accueil doit disposer d'au moins un échographe avec sonde vaginale. Projet de service partagé par tout le personnel impliqué, avec formation spécifique à cette activité. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Délai de rendez-vous","style":"cell_b"},{"t":"p","html":"Consultation obtenue dans les 5 jours suivant l'appel — l'IVG précoce réduit le risque de complications et élargit le choix des techniques. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Accueil téléphonique","style":"cell_b"},{"t":"p","html":"Ligne téléphonique dédiée, connue et diffusée ; message clair et précis hors présence du personnel. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Accueil/secrétariat","style":"cell_b"},{"t":"p","html":"Opérationnels pour répondre aux demandes, orienter vers les consultations préalables et informer sur les modalités de l'IVG ; signalés avec précision à l'entrée et dans l'établissement. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Mode de prise en charge","style":"cell_b"},{"t":"p","html":"Sauf cas exceptionnel, IVG réalisées en ambulatoire ou en hôpital de jour (séjour < 12 heures). <i>(AP)</i>","style":"cell"}]]},{"t":"section","text":"III. Consultations pré-IVG","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"}],[{"t":"p","html":"Information","style":"cell_b"},{"t":"p","html":"Informations claires et précises sur la procédure (méthode médicamenteuse ou chirurgicale), les choix d'anesthésie (locale/générale) et le temps de réflexion, à l'oral et par documents écrits. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Entretien psychosocial","style":"cell_b"},{"t":"p","html":"Un entretien d'information, de soutien et d'écoute doit pouvoir être proposé systématiquement, confié à des professionnels qualifiés pour cet accompagnement. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Âge gestationnel","style":"cell_b"},{"t":"p","html":"Précisé par l'interrogatoire et l'examen clinique ; recours à une échographie possible sur place lors de la consultation. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Dépistage","style":"cell_b"},{"t":"p","html":"Dépistage des IST (dont VIH) et frottis cervico-vaginaux proposés selon le contexte clinique. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Contraception ultérieure","style":"cell_b"},{"t":"p","html":"Abordée et éventuellement prescrite dès la consultation précédant l'IVG ; recherche des raisons de l'échec ou de l'absence de contraception. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Procédure d'urgence","style":"cell_b"},{"t":"p","html":"Permet de raccourcir le délai de réflexion pour les femmes dont l'âge gestationnel est situé entre 12 et 14 SA. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Bilan biologique","style":"cell_b"},{"t":"p","html":"Groupe sanguin Rhésus avec recherche d'agglutinines irrégulières (RAI) systématique pour toutes les patientes ; autres examens si besoin lors d'une éventuelle consultation préanesthésique. <i>(AP)</i>","style":"cell"}]]},{"t":"section","text":"IV. Techniques d'IVG — principes généraux","color":"navy"},{"t":"p","html":"Dans tous les cas possibles, la femme choisit la technique (médicale ou chirurgicale) et le mode d'anesthésie (locale ou générale). <i>(AP)</i> La technique chirurgicale repose sur la dilatation du col et l'évacuation du contenu utérin par aspiration, en conditions strictes d'asepsie, éventuellement précédée d'une préparation cervicale médicamenteuse. La technique médicamenteuse associe mifépristone et prostaglandines — <b>se référer aux recommandations HAS de décembre 2010</b> pour cette méthode (hors périmètre de cette fiche, voir avertissement en page 1).","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"<b>Préparation cervicale</b> (lorsqu'elle est recommandée) — mifépristone 200 mg per os 36 à 48 heures avant aspiration.","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"<b>Préparation cervicale</b> (alternative) — misoprostol 400 µg par voie orale ou vaginale 3 à 4 heures avant aspiration.","style":"cell"},{"t":"chip","label":"A"}]]},{"t":"p","html":"La préparation cervicale, quel que soit le produit utilisé, ne nécessite pas d'hospitalisation. Le contrôle visuel du produit d'aspiration est indispensable. <i>(AP)</i> En postopératoire, toute patiente ayant bénéficié d'une sédation intraveineuse, d'une anesthésie générale ou périmédullaire doit séjourner en salle de surveillance post-interventionnelle (SSPI). <i>(AP)</i>","style":"body_sm"},{"t":"section","text":"IV (suite). Technique selon l'âge gestationnel","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Âge gestationnel","style":"head_w"},{"t":"p","html":"Conduite recommandée","style":"head_w"}],[{"t":"p","html":"Jusqu'à 7 SA révolues (49 j)","style":"cell_b"},{"t":"p","html":"Techniques chirurgicale et médicale utilisables selon disponibilités et choix de la patiente. Risque d'échec de la technique chirurgicale inférieur à la technique médicale, mais plus élevé à cet âge gestationnel que plus tardivement. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"8e-9e SA (50 à 63 j)","style":"cell_b"},{"t":"p","html":"Deux techniques utilisables. Pour la technique chirurgicale, préparation cervicale médicamenteuse recommandée chez la nullipare (mifépristone 200 mg 36-48 h avant, ou misoprostol 400 µg 3-4 h avant). <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"10e-12e SA (64 à 84 j)","style":"cell_b"},{"t":"p","html":"Technique chirurgicale = technique de choix. Préparation cervicale médicamenteuse recommandée (mêmes 2 options). <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"13e-14e SA (85 à 98 j)","style":"cell_b"},{"t":"p","html":"Technique chirurgicale = technique de choix — évacuation par aspiration ± pinces spécifiques, nécessitant une formation spécifique. Préparation cervicale médicamenteuse recommandée. L'anesthésie locale éventuelle demande une très bonne maîtrise de la technique de dilatation-évacuation.","style":"cell"}]]},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"<b>13e-14e SA</b> — la technique chirurgicale est la technique de choix.","style":"cell"},{"t":"chip","label":"B"}]]},{"t":"section","text":"V. Prise en charge de la douleur — analgésie et anesthésie","color":"navy"},{"t":"p","html":"L'IVG médicamenteuse est responsable de douleurs modérées à sévères pour plus de 50 % des femmes, liées principalement aux prostaglandines ; l'efficacité des traitements antalgiques proposés a été peu évaluée. <i>(AP)</i>","style":"body_sm"},{"t":"table","rows":[[{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Lors des avortements par aspiration, l'anesthésie locale par bloc paracervical ne prévient pas la survenue de douleurs sévères pour environ le tiers des patientes.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"L'injection de lidocaïne intracervicale (région isthmique, orifice interne du col) diminue significativement le score de douleur par comparaison à la technique de bloc paracervical précédente.","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Facteurs de risque de douleur intense : jeune âge, peur de l'acte, utérus rétroversé, antécédents de dysménorrhée, grossesses les plus précoces et les plus avancées — justifient des antalgiques efficaces en préopératoire (AL) ou la proposition d'une anesthésie générale.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"L'administration d'ibuprofène (AINS) diminue les scores de douleur per- et postopératoire (seul l'AINS étudié).","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"Les benzodiazépines sont inefficaces sur la douleur de l'IVG par aspiration ; l'efficacité du paracétamol n'est pas prouvée.","style":"cell"},{"t":"chip","label":"AP"}],[{"t":"p","html":"Pour l'anesthésie générale : les halogénés à forte concentration augmentent le volume des pertes sanguines ; l'utilisation d'ocytocine le diminue.","style":"cell"},{"t":"chip","label":"B"}]]},{"t":"p","html":"La patiente doit être informée des différentes modalités d'anesthésie possibles (générale ou locale) ; le choix du type d'anesthésie lui revient. Le recours à l'anesthésie générale doit être possible ; si retenue, elle répond aux exigences du décret n° 94-1050 du 5 décembre 1994. Les données anciennes sur l'augmentation des complications liées à l'AG (perforations, hémorragies, mortalité) précèdent l'utilisation du misoprostol et les mesures de surveillance actuelles. <i>(AP)</i>","style":"body_sm"},{"t":"section","text":"VI-VII. Prévention infectieuse et prévention Rhésus","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Volet","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"}],[{"t":"p","html":"Prévention infectieuse (VI)","style":"cell_b"},{"t":"p","html":"Bien qu'il n'existe pas de démonstration d'un bénéfice à long terme, il est recommandé, en cas d'IVG chirurgicale, d'adopter une stratégie pouvant associer : antibiothérapie en cas d'antécédent connu d'infection génitale haute ; pour toute autre situation à risque d'IST, prélèvement vaginal et/ou recherche de Chlamydiae trachomatis par PCR urinaire, avec traitement de la patiente et du(des) partenaire(s) en cas de positivité ; en l'absence de facteur de risque, les antibiotiques réduisent la fièvre post-IVG mais sans données sur un bénéfice à long terme (incohérence source disclosed : bénéfice à court terme démontré, bénéfice à long terme non démontré). <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Prévention Rhésus (VII)","style":"cell_b"},{"t":"p","html":"Systématique chez toute femme Rhésus négatif, par injection intraveineuse d'une dose standard de gamma-globulines anti-D. En cas d'IVG médicamenteuse à domicile, la prévention est faite lors de la prise de mifépristone. <i>(AP)</i>","style":"cell"}]]},{"t":"section","text":"VIII-IX. Suites immédiates, visite de contrôle et évaluation","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Volet","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"}],[{"t":"p","html":"Avant la visite de contrôle","style":"cell_b"},{"t":"p","html":"Contraception œstroprogestative possible dès le lendemain de l'IVG (méthode médicamenteuse ou chirurgicale). Pose d'un dispositif intra-utérin (DIU) possible lors de l'examen de surveillance, ou en fin d'aspiration en cas d'IVG chirurgicale. Fiche de conseils sur les suites normales + numéro d'urgence remis à la patiente. <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Visite de contrôle","style":"cell_b"},{"t":"p","html":"Prévue entre le 14e et le 21e jour post-IVG. Contrôle de la vacuité utérine par examen clinique, complété par échographie selon les données de l'examen. Vérification de la compréhension et de la bonne utilisation de la contraception prescrite, et de la position d'un éventuel DIU (pose possible si non fait). Accompagnement psychologique spécifique proposé et disponible (peu de données sur le retentissement psychologique de l'IVG). <i>(AP)</i>","style":"cell"}],[{"t":"p","html":"Évaluation (IX)","style":"cell_b"},{"t":"p","html":"Les IVG doivent être déclarées. Un recueil national des données est nécessaire pour la surveillance épidémiologique et l'évaluation des pratiques ; ces données doivent être rapidement accessibles aux professionnels. <i>(AP)</i>","style":"cell"}]]},{"t":"section","text":"X. Axes de recherche future proposés (liste, non gradés)","color":"navy"},{"t":"p","html":"&bull; Comparer les techniques médicale et chirurgicale<br/>&bull; Améliorer la prise en charge de la douleur liée à l'IVG<br/>&bull; Déterminer l'utilité à long terme d'une antibioprophylaxie ou d'une antibiothérapie au cours de l'IVG<br/>&bull; Préciser le retentissement psychologique de l'IVG","style":"body_sm"},{"t":"section","text":"Sources et avertissement","color":"navy"},{"t":"p","html":"ANAES, « Prise en charge de l'interruption volontaire de grossesse jusqu'à 14 semaines », Recommandations pour la pratique clinique, mars 2001. Élaboré en partenariat avec l'ANCIC, l'ANSFL, le CNGE, le CNGOF, la Confédération nationale du mouvement pour le planning familial, la Fédération Française de Psychiatrie, la SFAR, la SFMG et la SFTG. Mise à jour partielle en décembre 2010 (HAS) pour l'IVG médicamenteuse uniquement.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement — document de 2001, partiellement actualisé en 2010 :</b> cette fiche est une synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend l'intégralité des recommandations énonçables du texte source pour la partie chirurgicale et les éléments communs aux deux méthodes d'IVG, mais ne remplace pas le texte intégral et n'est ni éditée ni validée par l'ANAES/HAS/SFAR. <b>Pour l'IVG médicamenteuse, se référer impérativement aux recommandations HAS de décembre 2010</b> (non incluses dans le PDF source de cette fiche). Le cadre légal, les techniques et les pratiques d'organisation des soins ayant pu évoluer depuis 2001/2010, se référer à un avis spécialisé et aux recommandations actualisées avant toute décision.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_ANAES_Prise-en-charge-de-l-interruption-volontaire-de-grossesse-jusqu-a-14-semaines.pdf';

insert into public.documents (title, doc_type, publication_date, source_url, original_language)
values ('Gestion perioperatoire des patients sous AOD pour un acte programmé', 'Autre', '2015-01-01', 'https://sfar.org/download/gestion-perioperatoire-des-patients-sous-aod-pour-un-acte-programme/?wpdmdl=33608', 'non_renseigne')
