where d.source_url = 'https://sfar.org/download/gestion-perioperatoire-des-patients-sous-aod-pour-un-acte-programme/?wpdmdl=33608' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade')
