update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/download/optimisation-hemodynamique-perioperatoire-pediatrie/?wpdmdl=62046' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'optimisation_hemodynamique_pediatrie_2024',
  card_json = $mgjson${"badge":"RPP — 9/9 Avis d'experts, Accord Fort","title":"Optimisation hémodynamique périopératoire — Pédiatrie","short":"SFAR, RPP, mars 2024 (transfusion exclue du champ). Méthode GRADE (analyse bibliographique PRISMA) + cotation GRADE grid — 9 avis d'experts sur 4 champs, TOUS à accord fort, document entièrement non gradé (aucun GRADE 1+/1-/2+/2- imprimé) : Champ 1 — cibles de pression artérielle moyenne peropératoire par tranche d'âge (> 35 mmHg si < 6 mois, > 43 mmHg si 6 mois-2 ans, > [1,5×âge+40] mmHg si 2-10 ans) ; Champ 2 — VES/indices dynamiques (Doppler œsophagien chez le patient à risque élevé/très élevé si échocardiographie indisponible ; absence de recommandation pour la population générale sur le monitorage du VES et les indices dynamiques seuls) ; Champ 3 — indices de perfusion tissulaire (lactatémie utile en cas de bas débit, monitorage cérébral chez le nourrisson < 1 an en chirurgie majeure ; absence de recommandation sur DIVA-CO2/ScvO2) ; Champ 4 — expansion volémique (cristalloïde balancé en 1re intention, albumine 4-5% chez le nouveau-né/nourrisson, vasoconstricteur à dose majorée par rapport à l'adulte si hypotension persistante ; absence de recommandation sur le choix du vasoconstricteur). 4 questions sans réponse, décompte source vérifié exact (aucune incohérence). Complémentaire de la fiche `remplissage_perioperatoire` (RFE SFAR/Adarpef 2012, adulte à haut risque, brève mention pédiatrique règle 4-2-1 uniquement) — ce RPP 2024 est dédié et beaucoup plus détaillé spécifiquement à la pédiatrie.","society":"SFAR","version":"Mars 2024","validated":"Groupe d'experts, méthode GRADE grid","methodology":"GRADE grid — 9 avis d'experts, 100 % Accord Fort, document non gradé (pas de GRADE numérique)","pages":2,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"optimisation_hemodynamique_pediatrie_2024","sections":[{"title":"Optimisation hémodynamique périopératoire — Pédiatrie","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Résumé :</b> RPP SFAR sur l'optimisation hémodynamique périopératoire en pédiatrie — 9 avis d'experts sur 4 champs : cibles de pression artérielle par tranche d'âge, monitorage du volume d'éjection systolique/indices dynamiques, indices de perfusion tissulaire, expansion volémique et vasoconstricteurs. Transfusion exclue du champ.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"AE"},{"t":"p","html":"<b>AE = Avis d'experts</b> — méthode GRADE grid (≥ 70 % d'opinions favorables, &lt; 20 % contraires). <b>Les 9 avis d'experts ont tous recueilli un accord fort</b>, sans exception ; document entièrement non gradé (aucun GRADE 1+/1-/2+/2- imprimé — la méthode GRADE n'a servi qu'à l'analyse bibliographique en amont). Une « absence de recommandation » (littérature insuffisante, 4 cas) est distincte d'une recommandation négative (« il ne faut pas faire », absente de ce document) — distinction explicite du texte source.","style":"badge_head"}]]},{"t":"section","text":"Champ 1 — Optimisation périopératoire de la pression artérielle","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"R1.1.1","style":"cell_b"},{"t":"p","html":"Chez l'enfant anesthésié &lt; 6 mois, maintenir une PA moyenne peropératoire &gt; 35 mmHg pour limiter les complications cérébrales.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.1.2","style":"cell_b"},{"t":"p","html":"Chez l'enfant anesthésié de 6 mois à 2 ans, maintenir une PA moyenne peropératoire &gt; 43 mmHg pour limiter les complications cérébrales.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.1.3","style":"cell_b"},{"t":"p","html":"Chez l'enfant anesthésié de 2 à 10 ans, maintenir une PA moyenne peropératoire &gt; [1,5 × âge (ans) + 40] mmHg pour limiter la morbidité postopératoire.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Champ 2 — VES et indices dynamiques pour l'expansion volémique","color":"navy"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Absence de recommandation</b> (littérature insuffisante — nécessite une évaluation individualisée bénéfice/risque) : intérêt du monitorage du volume d'éjection systolique pour optimiser l'hémodynamique et diminuer la morbi-mortalité, pour la population pédiatrique générale.","style":"body_sm"}},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Absence de recommandation</b> (littérature insuffisante — nécessite une évaluation individualisée bénéfice/risque) : intérêt des indices dynamiques seuls pour optimiser l'expansion volémique, pour la population pédiatrique générale.","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"R2.1","style":"cell_b"},{"t":"p","html":"Utiliser le Doppler œsophagien pour optimiser l'hémodynamique peropératoire du patient pédiatrique à risque élevé ou très élevé, si la tête est accessible et en l'absence d'échocardiographie peropératoire.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Champ 3 — Indices de perfusion tissulaire","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"R3.1","style":"cell_b"},{"t":"p","html":"La surveillance de la lactatémie, en cas de circonstances évocatrices d'hypoxie tissulaire (bas débit peropératoire), peut être utile pour estimer la sévérité de la souffrance cellulaire et son évolution.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Absence de recommandation</b> (littérature insuffisante — nécessite une évaluation individualisée bénéfice/risque) : intérêt de la différence veino-artérielle en CO2 (DIVA-CO2) et de la saturation veineuse en oxygène (ScvO2).","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"R3.2","style":"cell_b"},{"t":"p","html":"Utiliser un monitorage de la perfusion/oxygénation tissulaire cérébrale chez l'enfant &lt; 1 an opéré d'une chirurgie majeure ou à risque cérébral particulier, pour optimiser l'hémodynamique peropératoire.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Champ 4 — Expansion volémique, vasoconstricteurs, inotropes","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts","style":"head_w"},{"t":"p","html":"Cotation","style":"head_w_c"}],[{"t":"p","html":"R4.1.1","style":"cell_b"},{"t":"p","html":"Privilégier l'expansion volémique initiale par un soluté cristalloïde balancé, limité dans le temps, pour maintenir l'homéostasie biologique et circulatoire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.1.2","style":"cell_b"},{"t":"p","html":"Chez le nouveau-né et le jeune nourrisson, utiliser l'albumine à 4-5 % après l'expansion volémique initiale cristalloïde, pour limiter le volume d'expansion volémique.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.2","style":"cell_b"},{"t":"p","html":"En cas d'hypotension artérielle peropératoire persistante malgré une expansion volémique adaptée, utiliser un vasoconstricteur avec des doses rapportées au poids majorées par rapport à l'adulte.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Absence de recommandation</b> (littérature insuffisante — nécessite une évaluation individualisée bénéfice/risque) : quel vasoconstricteur utiliser pour la population pédiatrique.","style":"body_sm"}},{"t":"section","text":"Sources et avertissement","color":"navy"},{"t":"p","html":"SFAR, « Optimisation hémodynamique périopératoire – Pédiatrie », RPP, mars 2024. Méthode GRADE (analyse de la littérature, PRISMA) + cotation GRADE grid. Références bibliographiques citées dans le texte intégral (non reproduites ici) ; composition nominative du groupe d'experts (non reproduite).","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend intégralement les 9 avis d'experts et les 4 cas d'absence de recommandation du texte source, mais condense l'argumentaire de chaque item et omet la composition nominative du groupe d'experts. Elle ne remplace pas le texte intégral et n'est ni éditée ni validée par la SFAR.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/download/optimisation-hemodynamique-perioperatoire-pediatrie/?wpdmdl=62046';

