insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/download/prise-en-charge-de-la-douleur-de-laccouchement-analgesie-perimedullaire-et-alternatives-medicamenteuses-texte-court/?wpdmdl=106110' and s.acronym in ('HAS', 'SFAR', 'CARO')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/download/prise-en-charge-de-la-douleur-de-laccouchement-analgesie-perimedullaire-et-alternatives-medicamenteuses-texte-court/?wpdmdl=106110' and d.society_id is null and s.acronym = 'HAS';
update public.documents set
  fiche_key = 'douleur_accouchement_2025',
  card_json = $mgjson${"badge":"RBP HAS — GRADE (34 recs + 5 absences)","title":"Douleur de l'accouchement — Analgésie périmédullaire","short":"HAS, RBP validée par le Collège le 30 avril 2025, promue par la SFAR et le Collège d'Anesthésie et Réanimation en Obstétrique (CARO), en association avec CNGOF/SF2H/CNSF/CIANE/GIHP/SFTH et d'autres — actualisation des recommandations SFAR de 2006 sur l'analgésie obstétricale. Méthode GRADE (grade 1/grade 2 SANS signe +/-, comme resection_hepatique_2025), 5 champs — pose, initiation, entretien, gestion de l'insuffisance/échec, alternatives médicamenteuses à l'analgésie périmédullaire (APM) — 34 recommandations et 5 absences de recommandation (39 items). Points clés : pas de repérage échographique systématique (sauf obésité/rachis difficile) ; pas de préférence décubitus latéral/position assise ; délai après HBPM ≥12h (prophylactique)/≥24h (curative) ; technique avec ponction durale si efficacité rapide attendue ; accès à l'APM précoce (≤4cm) ; pas de dose-test à la lidocaïne ; bolus intermittent programmé (BIP) préféré au débit continu ; déambulation possible sous APM ; sufentanil systématique en adjuvant, pas de clonidine en 1re intention ni d'adrénaline ; mesures correctrices en cas d'échec avec algorithme dédié (Figure 4, d'après Rackelboom) et repose de cathéter à 45min si échec ; rémifentanil IV-PCA en 2e ligne si contre-indication à l'APM avec surveillance rapprochée (risque dépression respiratoire) ; pas de protoxyde d'azote comparé à l'APM. Ce document N'IMPRIME PAS de synthèse chiffrée globale à recouper (contrairement à resection_hepatique_2025) — décompte direct exhaustif uniquement, chaque marqueur R x.y[.z] et chaque bloc ABS (imprimé en encadrement avant ET après le texte, vérifié pour ne pas compter en double) apparié individuellement à son grade. 5 absences dont 2 sans aucun numéro R (port de la casaque stérile ; monitorage systématique maternel/RCF pendant la pose) — questions posées explicitement dans le texte source mais n'ayant reçu aucune proposition, même non numérotée.","society":"HAS / SFAR / CARO","version":"Avril 2025","validated":"Collège de la HAS, 30 avril 2025","methodology":"GRADE (sans signe +/-) — 34 recommandations (12 G1 + 10 G2 + 12 avis d'experts) + 5 absences, décompte direct exhaustif (pas de synthèse chiffrée source à recouper)","pages":5,"section":"Obstétrique"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"douleur_accouchement_2025","sections":[{"title":"Champ 1 — Pose de l'analgésie périmédullaire","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Résumé :</b> RBP HAS (avril 2025), promue par la SFAR et le CARO — actualisation des recommandations SFAR 2006 sur l'analgésie obstétricale. 5 champs — pose, initiation, entretien, gestion de l'insuffisance/échec de l'analgésie périmédullaire (APM), alternatives médicamenteuses — 34 recommandations et 5 absences de recommandation (39 items).","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"G1"},{"t":"chip","label":"G2"},{"t":"chip","label":"AE"},{"t":"chip","label":"ABS"},{"t":"p","html":"<b>G1/G2 = grade 1/grade 2</b> (le source imprime ces niveaux SANS signe +/- ; sens repris du verbe de la phrase). <b>AE</b> = avis d'experts. <b>ABS</b> = pas de recommandation (données insuffisantes, aucune proposition faite). 39 items au total (34 recommandations + 5 absences) sur 5 champs — ce document n'imprime pas de synthèse chiffrée globale à recouper (contrairement à fiche_resection_hepatique_2025.py) : décompte direct exhaustif uniquement.","style":"badge_head"}]]},{"t":"p","html":"<b>Définitions retenues :</b> APM <b>précoce</b> = pose à dilatation cervicale ≤ 4 cm. <b>Insuffisance</b> d'analgésie = analgésie peu ou partiellement efficace ; <b>échec</b> = absence totale d'efficacité. <b>Déambulation</b> = possibilité de marcher et/ou se verticaliser sous APM, au 1<super>er</super> stade, au 2<super>e</super> stade, ou aux deux.","style":"body_sm"},{"t":"section","text":"Champ 1 — Pose de l'analgésie périmédullaire (APM)","color":"navy"},{"t":"p","html":"<b>Repérage échographique</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.1.1","style":"cell_b"},{"t":"p","html":"Ne pas utiliser le repérage échographique de l'espace périmédullaire de manière systématique dans le but de réduire la morbidité maternelle.","style":"cell"},{"t":"chip","label":"G2"}],[{"t":"p","html":"R1.1.2","style":"cell_b"},{"t":"p","html":"Utiliser le repérage échographique de l'espace périmédullaire pour les patientes obèses et les rachis difficiles, pour faciliter la pose de l'APM.","style":"cell"},{"t":"chip","label":"G1"}]]},{"t":"p","html":"<b>Position à adopter</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.2","style":"cell_b"},{"t":"p","html":"Ne pas privilégier la pose en décubitus latéral par rapport à la position assise pour réduire la morbidité maternelle, les difficultés de pose, ou améliorer l'efficacité/la satisfaction maternelle.","style":"cell"},{"t":"chip","label":"G2"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>ABS — Pas de recommandation</b> (absence de données) : intérêt du monitorage systématique maternel et du rythme cardiaque fœtal pendant la pose de l'APM, pour réduire la morbidité néonatale.","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.3.1","style":"cell_b"},{"t":"p","html":"Dans tous les cas, si la pose de l'APM excède 30 minutes ou en cas de symptomatologie évocatrice d'une hypotension maternelle, vérifier la normalité de la pression artérielle maternelle et du RCF (même si cela impose une interruption transitoire de la procédure).","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>ABS — Pas de recommandation</b> (absence de données) : port de la casaque stérile (indépendamment des mesures d'asepsie recommandées par la SF2H), pour réduire la morbidité infectieuse maternelle.","style":"body_sm"}},{"t":"p","html":"<b>Femmes sous traitement anticoagulant (HBPM)</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.5.1","style":"cell_b"},{"t":"p","html":"Interrompre le traitement par HBPM à dose prophylactique ou curative avant la pose d'une APM, pour prévenir le risque d'hématome périmédullaire.","style":"cell"},{"t":"chip","label":"G1"}],[{"t":"p","html":"R1.5.2","style":"cell_b"},{"t":"p","html":"Poser l'APM au moins 12h après la dernière injection d'HBPM à dose prophylactique et au moins 24h après une dose curative, pour prévenir le risque d'hématome périmédullaire.","style":"cell"},{"t":"chip","label":"G2"}],[{"t":"p","html":"R1.5.3","style":"cell_b"},{"t":"p","html":"Chez une femme traitée par HBPM en cours de grossesse, vérifier avant la pose (ou l'ablation du cathéter) que l'activité anti-Xa est ≤ 0,1 UI/ml — si délai &lt; 12h (prophylactique) ou &lt; 24h (curative), ou en cas d'insuffisance rénale modérée à sévère (DFG &lt; 50 ml/min).","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Champs 2-3 — Initiation & entretien de l'APM","items":[{"t":"section","text":"Champ 2 — Initiation de l'APM","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R2.1","style":"cell_b"},{"t":"p","html":"Si une efficacité rapide de l'APM est attendue, proposer une technique avec ponction durale plutôt qu'une APM classique, pour améliorer le délai d'installation et la qualité du bloc initial.","style":"cell"},{"t":"chip","label":"G2"}],[{"t":"p","html":"R2.2.1","style":"cell_b"},{"t":"p","html":"Accéder à une demande d'APM précoce (améliore la satisfaction maternelle sans augmenter la morbidité ni modifier la voie d'accouchement ou la durée du travail).","style":"cell"},{"t":"chip","label":"G2"}],[{"t":"p","html":"R2.2.2","style":"cell_b"},{"t":"p","html":"Proposer une APM précoce dans les populations à risque* (maternel, anesthésique ou obstétrical), pour diminuer le risque de morbidité maternelle. *Ex. : obésité, comorbidité, intubation difficile prévisible, risque de césarienne augmenté, grossesse multiple.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.3.1","style":"cell_b"},{"t":"p","html":"Ne pas réaliser de « dose test à la lidocaïne » pour vérifier le bon positionnement du cathéter de péridurale.","style":"cell"},{"t":"chip","label":"G1"}],[{"t":"p","html":"R2.3.2","style":"cell_b"},{"t":"p","html":"Réaliser un bolus initial avec l'anesthésique local du mélange analgésique, pour détecter un mauvais positionnement du cathéter.","style":"cell"},{"t":"chip","label":"G1"}]]},{"t":"section","text":"Champ 3 — Entretien de l'APM","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R3.1","style":"cell_b"},{"t":"p","html":"Utiliser le mode bolus intermittent programmé (BIP) plutôt que le débit continu, pour améliorer l'efficacité analgésique et la satisfaction maternelle.","style":"cell"},{"t":"chip","label":"G2"}],[{"t":"p","html":"R3.2","style":"cell_b"},{"t":"p","html":"Permettre la déambulation pendant le travail sous APM aux patientes qui le souhaitent (pas d'impact négatif sur la morbidité maternelle/fœtale ni les issues obstétricales ; favorise la miction spontanée).","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Champ 4 — Gestion de l'insuffisance/échec (1/2)","items":[{"t":"section","text":"Champ 4 — Gestion de l'insuffisance et de l'échec de l'APM (1/2)","color":"navy"},{"t":"p","html":"<b>Surveillance pour limiter l'insuffisance/l'échec</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R4.1.1.1","style":"cell_b"},{"t":"p","html":"Réaliser la surveillance systématique de l'installation de l'APM et l'évaluation de l'intensité douloureuse à partir de 30 min après le bolus initial, avec identification des niveaux du bloc métamérique au test au froid.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.1.1.2","style":"cell_b"},{"t":"p","html":"Évaluer toutes les heures l'efficacité de l'APM (intensité douloureuse), pour dépister une insuffisance ou un échec.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.1.1.3","style":"cell_b"},{"t":"p","html":"Ne pas demander aux femmes de rester dans une position spécifique après l'injection péridurale dans le but d'améliorer l'efficacité ou de prévenir l'échec.","style":"cell"},{"t":"chip","label":"G2"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>ABS — Pas de recommandation</b> (absence de données) : organisation des soins d'anesthésie qui permettrait de limiter la survenue d'une insuffisance ou d'un échec d'analgésie.","style":"body_sm"}},{"t":"p","html":"<b>Anesthésique local et stratégies pharmacologiques</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R4.1.3","style":"cell_b"},{"t":"p","html":"Ne pas privilégier un anesthésique local plutôt qu'un autre, entre bupivacaïne, lévobupivacaïne et ropivacaïne, pour réduire l'insuffisance ou l'échec d'analgésie.","style":"cell"},{"t":"chip","label":"G1"}],[{"t":"p","html":"R4.1.4.1","style":"cell_b"},{"t":"p","html":"Associer systématiquement du sufentanil (morphinique liposoluble) aux anesthésiques locaux en péridural, pour réduire le risque d'insuffisance/échec et améliorer la satisfaction maternelle.","style":"cell"},{"t":"chip","label":"G1"}],[{"t":"p","html":"R4.1.4.2","style":"cell_b"},{"t":"p","html":"Ne pas utiliser en 1<super>re</super> intention la clonidine associée aux anesthésiques locaux en péridural.","style":"cell"},{"t":"chip","label":"G1"}],[{"t":"p","html":"R4.1.4.3","style":"cell_b"},{"t":"p","html":"Ne pas utiliser l'adrénaline en association aux anesthésiques locaux.","style":"cell"},{"t":"chip","label":"G2"}],[{"t":"p","html":"R4.2.1.1","style":"cell_b"},{"t":"p","html":"En cas d'insuffisance d'analgésie, administrer un bolus (répété si besoin) du mélange analgésique d'entretien.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.2.1.2","style":"cell_b"},{"t":"p","html":"Si l'insuffisance persiste, utiliser le même anesthésique local à plus forte concentration, éventuellement avec un adjuvant.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.2.2","style":"cell_b"},{"t":"p","html":"En cas d'insuffisance, injecter du sufentanil ou de la clonidine pour améliorer l'efficacité de l'APM.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Champ 4 — Gestion de l'insuffisance/échec (2/2) & Figure 4","items":[{"t":"section","text":"Champ 4 — Gestion de l'insuffisance et de l'échec de l'APM (2/2)","color":"navy"},{"t":"p","html":"<b>Évaluation complémentaire &amp; repose de cathéter</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R4.2.3","style":"cell_b"},{"t":"p","html":"En cas de reprise de la douleur, compléter l'évaluation de l'intensité douloureuse par une évaluation du niveau métamérique au test au froid.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.2.4.1","style":"cell_b"},{"t":"p","html":"En cas d'échec/insuffisance et/ou d'insatisfaction maternelle, conduire des mesures correctrices (cf Figure 4) et en évaluer l'efficacité dans les 30-45 min.","style":"cell"},{"t":"chip","label":"G1"}],[{"t":"p","html":"R4.2.4.2","style":"cell_b"},{"t":"p","html":"Poser à nouveau un cathéter péridural en cas d'échec à 45 min (après la 1<super>re</super> pose ou après les mesures correctrices).","style":"cell"},{"t":"chip","label":"G1"}],[{"t":"p","html":"R4.2.4.3","style":"cell_b"},{"t":"p","html":"Faire réaliser une nouvelle pose de cathéter après échec par un médecin anesthésiste-réanimateur expérimenté.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.2.4.4","style":"cell_b"},{"t":"p","html":"Utiliser une technique avec ponction durale en cas de nouvelle pose à dilatation cervicale avancée et/ou chez une parturiente hyperalgique.","style":"cell"},{"t":"chip","label":"G2"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>ABS — Pas de recommandation</b> (absence de données) : impact d'une position maternelle spécifique pour corriger une insuffisance ou un échec d'APM.","style":"body_sm"}},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>ABS — Pas de recommandation</b> (absence de données) : efficacité de l'hypnose et du soutien continu à prévenir/diminuer une insuffisance ou un échec d'APM.","style":"body_sm"}},{"t":"section","text":"Figure 4 — Algorithme de gestion de l'APM (d'après Rackelboom)","color":"grey"},{"t":"table","rows":[[{"t":"p","html":"Étape","style":"head_w"},{"t":"p","html":"Points clés","style":"head_w"}],[{"t":"p","html":"1. Pose","style":"cell_b"},{"t":"p","html":"Asepsie rigoureuse (antiseptique coloré) ; échorepérage si pose difficile prévue (obèse, rachis difficile) ; monitorage RCF+FC+PA/5min si pose &gt; 30 min ; délai après HBPM ≥ 12h (prophylactique) / ≥ 24h (curative).","style":"cell"}],[{"t":"p","html":"2. Initiation","style":"cell_b"},{"t":"p","html":"APD ou PPD avec bolus initial (AL faible concentration ≤ 1 mg/ml) ; si niveau sensitif &gt; T6 + bloc moteur → suspicion cathéter intrathécal ; si niveau &gt; T6 + mosaïque ± Sd de Claude Bernard-Horner → suspicion cathéter sous-dural : dans les deux cas, arrêt de toute injection et attente de récupération sensitivo-motrice avant repose (privilégier PRC ou PPD si travail avancé/hyperalgique).","style":"cell"}],[{"t":"p","html":"3. Entretien","style":"cell_b"},{"t":"p","html":"BIP + PCEA (ou débit continu + PCEA) ; objectif niveau sensitif T10 sans bloc moteur ; surveillance douleur/niveau sensitif/PA/bloc moteur, évaluation à 30 min puis toutes les heures et après chaque ajustement ; signes de toxicité aux AL ou douleur persistante/absence de niveau &gt; 45 min → arrêt et réévaluation complète.","style":"cell"}],[{"t":"p","html":"4. Insuffisance","style":"cell_b"},{"t":"p","html":"Niveau insuffisant &lt; T10 → vérifier absence de problème technique sur la ligne, effet volume (réinjection fractionnée), repère à la peau ; latéralisation/asymétrie → effet volume puis retrait du cathéter de 1 cm si échec à 15 min ; puissance insuffisante/point douloureux → effet concentration (AL plus concentré) puis adjuvant (clonidine dose unique ou sufentanil) ; dans tous les cas, réévaluation à 30-45 min.","style":"cell"}]]}]},{"title":"Champ 5 — Alternatives médicamenteuses & sources","items":[{"t":"section","text":"Champ 5 — Alternatives médicamenteuses à l'APM","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R5.1.1","style":"cell_b"},{"t":"p","html":"Recourir à l'APM plutôt qu'aux alternatives de type opioïdes en mode PCA, pour réduire la morbidité maternelle et améliorer l'efficacité/la satisfaction, sans impacter les issues obstétricales.","style":"cell"},{"t":"chip","label":"G1"}],[{"t":"p","html":"R5.1.2","style":"cell_b"},{"t":"p","html":"En cas de contre-indication à l'APM, utiliser le rémifentanil IV en mode autocontrôlé (PCA) plutôt que l'absence de prise en charge, pour améliorer la morbidité maternelle sans impact sur la morbidité néonatale.","style":"cell"},{"t":"chip","label":"G2"}],[{"t":"p","html":"R5.2.1","style":"cell_b"},{"t":"p","html":"Chez les parturientes sous opioïdes, assurer une surveillance rapprochée clinique (sédation, fréquence respiratoire) et paraclinique (SaO<sub>2</sub>, CO<sub>2</sub> expiré), pour réduire la morbidité maternelle.","style":"cell"},{"t":"chip","label":"G1"}],[{"t":"p","html":"R5.2.2","style":"cell_b"},{"t":"p","html":"Apporter un supplément d'oxygène tout au long de la PCA de rémifentanil, pour réduire la morbidité maternelle.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R5.3","style":"cell_b"},{"t":"p","html":"Ne pas utiliser le protoxyde d'azote dans le but d'améliorer l'efficacité analgésique ou la satisfaction maternelle comparé à l'APM.","style":"cell"},{"t":"chip","label":"G1"}]]},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Promoteurs :</b> SFAR et Collège d'Anesthésie et Réanimation en Obstétrique (CARO), en association avec le CNGOF, la SF2H, le CNSF, le CIANE, le GIHP, la SFTH, le Collège des Infirmier(e)s Puéricultrices(teurs) et l'AFPBN. RBP labellisée HAS, validée par le Collège de la HAS le 30 avril 2025 — actualisation des recommandations SFAR de 2006 sur l'analgésie obstétricale.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/prise-en-charge-de-la-douleur-de-laccouchement-analgesie-perimedullaire-et-alternatives-medicamenteuses/","style":"source"},{"t":"p","html":"<b>Couverture :</b> intégralité des 34 recommandations et des 5 absences de recommandation (5 champs). La Figure 4 (algorithme de gestion de l'insuffisance/échec) est retranscrite en tableau condensé depuis un rendu visuel. Les Figures 1 et 2 (schémas techniques APD/PRC/PPD et modes d'administration) ne sont pas retranscrites en détail — purement illustratives d'une terminologie déjà explicitée dans le texte des recommandations. Bibliographie et composition nominative des groupes de travail non reproduites.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend intégralement les 34 recommandations et les 5 absences de recommandation du texte source, mais condense l'argumentaire de chaque item. Elle ne remplace pas le texte intégral et n'est ni éditée ni validée par la HAS, la SFAR ni le CARO.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/download/prise-en-charge-de-la-douleur-de-laccouchement-analgesie-perimedullaire-et-alternatives-medicamenteuses-texte-court/?wpdmdl=106110';

