update public.documents set
  fiche_key = 'erreurs_medicamenteuses_2024',
  card_json = $mgjson${"badge":"RPP — 29 avis d'experts (accord fort 100 %)","title":"Prévention des erreurs médicamenteuses en anesthésie-réanimation","short":"SFAR, en collaboration avec la Société Française de Pharmacie Clinique (SFPC), RPP, texte validé par le Comité des Référentiels Cliniques de la SFAR le 30 avril 2024. Réactualisation, complémentaire et beaucoup plus étendue, de la préconisation SFAR/SFPC 2016 déjà git-trackée sous la clé erreurs_medicamenteuses_ar_2016 (les deux fiches restent utiles, sous des clés distinctes). Format RPP choisi en amont (pas RFE) faute d'un nombre suffisant d'études permettant une cotation GRADE numérique — les 29 recommandations sont donc TOUTES des avis d'experts, à accord fort pour 100 % d'entre elles (décompte source vérifié exact). 4 champs : 1. Environnement de travail et processus (protocoles de prescription/préparation/administration standardisés, logiciels de prescription et aide à la prescription en soins critiques, bilan médicamenteux et conciliation, double contrôle, codes couleurs internationaux d'étiquetage, mentions obligatoires sur les étiquettes de poches PCA/PCEA, étiquetage des voies d'administration, conformité ANSM/ISO 26825-2020, limitation du nombre de médicaments différents disponibles, seringues préremplies, normes de connectique, traçabilité par code barre, standardisation de l'approvisionnement/stockage) ; 2. Facteurs humains et organisationnels (lutte contre les interruptions de tâches, restriction des communications non essentielles, audits d'équipe, lecture attentive/double lecture/communication sécurisée, formation par simulation, intégration de pharmaciens cliniciens) ; 3. Gestion des risques a posteriori (déclaration et analyse des erreurs, REX) ; 4. Pénuries médicamenteuses (anticipation des changements de marché/ruptures, inclusion dans les plans de gestion des risques). 2 absences de recommandation : informatisation de la prescription en anesthésie (distincte des recommandations sur les soins critiques) ; systèmes data-matrix et RFID (distincts de la recommandation sur la traçabilité par code barre). Aucune annexe dans le document source.","society":"SFAR / Société Française de Pharmacie Clinique (SFPC)","version":"2024","validated":"Comité des Référentiels Cliniques SFAR, 30 avril 2024","methodology":"Format RPP (pas RFE) — 29 avis d'experts, accord fort 100 %, décompte source exact ; 2 absences de recommandation","pages":3,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"erreurs_medicamenteuses_2024","sections":[{"title":"Champ 1 — Environnement de travail et processus (1/2)","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Résumé :</b> RPP SFAR/SFPC (2024) — 29 recommandations (toutes avis d'experts, accord fort) et 2 absences de recommandation, sur 4 champs : environnement de travail et processus, facteurs humains et organisationnels, gestion des risques a posteriori, problématique des pénuries médicamenteuses. Complémentaire de la fiche déjà git-trackée <i>erreurs_medicamenteuses_ar_2016</i> (préconisation SFAR/SFPC antérieure, sur le même sujet).","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"AE"},{"t":"chip","label":"ABS"},{"t":"p","html":"<b>AE</b> = avis d'experts — format RPP choisi en amont (pas RFE) faute d'un nombre suffisant d'études permettant une cotation GRADE numérique : les 29 recommandations sont TOUTES des avis d'experts, à accord fort pour 100 % d'entre elles (décompte source vérifié exact). <b>ABS</b> = absence de recommandation (données insuffisantes, aucune proposition faite).","style":"badge_head"}]]},{"t":"section","text":"Champ 1 — Environnement de travail et processus (1/2)","color":"navy"},{"t":"p","html":"<b>Prescription</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R1.1","style":"cell_b"},{"t":"p","html":"Standardiser et utiliser des protocoles de prescription des médicaments (dilution, solvant, durée, vitesse, voie d'administration), pour réduire la survenue d'erreurs médicamenteuses.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.2.1","style":"cell_b"},{"t":"p","html":"Utiliser un logiciel de prescription en soins critiques, pour diminuer les erreurs médicamenteuses et les effets indésirables évitables.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.2.2","style":"cell_b"},{"t":"p","html":"Implémenter en soins critiques des outils informatiques d'aide à la prescription, pour réduire les erreurs médicamenteuses.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.2.3","style":"cell_b"},{"t":"p","html":"Adapter les logiciels de prescription et outils d'aide à la population des services de soins critiques (adultes, enfants, nouveau-nés), les paramétrer avant déploiement (soignants + pharmaciens cliniciens) et les actualiser en continu, pour réduire les erreurs médicamenteuses.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>ABS — Absence de recommandation</b> (données insuffisantes) : informatisation de la prescription en anesthésie (distincte de R1.2.1-1.2.3, spécifiques aux soins critiques).","style":"body_sm"}},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R1.3","style":"cell_b"},{"t":"p","html":"Réaliser un bilan médicamenteux et une conciliation médicamenteuse en anesthésie et soins critiques, pour réduire les erreurs médicamenteuses.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Préparation</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R1.4.1","style":"cell_b"},{"t":"p","html":"Standardiser la préparation des médicaments avec des protocoles (dilution, solvant, durée, vitesse, voie d'administration), pour réduire les erreurs médicamenteuses.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.4.2","style":"cell_b"},{"t":"p","html":"Proscrire la coexistence de différentes concentrations d'un même médicament dans le plateau de médicaments, pour éviter les erreurs d'administration.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Champ 1 — Environnement de travail et processus (2/2)","items":[{"t":"section","text":"Champ 1 — Environnement de travail et processus (2/2)","color":"navy"},{"t":"p","html":"<b>Administration</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R1.5.1","style":"cell_b"},{"t":"p","html":"Standardiser l'administration des médicaments, utiliser des protocoles (durée, vitesse, voie) et le double contrôle, pour réduire les erreurs médicamenteuses.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.5.2","style":"cell_b"},{"t":"p","html":"En dehors de l'IV directe, choisir des dispositifs médicaux adaptés (pousse-seringue électrique) à l'administration des médicaments injectables et former les professionnels à leur usage.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Étiquetage</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R1.6.1","style":"cell_b"},{"t":"p","html":"Utiliser les codes couleurs internationaux pour l'étiquetage des seringues, poches et voies d'administration.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.6.2","style":"cell_b"},{"t":"p","html":"Sur l'étiquette des poches de perfusion/PCA/PCEA, mentionner : nom du médicament (DCI), quantité/concentration, date-heure et auteur de la préparation, date-heure de pose, identité du patient (code barre).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.6.3","style":"cell_b"},{"t":"p","html":"Apposer sur les voies d'administration (parties proximale et distale) des étiquettes de couleur à bordure spécifique, mentionnant explicitement la voie d'administration.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Conditionnement, dispositifs et connectique</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R1.7.1","style":"cell_b"},{"t":"p","html":"Choisir des ampoules/flacons à étiquetage conforme aux recommandations ANSM (typographie, mentions, code couleur ISO 26825-2020 par classe pharmacologique).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.7.2","style":"cell_b"},{"t":"p","html":"Limiter au strict nécessaire le nombre de médicaments différents disponibles ; éviter deux concentrations différentes ou des conditionnements similaires (forme, couleur, dénomination) pour un même médicament.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.8","style":"cell_b"},{"t":"p","html":"Utiliser des seringues préremplies (SPR) plutôt que des seringues traditionnelles.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.9","style":"cell_b"},{"t":"p","html":"Utiliser des normes de connectique par type de voie d'administration.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.10","style":"cell_b"},{"t":"p","html":"Utiliser un système de traçabilité (code barre) aux différentes étapes du circuit du médicament.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>ABS — Absence de recommandation</b> (données insuffisantes) : systèmes data-matrix et RFID (distincts de R1.10, traçabilité par code barre).","style":"body_sm"}},{"t":"p","html":"<b>Approvisionnement et stockage</b>","style":"cell_b"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R1.11.1","style":"cell_b"},{"t":"p","html":"Standardiser l'approvisionnement, le rangement et le stockage en soins critiques (armoire à pharmacie, chariot d'urgence).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.11.2","style":"cell_b"},{"t":"p","html":"Standardiser l'approvisionnement/rangement/stockage en anesthésie avec un système commun à tous les sites (chariots d'ALR, de pédiatrie, d'urgence).","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Champs 2-4 — Facteurs humains, risques & pénuries, sources","items":[{"t":"section","text":"Champ 2 — Facteurs humains et organisationnels","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R2.1.1","style":"cell_b"},{"t":"p","html":"Lutter contre les interruptions de tâches et les distractions.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.1.2","style":"cell_b"},{"t":"p","html":"Restreindre les communications non essentielles lors de la préparation et de l'administration de médicaments.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.1.3","style":"cell_b"},{"t":"p","html":"Réaliser au sein de chaque équipe un audit standardisé visant à limiter les interruptions de tâches spécifiques à l'équipe et à l'organisation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.2","style":"cell_b"},{"t":"p","html":"Utiliser la lecture attentive, la double lecture, la concordance, une communication sécurisée et une organisation du processus lors de la préparation et de l'administration.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.3","style":"cell_b"},{"t":"p","html":"Utiliser la formation par tout type de simulation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.4","style":"cell_b"},{"t":"p","html":"Intégrer des pharmaciens cliniciens formés spécifiquement dans les services d'anesthésie et de soins critiques.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Champ 3 — Gestion des risques a posteriori","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R3.1.1","style":"cell_b"},{"t":"p","html":"Déclarer et analyser a posteriori les erreurs médicamenteuses.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R3.1.2","style":"cell_b"},{"t":"p","html":"Mettre en place des REX (Retour d'EXpérience).","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Champ 4 — Problématique des pénuries médicamenteuses","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R4.1.1","style":"cell_b"},{"t":"p","html":"Anticiper le plus possible les changements de médicaments (marché ou rupture), en partenariat avec les pharmaciens cliniciens.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.1.2","style":"cell_b"},{"t":"p","html":"Inclure des mesures de gestion des pénuries de produits de santé dans les plans de gestion des risques des établissements.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Méthode :</b> groupe d'experts SFAR/SFPC, recherche bibliographique 2004-2024 (PRISMA), format PICO. Format RPP choisi en amont faute de données suffisantes pour une cotation GRADE numérique — 29 recommandations formulées comme avis d'experts, votées par méthode GRADE grid, accord fort obtenu pour la totalité après un tour de vote et quelques ajustements.","style":"source"},{"t":"p","html":"<b>Document source :</b> SFAR, en collaboration avec la Société Française de Pharmacie Clinique (SFPC), « Prévention des erreurs médicamenteuses en anesthésie-réanimation », RPP, texte validé par le Comité des Référentiels Cliniques de la SFAR le 30 avril 2024.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/prevention-des-erreurs-medicamenteuses-en-anesthesie-reanimation/","style":"source"},{"t":"p","html":"<b>Couverture :</b> intégralité des 29 recommandations et des 2 absences de recommandation (4 champs). Aucune annexe dans le document source. Bibliographie et composition nominative du groupe d'experts non reproduites.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend intégralement les 29 recommandations et les 2 absences de recommandation du texte source, mais condense l'argumentaire de chaque item. Elle ne remplace pas le texte intégral et n'est ni éditée ni validée par la SFAR ni la SFPC.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/download/prevention-des-erreurs-medicamenteuses/?wpdmdl=68460';

insert into public.documents (title, doc_type, publication_date, source_url, original_language)
values ('Organisation de l’anesthésie pédiatrique', 'RPP', '2023-01-01', 'https://sfar.org/download/organisation-de-lanesthesie-pediatrique/?wpdmdl=43179', 'non_renseigne')
on conflict (source_url) do nothing;
insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/download/organisation-de-lanesthesie-pediatrique/?wpdmdl=43179' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade', 'pediatrie')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/download/organisation-de-lanesthesie-pediatrique/?wpdmdl=43179' and s.acronym in ('SFAR', 'ADARPEF')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/download/organisation-de-lanesthesie-pediatrique/?wpdmdl=43179' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'organisation_anesthesie_pediatrique_2023',
  card_json = $mgjson${"badge":"RPP — 34 avis d'experts (accord fort 100 %)","title":"Organisation de l'anesthésie pédiatrique","short":"SFAR-ADARPEF, « Organisation structurelle, matérielle et fonctionnelle des centres effectuant de l'anesthésie pédiatrique », RPP, texte validé par le Comité des Référentiels Cliniques de la SFAR le 19/01/2023. Complémentaire de la fiche déjà git-trackée anesth_pediatrique_structures (RFE SFAR 2000, matériel chiffré au sein d'UN site) — celle-ci porte sur l'organisation ENTRE sites/centres, deux échelles différentes, toutes deux nécessaires. Méthode GRADE prévue en amont mais les 34 recommandations (« préconisations ») sont TOUTES formulées comme avis d'experts, à accord fort pour la totalité (décompte source vérifié exact, aucune absence de recommandation dans ce document). 4 champs : 1. Structure et logistique (salle d'intervention adaptée, secteur pédiatrique en SSPI, hospitalisation en secteur dédié, consultation d'anesthésie en lieu adapté, plateau technique et réseaux de consultants spécialistes) ; 2. Équipement et matériel (matériel respiratoire/vasculaire adapté à l'âge, solutés hydro-électrolytiques et de remplissage par tranche d'âge, chariot d'urgence pédiatrique, monitorage adapté dont oxygénation régionale cérébrale pour les chirurgies majeures du nouveau-né/nourrisson, prévention de l'hypothermie, sondes échographiques 25-38mm/8-14MHz) ; 3. Formation (≥3 mois de stage en centre spécialisé pour tout interne, activité régulière minimale pour tout MAR pratiquant la pédiatrie, simulation) ; 4. Organisation fonctionnelle — réseaux ville/centre spécialisé avec critères d'orientation par âge et ASA (nouveau-né <6 semaines, ancien prématuré <60 semaines d'âge post-conceptionnel, ASA 3-5 vers un centre spécialisé), et surtout des **critères d'effectifs minimaux par tranche d'âge** directement actionnables (< 1 an ou ASA 4-5 : 2 professionnels dédiés exclusivement ; 1-3 ans et 3-10 ans : MAR + IADE dédiés ou MAR dédié avec second professionnel identifié à l'avance ; > 10 ans : règles adultes), plus les effectifs SSPI (IDE/IADE/puéricultrice formée, second paramédical, renfort si ≥6 postes).","society":"SFAR / ADARPEF","version":"2023","validated":"Comité des Référentiels Cliniques SFAR (19/01/2023), CA SFAR (26/01/2023)","methodology":"Format RPP — 34 avis d'experts, accord fort 100 %, décompte source exact ; aucune absence de recommandation","pages":4,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"organisation_anesthesie_pediatrique_2023","sections":[{"title":"Champ 1 — Structure et logistique","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Résumé :</b> RPP SFAR-ADARPEF (2023) sur l'organisation structurelle, matérielle et fonctionnelle des centres pratiquant l'anesthésie pédiatrique — 34 recommandations (toutes avis d'experts, accord fort) sur 4 champs : structure et logistique, équipement et matériel, formation, organisation fonctionnelle. Complémentaire de la fiche déjà git-trackée <i>anesth_pediatrique_structures</i> (RFE SFAR 2000, matériel chiffré au sein d'un site) — celle-ci porte sur l'organisation ENTRE sites (réseaux, orientation par âge/ASA, effectifs).","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"AE"},{"t":"p","html":"<b>AE</b> = avis d'experts — méthode GRADE prévue en amont, mais les 34 recommandations (« préconisations ») sont TOUTES formulées comme avis d'experts, à accord fort pour la totalité d'entre elles (décompte source vérifié exact). Aucune absence de recommandation dans ce document.","style":"badge_head"}]]},{"t":"section","text":"Champ 1 — Structure et logistique","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R1.1","style":"cell_b"},{"t":"p","html":"Réaliser l'anesthésie pédiatrique dans une salle d'intervention disposant de matériel adapté au poids et à l'âge de l'enfant.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.2","style":"cell_b"},{"t":"p","html":"Identifier un secteur pédiatrique en SSPI, pour regrouper personnel/matériel spécifiques et permettre la présence d'un accompagnant.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.3.1","style":"cell_b"},{"t":"p","html":"Hospitaliser les enfants en pré et postopératoire dans un secteur dédié à la pédiatrie (conventionnel, ambulatoire ou soins critiques).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.3.2","style":"cell_b"},{"t":"p","html":"Réaliser la consultation d'anesthésie dans un lieu dédié et adapté à l'enfant, pour favoriser son confort et diminuer son anxiété.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.4.1","style":"cell_b"},{"t":"p","html":"Disposer d'un accès à un plateau technique (laboratoire, radiologie, produits sanguins labiles) capable de répondre aux besoins pédiatriques, dont les micro-prélèvements, pour toute activité pédiatrique programmée et/ou non programmée.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R1.4.2","style":"cell_b"},{"t":"p","html":"Formaliser des réseaux de consultants spécialistes en pédiatrie, pour tout établissement ayant une activité pédiatrique programmée et/ou non programmée.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Champ 2 — Équipement et matériel","items":[{"t":"section","text":"Champ 2 — Équipement et matériel","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R2.1.1","style":"cell_b"},{"t":"p","html":"Adapter tout le matériel d'assistance respiratoire à l'âge, au poids et à la taille de l'enfant, pour assurer normoxémie et normocapnie.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.1.2","style":"cell_b"},{"t":"p","html":"Dans les salles non dédiées à la pédiatrie, utiliser un chariot mobile spécifique contenant le matériel de gestion des voies aériennes pédiatrique.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.2.1","style":"cell_b"},{"t":"p","html":"Utiliser un matériel d'accès vasculaire adapté à l'âge/taille/poids de l'enfant.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.2.2","style":"cell_b"},{"t":"p","html":"Disposer, dans tous les lieux d'anesthésie pédiatrique (bloc, SSPI), de matériel d'abord intra-osseux (perceuse et trocarts adaptés) pour les situations critiques.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.3.1","style":"cell_b"},{"t":"p","html":"Pour les apports hydro-électrolytiques peropératoires de base : soluté glucosé à 5 % + ≥ 4 g NaCl/l (nouveau-né) ; soluté isotonique balancé glucosé à 1 % (nourrisson/jeune enfant) ; soluté balancé isotonique (au-delà de 3 ans).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.3.2","style":"cell_b"},{"t":"p","html":"Pour le remplissage vasculaire péri-opératoire : soluté balancé isotonique en 1<super>re</super> intention ; albumine si hypovolémie persistante, en particulier chez le nouveau-né/nourrisson.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.4","style":"cell_b"},{"t":"p","html":"Disposer d'un chariot d'urgence pédiatrique avec aides cognitives spécifiques, en plus du matériel/médicaments d'urgence.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.5.1","style":"cell_b"},{"t":"p","html":"Utiliser un monitorage dont les composants sont adaptés au poids et/ou à l'âge de l'enfant, pour une interprétation fiable.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.5.2","style":"cell_b"},{"t":"p","html":"Chez le nouveau-né/nourrisson opéré de chirurgie majeure, monitorer l'oxygénation régionale cérébrale pour détecter précocement une désaturation cérébrale (hypotension, hypoxémie, anémie, hypocapnie).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.6.1","style":"cell_b"},{"t":"p","html":"Réaliser un monitorage systématique de la température péri-opératoire chez l'enfant.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.6.2","style":"cell_b"},{"t":"p","html":"Prévenir l'hypothermie dès le transport vers le bloc, débuter le réchauffement actif avant l'induction (dispositif adapté + contrôle de la température de salle), poursuivre en continu per- et postopératoire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R2.7","style":"cell_b"},{"t":"p","html":"Disposer de sondes échographiques linéaires 25-38 mm / 8-14 MHz pour les abords vasculaires et l'ALR chez l'enfant.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Champs 3-4 — Formation & organisation (réseaux)","items":[{"t":"section","text":"Champ 3 — Formation","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R3.1.1","style":"cell_b"},{"t":"p","html":"Appliquer les recommandations européennes selon les spécificités nationales/locales : tout interne d'anesthésie-réanimation doit suivre ≥ 3 mois de formation en anesthésie pédiatrique en centre spécialisé (≥ 6 mois + passage en soins critiques pédiatriques pour une activité régulière future).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R3.1.2","style":"cell_b"},{"t":"p","html":"Tout MAR pratiquant l'anesthésie pédiatrique doit avoir une activité régulière dédiée (≥ une demi-journée/semaine) et actualiser ses compétences via des programmes individuels, dans le cadre de la certification périodique.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R3.1.3","style":"cell_b"},{"t":"p","html":"Promouvoir les programmes de formation basés sur la simulation, en formation initiale et continue.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Champ 4 — Organisation fonctionnelle (1/2) — Réseaux et orientation","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R4.1.1","style":"cell_b"},{"t":"p","html":"Les centres de proximité et spécialisés ayant une activité d'anesthésie pédiatrique doivent s'organiser en réseaux avec un centre spécialisé à vocation régionale, pour la chirurgie programmée ou non.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.1.2","style":"cell_b"},{"t":"p","html":"Formaliser cette organisation en réseaux par une convention (charte de fonctionnement locale, transfert des cas complexes).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.2.1","style":"cell_b"},{"t":"p","html":"Prendre en charge en centre spécialisé (ou à vocation régionale) : nouveau-né à terme &lt; 6 semaines, ancien prématuré &lt; 60 semaines d'âge post-conceptionnel, patients ASA 3 à 5 (risque majoré de complications cardio-respiratoires sévères).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.2.2","style":"cell_b"},{"t":"p","html":"Certains patients ASA 3 peuvent être pris en charge hors centre spécialisé, dans un réseau de soins contractualisé (âge minimal, accord ARS).","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Champ 4 — Effectifs par âge & sources","items":[{"t":"section","text":"Champ 4 — Organisation fonctionnelle (2/2) — Effectifs par âge","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Tranche d'âge","style":"head_w"},{"t":"p","html":"Effectif requis","style":"head_w"}],[{"t":"p","html":"&lt; 1 an, ou ASA 4-5\n(R4.3.1)","style":"cell_b"},{"t":"p","html":"Risque majoré d'arrêt cardiaque/hypoxie : 2 professionnels dédiés exclusivement — ≥ 1 MAR à activité régulière et formation pédiatrique complémentaire, assisté d'un second professionnel d'anesthésie à activité pédiatrique régulière.","style":"cell"}],[{"t":"p","html":"1-3 ans\n(R4.3.2)","style":"cell_b"},{"t":"p","html":"Risque majoré de complications respiratoires : MAR formé dédié + IADE à activité pédiatrique régulière dédié, OU MAR dédié seul avec second professionnel identifié à l'avance immédiatement disponible au bloc. Choix sous la responsabilité exclusive du MAR.","style":"cell"}],[{"t":"p","html":"3-10 ans\n(R4.3.3)","style":"cell_b"},{"t":"p","html":"MAR formé + IADE dédié, OU MAR dédié avec second professionnel identifié à l'avance immédiatement disponible au bloc. Choix sous la responsabilité exclusive du MAR.","style":"cell"}],[{"t":"p","html":"&gt; 10 ans\n(R4.3.4)","style":"cell_b"},{"t":"p","html":"Mêmes règles organisationnelles que chez l'adulte.","style":"cell"}]]},{"t":"p","html":"MAR = médecin anesthésiste-réanimateur ; IADE = infirmier anesthésiste diplômé d'État.","style":"note"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Avis d'experts (accord fort)","style":"head_w"},{"t":"p","html":"","style":"head_w_c"}],[{"t":"p","html":"R4.4.1","style":"cell_b"},{"t":"p","html":"Présence permanente en SSPI d'une infirmière (IDE, IADE ou puéricultrice) formée au réveil pédiatrique.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.4.2","style":"cell_b"},{"t":"p","html":"Associer systématiquement un second professionnel paramédical, pour les spécificités du réveil de l'enfant.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.4.3","style":"cell_b"},{"t":"p","html":"Présence supplémentaire d'une seconde infirmière (IDE, IADE ou puéricultrice) si la SSPI a une capacité ≥ 6 postes.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.5","style":"cell_b"},{"t":"p","html":"Pour une équipe à pratique mixte adulte/pédiatrique, concentrer l'activité pédiatrique sur un nombre limité de praticiens formés et actualisés.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"R4.6","style":"cell_b"},{"t":"p","html":"Collecter les données épidémiologiques/anesthésiques (dont incidents critiques) pour évaluer la qualité des soins par comparaison à la littérature récente.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Méthode :</b> groupe d'experts SFAR-ADARPEF, méthode GRADE prévue en amont, mais les 34 recommandations retenues sont toutes formulées comme avis d'experts, votées par méthode GRADE grid en 2 tours, accord fort pour la totalité.","style":"source"},{"t":"p","html":"<b>Document source :</b> SFAR-ADARPEF, « Organisation structurelle, matérielle et fonctionnelle des centres effectuant de l'anesthésie pédiatrique », RPP, texte validé par le Comité des Référentiels Cliniques de la SFAR le 19/01/2023 et le Conseil d'Administration le 26/01/2023.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/organisation-de-lanesthesie-pediatrique/","style":"source"},{"t":"p","html":"<b>Couverture :</b> intégralité des 34 recommandations (4 champs). Aucune absence de recommandation dans ce document. R4.3.1-4.3.4 (effectifs par tranche d'âge) reproduites intégralement en tableau de recommandations ET résumées en tableau récapitulatif compact pour la lisibilité clinique. Bibliographie et composition nominative du groupe d'experts non reproduites.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend intégralement les 34 recommandations du texte source, mais condense l'argumentaire de chaque item. Elle ne remplace pas le texte intégral et n'est ni éditée ni validée par la SFAR ni l'ADARPEF.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/download/organisation-de-lanesthesie-pediatrique/?wpdmdl=43179';

insert into public.documents (title, doc_type, publication_date, source_url, original_language)
values ('Recommandations pour le fonctionnement des USC dans les établissements de santé', 'Autre', '2018-01-01', 'https://sfar.org/wp-content/uploads/2018/05/EXTE-USC-CNP.pdf', 'non_renseigne')
on conflict (source_url) do nothing;
insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/wp-content/uploads/2018/05/EXTE-USC-CNP.pdf' and s.slug in ('anesthesie_reanimation', 'medecine_intensive_reanimation')
on conflict do nothing;
update public.documents set
  fiche_key = 'organisation_usc_2018',
  card_json = $mgjson${"badge":"Recommandations CNP — 26 items (accord fort uniforme)","title":"Fonctionnement des Unités de Surveillance Continue (USC)","short":"Conseils Nationaux Professionnels de Médecine Intensive Réanimation, d'Anesthésie-Réanimation et de Médecine d'Urgence, « Recommandations pour le fonctionnement des Unités de Surveillance Continue (USC) dans les Établissements de Santé », 2018. Les USC (« soins intermédiaires ») se situent entre une unité de soins standard et la réanimation. Convention de cotation propre à ce document : chaque recommandation est suivie de la seule mention « Accord Fort » — pas de grille GRADE numérique, chip local réutilisé « Fort » (même convention que bris_dentaires, déjà git-trackée). 26 recommandations, toutes à accord fort (décompte vérifié exact, aucune absence de recommandation), sur 5 champs : 1. Typologie des patients (sélection sur critère de sécurité et non de tarif, USC ne se substituant pas à une suppléance d'organe, exclusion des situations de fin de vie) ; 2. Structure des USC (autorisation requise, rattachement à l'autorité de la réanimation si elle existe, projet médical/paramédical spécifique, taille minimale de 6 lits) ; 3. Organisation paramédicale (formation d'adaptation à l'emploi, effectif IDE+AS ≥ 0,4 par lit ouvert, mutualisation des plannings avec la réanimation) ; 4. Organisation médicale (formation en soins critiques, présence médicale 24h/24-7j/7, responsabilité clarifiée selon présence ou non d'une réanimation sur site) ; 5. USC dans le contexte des Groupements Hospitaliers de Territoire (GHT) — organisation en réseau, convention avec la réanimation du GHT, mutualisation du temps médical pour les USC isolées. Inclut le tableau des critères d'admission en USC de l'American College of Critical Care (référence externe citée par le source), reproduit intégralement par appareil (cardiovasculaire, respiratoire, neurologique, intoxications, digestif, endocrinien, chirurgical, divers).","society":"CNP Médecine Intensive Réanimation / Anesthésie-Réanimation / Médecine d'Urgence","version":"2018","validated":"Conseils Nationaux Professionnels concernés","methodology":"Convention « Accord Fort » uniforme (pas de grille GRADE) — 26 recommandations, décompte source exact, aucune absence de recommandation","pages":3,"section":"Réanimation"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"organisation_usc_2018","sections":[{"title":"Champs 1-2 — Typologie des patients & structure des USC","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Résumé :</b> recommandations conjointes des Conseils Nationaux Professionnels de Médecine Intensive Réanimation, Anesthésie-Réanimation et Médecine d'Urgence (2018) sur l'organisation des Unités de Surveillance Continue (USC) — « soins intermédiaires » entre unité standard et réanimation. 26 recommandations (accord fort) sur 5 champs : typologie des patients, structure des USC, organisation paramédicale, organisation médicale, USC dans le contexte des GHT.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"Fort"},{"t":"p","html":"Convention de ce document : chaque recommandation est suivie de la seule mention <b>« Accord Fort »</b> — pas de grille GRADE numérique, pas de distinction avis d'experts/recommandation graduée. 26 recommandations, toutes à accord fort, sur 5 champs. Aucune absence de recommandation dans ce document.","style":"badge_head"}]]},{"t":"section","text":"Champ 1 — Typologie des patients","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R1.1","style":"cell_b"},{"t":"p","html":"Sélectionner les patients pris en charge en USC dans un objectif de sécurité médicale, et non d'éligibilité à un tarif.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R1.2","style":"cell_b"},{"t":"p","html":"Organiser les USC pour prendre en charge des patients à risque de défaillance vitale nécessitant une surveillance rapprochée, avec capacité de faire face à la défaillance et de préparer un transfert rapide en réanimation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R1.3","style":"cell_b"},{"t":"p","html":"Adapter les moyens et compétences des USC aux filières de l'établissement (post-opératoire, urgences, post-réanimation, activités à risque) ; dans les centres sans réanimation, tenir compte des délais de transfert.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R1.4","style":"cell_b"},{"t":"p","html":"Les USC n'ont pas pour mission d'assurer la suppléance d'organe des patients en défaillance, en dehors de la préparation d'un transfert en réanimation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R1.5","style":"cell_b"},{"t":"p","html":"Les USC ne doivent pas recevoir de patients pour engager un processus de fin de vie.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Champ 2 — Structure des USC","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R2.1","style":"cell_b"},{"t":"p","html":"L'existence de lits d'USC dans une structure hospitalière devrait être soumise à autorisation.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R2.2","style":"cell_b"},{"t":"p","html":"Si l'établissement comporte une unité de réanimation, l'USC doit être placée sous la même autorité médicale et paramédicale que cette unité.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R2.3","style":"cell_b"},{"t":"p","html":"Une USC doit avoir un projet médical et paramédical qui lui est spécifique.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R2.4","style":"cell_b"},{"t":"p","html":"Sans unité de réanimation sur site, la mission et l'organisation de l'USC doivent être précisées et intégrées au projet médical des soins critiques du GHT.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R2.5","style":"cell_b"},{"t":"p","html":"Avec unité de réanimation, les lits d'USC peuvent être intégrés à cette unité ou constituer une unité distincte à proximité.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R2.6","style":"cell_b"},{"t":"p","html":"Regrouper le plus possible les lits de soins critiques au sein d'une structure hospitalière.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R2.7","style":"cell_b"},{"t":"p","html":"Ne pas descendre, hors particularités géographiques, en dessous de 6 lits pour une USC.","style":"cell"},{"t":"chip","label":"Fort"}]]}]},{"title":"Champs 3-4 — Organisation paramédicale & médicale","items":[{"t":"section","text":"Champ 3 — Organisation et management paramédical","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R3.1","style":"cell_b"},{"t":"p","html":"L'équipe paramédicale d'une USC doit faire l'objet d'une organisation et d'un projet de soins spécifiques.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R3.2","style":"cell_b"},{"t":"p","html":"Les paramédicaux exerçant en USC doivent recevoir une formation d'adaptation à l'emploi spécifique aux patients à risque de défaillance vitale.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R3.3","style":"cell_b"},{"t":"p","html":"Cette formation doit aborder les aspects techniques, de prévention/qualité, et humains/psychologiques.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R3.4","style":"cell_b"},{"t":"p","html":"L'effectif paramédical (IDE + AS) physiquement présent et affecté aux soins doit être ≥ 0,4 par lit ouvert.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R3.5","style":"cell_b"},{"t":"p","html":"Avec réanimation sur site, mutualiser le planning IDE entre USC et réanimation (rotation des personnels) ; sans réanimation, mutualiser avec les autres soins critiques (urgences, soins intensifs).","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Champ 4 — Organisation et management médical","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R4.1","style":"cell_b"},{"t":"p","html":"Les médecins exerçant en USC doivent avoir une formation initiale ou attestée à l'activité de soins critiques (anesthésie-réanimation, médecine intensive-réanimation ou médecine d'urgence).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R4.2","style":"cell_b"},{"t":"p","html":"L'équipe médicale d'une USC rattachée à un service de réanimation doit être sous la même responsabilité que ce service.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R4.3","style":"cell_b"},{"t":"p","html":"Sans unité de réanimation, l'équipe médicale de l'USC doit être sous la responsabilité d'un médecin exerçant à temps majoritaire dans l'USC.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R4.4","style":"cell_b"},{"t":"p","html":"Assurer la présence d'un médecin sur site 24h/24, 7j/7 (répondant aux critères de R4.1) ; mutualiser la permanence de nuit/week-end/jours fériés avec le service de rattachement (ou les autres soins critiques si pas de réanimation).","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R4.5","style":"cell_b"},{"t":"p","html":"Sans service de réanimation, assurer la formation continue et l'évaluation des pratiques en coopération avec le réseau de soins critiques du GHT.","style":"cell"},{"t":"chip","label":"Fort"}]]}]},{"title":"Champ 5 — GHT, critères d'admission & sources","items":[{"t":"section","text":"Champ 5 — USC dans le contexte des GHT","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"R5.1","style":"cell_b"},{"t":"p","html":"Les GHT doivent organiser la filière de soins critiques intégrant les USC selon le volume et la gravité des filières de patients « à risque ».","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R5.2","style":"cell_b"},{"t":"p","html":"Sans unité de réanimation in situ, l'USC doit établir une convention avec l'unité de réanimation du GHT.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R5.3","style":"cell_b"},{"t":"p","html":"Une USC doit avoir un projet d'unité précisant ses missions au sein du GHT, ses objectifs, et les catégories de patients qu'elle prend en charge.","style":"cell"},{"t":"chip","label":"Fort"}],[{"t":"p","html":"R5.4","style":"cell_b"},{"t":"p","html":"Pour les USC isolées, favoriser le partage de temps médical avec des réanimations partenaires (« pôle de soins critiques inter-établissements »), pour éviter l'isolement et les problèmes d'attractivité.","style":"cell"},{"t":"chip","label":"Fort"}]]},{"t":"section","text":"Tableau — Critères d'admission en USC (American College of Critical Care, cité par le source)","color":"grey"},{"t":"table","rows":[[{"t":"p","html":"Appareil","style":"head_w"},{"t":"p","html":"Indications d'admission en USC","style":"head_w"}],[{"t":"p","html":"Cardiovasculaire","style":"cell_b"},{"t":"p","html":"Suspicion d'IDM ou IDM hémodynamiquement stable ; troubles du rythme bien tolérés ; entraînement électrosystolique stable ; décompensation cardiaque modérée (NYHA 1-2) ; urgence hypertensive sans défaillance d'organe.","style":"cell"}],[{"t":"p","html":"Respiratoire","style":"cell_b"},{"t":"p","html":"Sevrage ventilatoire avec soins chroniques ; défaillance respiratoire stable nécessitant surveillance rapprochée et/ou CPAP ; besoin de soins/kinésithérapie respiratoire intense.","style":"cell"}],[{"t":"p","html":"Neurologique","style":"cell_b"},{"t":"p","html":"AVC stable nécessitant évaluations/nursing rapprochés ; traumatisme crânien aigu Glasgow &gt; 9 sous surveillance ; surveillance post-traitement d'anévrysme cérébral ; fuite de LCR ; trauma médullaire cervical stable ; hémorragie méningée non sévère en attente de sécurisation.","style":"cell"}],[{"t":"p","html":"Intoxications","style":"cell_b"},{"t":"p","html":"Surveillance cardiaque/pulmonaire/neurologique après intoxication médicamenteuse chez un patient stable.","style":"cell"}],[{"t":"p","html":"Digestif","style":"cell_b"},{"t":"p","html":"Hémorragie digestive modérée répondant au remplissage ; rupture de VO de faible intensité chez un patient stable ; insuffisance hépatocellulaire aiguë sans gravité vitale.","style":"cell"}],[{"t":"p","html":"Endocrinien","style":"cell_b"},{"t":"p","html":"Acidocétose ou décompensation hyperosmolaire sans coma ; thyrotoxicose/coma myxœdémateux.","style":"cell"}],[{"t":"p","html":"Chirurgical","style":"cell_b"},{"t":"p","html":"Transfusion/remplissage postopératoire chez un patient stable ; 24 premières heures postopératoires à soins infirmiers rapprochés (carotide, chirurgie vasculaire périphérique, neurochirurgie, greffe rénale…).","style":"cell"}],[{"t":"p","html":"Divers","style":"cell_b"},{"t":"p","html":"Sepsis stable sans choc ni défaillance d'organe ; monitorage du remplissage vasculaire ; pré-éclampsie/éclampsie ; soins infirmiers lourds ou pansements complexes.","style":"cell"}]]},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Document source :</b> Conseils Nationaux Professionnels de Médecine Intensive Réanimation, d'Anesthésie-Réanimation et de Médecine d'Urgence, « Recommandations pour le fonctionnement des Unités de Surveillance Continue (USC) dans les Établissements de Santé », 2018.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/wp-content/uploads/2018/05/EXTE-USC-CNP.pdf","style":"source"},{"t":"p","html":"<b>Couverture :</b> intégralité des 26 recommandations (5 champs), toutes à accord fort — aucune absence de recommandation dans ce document. Le tableau des critères d'admission ACCC (référence externe citée par le source) est reproduit intégralement. L'Annexe 1 (actes consommateurs de temps IDE) et les Tableaux 1-3 (valorisation tarifaire, organisation, charge en soins) ne sont pas retranscrits — administratifs/méthodologiques, non actionnables au chevet. Bibliographie et composition nominative du groupe de travail non reproduites.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante, produite pour un usage d'aide-mémoire. Elle reprend intégralement les 26 recommandations du texte source, mais condense l'argumentaire de chaque item. Elle ne remplace pas le texte intégral et n'est ni éditée ni validée par les Conseils Nationaux Professionnels concernés.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2018/05/EXTE-USC-CNP.pdf';

insert into public.documents (title, doc_type, publication_date, source_url, original_language)
values ('Transfusion de globules rouges homologues : produits, indications alternatives', 'RBP', '2014-01-01', 'https://sfar.org/wp-content/uploads/2015/10/2_HAS_transfusion_de_globules_rouges_homologues_-_produits_indications_alternatives_-_recommandations.pdf', 'non_renseigne')
on conflict (source_url) do nothing;
insert into public.document_specialties (document_id, specialty_id)
