update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Gestion-perioperatoire-des-traitements-chroniques-et-dispositifs-medicaux.pdf#gestion_traitements_chroniques_cardio_2009' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'gestion_traitements_chroniques_cardio_2009',
  card_json = $mgjson${"badge":"SFAR RFE 2009 — Module 1/4 (périmètre limité)","title":"Gestion périopératoire des traitements chroniques — Cardiovasculaire","short":"SFAR, « Gestion périopératoire des traitements chroniques et dispositifs médicaux », Recommandations Formalisées d'Experts, Ann Fr Anesth Réanim 28 (2009) 1037-1045. Le référentiel complet fusionne en réalité plusieurs articles distincts publiés entre 2009 et 2011, correspondant aux 4 modules annoncés par son Préambule (Cardiovasculaire ; Douleur chronique/toxicomanie ; Infectieux/immunosuppresseurs ; Neurologique-psychiatrique et/ou endocrinien). Cette fiche couvre UNIQUEMENT le Module 1 — Pathologies cardiovasculaires (le plus transversal à toute anesthésie programmée) : bêtabloquants, inhibiteurs calciques, diurétiques, activateurs des canaux potassiques (nicorandil), inhibiteurs du SRAA (IEC/sartans), dérivés nitrés, statines, antiarythmiques (classes I et III de Vaughan-Williams), et stimulateurs cardiaques/défibrillateurs automatiques implantables (DCI, section pratique non gradée). Les 3 autres modules sont traités dans des fiches séparées. Les traitements antithrombotiques (antiagrégants plaquettaires, AVK) sont explicitement exclus de l'ensemble du référentiel par son comité d'organisation lui-même (déjà couverts par d'autres textes SFAR/HAS distincts, sans risque de chevauchement). Grille ANAES 2004 A/B/C/D — D étant systématiquement renforcé par méthode Delphi en « accord fort » (chip local AF) dans ce module. 15 recommandations gradées (A:0, B:3, C:3, AF:9) + 1 recommandation explicitement non gradée par la source elle-même (antiarythmiques classe I) + 1 section pratique non gradée (stimulateurs cardiaques/DCI, incluant 2 points explicitement signalés par la source comme ne faisant pas l'objet d'un consensus).","society":"SFAR (Société française d'anesthésie et de réanimation)","version":"2009","validated":"Comité des référentiels de la SFAR","methodology":"Grille ANAES 2004 A/B/C/D (D renforcé en « accord fort » par méthode Delphi) — 15 recommandations gradées + 1 non gradée, Module 1/4 uniquement (pathologies cardiovasculaires)","pages":4,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"gestion_traitements_chroniques_cardio_2009","sections":[{"title":"Bêtabloquants & inhibiteurs calciques","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Périmètre limité :</b> le référentiel SFAR complet (2009-2011) comporte 4 modules distincts (Cardiovasculaire ; Douleur chronique/toxicomanie ; Infectieux/immunosuppresseurs ; Neurologique-psychiatrique et/ou endocrinien). Cette fiche couvre UNIQUEMENT le <b>Module 1 — Pathologies cardiovasculaires</b> (le plus transversal à toute anesthésie programmée). Les 3 autres modules ne sont pas traités — hors périmètre de cette fiche, disclosed explicitement, à construire séparément. Les traitements antithrombotiques (antiagrégants plaquettaires, AVK) sont explicitement exclus de l'ensemble du référentiel par son comité d'organisation lui-même (déjà couverts par d'autres textes SFAR/HAS distincts).","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"A"},{"t":"chip","label":"B"},{"t":"chip","label":"C"},{"t":"chip","label":"AF"},{"t":"p","html":"<b>Grille ANAES 2004</b> — <b>A</b> : preuve scientifique établie ; <b>B</b> : présomption scientifique ; <b>C</b> : faible niveau de preuve ; <b>AF</b> : accord fort (grade D — accord professionnel — renforcé par méthode Delphi à 2 tours, seule forme de grade D imprimée dans ce module). Fiche limitée au Module 1/4 du référentiel (pathologies cardiovasculaires) — voir encadré de périmètre ci-dessous.","style":"badge_head"}]]},{"t":"section","text":"Bêtabloquants","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Bêtabloquants","style":"cell_b"},{"t":"p","html":"Ne pas interrompre le traitement chronique en périopératoire ; administrer le matin de l'intervention avec la prémédication, reprendre le plus rapidement possible (relais parentéral si voie orale indisponible).","style":"cell"},{"t":"chip","label":"AF"}]]},{"t":"p","html":"<i>Précision du source :</i> traitement chronique bien toléré sur le plan hémodynamique en périopératoire (grade C) ; possibilité d'hypotension artérielle ou de bradycardie lors de l'anesthésie si la posologie est titrée sur la fréquence cardiaque, d'autant plus que l'intensité du traitement est forte (grade A). Avis cardiologique non indispensable ; aucune technique d'anesthésie n'est spécifiquement contre-indiquée.","style":"note"},{"t":"section","text":"Inhibiteurs calciques","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Inhib. calciques","style":"cell_b"},{"t":"p","html":"Poursuite du traitement (visée antiarythmique ou antihypertensive) recommandée en périopératoire.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Inhib. calciques","style":"cell_b"},{"t":"p","html":"Éviter la bupivacaïne périmédullaire (notamment péridurale) chez le patient traité au long cours par vérapamil (risque d'hypotension ou de bradycardie).","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Inhib. calciques","style":"cell_b"},{"t":"p","html":"Préférer l'isoflurane, le desflurane ou le sévoflurane à l'halothane chez le patient traité par vérapamil (association délétère par addition d'effets dépresseurs myocardiques).","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Inhib. calciques","style":"cell_b"},{"t":"p","html":"Préférer la lidocaïne à la bupivacaïne pour toute ALR chez le patient traité par diltiazem ou vérapamil — mais cette association peut augmenter expérimentalement la toxicité cardiaque de la lidocaïne.","style":"cell"},{"t":"chip","label":"B"}]]}]},{"title":"Diurétiques, nicorandil & inhibiteurs du SRAA","items":[{"t":"section","text":"Diurétiques","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Diurétiques","style":"cell_b"},{"t":"p","html":"Ne pas administrer les diurétiques le matin de l'intervention (contrôle de la kaliémie souhaitable).","style":"cell"},{"t":"chip","label":"AF"}]]},{"t":"section","text":"Activateurs des canaux potassiques (nicorandil)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Nicorandil","style":"cell_b"},{"t":"p","html":"Ne pas interrompre le nicorandil en préopératoire.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Nicorandil","style":"cell_b"},{"t":"p","html":"À la posologie orale de 20 mg/j, peut être poursuivi et administré en prémédication sans conséquence hémodynamique notoire lors de l'anesthésie.","style":"cell"},{"t":"chip","label":"B"}]]},{"t":"section","text":"Inhibiteurs du SRAA (IEC et sartans)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"IEC / sartans","style":"cell_b"},{"t":"p","html":"Interrompre au moins 12 heures avant l'intervention lorsqu'ils constituent un traitement de fond de l'hypertension artérielle.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"IEC / sartans","style":"cell_b"},{"t":"p","html":"Maintenir lorsqu'ils sont prescrits dans le cadre d'une insuffisance cardiaque — risque d'hypotension à prendre en compte si chirurgie majeure ou rachianesthésie.","style":"cell"},{"t":"chip","label":"AF"}]]}]},{"title":"Dérivés nitrés, statines & antiarythmiques classe I","items":[{"t":"section","text":"Dérivés nitrés","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Dérivés nitrés","style":"cell_b"},{"t":"p","html":"Ne pas interrompre les dérivés nitrés par voie orale en préopératoire.","style":"cell"},{"t":"chip","label":"AF"}]]},{"t":"section","text":"Statines","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Statines","style":"cell_b"},{"t":"p","html":"Ne pas interrompre le traitement chronique en périopératoire ; administrer le soir précédant l'intervention, reprendre le soir de l'intervention.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Statines","style":"cell_b"},{"t":"p","html":"En cas d'interruption du transit intestinal et d'absence de forme parentérale disponible, une administration par sonde nasogastrique est recommandée.","style":"cell"},{"t":"chip","label":"C"}]]},{"t":"p","html":"<i>Précision du source :</i> l'arrêt d'un traitement chronique par statines est associé à une augmentation des complications coronaires postopératoires par effet rebond (grade C) ; la fréquence des élévations des marqueurs musculaires biologiques n'est pas augmentée en cas de traitement chronique, malgré un risque théorique de rhabdomyolyse (grade C, absence de preuve liée au caractère exceptionnel de cette complication). Avis cardiologique non nécessaire.","style":"note"},{"t":"section","text":"Antiarythmiques — classe I de Vaughan-Williams","color":"navy"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Non gradée par la source :</b> interrompre 24 heures avant une intervention chirurgicale programmée un traitement oral par antiarythmique de classe I (quinidine, procaïnamide, disopyramide, lidocaïne, mexilétine, diphénylhydantoïne, flécaïnide, propafénone, cibenzoline) prescrit en prévention primaire de la fibrillation auriculaire — seul énoncé prescriptif de cette section sans grade ni accord attaché par la source elle-même (aucun grade inventé ici).","style":"body_sm"}}]},{"title":"Antiarythmiques classe III & stimulateurs cardiaques","items":[{"t":"section","text":"Antiarythmiques — classe III de Vaughan-Williams","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Amiodarone","style":"cell_b"},{"t":"p","html":"Poursuivie sans interruption jusqu'au matin de l'intervention (en raison de sa longue demi-vie d'élimination).","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Sotalol","style":"cell_b"},{"t":"p","html":"Ne doit pas être interrompu brutalement avant une intervention chirurgicale (risque de troubles du rythme graves, d'infarctus ou de mort subite chez le patient coronarien).","style":"cell"},{"t":"chip","label":"AF"}]]},{"t":"section","text":"Stimulateurs cardiaques et défibrillateurs automatiques implantables (DCI)","color":"grey"},{"t":"p","html":"<b>Section non gradée par la source</b> (aucun A/B/C/D attaché à aucun moment) — reproduite ici en repère pratique condensé plutôt qu'en tableau de recommandations gradées, pour ne pas inventer de grade absent du texte source.","style":"body_sm"},{"t":"p","html":"<b>Interférences électromagnétiques (IEM)</b> : risques — inhibition de la stimulation (bradycardie ventriculaire), passage transitoire en mode asynchrone, reprogrammation aléatoire (exceptionnelle). Sources : bistouri électrique (favorisé par courant puissant, mode monopolaire, application prolongée, boîtier dans l'axe plaque-site), ablation par radiofréquence, lithotripsie, IRM (contre-indiquée).","style":"body_sm"},{"t":"p","html":"<b>Bistouri électrique</b> : privilégier le mode bipolaire ; courant de coagulation le plus faible possible ; application brève et intermittente ; boîtier hors de l'axe reliant le site de coagulation et la plaque de terre.","style":"body_sm"},{"t":"p","html":"<b>Aimant sur le boîtier</b> : pour un DCI implanté en France, inhibe la fonction antiarythmique sans modifier la stimulation, le temps de l'application. Certains DCI (non implantés en France au moment du texte) peuvent voir cette fonction inhibée de façon permanente après application prolongée (&gt; 30 min) — surveillance continue du rythme jusqu'à confirmation de la réactivation.","style":"body_sm"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Absence de consensus (signalée par la source elle-même) :</b> la reprogrammation préopératoire du stimulateur en mode asynchrone chez le patient stimulo-dépendant, et la déprogrammation de la fonction d'asservissement, peuvent être proposées mais ne font l'une ni l'autre l'objet d'un consensus selon la source.","style":"body_sm"}},{"t":"p","html":"<b>Avis spécialisé</b> (cardiologue traitant) à obtenir si : symptômes fonctionnels ; dernier contrôle ancien (stimulateur &gt; 1 an, DCI &gt; 3 mois) ; besoin de reprogrammation. <b>Choc électrique externe (CEE)</b> : vérification du stimulateur/DCI indispensable après le choc ; électrodes en position antéropostérieure chez le porteur d'un DCI actif. <b>Postopératoire</b> : vérification du stimulateur/DCI exposé à une IEM recommandée ; reprogrammation si anomalie ou si le programme avait été modifié en préopératoire.","style":"body_sm"},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Document source :</b> Société française d'anesthésie et de réanimation (SFAR), « Gestion périopératoire des traitements chroniques et dispositifs médicaux — Pathologies cardiovasculaires », Recommandations Formalisées d'Experts, Annales Françaises d'Anesthésie et de Réanimation 28 (2009) 1037-1045.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/gestion-perioperatoire-des-traitements-chroniques-et-dispositifs-medicaux-anti-infectieux-immunosuppresseurs/","style":"source"},{"t":"p","html":"<b>Couverture :</b> Module 1/4 du référentiel uniquement (pathologies cardiovasculaires) — 15 recommandations gradées (A/B/C/accord fort) + 1 recommandation explicitement non gradée par la source + 1 section pratique non gradée (stimulateurs cardiaques/DCI). Les modules Douleur chronique/toxicomanie, Infectieux/immunosuppresseurs, et Neurologique-psychiatrique/endocrinien ne sont pas couverts — hors périmètre de cette fiche, disclosed en page 1. Traitements antithrombotiques (antiagrégants, AVK) hors périmètre de l'ensemble du référentiel (couverts par d'autres textes SFAR/HAS). Argumentaire scientifique détaillé (document source complet) non reproduit.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante et PARTIELLE (Module 1 uniquement). Elle ne remplace pas le texte intégral — en particulier pour toute question relevant des 3 autres modules du référentiel. Cette fiche n'est ni éditée ni validée par la SFAR.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Gestion-perioperatoire-des-traitements-chroniques-et-dispositifs-medicaux.pdf#gestion_traitements_chroniques_cardio_2009';

