update public.documents set
  fiche_key = 'gestion_traitements_chroniques_infectieux_2009',
  card_json = $mgjson${"badge":"SFAR RFE 2009 — Module 3/4 (périmètre limité)","title":"Gestion périopératoire des traitements chroniques — Anti-infectieux, immunosuppresseurs","short":"SFAR, « Gestion périopératoire des traitements chroniques et dispositifs médicaux — Anti-infectieux, immunosuppresseurs », RFE, Ann Fr Anesth Réanim 28 (2009) 1057-1065. Même document source composite que les Modules 1, 2 et 4 (fiches séparées — la fiche bibliothèque de ce document source unique renvoie vers le Module 1 ; accédez à ce Module 3 directement via cette carte ou la barre latérale). Ce module ACHÈVE la couverture des 4 modules effectivement présents dans le PDF fusionné de ce référentiel. Couvre : antituberculeux, antirétroviraux, et 6 immunosuppresseurs distincts — inhibiteurs de calcineurine (ciclosporine, tacrolimus), thalidomide, méthotrexate, azathioprine, mycophénolate mofétil, cyclophosphamide, anticorps monoclonaux anti-TNF. Seuls deux grades apparaissent effectivement dans ce module (grille ANAES 2004) : grade C (faible niveau de preuve) et accord fort (grade D renforcé par méthode Delphi, même convention que les Modules 1/2) — aucune citation A, B ou D nu. 30 lignes de recommandations gradées (accord fort:16, grade C:14) ; le module anti-TNF consolide 3 citations de même grade portant sur le même scénario clinique (dont une phrase source dupliquée mot pour mot dans le texte) en une seule ligne, sans jamais fusionner des grades différents.","society":"SFAR (Société française d'anesthésie et de réanimation)","version":"2009","validated":"Comité des référentiels de la SFAR","methodology":"Grille ANAES 2004 — seuls grade C et accord fort apparaissent dans ce module — 30 lignes de recommandations gradées, Module 3/4 uniquement (anti-infectieux, immunosuppresseurs)","pages":3,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"gestion_traitements_chroniques_infectieux_2009","sections":[{"title":"Antituberculeux & antirétroviraux","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Périmètre limité :</b> le référentiel SFAR complet (2009-2011) comporte 4 modules (Cardiovasculaire, Douleur chronique/toxicomanie et Neurologique-psychiatrique/phytothérapie, traités dans des fiches séparées). Cette fiche couvre le Module 3 — anti-infectieux, immunosuppresseurs.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"C"},{"t":"chip","label":"AF"},{"t":"p","html":"<b>Grille ANAES 2004</b> — seuls deux grades apparaissent effectivement dans ce module : <b>C</b> : faible niveau de preuve ; <b>AF</b> : accord fort (grade D renforcé par méthode Delphi, même convention que les Modules 1 et 2). Fiche limitée au Module 3/4 du référentiel (anti-infectieux, immunosuppresseurs) — voir encadré de périmètre ci-dessous.","style":"badge_head"}]]},{"t":"section","text":"Antituberculeux","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Antituberculeux","style":"cell_b"},{"t":"p","html":"Poursuivre le traitement instauré aux mêmes posologies et par voie orale, ainsi que la supplémentation vitaminique associée (B1 et B6).","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Antituberculeux","style":"cell_b"},{"t":"p","html":"En cas de nécessité d'interruption prolongée du traitement, une prise en charge pluridisciplinaire est recommandée.","style":"cell"},{"t":"chip","label":"AF"}]]},{"t":"p","html":"<i>Précision du source :</i> isoniazide/rifampicine/thioamides favorisent une toxicité hépatique ; la rifampicine est inductrice enzymatique (majorer de 30-50% la posologie des corticoïdes associés) et peut provoquer une thrombopénie (à écarter avant chirurgie) ; aminosides potentiellement néphrotoxiques (monitorage rénal) ; surveillance glycémique sous thioamides. Agents anesthésiques : thiopental proscrit (induction enzymatique majore l'hépatotoxicité) ; halothane et enflurane contre-indiqués ; propofol, isoflurane, desflurane et sévoflurane utilisables raisonnablement avec surveillance hépatique rapprochée. Curares : mivacurium/atracurium/cisatracurium indiqués si atteinte hépatique (métabolisme indépendant) ; prudence si traitement par aminoside (potentialisation du bloc). Isolement respiratoire obligatoire si traitement < 15 jours (circulaire DGS/VS-DH n° 69 du 29/10/1993) ; BK tubage en urgence au-delà. Éviter les fortes doses de paracétamol. Relais IV possible pour isoniazide, éthambutol et rifampicine uniquement ; avis spécialisé indispensable pour les autres molécules (guidé par l'antibiogramme). Adaptations posologiques en cas d'insuffisance rénale (clairance < 30 ml/min) et de toxicité hépatique (paliers selon les transaminases) détaillées dans le texte source.","style":"note"},{"t":"section","text":"Antirétroviraux","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Antirétroviraux","style":"cell_b"},{"t":"p","html":"En raison de l'importance de l'observance, les arrêts de traitement doivent être évités en période périopératoire.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Antirétroviraux","style":"cell_b"},{"t":"p","html":"Toute interruption non évitable (jeûne préopératoire) sera la plus courte possible, au plus 48 heures maximum.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Antirétroviraux","style":"cell_b"},{"t":"p","html":"En cas d'arrêt, tous les antirétroviraux doivent être interrompus et repris simultanément (éviter une monothérapie, source de résistance virale).","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Antirétroviraux","style":"cell_b"},{"t":"p","html":"Tout arrêt de traitement doit faire l'objet d'un avis spécialisé.","style":"cell"},{"t":"chip","label":"AF"}]]},{"t":"p","html":"<i>Précision du source :</i> les inhibiteurs de protéase (IP) nécessitent une prise alimentaire concomitante, incompatible avec le jeûne préopératoire. Rifampicine contre-indiquée avec les IP non associés au ritonavir (monitorage thérapeutique obligatoire si nécessité impérative). Risque d'acutisation d'une hépatite B chronique à l'arrêt prolongé d'un antirétroviral actif sur ce virus (lamivudine, ténofovir, emtricitabine). Interactions via les cytochromes P450 (CYP2B6, CYP3A4) avec de nombreux médicaments d'anesthésie ; midazolam potentiellement majoré (dépression respiratoire, somnolence). Neuropathie sous INTI (ex. didanosine) à prendre en compte pour l'ALR périnerveuse. En réanimation prolongée : monitorage thérapeutique nécessaire (absence de forme injectable pour la plupart des molécules, altération de l'absorption digestive).","style":"note"}]},{"title":"Immunosuppresseurs & sources","items":[{"t":"section","text":"Inhibiteurs de calcineurine (ciclosporine, tacrolimus)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Inhib. calcineurine","style":"cell_b"},{"t":"p","html":"La poursuite de l'immunosuppression peut s'accompagner d'un risque plus élevé d'infections postopératoires.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Inhib. calcineurine","style":"cell_b"},{"t":"p","html":"Monitorage indispensable (et possible diminution des doses) des curares non dépolarisants — la ciclosporine peut augmenter l'intensité et la durée de la curarisation.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Inhib. calcineurine","style":"cell_b"},{"t":"p","html":"Le midazolam et la lidocaïne diminueraient le métabolisme du tacrolimus.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Inhib. calcineurine","style":"cell_b"},{"t":"p","html":"De grandes modifications des taux sanguins sont possibles en cas de remplissage massif périopératoire ou de circulation extracorporelle.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Inhib. calcineurine","style":"cell_b"},{"t":"p","html":"Surveiller les taux plasmatiques et la fonction rénale en concertation avec le spécialiste en charge de l'immunosuppression du patient.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Inhib. calcineurine","style":"cell_b"},{"t":"p","html":"La reprise précoce du traitement est nécessaire (voie orale ou intraveineuse selon la situation).","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Inhib. calcineurine","style":"cell_b"},{"t":"p","html":"Si la voie entérale est compromise, il est possible d'administrer le traitement par voie intraveineuse.","style":"cell"},{"t":"chip","label":"C"}]]},{"t":"p","html":"<i>Précision du source :</i> ne pas donner la ciclosporine le matin de l'intervention en cas d'AG (le tacrolimus peut être poursuivi par voie sublinguale) ; éviter les AINS (potentiel néphrotoxique en association) ; monitorage des taux indispensable quelle que soit la technique d'anesthésie (C2 pour la ciclosporine, taux résiduel pour le tacrolimus).","style":"note"},{"t":"section","text":"Thalidomide","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Thalidomide","style":"cell_b"},{"t":"p","html":"Ne pas interrompre la thalidomide, en tenant compte de la fréquence des neuropathies et du risque de maladie thromboembolique veineuse.","style":"cell"},{"t":"chip","label":"AF"}]]},{"t":"p","html":"<i>Précision du source :</i> évaluation précise d'une éventuelle neuropathie périphérique avant toute ALR (touche en particulier les nerfs saphènes externes et médians, peut persister après l'arrêt) ; prévention efficace du risque thromboembolique veineux périopératoire.","style":"note"},{"t":"section","text":"Méthotrexate","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Méthotrexate","style":"cell_b"},{"t":"p","html":"Une toxicité médullaire et muqueuse est fortement suspectée en présence de protoxyde d'azote.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Méthotrexate","style":"cell_b"},{"t":"p","html":"Les AINS sont contre-indiqués pour l'analgésie (potentialisation de la toxicité hématologique et rénale).","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Méthotrexate","style":"cell_b"},{"t":"p","html":"Ne pas interrompre le traitement, en tenant compte de la toxicité hématologique et rénale, en particulier en association avec le protoxyde d'azote ou les AINS en périopératoire.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Méthotrexate","style":"cell_b"},{"t":"p","html":"En cas de maintien ou de reprise précoce, il est conseillé de ne pas utiliser de protoxyde d'azote durant l'anesthésie.","style":"cell"},{"t":"chip","label":"C"}]]},{"t":"section","text":"Azathioprine","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Azathioprine","style":"cell_b"},{"t":"p","html":"Le taux d'infection postopératoire après induction de l'immunosuppression pour transplantation n'est pas élevé.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Azathioprine","style":"cell_b"},{"t":"p","html":"Dans le contexte de la chirurgie colique, le maintien n'est pas associé à un risque accru de complications postopératoires.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Azathioprine","style":"cell_b"},{"t":"p","html":"La posologie de curare semble pouvoir être identique à celle utilisée chez le sujet sain, malgré une diminution de leur effet par l'azathioprine.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Azathioprine","style":"cell_b"},{"t":"p","html":"Administrer le traitement avec la prémédication.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Azathioprine","style":"cell_b"},{"t":"p","html":"En cas d'interruption prolongée, se concerter avec le spécialiste prenant en charge le patient pour ce traitement.","style":"cell"},{"t":"chip","label":"AF"}]]},{"t":"section","text":"Mycophénolate mofétil","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Mycophénolate","style":"cell_b"},{"t":"p","html":"Administrer le traitement avec la prémédication.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Mycophénolate","style":"cell_b"},{"t":"p","html":"En cas d'interruption prolongée, se concerter avec le spécialiste prenant en charge le patient pour ce traitement.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Mycophénolate","style":"cell_b"},{"t":"p","html":"Il n'y a pas d'intérêt au dosage de la molécule pour le suivi thérapeutique ou l'adaptation posologique.","style":"cell"},{"t":"chip","label":"C"}]]},{"t":"section","text":"Cyclophosphamide","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Cyclophosphamide","style":"cell_b"},{"t":"p","html":"L'effet des curares dépolarisants peut être prolongé chez les patients ayant reçu du cyclophosphamide, même à distance de la prise.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Cyclophosphamide","style":"cell_b"},{"t":"p","html":"Administrer le traitement avec la prémédication.","style":"cell"},{"t":"chip","label":"AF"}],[{"t":"p","html":"Cyclophosphamide","style":"cell_b"},{"t":"p","html":"En cas d'interruption prolongée, se concerter avec le spécialiste prenant en charge le patient pour ce traitement.","style":"cell"},{"t":"chip","label":"AF"}]]},{"t":"section","text":"Anticorps monoclonaux anti-TNF (infliximab, adalimumab, étanercept)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Classe","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Anti-TNF","style":"cell_b"},{"t":"p","html":"Dans le contexte de la chirurgie colique (maladie de Crohn ou RCH), le traitement n'est pas associé à un risque accru de complications postopératoires et pourra être poursuivi.","style":"cell"},{"t":"chip","label":"C"}]]},{"t":"p","html":"<i>Précision du source :</i> compte tenu du risque potentiel de sepsis et de la demi-vie longue de ces traitements, il est conseillé de les arrêter une semaine avant une chirurgie programmée (hors contexte Crohn/RCH ci-dessus) ; reprise possible la semaine suivant l'intervention en l'absence de complication.","style":"note"},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Document source :</b> Société française d'anesthésie et de réanimation (SFAR), « Gestion périopératoire des traitements chroniques et dispositifs médicaux — Anti-infectieux, immunosuppresseurs », Recommandations Formalisées d'Experts, Annales Françaises d'Anesthésie et de Réanimation 28 (2009) 1057-1065.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/gestion-perioperatoire-des-traitements-chroniques-et-dispositifs-medicaux-anti-infectieux-immunosuppresseurs/","style":"source"},{"t":"p","html":"<b>Couverture :</b> Module 3/4 du référentiel uniquement (anti-infectieux, immunosuppresseurs) — 30 lignes de recommandations gradées (accord fort:16, grade C:14 ; consolidation de 3 citations de même grade sur le même scénario clinique dans le module anti-TNF, dont une phrase source dupliquée mot pour mot). Ce module achève la couverture des 4 modules effectivement présents dans le PDF fusionné de ce référentiel (Cardiovasculaire, Douleur chronique/toxicomanie et Neurologique-psychiatrique/phytothérapie, traités dans des fiches séparées). Argumentaire scientifique détaillé (document source complet) non reproduit.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante et PARTIELLE (Module 3 uniquement). Elle ne remplace pas le texte intégral. Cette fiche n'est ni éditée ni validée par la SFAR.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Gestion-perioperatoire-des-traitements-chroniques-et-dispositifs-medicaux.pdf#gestion_traitements_chroniques_infectieux_2009';

insert into public.documents (title, doc_type, publication_date, source_url, original_language)
values ('Délivrance de l’information à la personne sur son état de santé', 'RBP', '2010-01-01', 'https://sfar.org/wp-content/uploads/2015/10/2a_HAS_texte-court_Delivrance-de-linformation-a-la-personne-sur-son-etat-de-sante.pdf', 'non_renseigne')
on conflict (source_url) do nothing;
insert into public.document_specialties (document_id, specialty_id)
select d.id, s.id from public.documents d, public.specialties s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2a_HAS_texte-court_Delivrance-de-linformation-a-la-personne-sur-son-etat-de-sante.pdf' and s.slug in ('anesthesie_reanimation', 'infirmierere_anesthesiste_iade', 'medecine_intensive_reanimation')
on conflict do nothing;
insert into public.document_societies (document_id, society_id)
select d.id, s.id from public.documents d, public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2a_HAS_texte-court_Delivrance-de-linformation-a-la-personne-sur-son-etat-de-sante.pdf' and s.acronym in ('HAS')
on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2a_HAS_texte-court_Delivrance-de-linformation-a-la-personne-sur-son-etat-de-sante.pdf' and d.society_id is null and s.acronym = 'HAS';
update public.documents set
  fiche_key = 'delivrance_information_2012',
  card_json = $mgjson${"badge":"HAS — RBP, mai 2012","title":"Délivrance de l'information à la personne sur son état de santé","short":"HAS, « Délivrance de l'information à la personne sur son état de santé », Recommandation de Bonne Pratique, validée par le Collège de la HAS en mai 2012. Actualise et remplace « Information des patients — Recommandations destinées aux médecins » (ANAES, mars 2000, désormais lien mort). Couvre : le contenu et les qualités de l'information (ce qu'elle doit contenir, comment la délivrer pour qu'elle soit comprise) ; les modalités de délivrance (entretien individuel, accompagnant, personne de confiance, documents écrits, coordination entre professionnels, traçabilité) ; l'information du mineur, du majeur protégé ou du majeur inapte à recevoir l'information (cas particuliers détaillés) ; l'évaluation de l'information donnée. Grille HAS A/B/C/AE définie en préambule mais jamais citée individuellement — la source énonce explicitement que l'absence de données scientifiques suffisantes fait reposer toutes les recommandations sur un accord d'experts (AE), appliqué uniformément aux 28 items de la fiche. Divergence disclosed : l'index bibliothèque date ce document de 2010, mais le document lui-même affiche mai 2012 comme date de validation par le Collège de la HAS ; le lien PDF direct de l'index contient aussi une coquille (corrigée pour cette fiche).","society":"HAS (Haute Autorité de Santé)","version":"2012","validated":"Collège de la HAS, mai 2012","methodology":"Grille HAS A/B/C/AE définie mais jamais citée individuellement — source explicite : absence de données suffisantes, toutes les recommandations reposent sur un accord d'experts (AE) — 28 items, couverture intégrale des 4 sections","pages":3,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"delivrance_information_2012","sections":[{"title":"Le contenu et les qualités de l'information","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Périmètre :</b> ces recommandations actualisent et remplacent « Information des patients — Recommandations destinées aux médecins » (ANAES, mars 2000). Elles N'ABORDENT PAS : l'information sur des risques inconnus au moment de l'acte et révélés ultérieurement par la science ; l'information sur les circonstances et causes d'un dommage lié aux soins ; les pratiques de bioéthique ; l'information en fin de vie (régie par la loi du 22 avril 2005). Elles concernent l'ensemble des professionnels de santé (pas seulement les médecins).","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"AE"},{"t":"p","html":"Convention de ce document : la grille HAS A/B/C/AE est définie en préambule, mais aucune citation individuelle n'apparaît dans le texte — la source énonce explicitement que « toutes les recommandations reposent sur un accord entre experts » (absence de données permettant un grade). Chip <b>AE</b> (accord d'experts) appliqué uniformément.","style":"badge_head"}]]},{"t":"section","text":"1. Le contenu et les qualités de l'information","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Contenu","style":"cell_b"},{"t":"p","html":"L'information porte sur l'état de santé, les investigations/traitements/actions de prévention envisagés, pour permettre à la personne de décider en connaissance de cause ; le professionnel décrit le suivi proposé et répond aux questions.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Contenu","style":"cell_b"},{"t":"p","html":"Elle porte sur : l'état de santé et son évolution habituelle (avec et sans traitement, qualité de vie) ; la description et le déroulement des actes envisagés et l'existence d'alternatives ; leurs objectifs, bénéfices, inconvénients, complications et risques fréquents ou graves prévisibles ; les précautions recommandées ; les modalités de suivi.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Contenu","style":"cell_b"},{"t":"p","html":"Présenter les différents choix possibles pour permettre à la personne de se représenter les enjeux de sa décision, quelle qu'elle soit (accord ou refus).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Qualités","style":"cell_b"},{"t":"p","html":"L'information est synthétique, hiérarchisée, compréhensible et personnalisée ; elle présente les alternatives, puis les bénéfices attendus, puis les inconvénients et risques éventuels.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Qualités","style":"cell_b"},{"t":"p","html":"Elle porte sur les risques fréquents et, pour les risques normalement prévisibles, sur les risques graves (pronostic vital ou fonctionnel), ainsi que sur les risques spécifiques à la personne et les précautions particulières associées.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Qualités","style":"cell_b"},{"t":"p","html":"Le professionnel s'assure de la compréhension (ex. faire reformuler), indique la proposition qu'il préfère en expliquant ses raisons, et propose un second avis si nécessaire.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Les modalités de la délivrance de l'information","items":[{"t":"section","text":"2. Les modalités de la délivrance de l'information","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Entretien individuel","style":"cell_b"},{"t":"p","html":"La délivrance se fait toujours dans le cadre d'un entretien individuel, avec tact et disponibilité ; elle peut être progressive, réitérée et actualisée si nécessaire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Entretien individuel","style":"cell_b"},{"t":"p","html":"La volonté d'une personne de ne pas être informée est respectée, sauf lorsque des tiers sont exposés à un risque de transmission.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Avec accompagnant","style":"cell_b"},{"t":"p","html":"S'assurer du souhait de présence de l'accompagnant et proposer qu'une partie de l'entretien se fasse en tête-à-tête, sauf opposition de la personne.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Avec accompagnant","style":"cell_b"},{"t":"p","html":"Recourir à un interprète pour une personne étrangère, ou à un assistant de communication en cas de handicap sensoriel ou moteur, est recommandé.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Personne de confiance","style":"cell_b"},{"t":"p","html":"Si désignée et si le patient a choisi de s'en faire assister, l'entretien a lieu en sa présence, avec un temps en tête-à-tête proposé.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Documents écrits","style":"cell_b"},{"t":"p","html":"L'information orale est primordiale ; des documents écrits peuvent la compléter (jamais à faire signer par la personne).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Documents écrits","style":"cell_b"},{"t":"p","html":"Les documents sont hiérarchisés, fondés sur des données validées, présentent les bénéfices avant les inconvénients/risques, précisent les risques fréquents et graves, les moyens de faire face aux complications et les signes d'alerte ; ils sont synthétiques, clairs et courts.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Documents écrits","style":"cell_b"},{"t":"p","html":"Il est souhaitable de disposer de documents en langues étrangères et de supports adaptés (malvoyance, troubles du développement…).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Plusieurs professionnels","style":"cell_b"},{"t":"p","html":"Chaque professionnel informe sur son domaine de compétence sans présumer que l'information a été donnée par un autre, mais s'enquiert de ce qui a déjà été délivré ; un référent unique remet une synthèse aux différentes étapes du soin.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Traçabilité","style":"cell_b"},{"t":"p","html":"Le dossier mentionne les informations majeures délivrées, par qui, à quelle date, et les difficultés éventuellement rencontrées.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Traçabilité","style":"cell_b"},{"t":"p","html":"Ces mentions suffisent comme moyen de preuve en cas de litige — il n'y a pas lieu de demander à la personne une confirmation signée.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Information du mineur/majeur protégé, évaluation & sources","items":[{"t":"section","text":"3. Information du mineur, du majeur protégé ou inapte","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Mineur","style":"cell_b"},{"t":"p","html":"Le droit à l'information est exercé par les titulaires de l'autorité parentale, mais le mineur reçoit lui-même une information adaptée à son degré de maturité pour l'associer à la décision (le dossier trace les deux informations).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Mineur","style":"cell_b"},{"t":"p","html":"Si les deux titulaires sont présents : informer les deux ainsi que le mineur ; un temps d'entretien singulier avec le mineur peut être proposé selon son âge.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Mineur","style":"cell_b"},{"t":"p","html":"Si un seul titulaire est présent : l'informer et lui exposer la nécessité d'informer l'autre titulaire (en particulier si les parents sont séparés) ; un entretien avec les deux parents peut être proposé si le pronostic est grave.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Mineur","style":"cell_b"},{"t":"p","html":"Si l'accompagnant n'est pas titulaire de l'autorité parentale : lui délivrer une information strictement utile et nécessaire, à compléter avec le(s) titulaire(s).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Mineur","style":"cell_b"},{"t":"p","html":"Mineur non accompagné : l'informer si sa maturité et la situation clinique le permettent, en indiquant si besoin la nécessité de réitérer l'information en présence du/des titulaire(s).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Mineur","style":"cell_b"},{"t":"p","html":"Mineur s'opposant à l'information des titulaires pour garder le secret : le médecin (seul, et non tout professionnel de santé) peut mettre en œuvre le traitement nécessaire à la sauvegarde de sa santé sans autorisation parentale, à condition que le mineur se fasse accompagner d'un majeur de son choix.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Majeur protégé","style":"cell_b"},{"t":"p","html":"Le majeur protégé reçoit lui-même l'information, adaptée à ses facultés de compréhension (principe d'autonomie, loi du 5 mars 2007) ; le juge des tutelles peut prévoir que le tuteur la reçoive en sa présence, ou seul si le majeur n'est pas en état de la recevoir.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Majeur inapte","style":"cell_b"},{"t":"p","html":"Information adaptée aux facultés de compréhension ; consulter la personne de confiance si désignée alors que la personne avait encore ses facultés, ou à défaut les proches présents — en traçant dans le dossier le motif et le contenu de l'information donnée.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"4. Évaluation de l'information donnée","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Thème","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Satisfaction","style":"cell_b"},{"t":"p","html":"La satisfaction des personnes à l'égard de l'information orale et écrite fait l'objet d'une évaluation rétrospective par les établissements de santé (ex. commissions des relations avec les usagers).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Pratiques","style":"cell_b"},{"t":"p","html":"Une évaluation régulière des pratiques d'information devrait s'appuyer sur des enquêtes auprès des personnes et sur l'analyse rétrospective des dossiers médicaux.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Documents écrits","style":"cell_b"},{"t":"p","html":"L'évaluation des documents vérifie la méthode d'élaboration et le contenu scientifique, l'identité des auteurs et la date d'établissement, et l'absence de toute signature demandée à la personne (contrôlé en visite de certification HAS).","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Document source :</b> Haute Autorité de Santé (HAS), « Délivrance de l'information à la personne sur son état de santé », Recommandation de Bonne Pratique, validée par le Collège de la HAS en mai 2012.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/delivrance-de-linformation-a-la-personne-sur-son-etat-de-sante/","style":"source"},{"t":"p","html":"<b>Couverture :</b> intégralité des 4 sections de recommandations (28 items, tous AE — grille A/B/C/AE définie en préambule mais jamais citée individuellement, la source énonçant explicitement que toutes les recommandations reposent sur un accord d'experts). Annexe 1 (liste réglementaire des professions de santé) et la section Participants non reproduites — non actionnables au chevet. Divergence de date disclosed en tête de script (index bibliothèque : 2010 ; document : mai 2012) et lien source corrigé (coquille dans l'URL de l'index). Argumentaire scientifique détaillé (document source complet) non reproduit.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante, produite pour un usage d'aide-mémoire en anesthésie-réanimation. Elle ne remplace pas le texte intégral ni un conseil juridique. Cette fiche n'est ni éditée ni validée par la HAS.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2a_HAS_texte-court_Delivrance-de-linformation-a-la-personne-sur-son-etat-de-sante.pdf';

insert into public.documents (title, doc_type, publication_date, source_url, original_language)
values ('Les blocs périmédullaires chez l’adulte', 'RFE', '2005-09-24', 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Blocs-perimedullaires-chez-ladulte.pdf#blocs_perimedullaires_ci_2006', 'non_renseigne')
on conflict (source_url) do nothing;
insert into public.document_specialties (document_id, specialty_id)
