update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Blocs-perimedullaires-chez-ladulte.pdf#blocs_perimedullaires_infectieux_2006' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'blocs_perimedullaires_infectieux_2006',
  card_json = $mgjson${"badge":"SFAR/Sofcot/Sofmer — RPC 2007 (Q13/15, périmètre limité)","title":"Les blocs périmédullaires chez l'adulte — Terrain infectieux (Q13/15)","short":"SFAR/Sofcot/Sofmer, « Les blocs périmédullaires chez l'adulte », RPC, Ann Fr Anesth Réanim 26 (2007) 720-752. Huitième installment de ce document — dernière d'une série de 5 « Questions terrain » consécutives (9 à 13) ; les Questions 1-2, 3-5, 7, 8, 9-10, 11 et 12 sont des fiches séparées. Cette fiche couvre INTÉGRALEMENT la Question 13 (terrain infectieux : patient fébrile, femme enceinte fébrile, états septiques graves, infections virales, VIH, réactivation herpétique post-opiacés) — 8 recommandations gradées (A:0, B:2, C:6), aucune consolidation nécessaire (correspondance directe avec les 8 citations brutes du source). Aucune citation « grade D », accord/consensus professionnel ni avis d'experts dans ce périmètre. Le VIH est abordé ici sous l'angle infectieux général (indication opératoire, bilan préopératoire), complémentaire — non redondant — de l'angle neurologique déjà couvert dans la fiche de la Question 12 (évolution de l'infection, blood-patch). La Question 6 reste EXCLUE (superseded par la fiche HAS 2025 dédiée) ; les Questions 14-15 (gestion de l'échec, facteurs de risque de complications) restent hors périmètre — derniers installments avant couverture intégrale de ce document (hors Question 6).","society":"SFAR / Sofcot / Sofmer","version":"2006-2007","validated":"Comité des référentiels de la SFAR","methodology":"Grille EBM classique A/B/C (aucun D/AE dans ce périmètre) — 8 recommandations gradées (A:0, B:2, C:6), Question 13/15 uniquement (périmètre limité)","pages":1,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"blocs_perimedullaires_infectieux_2006","sections":[{"title":"Question 13 — Terrain infectieux & sources","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Périmètre limité — installment 8/n :</b> ce document source compte 15 « Questions » cliniques. Cette fiche couvre INTÉGRALEMENT la Question 13 (terrain infectieux) — la dernière d'une série de 5 « Questions terrain » consécutives (9 à 13). Les Questions 14-15 (gestion de l'échec, facteurs de risque de complications) ne sont PAS couvertes ici — installments futurs, derniers restants avant couverture intégrale du document (hors Question 6, exclue). Les Questions 1-2, 3-5, 7, 8, 9-10, 11 et 12 sont couvertes par des fiches séparées ; la Question 6 est exclue (superseded par une fiche HAS 2025).","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"A"},{"t":"chip","label":"B"},{"t":"chip","label":"C"},{"t":"p","html":"<b>Grille EBM classique</b> — <b>A</b> : essais randomisés de forte puissance/méta-analyses ; <b>B</b> : essais randomisés de faible puissance/études de cohorte ; <b>C</b> : cas-témoins/études rétrospectives. Aucune citation « grade D », « accord professionnel », « consensus professionnel » ni « avis d'experts » dans ce périmètre. Fiche limitée à la Question 13/15 — dernière des 5 « Questions terrain » consécutives (9 à 13).","style":"badge_head"}]]},{"t":"section","text":"Question 13 — Anesthésie périmédullaire et pathologie infectieuse","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Patient fébrile","style":"cell_b"},{"t":"p","html":"De principe, la fièvre est une contre-indication à l'APM ; une étiologie non-infectieuse de la fièvre autorise l'APM.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Patient fébrile","style":"cell_b"},{"t":"p","html":"Un foyer infectieux bactérien localisé à distance du site de ponction est compatible avec l'APM, mais la mobilisation du site infecté doit être réalisée sous couvert d'une antibiothérapie adaptée.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Femme enceinte fébrile","style":"cell_b"},{"t":"p","html":"La pose d'un cathéter péridural reste indiquée en fonction du rapport bénéfice/risque pour la patiente.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Femme enceinte fébrile","style":"cell_b"},{"t":"p","html":"La chorioamniotite et les infections urinaires n'augmentent pas le risque de complication septique lié à l'analgésie péridurale ; une antibioprophylaxie ou antibiothérapie peut être associée.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"États septiques graves","style":"cell_b"},{"t":"p","html":"Les états septiques graves avec retentissement systémique (choc septique), quel que soit l'agent étiologique ou le foyer initial, sont une contre-indication à l'APM — surtout en cas de troubles de la coagulation associés (CIVD) ou d'infection intravasculaire active (endocardite, infection sur cathéter).","style":"cell"},{"t":"chip","label":"B"}],[{"t":"p","html":"Infections virales","style":"cell_b"},{"t":"p","html":"Aucun lien n'a été démontré entre une infection virale évolutive et une complication infectieuse de l'APM ; en évitant les fortes doses de morphiniques (qui augmentent la réplication virale), l'APM peut être intéressante.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"VIH","style":"cell_b"},{"t":"p","html":"L'APM est recommandée en cas d'indication opératoire chez les patients infectés par le VIH, sous réserve que le bilan préopératoire ait éliminé une complication opportuniste et en l'absence d'atteinte évolutive du système nerveux central.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Réactivation herpétique","style":"cell_b"},{"t":"p","html":"Plusieurs cas de réactivation d'infection herpétique (herpès labial en post-partum) ont été rapportés après administration d'opiacés par voie périmédullaire — à intégrer dans l'évaluation bénéfice/risque de l'APM en milieu obstétrical (risque pour l'enfant).","style":"cell"},{"t":"chip","label":"B"}]]},{"t":"p","html":"<b>Repères pratiques non gradés :</b>","style":"body_sm"},{"t":"p","html":"• Hépatopathies chroniques postvirales (VHB, VHC) : peuvent induire des thrombopénies/thrombopathies, des déficits en facteurs contact et un effondrement du TP — les troubles de la coagulation qui en résultent peuvent contre-indiquer une APM (voir la fiche dédiée à l'hémostase pour le détail des seuils).","style":"body_sm"},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Document source :</b> SFAR/Sofcot/Sofmer, « Les blocs périmédullaires chez l'adulte », Recommandations pour la Pratique Clinique, présentées le 24 septembre 2005 (47e congrès SFAR), Annales Françaises d'Anesthésie et de Réanimation 26 (2007) 720-752.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/les-blocs-perimedullaires-chez-ladulte/","style":"source"},{"t":"p","html":"<b>Couverture :</b> Question 13/15 uniquement (terrain infectieux) — 8 recommandations gradées (A:0, B:2, C:6). Les Questions 14-15 (gestion de l'échec, facteurs de risque de complications) ne sont pas couvertes ici — hors périmètre de cette fiche, derniers installments à venir. Argumentaire scientifique détaillé (document source complet) non reproduit.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante et PARTIELLE (Question 13 uniquement, sur 15). Elle ne remplace pas le texte intégral — en particulier pour la gestion de l'échec ou les facteurs de risque de complications. Pour le détail des seuils d'hémostase (thrombopénie, anticoagulants), voir la fiche dédiée à la Question 11 de ce même document. Cette fiche n'est ni éditée ni validée par la SFAR.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Blocs-perimedullaires-chez-ladulte.pdf#blocs_perimedullaires_infectieux_2006';

