update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Blocs-perimedullaires-chez-ladulte.pdf#blocs_perimedullaires_echec_2006' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'blocs_perimedullaires_echec_2006',
  card_json = $mgjson${"badge":"SFAR/Sofcot/Sofmer — RPC 2007 (Q14/15, périmètre limité)","title":"Les blocs périmédullaires chez l'adulte — Échec d'une anesthésie périmédullaire (Q14/15)","short":"SFAR/Sofcot/Sofmer, « Les blocs périmédullaires chez l'adulte », RPC, Ann Fr Anesth Réanim 26 (2007) 720-752. Neuvième installment de ce document — les Questions 1-2, 3-5, 7, 8, 9-10, 11, 12 et 13 sont des fiches séparées. Cette fiche couvre INTÉGRALEMENT la Question 14 (gestion de l'échec d'une anesthésie périmédullaire : diagnostic et prévention de l'échec, causes liées à la technique/à l'anesthésique local/au matériel, conduite à tenir devant une analgésie insuffisante ou de durée insuffisante) — 27 recommandations gradées (A:4, C:15, D:5, AE:3), avant-dernière Question du document. Un « grade D » non défini par le préambule méthodologique du source (déjà rencontré en Questions 7 et 12) réapparaît ici avec la densité la plus élevée rencontrée à ce jour dans ce document (5 occurrences). Piège de césure typographique disclosed et corrigé AVANT rédaction du script (même catégorie que celui rencontré en Question 11) : une citation « consensus professionnel » coupée par un retour à la ligne (« con-/sensus professionnel ») avait échappé à un premier grep automatique sur texte aplati — retrouvée par recherche ciblée des motifs de fin/début de ligne, portant le total de citations brutes de 27 à 28 avant consolidation (28 → 27 après regroupement de 2 citations de grade C décrivant la même conséquence clinique — passage transforaminal/septum et passage sous-dural du cathéter). Seule la Question 15 (facteurs de risque de complications) reste à construire pour une couverture intégrale du document (hors Question 6, exclue — superseded par la fiche HAS 2025 dédiée).","society":"SFAR / Sofcot / Sofmer","version":"2006-2007","validated":"Comité des référentiels de la SFAR","methodology":"Grille EBM classique A/C/D (aucun grade B dans ce périmètre) + « consensus professionnel » (AE) — 27 recommandations gradées (A:4, C:15, D:5, AE:3), Question 14/15 uniquement (périmètre limité)","pages":2,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"blocs_perimedullaires_echec_2006","sections":[{"title":"Question 14 — Échec d'une anesthésie périmédullaire","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Périmètre limité — installment 9/n :</b> ce document source compte 15 « Questions » cliniques. Cette fiche couvre INTÉGRALEMENT la Question 14 (gestion de l'échec d'une APM) — avant-dernière Question du document ; seule la Question 15 (facteurs de risque de complications) restera à construire pour une couverture intégrale (hors Question 6, exclue). Les Questions 1-2, 3-5, 7, 8, 9-10, 11, 12 et 13 sont couvertes par des fiches séparées.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"A"},{"t":"chip","label":"C"},{"t":"chip","label":"D"},{"t":"chip","label":"AE"},{"t":"p","html":"<b>Grille EBM classique</b> — <b>A</b> : essais randomisés de forte puissance/méta-analyses ; <b>C</b> : cas-témoins/études rétrospectives (aucun grade B dans ce périmètre) ; <b>D</b> : palier non défini par le préambule méthodologique du source (déjà rencontré en Q7/Q12) — 5 occurrences, la plus forte densité rencontrée à ce jour ; <b>AE</b> : « consensus professionnel » (3 occurrences, dont 1 initialement masquée par une césure typographique de fin de ligne, disclosed). Fiche limitée à la Question 14/15.","style":"badge_head"}]]},{"t":"p","html":"<b>Définitions (non gradées) :</b>","style":"body_sm"},{"t":"p","html":"• Échec : la réalisation d'une APM n'a pas permis de repérer l'espace ou de mettre en place le matériel, ou il n'existe aucun bloc sensitif.","style":"body_sm"},{"t":"p","html":"• Bloc incomplet : l'injection d'AL entraîne un bloc sensitif ou moteur insuffisant pour l'acte chirurgical ou une analgésie de qualité.","style":"body_sm"},{"t":"p","html":"• Durée insuffisante : lors d'une injection unique, la durée d'action de l'AL peut être insuffisante si la chirurgie se prolonge.","style":"body_sm"},{"t":"p","html":"• Dans tous ces cas, envisager un complément d'injection, une nouvelle APD, ou convertir en AG.","style":"body_sm"},{"t":"section","text":"Diagnostic, prévention et causes de l'échec","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Diagnostic échec","style":"cell_b"},{"t":"p","html":"Doit être fait le plus vite possible avant de débuter l'intervention chirurgicale ou l'analgésie obstétricale.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Diagnostic échec","style":"cell_b"},{"t":"p","html":"Bonne corrélation entre le niveau d'analgésie cutanée au toucher et la qualité de l'analgésie chirurgicale.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Prévention","style":"cell_b"},{"t":"p","html":"Hors antécédents de chirurgie rachidienne, il est très difficile de prévoir une insuffisance de l'analgésie péridurale.","style":"cell"},{"t":"chip","label":"D"}],[{"t":"p","html":"Expérience opérateur","style":"cell_b"},{"t":"p","html":"Un minimum de 30-50 APD et autant de rachianesthésies est nécessaire pour réduire significativement le taux d'échec de ces techniques.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Expérience opérateur","style":"cell_b"},{"t":"p","html":"L'examen du dos a une bonne valeur prédictive de la difficulté de ponction.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Expérience opérateur","style":"cell_b"},{"t":"p","html":"Une chirurgie vertébrale postérieure ne contre-indique pas la rachianesthésie, mais la fibrose et la présence de matériel rendent la ponction plus difficile.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Expérience opérateur","style":"cell_b"},{"t":"p","html":"La voie médiane génère un taux d'échec plus élevé ; la voie paramédiane, plus douloureuse, comporte un risque plus élevé de plaie vasculaire.","style":"cell"},{"t":"chip","label":"C"}]]},{"t":"section","text":"Causes liées à la technique, à l'anesthésique local et au matériel","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Technique","style":"cell_b"},{"t":"p","html":"Le choix d'une posture favorable à la diffusion du produit vers la zone opératoire reste préconisé.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Technique","style":"cell_b"},{"t":"p","html":"L'utilisation d'un mandrin gazeux pour le repérage de l'espace péridural augmente le risque d'échec de l'APD.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Technique","style":"cell_b"},{"t":"p","html":"L'introduction du cathéter péridural avec le biseau en direction céphalique procure la meilleure analgésie au cours du travail.","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"Technique","style":"cell_b"},{"t":"p","html":"La dilatation de l'espace péridural avec du sérum physiologique peut faciliter la montée du cathéter.","style":"cell"},{"t":"chip","label":"D"}],[{"t":"p","html":"Technique","style":"cell_b"},{"t":"p","html":"Injecter la première dose dans l'aiguille de Tuohy pour une anesthésie chirurgicale, et par le cathéter pour une péridurale analgésique — le cathéter doit alors être impérativement fonctionnel.","style":"cell"},{"t":"chip","label":"D"}],[{"t":"p","html":"Technique","style":"cell_b"},{"t":"p","html":"Vérifier l'efficacité du cathéter avant son utilisation.","style":"cell"},{"t":"chip","label":"D"}],[{"t":"p","html":"Anesthésique local","style":"cell_b"},{"t":"p","html":"Un bloc sensitif limité aux territoires sacrés et lombaires malgré une dose « normale » d'AL doit faire suspecter une mauvaise distribution (« maldistribution »), pouvant induire des lésions neurologiques irréversibles (syndrome de la queue-de-cheval).","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Matériel","style":"cell_b"},{"t":"p","html":"L'introduction d'une longueur trop importante de cathéter dans l'espace péridural peut expliquer une APD incomplète.","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"Matériel","style":"cell_b"},{"t":"p","html":"Le passage transforaminal du cathéter, la présence d'un septum dans l'espace, ou le passage sous-dural du cathéter, peuvent expliquer une APD incomplète.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Matériel","style":"cell_b"},{"t":"p","html":"Des problèmes mécaniques (coudure, obstruction partielle ou complète, compression, raccord trop serré ou déconnecté) peuvent gêner l'injection des produits par voie péridurale.","style":"cell"},{"t":"chip","label":"C"}]]},{"t":"section","text":"Conduite à tenir devant une analgésie insuffisante","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Niveau insuffisant","style":"cell_b"},{"t":"p","html":"En cas d'APD avec cathéter, réinjecter la même solution d'AL (effet volume) pour obtenir le niveau souhaité.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Niveau insuffisant","style":"cell_b"},{"t":"p","html":"En cas d'APD asymétrique avec cathéter trop introduit, il est possible de le retirer de quelques centimètres (laisser 3-5 cm) et de réinjecter une dose d'AL.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Niveau insuffisant","style":"cell_b"},{"t":"p","html":"En cas de rachianesthésie avec solution hyperbare, la position déclive tête en bas peut permettre une diffusion céphalique.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Niveau insuffisant","style":"cell_b"},{"t":"p","html":"Si ces manœuvres sont insuffisantes, procéder à une nouvelle APM (en tenant compte des doses déjà injectées) ou convertir en AG.","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Durée insuffisante","style":"cell_b"},{"t":"p","html":"Injecter un adjuvant (morphinique liposoluble) est la meilleure solution.","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"Durée insuffisante","style":"cell_b"},{"t":"p","html":"Injecter 50-75 µg de clonidine.","style":"cell"},{"t":"chip","label":"A"}],[{"t":"p","html":"Rachianesthésie continue","style":"cell_b"},{"t":"p","html":"En cas d'échec par mauvaise distribution, les changements de baricité de la solution et de position du patient sont des mesures constamment efficaces ; il est possible de recourir à une AG.","style":"cell"},{"t":"chip","label":"D"}],[{"t":"p","html":"Après échec APD","style":"cell_b"},{"t":"p","html":"La réalisation d'une rachianesthésie pour une césarienne après un échec d'APD reste controversée (risque de bloc étendu).","style":"cell"},{"t":"chip","label":"C"}],[{"t":"p","html":"Après échec APD","style":"cell_b"},{"t":"p","html":"Il est recommandé de passer en anesthésie générale.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Passage à l'AG","style":"cell_b"},{"t":"p","html":"Si le bloc reste incomplet malgré les traitements proposés, il faut pratiquer une anesthésie générale.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<i>Précision du source :</i> un complément sédatif IV peut être utilisé pour l'anxiété du patient, mais lorsque l'analgésie d'un bloc périmédullaire est insuffisante, le risque est de masquer ou de favoriser des complications (non gradé).","style":"note"},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Document source :</b> SFAR/Sofcot/Sofmer, « Les blocs périmédullaires chez l'adulte », Recommandations pour la Pratique Clinique, présentées le 24 septembre 2005 (47e congrès SFAR), Annales Françaises d'Anesthésie et de Réanimation 26 (2007) 720-752.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/les-blocs-perimedullaires-chez-ladulte/","style":"source"},{"t":"p","html":"<b>Couverture :</b> Question 14/15 uniquement (gestion de l'échec) — 27 recommandations gradées (A:4, C:15, D:5, AE:3). Seule la Question 15 (facteurs de risque de complications) reste à construire pour une couverture intégrale du document (hors Question 6, exclue). Argumentaire scientifique détaillé (document source complet) non reproduit.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante et PARTIELLE (Question 14 uniquement, sur 15). Elle ne remplace pas le texte intégral — en particulier pour les facteurs de risque de complications (Question 15, installment à venir). Cette fiche n'est ni éditée ni validée par la SFAR.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_AFAR_Blocs-perimedullaires-chez-ladulte.pdf#blocs_perimedullaires_echec_2006';

