on conflict do nothing;
update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_PUROL_Recommandations-chirurgie-ambulatoire-en-urologie.pdf' and d.society_id is null and s.acronym = 'AFU';
update public.documents set
  fiche_key = 'chir_ambu_urologie_2013',
  card_json = $mgjson${"badge":"AFU/SFAR/AFCA/ANAP — Consensus formalisé HAS, 2013","title":"Chirurgie ambulatoire en urologie — Recommandations AFU/SFAR/AFCA/ANAP","short":"AFU/SFAR/AFCA/ANAP, « Chirurgie ambulatoire en urologie », texte des recommandations AFU (novembre 2013), Progrès en Urologie (2013) 23, 62-66. Label HAS (recommandation de bonne pratique élaborée selon les procédures et règles méthodologiques préconisées par la HAS, méthode du consensus formalisé). Couvre le parcours de soin en chirurgie ambulatoire urologique (éthique, éligibilité, organisation, particularités anesthésiques, place du médecin traitant, place du patient, continuité des soins), les spécificités chez la personne âgée, et la prévention/prise en charge des risques rétentionnel, infectieux, douloureux et hémorragique postopératoires. 59 recommandations au total. Particularité méthodologique notable, disclosed : bien que la grille définisse 4 niveaux (A/B/C/AE), AUCUNE des 59 recommandations n'est gradée A, B ou C — 57 reposent sur un accord d'experts (AE) et 2 (n°19, n°43) ne portent aucune mention de grade dans le source (chip « NG », jamais un grade inventé). Piège d'extraction résolu : le PDF source (mise en page 2 colonnes) livre un ordre de lecture incohérent en extraction brute ; corrigé par tri explicite des blocs de texte par colonne puis par position verticale, vérifié recommandation par recommandation (1 à 59, aucun numéro manquant). Ne couvre que le texte court des recommandations (pages 62-66 du document source) — l'argumentaire scientifique détaillé (61 pages) et la tribune d'opinion syndicale de fin de document (SNCUF) sont hors périmètre.","society":"AFU / SFAR / AFCA / ANAP","version":"2013","validated":"HAS (label, méthode consensus formalisé)","methodology":"Grille HAS « consensus formalisé » A/B/C/AE — en pratique, 57/59 recommandations « accord d'experts » (AE), 2/59 non gradées dans le source (disclosed, chip « NG »), aucune recommandation A/B/C malgré ces grades étant définis","pages":4,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"chir_ambu_urologie_2013","sections":[{"title":"Parcours de soin, personne âgée & risque rétentionnel","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Périmètre :</b> cette fiche synthétise le texte court des recommandations AFU (pages 62-66 du document source) — l'argumentaire scientifique détaillé (61 pages) et la tribune d'opinion syndicale de fin de document ne sont pas repris ici.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"AE"},{"t":"chip","label":"NG"},{"t":"p","html":"<b>Grille HAS « consensus formalisé »</b> — A/B/C/AE définis par le préambule méthodologique (A : essais randomisés forte puissance/méta-analyses ; B : essais randomisés faible puissance/cohortes ; C : cas-témoins/rétrospectives ; AE : accord d'experts). <b>Particularité disclosed :</b> sur 59 recommandations, AUCUNE n'est gradée A, B ou C — 57 portent la mention « accord d'experts » (AE), et 2 (n°19, n°43) ne portent AUCUNE mention de grade dans le source (chip <b>NG</b> = non gradée, jamais un grade inventé).","style":"badge_head"}]]},{"t":"section","text":"Spécificité du parcours de soin en chirurgie ambulatoire urologique","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Éthique","style":"cell_b"},{"t":"p","html":"Il est recommandé d'appliquer les recommandations selon le contexte, pour un patient, un acte chirurgical, une organisation et une équipe médico-chirurgicale donnés.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Éligibilité","style":"cell_b"},{"t":"p","html":"Il est recommandé de privilégier le mode d'hospitalisation ambulatoire lorsque les conditions d'éligibilité du patient sont réunies.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Éligibilité","style":"cell_b"},{"t":"p","html":"Il est recommandé d'identifier dans l'entourage du patient les personnes ressources (accompagnant, aidant naturel, personne de confiance) susceptibles d'intervenir dans la prise en charge ambulatoire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Éligibilité","style":"cell_b"},{"t":"p","html":"Il est recommandé de vérifier la conformité des conditions requises pour la pratique de l'ambulatoire à toutes les étapes de la prise en charge.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Éligibilité","style":"cell_b"},{"t":"p","html":"Une déficience physique ou intellectuelle n'interdit pas la prise en charge ambulatoire ; elle nécessite des adaptations spécifiques.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Éligibilité","style":"cell_b"},{"t":"p","html":"Les enfants sont d'excellents candidats à la prise en charge ambulatoire ; il est recommandé que les particularités liées au jeune âge soient prises en compte.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Éligibilité","style":"cell_b"},{"t":"p","html":"Le grand âge en soi est une bonne indication à la prise en charge ambulatoire lorsque les conditions d'éligibilité sont réunies (diminuerait le risque confusionnel).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Organisation","style":"cell_b"},{"t":"p","html":"La consultation de programmation opératoire est un temps essentiel de l'organisation ambulatoire et de l'information du patient ; elle nécessite des moyens en temps médical et non médical.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Organisation","style":"cell_b"},{"t":"p","html":"Il est recommandé, à chaque étape de la chirurgie ambulatoire, d'identifier les sources de perte de temps dans l'organisation des flux (planification, temps d'attente, transfert).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Organisation","style":"cell_b"},{"t":"p","html":"Il est recommandé que l'équipe de l'unité de chirurgie ambulatoire (UCA) soit sensibilisée, expérimentée et formée à la pratique de l'ambulatoire et à la réhabilitation précoce.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Organisation","style":"cell_b"},{"t":"p","html":"Il est recommandé de mettre en place au sein de l'UCA une démarche de gestion des risques (processus de prise en charge, défaut d'adhésion, pressions institutionnelles).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Anesthésie","style":"cell_b"},{"t":"p","html":"Il est recommandé que le médecin anesthésiste-réanimateur soit informé par l'urologue du choix d'un mode d'hospitalisation ambulatoire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Anesthésie","style":"cell_b"},{"t":"p","html":"Il est recommandé qu'à l'issue de la consultation d'anesthésie, l'urologue soit informé en cas de réserve sur le mode d'hospitalisation ambulatoire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Anesthésie","style":"cell_b"},{"t":"p","html":"Il est recommandé d'hydrater par voie orale les patients par des liquides clairs jusqu'à 2 heures avant l'intervention (jeûne : 6h solides, 2h liquides clairs).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Anesthésie","style":"cell_b"},{"t":"p","html":"Il est recommandé de déterminer pour chaque intervention, de façon collégiale, une durée de surveillance postopératoire minimale requise.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Médecin traitant","style":"cell_b"},{"t":"p","html":"Il est recommandé d'informer le médecin traitant du caractère ambulatoire de la prise en charge chirurgicale dès la consultation de programmation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Médecin traitant","style":"cell_b"},{"t":"p","html":"Il est recommandé d'échanger avec le médecin traitant toute information utile à la prise en charge ambulatoire (avant, entre et après l'intervention) et de lui transmettre les éléments post-interventionnels.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Place du patient","style":"cell_b"},{"t":"p","html":"Il est recommandé d'expliquer au patient les modalités de la chirurgie ambulatoire, de recueillir son assentiment (décision partagée), et de l'informer sur l'importance de respecter les consignes pré- et postopératoires.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Continuité des soins","style":"cell_b"},{"t":"p","html":"Selon les textes réglementaires (Art. D6124-304 CSP), les conditions de mise en œuvre de la continuité des soins doivent être organisées par l'UCA en collaboration avec l'urologue et formalisées par écrit.","style":"cell"},{"t":"chip","label":"NG"}],[{"t":"p","html":"Continuité des soins","style":"cell_b"},{"t":"p","html":"Il est recommandé d'organiser par anticipation, lors des consultations préopératoires, les mesures à prendre à la sortie (ordonnances, consignes, rendez-vous postopératoire), à réévaluer en postopératoire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Continuité des soins","style":"cell_b"},{"t":"p","html":"Il est recommandé de communiquer au patient les informations sur le geste pratiqué et les suites prévisibles, et de lui délivrer un dossier de liaison pour son retour à domicile.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Continuité des soins","style":"cell_b"},{"t":"p","html":"Il est recommandé de formaliser la procédure de contact (numéro joignable 24h/24) pour la continuité des soins.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Continuité des soins","style":"cell_b"},{"t":"p","html":"Il est recommandé d'informer le patient des signes devant faire évoquer une complication postopératoire (infection, rétention, hémorragie, douleur) et de la conduite à tenir.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Personne âgée & risque rétentionnel postopératoire","color":"navy"},{"t":"p","html":"<b>Spécificités chez la personne âgée</b>","style":"body"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Personne âgée","style":"cell_b"},{"t":"p","html":"Il est recommandé d'apporter une attention particulière à l'évaluation préopératoire du sujet âgé (antécédents, traitements, troubles cognitifs, entourage), avec avis gériatrique si besoin ; optimiser l'hydratation et évaluer l'état cognitif avant la sortie de l'UCA.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Personne âgée","style":"cell_b"},{"t":"p","html":"Il est recommandé de surveiller particulièrement les risques d'hypoxémie, d'hypothermie et d'hypovolémie chez le sujet âgé.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Risque rétentionnel postopératoire</b>","style":"body"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Évaluation","style":"cell_b"},{"t":"p","html":"Il est recommandé d'évaluer le risque de rétention urinaire lors de la consultation de programmation, en distinguant risque faible et risque élevé selon le patient, le type de chirurgie et le type d'anesthésie.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Prévention","style":"cell_b"},{"t":"p","html":"Il est recommandé de maintenir un traitement alpha-bloquant en périopératoire, sauf contre-indication (chirurgie de la cataracte).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Prévention","style":"cell_b"},{"t":"p","html":"Il est recommandé de ne pas limiter les apports hydriques, car cela augmente le risque de déshydratation, de caillotage vésical et ralentit la reprise des mictions.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Prévention","style":"cell_b"},{"t":"p","html":"Il est recommandé d'obtenir une miction avant toute intervention.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Prévention","style":"cell_b"},{"t":"p","html":"Il est recommandé de cathétériser la vessie en début d'intervention pour éviter une distension vésicale si la diurèse attendue avant la reprise des mictions dépasse 500 mL.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Prévention","style":"cell_b"},{"t":"p","html":"L'anesthésie générale présente moins de risque de rétention urinaire qu'une anesthésie rachidienne ; envisager une alternative en cas de risque rétentionnel élevé, ou réduire les doses d'AL et surveiller la reprise mictionnelle si la rachianesthésie est indiquée.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Prévention","style":"cell_b"},{"t":"p","html":"Il est recommandé de limiter l'utilisation de médicaments augmentant le risque de rétention urinaire (morphiniques, anticholinergiques).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Sortie","style":"cell_b"},{"t":"p","html":"Chez un patient à faible risque rétentionnel, il n'est pas nécessaire d'attendre la reprise mictionnelle avant la sortie (chirurgie urologique et non urologique).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Sortie","style":"cell_b"},{"t":"p","html":"Chez un patient à risque rétentionnel élevé, il est recommandé de quantifier la miction et d'évaluer le résidu post-mictionnel avant la sortie (chirurgie urologique et non urologique).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Sortie","style":"cell_b"},{"t":"p","html":"En chirurgie ambulatoire, il est possible de laisser sortir le patient avec une sonde urinaire ; lors de l'ablation, il est recommandé d'évaluer la reprise des mictions.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Risque infectieux & risque de douleur","items":[{"t":"section","text":"Risque infectieux & risque de douleur postopératoires","color":"navy"},{"t":"p","html":"<b>Risque infectieux postopératoire</b>","style":"body"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"ECBU","style":"cell_b"},{"t":"p","html":"En l'absence de sonde à demeure, il est recommandé de réaliser un ECBU dans les 5 à 10 jours précédant toute chirurgie de l'appareil urinaire ; l'UCA doit permettre l'accès à son résultat tout au long de la prise en charge.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"ECBU","style":"cell_b"},{"t":"p","html":"L'interprétation de l'ECBU relève de l'urologue ; le dossier médical doit contenir le résultat et la conduite adoptée.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"ECBU","style":"cell_b"},{"t":"p","html":"Si un ECBU préopératoire est nécessaire, il est recommandé de vérifier son résultat et la conduite adoptée avant l'admission en UCA (« appel de la veille ») et lors de la check-list au bloc opératoire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Colonisation","style":"cell_b"},{"t":"p","html":"En présence d'une colonisation sur sonde, il est recommandé de débuter une antibiothérapie adaptée au moins 48 heures avant l'intervention et de changer la sonde 24 heures après le début du traitement.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Colonisation","style":"cell_b"},{"t":"p","html":"En cas de colonisation urinaire non traitée, il est recommandé de reporter une chirurgie programmée de l'appareil urinaire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Antibioprophylaxie","style":"cell_b"},{"t":"p","html":"L'antibioprophylaxie doit être adaptée au site opératoire et à l'intervention, conformément aux recommandations du CIAFU et de la SFAR.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Colonisation","style":"cell_b"},{"t":"p","html":"En cas d'antibiothérapie préopératoire pour une colonisation, il est recommandé de la poursuivre au moins 48 heures après l'intervention et jusqu'à l'ablation de la sonde.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Tabac","style":"cell_b"},{"t":"p","html":"Il est recommandé de favoriser l'arrêt du tabagisme le plus tôt possible avant la chirurgie et d'informer le patient des bénéfices de cet arrêt pour la qualité des suites opératoires.","style":"cell"},{"t":"chip","label":"NG"}],[{"t":"p","html":"Nutrition","style":"cell_b"},{"t":"p","html":"Il est recommandé de tenir compte de l'état nutritionnel avant l'acte chirurgical.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Préparation cutanée","style":"cell_b"},{"t":"p","html":"Il est recommandé que la douche antiseptique soit réalisée au plus près de l'intervention par le patient à domicile, et que la dépilation (si nécessaire) soit faite le jour même par tonte — le rasage doit être proscrit.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Drainage","style":"cell_b"},{"t":"p","html":"Lorsqu'un drainage du site opératoire est indispensable, il est recommandé de privilégier un drainage aspiratif par contre-incision et de le laisser en place le moins longtemps possible.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Risque de douleur postopératoire</b>","style":"body"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Prévention","style":"cell_b"},{"t":"p","html":"Il est recommandé de ne pas recourir systématiquement à une endoprothèse urétérale après une urétéroscopie réalisée en ambulatoire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Prévention","style":"cell_b"},{"t":"p","html":"Il est recommandé de ne pas recourir systématiquement à un drainage vésical, source potentielle d'infection et d'inconfort.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Information","style":"cell_b"},{"t":"p","html":"Il est recommandé de donner au patient, en préopératoire, une information sur la douleur postopératoire et sa prise en charge.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Dépistage","style":"cell_b"},{"t":"p","html":"Il est souhaitable de dépister les terrains d'hyperalgésie afin de proposer une prise en charge spécifique de la douleur postopératoire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Évaluation","style":"cell_b"},{"t":"p","html":"Il est recommandé de diagnostiquer, d'évaluer (EVA) et de prendre en charge rapidement une douleur postopératoire, et de la réévaluer avant la sortie du patient.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Traitement","style":"cell_b"},{"t":"p","html":"Il est recommandé de prendre en charge efficacement et précocement la douleur postopératoire, celle-ci pouvant favoriser une douleur chronique.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Traitement","style":"cell_b"},{"t":"p","html":"Il est recommandé de privilégier l'analgésie multimodale, notamment par anesthésiques locaux de longue durée d'action (infiltration de la cicatrice ou bloc périnerveux), en concertation avec l'anesthésiste.","style":"cell"},{"t":"chip","label":"AE"}]]}]},{"title":"Risque hémorragique & sources","items":[{"t":"section","text":"Risque hémorragique postopératoire","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Organisation","style":"cell_b"},{"t":"p","html":"La gestion du risque hémorragique en chirurgie ambulatoire doit être une préoccupation majeure de tous les intervenants (urologue, anesthésiste-réanimateur, médecin traitant, cardiologue, infirmier, patient, aidant naturel).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Antithrombotiques","style":"cell_b"},{"t":"p","html":"Une gestion périopératoire clairement définie, adaptée et organisée des traitements antithrombotiques permet de limiter les risques de complications hémorragiques et thrombotiques.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Antithrombotiques","style":"cell_b"},{"t":"p","html":"Il est recommandé qu'un échange périopératoire ait lieu entre anesthésiste-réanimateur, urologue, médecin traitant et si nécessaire cardiologue, pour définir le risque hémorragique et le risque thromboembolique de l'arrêt des traitements antithrombotiques.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Antithrombotiques","style":"cell_b"},{"t":"p","html":"Il est recommandé d'organiser, entre les mêmes intervenants, le relais, l'arrêt ou le maintien des traitements antithrombotiques, en tenant compte du terrain cardiovasculaire et de l'intervention prévue.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Antithrombotiques","style":"cell_b"},{"t":"p","html":"Il est recommandé de vérifier, lors de l'appel de la veille, la gestion des traitements antithrombotiques.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Anémie","style":"cell_b"},{"t":"p","html":"Il est recommandé de prendre en compte une anémie périopératoire et un risque hémorragique, pour prévenir les retards de cicatrisation et le surcroît de complications infectieuses.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Document source :</b> AFU/SFAR/AFCA/ANAP, « Chirurgie ambulatoire en urologie », texte des recommandations AFU (novembre 2013), Progrès en Urologie (2013) 23, 62-66. Label HAS (recommandation de bonne pratique élaborée selon les procédures et règles méthodologiques préconisées par la HAS).","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/recommandations-afusfarafcaanap-chirurgie-ambulatoire-en-urologie/","style":"source"},{"t":"p","html":"<b>Couverture :</b> texte court des 59 recommandations AFU (pages 62-66 du document source) intégralement repris. 57 recommandations « accord d'experts » (AE), 2 recommandations non gradées dans le source (n°19, n°43, disclosed — chip « NG »), aucune recommandation gradée A/B/C malgré ces grades étant définis par le préambule méthodologique. L'argumentaire scientifique détaillé (61 pages) et les commentaires syndicaux de fin de document ne sont pas reproduits.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante du texte court des recommandations. Elle ne remplace pas le texte intégral ni l'argumentaire scientifique détaillé. Cette fiche n'est ni éditée ni validée par la SFAR, l'AFU, l'AFCA, l'ANAP ni la HAS.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/wp-content/uploads/2015/10/2_PUROL_Recommandations-chirurgie-ambulatoire-en-urologie.pdf';

