update public.documents d set society_id = s.id from public.societies s
where d.source_url = 'https://sfar.org/download/prise-en-charge-des-voies-aeriennes-de-ladulte-au-bloc-operatoire-recommandation/?wpdmdl=145883' and d.society_id is null and s.acronym = 'SFAR';
update public.documents set
  fiche_key = 'voies_aeriennes_bloc_2026',
  card_json = $mgjson${"badge":"SFAR/CARORL/CARO/FHS/SFORL — RBP HAS, 03/09/2026","title":"Prise en charge des voies aériennes de l'adulte au bloc opératoire","short":"SFAR/CARORL/CARO/FHS/SFORL (+ CORASSO), « Prise en charge des voies aériennes de l'adulte au bloc opératoire », Recommandation de Bonne Pratique labellisée HAS, adoptée par le Collège de la HAS le 3 septembre 2026 — document très récent, trouvé via recherche web (absent de l'index habituel de ce site à la date de sa publication). Couvre 3 champs : voies aériennes SANS difficulté prévisible (vidéolaryngoscopie de première intention, dispositifs supraglottiques de 2ème génération, oxygénation nasale à haut débit en sédation procédurale, capnographie), voies aériennes DIFFICILES prévues ou non (stratégies d'oxygénation apnéique, dispositifs supraglottiques de 2ème génération en cas de ventilation au masque difficile, cricothyroïdotomie technique SMS en situation « cannot intubate, cannot oxygenate »), et facteurs humains/dimensions organisationnelles (simulation, seuils de maintien de compétences par technique, briefing/debriefing/defusing, revue de mortalité-morbidité). 28 recommandations (grade 1:1, grade 2:13, avis d'experts:13, absence de recommandation:1), vérifiées par recoupement avec le tableau de synthèse du document source lui-même. ACTUALISE/SUPERSEDE cliniquement les fiches « Intubation difficile et extubation en anesthésie chez l'adulte » (RFE 2017) et « Prise en charge des voies aériennes en anesthésie adulte, à l'exception de l'intubation difficile » (Conférence de Consensus 2002/2003), toutes deux conservées sur ce site pour leur valeur historique. Exclut explicitement la pédiatrie et les soins critiques (choix du source). Les 7 algorithmes/aides cognitives visuelles publiés séparément par la SFAR (outils imprimables) ne sont pas reproduits ici — disclosed, liens directs en section Sources de la fiche.","society":"SFAR / CARORL / CARO / FHS / SFORL / CORASSO","version":"2026","validated":"Collège de la HAS (labellisation RBP, 03/09/2026)","methodology":"Grille GRADE — grade 1 (recommandation forte), grade 2 (recommandation faible), AE (avis d'experts), absence de recommandation (chip « 0/ ») — 28 recommandations (grade 1:1, grade 2:13, AE:13, 0/:1), aucune recommandation « contre » gradée numériquement","pages":3,"section":"Anesthésie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"voies_aeriennes_bloc_2026","sections":[{"title":"Prise en charge des voies aériennes de l'adulte au bloc opératoire","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Document très récent</b> (adopté par le Collège de la HAS le 3 septembre 2026) — trouvé hors du processus habituel de ce dépôt (absent de <code>library_final.json</code> à la date de sa publication), via recherche web. <b>Actualise/supersede</b> deux documents déjà couverts par ce dépôt : la fiche <code>intubation_difficile_adulte</code> (RFE SFAR 2017) pour le Champ 2, et la fiche <code>voies_aeriennes_adulte</code> (Conférence de Consensus SFAR 2002/2003) pour le Champ 1 — ces deux anciennes fiches restent disponibles sur le site (valeur historique) mais sont cliniquement dépassées par ce référentiel. <b>Périmètre explicite du source :</b> patients adultes au bloc opératoire ou en plateau technique interventionnel — exclut explicitement la pédiatrie et les soins critiques. <b>Non reproduits ici</b> (disclosed) : 7 figures/algorithmes visuels (aides cognitives, organigrammes de décision) publiés séparément par la SFAR comme outils imprimables autonomes — liens directs en section Sources.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"chip","label":"2+"},{"t":"chip","label":"AE"},{"t":"chip","label":"0/"},{"t":"p","html":"<b>Grille GRADE</b> — <b>1</b> : recommandation forte (essais randomisés de forte qualité) ; <b>2</b> : recommandation faible (qualité modérée ou bénéfice peu pertinent) — le suffixe <b>+</b> indique une recommandation POUR l'intervention (aucune recommandation « contre » gradée numériquement dans ce document) ; <b>AE</b> : avis d'experts (balance bénéfices/risques indéterminée) ; <b>0/</b> : absence de recommandation (données insuffisantes, 1 occurrence). VLS = vidéolaryngoscope/vidéolaryngoscopie. Document très récent : adopté par le Collège HAS le 3 septembre 2026.","style":"badge_head"}]]},{"t":"section","text":"Champ 1 — Voies aériennes sans difficulté prévisible","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"VLS","style":"cell_b"},{"t":"p","html":"En l'absence de critères prédictifs d'intubation difficile, il est recommandé d'utiliser un vidéolaryngoscope en première intention plutôt qu'un laryngoscope direct pour augmenter le succès à la première tentative.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"VLS","style":"cell_b"},{"t":"p","html":"En l'absence de critères prédictifs d'intubation difficile, il est recommandé d'utiliser un vidéolaryngoscope en première intention plutôt qu'un laryngoscope direct pour diminuer les complications associées à l'intubation trachéale.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Curarisation","style":"cell_b"},{"t":"p","html":"Chez les patients sans critères prédictifs d'intubation difficile, les experts suggèrent d'administrer un curare lors de l'utilisation d'un vidéolaryngoscope pour faciliter l'intubation trachéale.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Dispositifs supraglott.","style":"cell_b"},{"t":"p","html":"Sans facteur de risque d'estomac plein, sous ventilation mécanique programmée, lorsque l'installation et la technique chirurgicale le permettent, il est recommandé de privilégier les dispositifs supraglottiques de 2ème génération à l'intubation trachéale pour diminuer les complications respiratoires périopératoires.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Dispositifs supraglott.","style":"cell_b"},{"t":"p","html":"Sans facteur de risque d'estomac plein, pour une chirurgie abdominopelvienne programmée (y compris laparoscopique), il est recommandé de privilégier les dispositifs supraglottiques de 2ème génération à l'intubation trachéale pour diminuer les complications respiratoires périopératoires.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Dispositifs supraglott.","style":"cell_b"},{"t":"p","html":"Sans facteur de risque d'estomac plein, sous ventilation mécanique programmée, il est recommandé d'utiliser des dispositifs supraglottiques de 2ème génération afin de diminuer l'incidence des douleurs pharyngées postopératoires.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Obstétrique (>16 SA)","style":"cell_b"},{"t":"p","html":"Chez la femme enceinte après 16 semaines d'aménorrhée, sous ventilation mécanique programmée, les experts suggèrent de ne PAS utiliser un dispositif supraglottique par rapport à l'intubation trachéale, afin de diminuer les complications respiratoires peropératoires.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Obstétrique (<16 SA)","style":"cell_b"},{"t":"p","html":"Chez la femme enceinte avant 16 semaines d'aménorrhée, les experts suggèrent d'appliquer les recommandations en vigueur chez le patient adulte afin d'améliorer la sécurité respiratoire peropératoire.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Écho gastrique","style":"cell_b"},{"t":"p","html":"Chez le patient adulte, les données de la littérature ne permettent pas de conclure sur l'intérêt de l'échographie gastrique dans la décision d'induction en séquence rapide pour prévenir le risque d'inhalation.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"Sédation procédurale","style":"cell_b"},{"t":"p","html":"Pour les procédures et/ou populations à risque de désaturation, il est recommandé d'utiliser l'oxygénation nasale à haut débit par rapport à une oxygénation bas débit, pour diminuer l'incidence des épisodes de désaturation durant la procédure.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Sédation procédurale","style":"cell_b"},{"t":"p","html":"Pour les procédures et/ou populations à risque de désaturation, il est recommandé d'utiliser l'oxygénation nasale à haut débit par rapport à une oxygénation bas débit, pour diminuer les interruptions de procédure et les manœuvres sur les voies aériennes supérieures.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Sédation en apnée","style":"cell_b"},{"t":"p","html":"Lors d'un acte sur les voies aériennes réalisé en apnée et sans intubation trachéale, les experts suggèrent de mettre en place une oxygénation nasale à haut débit plutôt qu'une oxygénothérapie bas débit, pour retarder la désaturation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Capnie","style":"cell_b"},{"t":"p","html":"Lors d'une sédation procédurale en ventilation spontanée, il est recommandé de monitorer la capnographie afin de dépister toute apnée et éviter la désaturation, y compris avec oxygénation nasale à haut débit.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Capnie","style":"cell_b"},{"t":"p","html":"Lors de l'oxygénation nasale à haut débit en apnée, les experts suggèrent de réduire au maximum la durée d'apnée, même en l'absence de désaturation, pour prévenir le risque d'hypercapnie.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Champ 2 — Voies aériennes difficiles (prévue ou non)","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Préox. + ONHD","style":"cell_b"},{"t":"p","html":"Après préoxygénation bien conduite, en cas d'intubation difficile prévue chez un patient a priori ventilable (y compris obèse ou estomac plein), il est recommandé de mettre en place une oxygénation nasale à haut débit pendant la laryngoscopie, pour prolonger le temps sans désaturation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Obstétrique","style":"cell_b"},{"t":"p","html":"En obstétrique, en cas d'intubation trachéale sans indication au maintien de la ventilation spontanée, les experts suggèrent de maintenir une oxygénation nasale (bas ou haut débit) pendant la phase apnéique, pour prolonger le temps sans désaturation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Vidéo vs fibro.","style":"cell_b"},{"t":"p","html":"En cas d'intubation difficile prévue chez un patient a priori NON ventilable (indication de maintien de la ventilation spontanée), sous réserve d'ouverture buccale suffisante, d'un opérateur expérimenté et d'un matériel de fibroguidage disponible, il est recommandé d'utiliser indifféremment la vidéolaryngoscopie ou la fibroscopie pour garantir le succès de l'intubation.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Dispositifs supraglott.","style":"cell_b"},{"t":"p","html":"En cas d'intubation ET ventilation au masque difficiles (y compris chez la femme enceinte), il est recommandé de recourir en première intention à un dispositif supraglottique de 2ème génération plutôt qu'à un dispositif de 1ère génération ou dédié à l'intubation (type LMA-Fastrach®), pour restaurer rapidement l'oxygénation.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Dispositifs supraglott.","style":"cell_b"},{"t":"p","html":"Après restauration d'une ventilation efficace à travers un dispositif supraglottique de 2ème génération (y compris chez la femme enceinte), en cas d'indication formelle à l'intubation, il est recommandé d'utiliser un fibroscope plutôt qu'une intubation à l'aveugle pour guider la sonde.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"« Cannot intubate, cannot oxygenate »","style":"cell_b"},{"t":"p","html":"En cas d'intubation ET ventilation impossibles malgré un dispositif supraglottique de 2ème génération (y compris chez la femme enceinte), il est recommandé de réaliser en première intention une cricothyroïdotomie selon la technique SMS (Scalpel - Mandrin long béquillé - Sonde d'intubation), par rapport aux autres techniques d'abord sous-glottique d'urgence.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"section","text":"Champ 3 — Facteurs humains & dimensions organisationnelles","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Catégorie","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"Formation initiale","style":"cell_b"},{"t":"p","html":"Dans la formation initiale des internes d'anesthésie-réanimation et des étudiants IADE à la gestion difficile des voies aériennes, il est recommandé d'organiser un programme de simulation en complément de la formation théorique, pour améliorer la performance individuelle et collective.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Formation continue","style":"cell_b"},{"t":"p","html":"Dans la formation continue des médecins anesthésistes-réanimateurs et des IADE, il est recommandé d'organiser un programme de simulation en complément de la formation théorique, pour améliorer la performance individuelle et collective.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"Fréquence de pratique","style":"cell_b"},{"t":"p","html":"Pour la préparation à une gestion difficile des voies aériennes, les experts suggèrent de réaliser régulièrement les procédures (en simulation et/ou en situation réelle), pour améliorer la performance individuelle et collective.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Briefing","style":"cell_b"},{"t":"p","html":"En prévision d'une gestion difficile des voies aériennes, les experts suggèrent de réaliser un briefing associant tous les acteurs impliqués (et si possible le patient), pour améliorer la performance individuelle et collective.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Préparation mentale","style":"cell_b"},{"t":"p","html":"Pour la préparation à une gestion difficile des voies aériennes, les experts suggèrent d'utiliser des techniques de préparation mentale, pour améliorer la performance individuelle et collective.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Defusing","style":"cell_b"},{"t":"p","html":"Après une gestion difficile des voies aériennes compliquée d'un événement indésirable, les experts suggèrent de procéder à un « defusing » immédiatement après l'événement, pour maintenir la sécurité psychologique.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"Debriefing","style":"cell_b"},{"t":"p","html":"Après une gestion difficile des voies aériennes, les experts suggèrent de réaliser un debriefing associant tous les acteurs impliqués (IADE, anesthésiste-réanimateur, IDE de bloc, chirurgien), pour améliorer la performance future et apporter du soutien aux professionnels.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"RMM","style":"cell_b"},{"t":"p","html":"Après une gestion difficile des voies aériennes compliquée d'un événement indésirable, les experts suggèrent de procéder à une revue de mortalité et de morbidité, pour améliorer la performance individuelle et collective future.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"p","html":"<b>Tableau 1 — Nombre minimal de procédures pour une performance satisfaisante (avis d'experts)</b>","style":"body"},{"t":"table","rows":[[{"t":"p","html":"Technique","style":"head_w"},{"t":"p","html":"Seuil","style":"head_w"},{"t":"p","html":"Commentaire","style":"head_w"}],[{"t":"p","html":"Vidéolaryngoscopie","style":"cell"},{"t":"p","html":">15 procédures","style":"cell"},{"t":"p","html":"Apprentissage à débuter par la simulation ; entretien des compétences si changement de dispositif (>5 procédures).","style":"cell"}],[{"t":"p","html":"Vidéolaryngoscopie, lame hyperangulée","style":"cell"},{"t":"p","html":">12 procédures","style":"cell"},{"t":"p","html":"Apprentissage par simulation ; entraînement annuel type atelier de gestion difficile des voies aériennes.","style":"cell"}],[{"t":"p","html":"Dispositif supraglottique de 2ème génération","style":"cell"},{"t":"p","html":">20 procédures","style":"cell"},{"t":"p","html":"Éducation initiale à la détermination de la pression de fuite ; entretien si changement de dispositif (>5 procédures).","style":"cell"}],[{"t":"p","html":"Fibroscopie pour intubation vigile","style":"cell"},{"t":"p","html":">15 procédures","style":"cell"},{"t":"p","html":"Apprentissage par simulation ; entraînement annuel type atelier.","style":"cell"}],[{"t":"p","html":"Fibroscopie à travers un dispositif supraglottique","style":"cell"},{"t":"p","html":">10 procédures","style":"cell"},{"t":"p","html":"Apprentissage à débuter par la simulation.","style":"cell"}],[{"t":"p","html":"Technique SMS (Scalpel-Mandrin-Sonde)","style":"cell"},{"t":"p","html":">3 procédures","style":"cell"},{"t":"p","html":"Apprentissage exclusivement hors clinique.","style":"cell"}]]},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Document source :</b> SFAR/CARORL/CARO/FHS/SFORL (+ CORASSO), « Prise en charge des voies aériennes de l'adulte au bloc opératoire », Recommandation de Bonne Pratique labellisée HAS, adoptée par le Collège de la HAS le 3 septembre 2026.","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/prise-en-charge-des-voies-aeriennes-de-ladulte-au-bloc-operatoire/","style":"source"},{"t":"p","html":"<b>Outils visuels non reproduits ici (disclosed) :</b> Algorithme difficultés prévisibles, Algorithme stratégie en apnée, Aide cognitive intubation en ventilation spontanée, Aide cognitive intubation difficile en apnée, Cricothyroïdotomie technique SMS, Aides cognitives briefing/debriefing, Certificat de voies aériennes difficiles — tous publiés séparément et téléchargeables depuis l'URL source ci-dessus (section « Outils »).","style":"source"},{"t":"p","html":"<b>Couverture :</b> les 28 recommandations textuelles du document (Champs 1 à 3) sont intégralement reprises (grade 1:1, grade 2:13, AE:13, absence de recommandation:1), vérifiées par recoupement avec le tableau de synthèse du source lui-même. Actualise/supersede les fiches déjà présentes sur ce site « Intubation difficile et extubation en anesthésie chez l'adulte » (RFE 2017) et « Prise en charge des voies aériennes en anesthésie adulte, à l'exception de l'intubation difficile » (Conférence de Consensus 2002/2003), conservées pour leur valeur historique. Exclut explicitement la pédiatrie et les soins critiques (choix du source lui-même). Argumentaire scientifique détaillé (document séparé) non reproduit.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante des 28 recommandations textuelles de ce référentiel. Elle ne remplace pas le texte intégral, l'argumentaire scientifique, ni les outils visuels (algorithmes, aides cognitives) publiés séparément par la SFAR. Cette fiche n'est ni éditée ni validée par la SFAR, la HAS, ni les sociétés associées.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/download/prise-en-charge-des-voies-aeriennes-de-ladulte-au-bloc-operatoire-recommandation/?wpdmdl=145883';

