update public.documents set
  fiche_key = 'infections_intra_abdominales_2026',
  card_json = $mgjson${"badge":"SFAR/FCVD/SFCD/SFED/SFM/SFR/SPILF/SFPT — RFE, validée 24/06/2026","title":"Infections intra-abdominales de l'adulte — prise en charge","short":"SFAR, en association avec FCVD/SFCD/SFED/SFM/SFR/SPILF/SFPT, « Prise en charge thérapeutique des Infections intra-abdominales de l'adulte », RFE, validée par le Comité des Référentiels Cliniques de la SFAR (09/06/2026) et le CA de la SFAR (24/06/2026) — document très récent trouvé via recherche web (absent de l'index habituel de ce site à la date de sa publication). ACTUALISE cliniquement la fiche « Prise en charge des infections intra-abdominales » (CC SFAR/SFCD/SPILF/AFC, 2014/2015), conservée sur ce site pour sa valeur historique. Périmètre : adulte nécessitant une prise en charge interventionnelle (chirurgie, endoscopie ou radiologie interventionnelle). Couvre 3 champs : prise en charge initiale (contrôle de la source, antibiothérapie probabiliste détaillée par contexte communautaire/associé aux soins avec facteurs de risque de BLSE/BMR, orientation en soins critiques) ; surveillance clinique et durée de traitement (désescalade, durées d'antibiothérapie/antifongique selon le contexte) ; complications évolutives (réintervention, antibiothérapie de complication postopératoire). 43 recommandations (GRADE1:8, GRADE2:13, avis d'experts:21, absence de recommandation:1) — décompte vérifié exactement identique à celui annoncé par le document source lui-même dans sa section « Synthèse des résultats », aucune divergence.","society":"SFAR / FCVD / SFCD / SFED / SFM / SFR / SPILF / SFPT","version":"2026","validated":"Comité des Référentiels Cliniques SFAR (09/06/2026) et CA SFAR (24/06/2026)","methodology":"Grille GRADE — GRADE 1/2 (forte/faible, pour ou contre), AE (avis d'experts), absence de recommandation (chip « 0/ ») — 43 recommandations (GRADE1:8, GRADE2:13, AE:21, 0/:1), décompte identique à celui annoncé par le source","pages":4,"section":"Infectiologie"}$mgjson$::jsonb,
  presentation_json = $mgjson${"v":1,"key":"infections_intra_abdominales_2026","sections":[{"title":"Infections intra-abdominales de l'adulte — Champs 1 à 3","items":[{"t":"panel","tone":"default","content":{"t":"p","html":"<b>Document très récent</b> (validé CA SFAR 24/06/2026) — trouvé via recherche web (absent de <code>library_final.json</code> à la publication). <b>ACTUALISE</b> la fiche « Prise en charge des infections intra-abdominales » (CC SFAR/SFCD/SPILF/AFC, 2014/2015, conservée pour sa valeur historique). <b>Périmètre :</b> adulte nécessitant une prise en charge interventionnelle (chirurgie, endoscopie, radiologie interventionnelle) — exclut pédiatrie, aplasie/greffe d'organe, cirrhose, infections biliaires/hépatiques isolées, appendicites non opérées.","style":"body"}},{"t":"table","rows":[[{"t":"chip","label":"1+"},{"t":"chip","label":"1-"},{"t":"chip","label":"2+"},{"t":"chip","label":"2-"},{"t":"chip","label":"AE"},{"t":"chip","label":"0/"},{"t":"p","html":"<b>Grille GRADE</b> — <b>1+/1-</b> : recommandation forte, pour/contre ; <b>2+/2-</b> : recommandation faible, pour/contre ; <b>AE</b> : avis d'experts (toujours accord fort) ; <b>0/</b> : absence de recommandation (littérature insuffisante). Décompte annoncé par le source lui-même — 43 recommandations (GRADE1:8, GRADE2:13, AE:21, absence:1) — vérifié exact par recomptage complet du tableau de synthèse, aucune divergence.","style":"badge_head"}]]},{"t":"section","text":"Champ 1 — Prise en charge initiale : contrôle de la source","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"1.1.1","style":"cell_b"},{"t":"p","html":"Instabilité hémodynamique : contrôle de la source infectieuse par voie chirurgicale le plus rapidement possible, associé à un lavage de l'ensemble de la cavité abdominale.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"1.1.2","style":"cell_b"},{"t":"p","html":"Instabilité hémodynamique non/mal contrôlée en peropératoire : les experts suggèrent une chirurgie « Damage Control » ou « laparotomie écourtée », avec reprise chirurgicale définitive à 24-48h après stabilisation.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.1.3","style":"cell_b"},{"t":"p","html":"Suspicion de péritonite par perforation d'organe creux : discuter la voie d'abord (cœlioscopie ou laparotomie) entre chirurgien et anesthésiste-réanimateur — cœlioscopie possible si absence d'hypotension persistante et lésion accessible selon l'expertise du chirurgien.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.1.4","style":"cell_b"},{"t":"p","html":"Patient stable, infection postopératoire avec collection accessible : traitement mini-invasif en 1ère intention (endoscopie interventionnelle ou drainage percutané guidé par imagerie), notamment en cas de fistule secondaire.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"1.1.5","style":"cell_b"},{"t":"p","html":"Diverticulite sigmoïdienne perforée purulente (Hinchey III) sans sepsis : ne pas réaliser de lavage péritonéal exclusif sans résection — réaliser une résection sigmoïdienne avec anastomose primaire (protégée ou non par iléostomie) associée à un lavage péritonéal.","style":"cell"},{"t":"chip","label":"1+"}]]},{"t":"section","text":"Champ 1 — Antibiothérapie probabiliste initiale","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"1.2.1","style":"cell_b"},{"t":"p","html":"Communautaire sans sepsis/choc : céphalosporine de 3e génération (céfotaxime, ceftriaxone) + métronidazole.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"1.2.2","style":"cell_b"},{"t":"p","html":"Communautaire sans sepsis/choc : ne pas prendre en compte les entérobactéries productrices de BLSE dans le choix probabiliste.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"1.2.3","style":"cell_b"},{"t":"p","html":"Communautaire, patient en sepsis : carbapénème envisageable seulement si antécédent documenté de colonisation/infection à BLSE < 6 mois.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.2.4","style":"cell_b"},{"t":"p","html":"Communautaire, choc septique, sans facteur de risque de BLSE : pipéracilline-tazobactam.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"1.2.5","style":"cell_b"},{"t":"p","html":"Communautaire, choc septique, ≥1 facteur de risque de BLSE : carbapénème selon la prévalence locale.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"1.2.6","style":"cell_b"},{"t":"p","html":"Associée aux soins (1er épisode), sans facteur de risque de BMR, y compris sepsis/choc : céfépime + métronidazole.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"1.2.7","style":"cell_b"},{"t":"p","html":"Idem, si monitorage plasmatique du céfépime impossible : pipéracilline-tazobactam selon l'écologie locale.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.2.8","style":"cell_b"},{"t":"p","html":"Associée aux soins, choc septique, céfépime + métronidazole (non actif sur entérocoques) : ajouter linézolide, vancomycine ou teicoplanine.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.2.9","style":"cell_b"},{"t":"p","html":"Associée aux soins, pipéracilline-tazobactam choisie + facteur de risque d'entérocoque ampicilline-résistant : ajouter linézolide, vancomycine ou teicoplanine.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.2.10","style":"cell_b"},{"t":"p","html":"1er épisode associé aux soins, ≥2 critères de BMR (tableau ci-dessous) : carbapénème d'emblée — un seul critère suffit si sepsis/choc septique.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"1.2.11","style":"cell_b"},{"t":"p","html":"Communautaire (± sepsis/choc), allergie aux β-lactamines excluant céphalosporines et carbapénèmes : lévofloxacine + métronidazole, ou moxifloxacine* (*QT corrigé contrôlé) ; ou tigécycline/éravacycline si fluoroquinolones contre-indiquées, réévaluation à 48h.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.2.12","style":"cell_b"},{"t":"p","html":"Associée aux soins, même contexte d'allergie : ciprofloxacine + métronidazole (± linézolide/vancomycine/teicoplanine) ; ou aztréonam + métronidazole (± idem) ; ou tigécycline/éravacycline + ciprofloxacine.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"1.2.13","style":"cell_b"},{"t":"p","html":"Communautaire en sepsis/choc ou associée aux soins : traitement antifongique si examen direct positif à levures, ou ≥3 critères parmi défaillance hémodynamique, sexe féminin, chirurgie sus-mésocolique, antibiothérapie > 48h.","style":"cell"},{"t":"chip","label":"2+"}]]},{"t":"table","rows":[[{"t":"p","html":"<b>Bactérie</b>","style":"cell_b"},{"t":"p","html":"<b>Facteurs de risque retenus</b>","style":"cell_b"}],[{"t":"p","html":"BLSE","style":"cell"},{"t":"p","html":"ATCD infection/colonisation BLSE < 6 mois ; prévalence locale élevée ; amoxicilline-ac. clavulanique/C2G/C3G/fluoroquinolones dans les 6 mois ; voyage en zone d'endémie < 3 mois ; vie en institution médico-sociale avec dispositif invasif permanent (sonde urinaire à demeure et/ou gastrostomie).","style":"cell"}],[{"t":"p","html":"BMR (au sens large)","style":"cell"},{"t":"p","html":"C3G ou fluoroquinolones dans les 3 mois ; portage documenté < 3 mois de BLSE ou P. aeruginosa résistant ceftazidime ; hospitalisation à l'étranger < 12 mois ; vie en institution médico-sociale avec dispositif invasif permanent ; échec d'un traitement antérieur par C3G/fluoroquinolones/pipéracilline-tazobactam ; récidive < 15 jours d'une infection traitée ≥ 3 jours par pipéracilline-tazobactam.","style":"cell"}],[{"t":"p","html":"Entérocoque ampicilline-résistant","style":"cell"},{"t":"p","html":"Péritonite d'origine hépato-biliaire suspectée ; antécédent de transplantation hépatique, patient immunodéprimé ; patient déjà sous antibiothérapie ou antibiothérapie préalable par céphalosporine.","style":"cell"}]]},{"t":"p","html":"Tableau 1 du source — facteurs de risque de bactéries résistantes, rattaché aux R1.2.3/1.2.5/1.2.10.","style":"source"},{"t":"section","text":"Champ 1 — Orientation en soins critiques","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"1.3.1","style":"cell_b"},{"t":"p","html":"Choc septique ou sepsis : admission systématique en soins critiques.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"1.3.2","style":"cell_b"},{"t":"p","html":"Sans choc ni sepsis : baser la décision d'admission sur âge > 60 ans, comorbidités, péritonite généralisée.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"1.3.3","style":"cell_b"},{"t":"p","html":"Sans choc ni sepsis : les scores CPIRO, WSES Sepsis Severity Score ou PIPAS Severity Score peuvent être utilisés pour identifier les patients nécessitant une admission en soins critiques.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Champ 2 — Surveillance clinique & durée de traitement","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"2.1.1","style":"cell_b"},{"t":"p","html":"5 premiers jours postopératoires : ne pas réaliser systématiquement — dosage PCT/CRP, nouvelle laparotomie systématique (hors Damage Control initial ou doute sur vitalité digestive), cultures microbiologiques des liquides de drainage.","style":"cell"},{"t":"chip","label":"2-"}],[{"t":"p","html":"2.1.2","style":"cell_b"},{"t":"p","html":"Évolution favorable : les experts suggèrent de ne pas réaliser de tomodensitométrie abdominale systématique dans les 5 premiers jours.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.2.1","style":"cell_b"},{"t":"p","html":"Appendicite aiguë non compliquée, contrôle de la source obtenu : pas d'antibiothérapie postopératoire au-delà de l'antibioprophylaxie peropératoire (dose unique).","style":"cell"},{"t":"chip","label":"1-"}],[{"t":"p","html":"2.2.2","style":"cell_b"},{"t":"p","html":"Appendicite aiguë compliquée, contrôle de la source obtenu : antibiothérapie probabiliste postopératoire courte (2 jours).","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"2.2.3","style":"cell_b"},{"t":"p","html":"Infection communautaire compliquée (hors appendicite), contrôle de la source obtenu : limiter la durée d'antibiothérapie à 4 jours, y compris en cas de sepsis initial ou de contrôle par drainage percutané/endoscopique.","style":"cell"},{"t":"chip","label":"1+"}],[{"t":"p","html":"2.2.4","style":"cell_b"},{"t":"p","html":"Associée aux soins (hors postopératoire), sans sepsis/choc, contrôle de la source obtenu : les experts suggèrent de limiter la durée à 4 jours.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.2.5","style":"cell_b"},{"t":"p","html":"Associée aux soins, sepsis/choc, contrôle de la source obtenu : limiter la durée d'antibiothérapie à 8 jours.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"2.3.1","style":"cell_b"},{"t":"p","html":"Antifongique instauré d'emblée, culture positive à Candida sp. : les experts suggèrent de limiter le traitement à 8 jours si contrôle de la source rapide/efficace, évolution favorable, et absence de candidémie — tous critères réunis.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.3.1bis","style":"cell_b"},{"t":"p","html":"Mêmes circonstances mais critères ci-dessus non tous réunis : absence de recommandation sur la durée nécessaire de traitement antifongique.","style":"cell"},{"t":"chip","label":"0/"}],[{"t":"p","html":"2.3.2","style":"cell_b"},{"t":"p","html":"Antifongique instauré d'emblée, culture à Candida négative ou non disponible : dosage de B-D-glucane à J0 et J3 ; arrêt précoce envisageable si les deux prélèvements sont négatifs.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"2.4.1","style":"cell_b"},{"t":"p","html":"Évolution favorable après contrôle de la source : désescalader l'antibiothérapie après résultats bactériologiques.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"2.4.2","style":"cell_b"},{"t":"p","html":"Évolution favorable après contrôle de la source : désescalade antifongique envisageable si patient non neutropénique, contrôle adéquat de la source, prélèvements initiaux interprétables, amélioration clinique à 48-72h, traitement initial optimisé (PK/PD), durée post-désescalade > 24h.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Champ 3 — Complications évolutives","color":"navy"},{"t":"table","rows":[[{"t":"p","html":"Réf.","style":"head_w"},{"t":"p","html":"Recommandation","style":"head_w"},{"t":"p","html":"Grade","style":"head_w_c"}],[{"t":"p","html":"3.1.1","style":"cell_b"},{"t":"p","html":"Évolution défavorable, suspicion de complication infectieuse : contrôle de la source en urgence.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"3.1.2","style":"cell_b"},{"t":"p","html":"Patient stable hémodynamiquement, évolution défavorable : les experts suggèrent une approche mini-invasive (percutanée et/ou endoscopique) si techniquement possible.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"3.2.1","style":"cell_b"},{"t":"p","html":"Phase précoce (≤72h), fièvre ou iléus ou persistance de défaillance d'organe : suspecter une complication infectieuse ou un contrôle de la source imparfait, réaliser un contrôle de la source en urgence.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"3.2.2","style":"cell_b"},{"t":"p","html":"Phase précoce (≤72h), évolution défavorable : scanner issu d'une discussion multidisciplinaire, pas systématique ; ne pas doser CRP/PCT ; ne pas cultiver le liquide d'un drain déjà en place.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"3.2.3","style":"cell_b"},{"t":"p","html":"Phase tardive (>72h), évolution défavorable : scanner thoraco-abdomino-pelvien injecté (± opacification intra-luminale si geste gastrique/colique).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"3.3.1","style":"cell_b"},{"t":"p","html":"Complication postopératoire : antibiothérapie probabiliste couvrant les micro-organismes à risque de résistance (entérobactéries multirésistantes dont BLSE, P. aeruginosa, E. faecium), adaptée à l'écologie locale et du patient.","style":"cell"},{"t":"chip","label":"2+"}],[{"t":"p","html":"3.3.2","style":"cell_b"},{"t":"p","html":"Complication postopératoire : les experts suggèrent d'ajuster secondairement l'antibiothérapie aux prélèvements peropératoires/de reprise, ou aux hémocultures seules si prélèvements non contributifs.","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"3.3.3","style":"cell_b"},{"t":"p","html":"Soins critiques ou risque de surdosage : suivi thérapeutique pharmacologique pour adaptation posologique optimisée (bêta-lactamines : recommandations SFAR/SFPT 2018).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"3.3.4","style":"cell_b"},{"t":"p","html":"Contrôle de la source obtenu, amélioration clinique sous antibiothérapie adaptée : limiter la durée à 8 jours — au-delà, discussion multidisciplinaire (anesthésistes-réanimateurs, chirurgiens, infectiologues, microbiologistes).","style":"cell"},{"t":"chip","label":"AE"}],[{"t":"p","html":"3.3.5","style":"cell_b"},{"t":"p","html":"Mauvaise évolution sous antibiothérapie avec signes de gravité hémodynamique, ou levures à l'examen direct : traitement antifongique probabiliste systématique, échinocandines privilégiées.","style":"cell"},{"t":"chip","label":"AE"}]]},{"t":"section","text":"Sources et avertissement","color":"grey"},{"t":"p","html":"<b>Document source :</b> SFAR/FCVD/SFCD/SFED/SFM/SFR/SPILF/SFPT, « Prise en charge thérapeutique des Infections intra-abdominales de l'adulte », RFE, validée par le Comité des Référentiels Cliniques de la SFAR (09/06/2026) et le CA de la SFAR (24/06/2026).","style":"source"},{"t":"p","html":"<b>URL source :</b> https://sfar.org/prise-en-charge-therapeutique-des-infections-intra-abdominales-de-ladulte/","style":"source"},{"t":"p","html":"<b>Couverture :</b> les 43 recommandations du document (Champs 1 à 3) sont intégralement reprises (GRADE1:8, GRADE2:13, avis d'experts:21, absence de recommandation:1) — décompte identique à celui annoncé par le source lui-même dans sa section « Synthèse des résultats », vérifié par recomptage exhaustif du tableau de synthèse. Actualise/supersede cliniquement la fiche « Prise en charge des infections intra-abdominales » (CC SFAR/SFCD/SPILF/AFC, 2014/2015, conservée sur ce site pour sa valeur historique). Argumentaire scientifique détaillé (études, méta-analyses, même document, 91 pages) non repris.","style":"source"},{"t":"panel","tone":"grey","content":{"t":"p","html":"<b>Avertissement :</b> cette fiche est une synthèse indépendante des 43 recommandations de ce référentiel. Elle ne remplace pas le texte intégral ni l'argumentaire scientifique. Cette fiche n'est ni éditée ni validée par la SFAR ni les sociétés co-signataires.","style":"body_sm"}}]}]}$mgjson$::jsonb
where source_url = 'https://sfar.org/download/prise-en-charge-therapeutique-des-infections-intra-abdominales-de-ladulte/?wpdmdl=145222';

insert into public.documents (title, doc_type, publication_date, source_url, original_language)
values ('Nutrition clinique de l''adulte en contexte périopératoire et en soins critiques', 'RBP', '2026-01-01', 'https://sfar.org/download/nutrition-clinique-de-ladulte-en-contexte-perioperatoire-et-en-soins-critiques-version-courte/?wpdmdl=145550', 'non_renseigne')
